const SCP_SHORT_LABELS: Partial<Record<ApplicantType, string>> = {
  REGULAR: "BEC",
  LATE_ENROLLEE: "Late",
  SCIENCE_TECHNOLOGY_AND_ENGINEERING: "STE",
  SPECIAL_PROGRAM_IN_THE_ARTS: "SPA",
  SPECIAL_PROGRAM_IN_SPORTS: "SPS",
  SPECIAL_PROGRAM_IN_JOURNALISM: "SPJ",
  SPECIAL_PROGRAM_IN_FOREIGN_LANGUAGE: "SPFL",
  SPECIAL_PROGRAM_IN_TECHNICAL_VOCATIONAL_EDUCATION: "SPTVE",
};

const formatLearnerName = (
  learner: Pick<PoolLearner, "lastName" | "firstName" | "middleName">,
) => {
  const middleInitial = learner.middleName?.charAt(0)
    ? ` ${learner.middleName.charAt(0)}.`
    : "";
  return `${learner.lastName}, ${learner.firstName}${middleInitial}`;
};

const sortLearnersByAverage = (first: PoolLearner, second: PoolLearner) => {
  const firstAverage = first.genAve ?? -1;
  const secondAverage = second.genAve ?? -1;
  return (
    secondAverage - firstAverage || first.applicationId - second.applicationId
  );
};

const _interleaveBySex = (learners: PoolLearner[]) => {
  const males = learners
    .filter((learner) => learner.sex === "MALE")
    .sort(sortLearnersByAverage);
  const females = learners
    .filter((learner) => learner.sex === "FEMALE")
    .sort(sortLearnersByAverage);
  const ordered: PoolLearner[] = [];
  let maleIndex = 0;
  let femaleIndex = 0;
  let preferMale = males.length >= females.length;

  while (maleIndex < males.length || femaleIndex < females.length) {
    const preferred = preferMale ? males[maleIndex] : females[femaleIndex];
    const fallback = preferMale ? females[femaleIndex] : males[maleIndex];
    const selected = preferred ?? fallback;
    if (!selected) break;

    ordered.push(selected);
    if (selected.sex === "MALE") maleIndex += 1;
    else femaleIndex += 1;
    preferMale = !preferMale;
  }

  return ordered;
};

const buildDraftSlots = (sections: SectionSummary[]) => {
  const ordered = [...sections].sort(
    (first, second) =>
      first.sortOrder - second.sortOrder ||
      first.name.localeCompare(second.name) ||
      first.id - second.id,
  );
  const remainingBySection = new Map(
    ordered.map((section) => [
      section.id,
      Math.max(0, section.maxCapacity - section.currentCount),
    ]),
  );
  const slots: number[] = [];
  let forward = true;

  while (
    ordered.some((section) => (remainingBySection.get(section.id) ?? 0) > 0)
  ) {
    const pass = forward ? ordered : [...ordered].reverse();
    for (const section of pass) {
      const remaining = remainingBySection.get(section.id) ?? 0;
      if (remaining <= 0) continue;
      slots.push(section.id);
      remainingBySection.set(section.id, remaining - 1);
    }
    forward = !forward;
  }

  return slots;
};

const calculateGenderCounts = (
  section: SectionSummary,
  learners: DraftLearnerPlacement[],
): DraftGenderCounts => ({
  boys:
    section.boys + learners.filter((learner) => learner.sex === "MALE").length,
  girls:
    section.girls +
    learners.filter((learner) => learner.sex === "FEMALE").length,
});

const buildRoster = (
  section: SectionSummary,
  learners: DraftLearnerPlacement[],
): DraftSectionRoster => {
  const sortedLearners = [...learners].sort(sortLearnersByAverage);
  const totalCount = section.currentCount + sortedLearners.length;
  return {
    section,
    learners: sortedLearners,
    genderCounts: calculateGenderCounts(section, sortedLearners),
    totalCount,
    isOverCapacity: totalCount > section.maxCapacity,
  };
};

const rebuildDraftPlacement = (draft: DraftPlacement): DraftPlacement => ({
  ...draft,
  rosters: draft.rosters.map((roster) =>
    buildRoster(roster.section, roster.learners),
  ),
});

const createDraftPlacement = (
  gradeLevelId: number,
  learners: PoolLearner[],
  sections: SectionSummary[],
  homogeneousSectionCount: number,
): DraftPlacement => {
  const rostersBySectionId = new Map<number, DraftLearnerPlacement[]>(
    sections.map((section) => [section.id, []]),
  );
  const unplacedLearners: PoolLearner[] = [];
  const programTypes = Array.from(
    new Set(learners.map((learner) => getAutoDraftProgramType(learner))),
  );

  for (const programType of programTypes) {
    const rawProgramLearners = learners.filter(
      (learner) => getAutoDraftProgramType(learner) === programType,
    );
    const programSections = sections.filter(
      (section) => section.programType === programType,
    );

    let programLearners: PoolLearner[] = [];
    let slots: number[] = [];

    const sortedLearners = [...rawProgramLearners].sort(sortLearnersByAverage);
    const orderedSections = [...programSections].sort(
      (first, second) =>
        first.sortOrder - second.sortOrder ||
        first.name.localeCompare(second.name) ||
        first.id - second.id,
    );

    const totalLearners = sortedLearners.length;
    if (totalLearners === 0 || orderedSections.length === 0) {
      unplacedLearners.push(...sortedLearners);
      continue;
    }

    const males = sortedLearners.filter((l) => l.sex === "MALE");
    const females = sortedLearners.filter((l) => l.sex === "FEMALE");

    const allSlots = buildDraftSlots(orderedSections);
    const activeSlots = allSlots.slice(0, totalLearners);

    const sectionTotalSlots = new Map<number, number>(
      orderedSections.map((s) => [s.id, 0])
    );
    for (const id of activeSlots) {
      sectionTotalSlots.set(id, sectionTotalSlots.get(id)! + 1);
    }

    const sectionMaleSlots = new Map<number, number>();
    const sectionFemaleSlots = new Map<number, number>();

    let allocatedMales = 0;
    const maleFractions = new Map<number, number>();

    for (const section of orderedSections) {
      const total = sectionTotalSlots.get(section.id)!;
      if (total === 0) {
        sectionMaleSlots.set(section.id, 0);
        continue;
      }
      const exactMales = total * (males.length / totalLearners);
      const baseMales = Math.floor(exactMales);
      sectionMaleSlots.set(section.id, baseMales);
      allocatedMales += baseMales;
      maleFractions.set(section.id, exactMales - baseMales);
    }

    const remainingMalesCount = males.length - allocatedMales;
    const sortedByFraction = [...orderedSections].sort(
      (a, b) =>
        (maleFractions.get(b.id) ?? 0) - (maleFractions.get(a.id) ?? 0) ||
        a.id - b.id
    );

    for (let i = 0; i < remainingMalesCount; i++) {
      const section = sortedByFraction[i % sortedByFraction.length];
      sectionMaleSlots.set(section.id, sectionMaleSlots.get(section.id)! + 1);
    }

    for (const section of orderedSections) {
      const total = sectionTotalSlots.get(section.id)!;
      const mSlots = sectionMaleSlots.get(section.id)!;
      sectionFemaleSlots.set(section.id, total - mSlots);
    }

    const activeHomoCount = programType === "REGULAR" ? homogeneousSectionCount : 0;
    const topSections = orderedSections.slice(0, activeHomoCount);
    const remainingSections = orderedSections.slice(activeHomoCount);

    const maleSlotsArray: number[] = [];
    const femaleSlotsArray: number[] = [];

    for (const section of topSections) {
      const mCount = sectionMaleSlots.get(section.id)!;
      for (let i = 0; i < mCount; i++) maleSlotsArray.push(section.id);
      
      const fCount = sectionFemaleSlots.get(section.id)!;
      for (let i = 0; i < fCount; i++) femaleSlotsArray.push(section.id);
    }

    const remMaleCounts = new Map(remainingSections.map((s) => [s.id, sectionMaleSlots.get(s.id)!]));
    const remFemaleCounts = new Map(remainingSections.map((s) => [s.id, sectionFemaleSlots.get(s.id)!]));

    let forward = true;
    while (Array.from(remMaleCounts.values()).some((c) => c > 0)) {
      const pass = forward ? remainingSections : [...remainingSections].reverse();
      for (const section of pass) {
        if (remMaleCounts.get(section.id)! > 0) {
          maleSlotsArray.push(section.id);
          remMaleCounts.set(section.id, remMaleCounts.get(section.id)! - 1);
        }
      }
      forward = !forward;
    }

    forward = true;
    while (Array.from(remFemaleCounts.values()).some((c) => c > 0)) {
      const pass = forward ? remainingSections : [...remainingSections].reverse();
      for (const section of pass) {
        if (remFemaleCounts.get(section.id)! > 0) {
          femaleSlotsArray.push(section.id);
          remFemaleCounts.set(section.id, remFemaleCounts.get(section.id)! - 1);
        }
      }
      forward = !forward;
    }

    const placedMales = males.slice(0, maleSlotsArray.length);
    const unplacedMales = males.slice(maleSlotsArray.length);
    
    const placedFemales = females.slice(0, femaleSlotsArray.length);
    const unplacedFemales = females.slice(femaleSlotsArray.length);

    programLearners = [...placedMales, ...placedFemales, ...unplacedMales, ...unplacedFemales];
    slots = [...maleSlotsArray, ...femaleSlotsArray];

    for (const [index, learner] of programLearners.entries()) {
      const sectionId = slots[index];
      if (sectionId === undefined) {
        unplacedLearners.push(learner);
        continue;
      }

      const rosterLearners = rostersBySectionId.get(sectionId);
      if (!rosterLearners) {
        unplacedLearners.push(learner);
        continue;
      }

      rosterLearners.push({
        ...learner,
        sectionId,
        isOverridden: false,
      });
    }
  }

  return {
    gradeLevelId,
    generatedAt: new Date().toISOString(),
    rosters: sections.map((section) =>
      buildRoster(section, rostersBySectionId.get(section.id) ?? []),
    ),
    unplacedLearners,
  };
};
export function SectioningWorkspace() {
  const { isHistoricalReadOnly } = useHistoricalReadOnly();

  const [sections, setSections] = useState<SectionSummary[]>([]);
  const [pool, setPool] = useState<PoolLearner[]>([]);
  const [processing, setProcessing] = useState(false);
  const [draftPlacement, setDraftPlacement] = useState<DraftPlacement | null>(
    null,
  );
  const [expandedSectionIds, setExpandedSectionIds] = useState<Set<number>>(
    new Set(),
  );
  const [draftMoveAction, setDraftMoveAction] =
    useState<DraftMoveAction | null>(null);
  const [normalMoveAction, setNormalMoveAction] = useState<{
    learnerApplicationId: number;
    fromSectionId: number;
  } | null>(null);
  const [moveDestinationSectionId, setMoveDestinationSectionId] = useState("");
  const [swapApplicationId, setSwapApplicationId] = useState("");
  const [autoAssignConfirmOpen, setAutoAssignConfirmOpen] = useState(false);
  const [commitDialogOpen, setCommitDialogOpen] = useState(false);
  const [allowCapacityOverride, setAllowCapacityOverride] = useState(false);
  const [commitProcessing, setCommitProcessing] = useState(false);
  const [masterlistModalSectionId, setMasterlistModalSectionId] = useState<
    number | null
  >(null);

  const queryClient = useQueryClient();

  const activeGradeLevelId = useSettingsStore((s) => s.uiPreferences.sectioningGradeId);
  const setActiveGradeLevelId = (id: string) => useSettingsStore.getState().updateUiPreference("sectioningGradeId", id);
  const homogeneousSectionCount = useSettingsStore((s) => s.homogeneousSectionCount);

  const { data: sectionsData, isLoading: sectionsInitialLoading } = useQuery({
    queryKey: queryKeys.sectioningSections(),
    queryFn: () =>
      api
        .get<SectionSummary[]>("/sectioning/sections-summary")
        .then((r) => r.data),
    enabled: !isHistoricalReadOnly,
    refetchInterval: 5_000,
    refetchOnWindowFocus: true,
    staleTime: 3_000,
  });

  const { data: poolData, isLoading: poolInitialLoading } = useQuery({
    queryKey: queryKeys.sectioningPool(),
    queryFn: () =>
      api.get<PoolLearner[]>("/sectioning/pool").then((r) => r.data),
    enabled: !isHistoricalReadOnly,
    refetchInterval: 5_000,
    refetchOnWindowFocus: true,
    staleTime: 3_000,
  });

  const { data: gradeLevelsResponse, isLoading: gradeLevelsLoading } = useQuery(
    {
      queryKey: ["settings", "grade-levels"],
      queryFn: () =>
        api
          .get<GradeLevelsResponse>("/school-years/grade-levels")
          .then((response) => response.data),
      staleTime: 60_000,
    },
  );

  useEffect(() => {
    if (sectionsData && !draftPlacement) setSections(sectionsData);
  }, [sectionsData, draftPlacement]);
  useEffect(() => {
    if (poolData && !draftPlacement) setPool(poolData);
  }, [poolData, draftPlacement]);

  const loading =
    (sectionsInitialLoading || poolInitialLoading || gradeLevelsLoading) &&
    !isHistoricalReadOnly;

  const [selectedAppIds, setSelectedAppIds] = useState<number[]>([]);
  const guardedSetActiveGradeLevelId = useGuardedTabChange(
    setActiveGradeLevelId,
  );

  type SortConfig = { key: "genAve"; direction: "asc" | "desc" } | null;
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const handleSort = (key: "genAve") => {
    let direction: "asc" | "desc" = "asc";
    if (
      sortConfig &&
      sortConfig.key === key &&
      sortConfig.direction === "asc"
    ) {
      direction = "desc";
    }
    setSortConfig({ key, direction });
  };

  const [filterProgram, setFilterProgram] = useState<string>("all");
  const {
    inputValue: searchQuery,
    setInputValue: setSearchQuery,
    activeFilter: activeSearchQuery,
  } = useDebouncedSearch();
  const [targetSectionId, setTargetSectionId] = useState<number | null>(null);

  const gradeLevels = useMemo(() => {
    const raw = gradeLevelsResponse?.gradeLevels ?? [];
    const jhs = raw.filter((gradeLevel) =>
      ["Grade 7", "Grade 8", "Grade 9", "Grade 10"].includes(gradeLevel.name),
    );
    return jhs.sort((a, b) => {
      const orderA = a.displayOrder ?? parseInt(a.name.replace(/\D/g, "")) ?? 0;
      const orderB = b.displayOrder ?? parseInt(b.name.replace(/\D/g, "")) ?? 0;
      return orderA - orderB;
    });
  }, [gradeLevelsResponse]);

  useEffect(() => {
    if (gradeLevels.length > 0) {
      const isValid = gradeLevels.some(g => String(g.id) === activeGradeLevelId);
      if (!isValid) {
        setActiveGradeLevelId(String(gradeLevels[0].id));
      }
    }
  }, [gradeLevels, activeGradeLevelId, setActiveGradeLevelId]);

  const isDraftActive = draftPlacement !== null;
  const _isLockedIn = selectedAppIds.length > 0 || isDraftActive;

  const currentGradeSections = useMemo(() => {
    if (!activeGradeLevelId) return [];
    return sections.filter(
      (s) => String(s.gradeLevelId) === activeGradeLevelId,
    );
  }, [sections, activeGradeLevelId]);

  const currentGradePool = useMemo(() => {
    if (!activeGradeLevelId) return [];
    return pool.filter((p) => String(p.gradeLevelId) === activeGradeLevelId);
  }, [pool, activeGradeLevelId]);
  const draftLearnerCount = useMemo(
    () =>
      draftPlacement?.rosters.reduce(
        (total, roster) => total + roster.learners.length,
        0,
      ) ?? 0,
    [draftPlacement],
  );
  const hasDraftOverflow = useMemo(
    () =>
      draftPlacement?.rosters.some((roster) => roster.isOverCapacity) ?? false,
    [draftPlacement],
  );
  const selectedProgramTypes = useMemo(
    () =>
      new Set(
        currentGradePool
          .filter((learner) => selectedAppIds.includes(learner.applicationId))
          .map((learner) => learner.programType),
      ),
    [currentGradePool, selectedAppIds],
  );

  const filteredPool = useMemo(() => {
    return currentGradePool.filter((l) => {
      if (filterProgram !== "all" && l.programType !== filterProgram) return false;
      if (activeSearchQuery) {
        const q = activeSearchQuery.toLowerCase();
        const fullName = `${l.lastName} ${l.firstName}`.toLowerCase();
        if (!fullName.includes(q) && !l.lrn?.toLowerCase().includes(q)) {
          return false;
        }
      }
      return true;
    });
  }, [currentGradePool, activeSearchQuery, filterProgram]);

  const filteredAndSortedPool = useMemo(() => {
    const result = [...filteredPool];
    if (sortConfig !== null) {
      result.sort((a, b) => {
        if (sortConfig.key === "genAve") {
          const aVal = a.genAve ?? -1;
          const bVal = b.genAve ?? -1;
          if (aVal < bVal) return sortConfig.direction === "asc" ? -1 : 1;
          if (aVal > bVal) return sortConfig.direction === "asc" ? 1 : -1;
          return 0;
        }
        return 0;
      });
    }
    return result;
  }, [filteredPool, sortConfig]);

  const assignLearners = async () => {
    if (!targetSectionId || selectedAppIds.length === 0) return;

    setProcessing(true);
    try {
      await api.post("/sectioning/assign-bulk", {
        sectionId: targetSectionId,
        applicationIds: selectedAppIds,
      });

      const sectionName = currentGradeSections.find(
        (s) => s.id === targetSectionId,
      )?.name;
      sileo.success({
        title: "Assignment Successful",
        description: `Assigned ${selectedAppIds.length} learners to ${sectionName}.`,
      });
      setSelectedAppIds([]);
      setTargetSectionId(null);
      void queryClient.invalidateQueries({
        queryKey: queryKeys.sectioningPool(),
      });
      void queryClient.invalidateQueries({
        queryKey: queryKeys.sectioningSections(),
      });
    } catch (error: unknown) {
      sileo.error({
        title: "Assignment Failed",
        description:
          (isAxiosError<ApiMessageResponse>(error)
            ? error.response?.data.message
            : undefined) ??
          "An error occurred while moving learners. Please try again.",
      });
    } finally {
      setProcessing(false);
    }
  };

  const generateDraftPlacement = () => {
    if (!activeGradeLevelId) return;

    const parsedGradeLevelId = Number(activeGradeLevelId);
    const draft = createDraftPlacement(
      parsedGradeLevelId,
      currentGradePool,
      currentGradeSections,
      homogeneousSectionCount,
    );
    const populatedSectionIds = draft.rosters
      .filter((roster) => roster.learners.length > 0)
      .map((roster) => roster.section.id);

    setDraftPlacement(draft);
    setExpandedSectionIds(new Set(populatedSectionIds));
    setSelectedAppIds([]);
    setTargetSectionId(null);
    setAllowCapacityOverride(false);

    sileo.success({
      title: "Draft Placement Generated",
      description: `${draft.rosters.reduce((total, roster) => total + roster.learners.length, 0)} learner(s) are ready for review.`,
    });
  };

  const discardDraft = useCallback(() => {
    setDraftPlacement(null);
    setExpandedSectionIds(new Set());
    setDraftMoveAction(null);
    setMoveDestinationSectionId("");
    setSwapApplicationId("");
    setAllowCapacityOverride(false);
    if (sectionsData) setSections(sectionsData);
    if (poolData) setPool(poolData);
  }, [poolData, sectionsData]);

  useUnsavedChanges({
    id: "sectioning-draft-placement",
    label: "Draft section placement",
    isDirty: isDraftActive,
    isSubmitting: commitProcessing,
    onDiscard: discardDraft,
  });

  const toggleExpandedSection = (sectionId: number) => {
    setExpandedSectionIds((prev) => {
      const next = new Set(prev);
      if (next.has(sectionId)) next.delete(sectionId);
      else next.add(sectionId);
      return next;
    });
  };

  const findDraftLearner = (applicationId: number) => {
    if (!draftPlacement) return null;
    for (const roster of draftPlacement.rosters) {
      const learner = roster.learners.find(
        (item) => item.applicationId === applicationId,
      );
      if (learner) return learner;
    }
    return null;
  };

  const openMoveDialog = (
    learnerApplicationId: number,
    fromSectionId: number,
  ) => {
    setDraftMoveAction({ type: "MOVE", learnerApplicationId, fromSectionId });
    setMoveDestinationSectionId("");
  };

  const openNormalMoveDialog = (
    learnerApplicationId: number,
    fromSectionId: number,
  ) => {
    setNormalMoveAction({ learnerApplicationId, fromSectionId });
    setMoveDestinationSectionId("");
  };

  const openSwapDialog = (
    learnerApplicationId: number,
    fromSectionId: number,
  ) => {
    setDraftMoveAction({ type: "SWAP", learnerApplicationId, fromSectionId });
    setSwapApplicationId("");
  };

  const executeMove = () => {
    if (!draftPlacement || !draftMoveAction || draftMoveAction.type !== "MOVE")
      return;
    const destinationSectionId = Number(moveDestinationSectionId);
    if (!Number.isInteger(destinationSectionId) || destinationSectionId <= 0)
      return;

    setDraftPlacement((current) => {
      if (!current) return current;

      let movingLearner: DraftLearnerPlacement | null = null;
      const rosters = current.rosters.map((roster) => {
        if (roster.section.id !== draftMoveAction.fromSectionId) return roster;
        const remainingLearners = roster.learners.filter((learner) => {
          if (learner.applicationId !== draftMoveAction.learnerApplicationId)
            return true;
          movingLearner = learner;
          return false;
        });
        return buildRoster(roster.section, remainingLearners);
      });

      if (!movingLearner) return current;

      const updatedRosters = rosters.map((roster) => {
        if (roster.section.id !== destinationSectionId || !movingLearner)
          return roster;
        return buildRoster(roster.section, [
          ...roster.learners,
          {
            ...movingLearner,
            sectionId: destinationSectionId,
            isOverridden: true,
          },
        ]);
      });

      return rebuildDraftPlacement({ ...current, rosters: updatedRosters });
    });

    setExpandedSectionIds((prev) => {
      const next = new Set(prev);
      next.add(destinationSectionId);
      return next;
    });

    setDraftMoveAction(null);
    setMoveDestinationSectionId("");
  };

  const executeNormalMove = async () => {
    if (!normalMoveAction) return;
    const destinationSectionId = Number(moveDestinationSectionId);
    if (!Number.isInteger(destinationSectionId) || destinationSectionId <= 0)
      return;

    setProcessing(true);
    try {
      await api.post("/sections/transfer-learner", {
        targetSectionId: destinationSectionId,
        enrollmentApplicationId: normalMoveAction.learnerApplicationId,
      });
      sileo.success({
        title: "Assignment Successful",
        description: "Learner successfully moved to the new section.",
      });
      const oldSectionId = normalMoveAction.fromSectionId;
      setNormalMoveAction(null);
      setMoveDestinationSectionId("");
      void queryClient.invalidateQueries({
        queryKey: queryKeys.sectioningSections(),
      });
      void queryClient.invalidateQueries({
        queryKey: ["section-masterlist", oldSectionId],
      });
      void queryClient.invalidateQueries({
        queryKey: ["section-masterlist", destinationSectionId],
      });
    } catch (_error: unknown) {
      sileo.error({
        title: "Move Failed",
        description: "An error occurred while moving the learner. Please try again.",
      });
    } finally {
      setProcessing(false);
    }
  };

  const executeSwap = () => {
    if (!draftPlacement || !draftMoveAction || draftMoveAction.type !== "SWAP")
      return;
    const otherApplicationId = Number(swapApplicationId);
    if (!Number.isInteger(otherApplicationId) || otherApplicationId <= 0)
      return;

    setDraftPlacement((current) => {
      if (!current) return current;

      const sourceLearner = findDraftLearner(
        draftMoveAction.learnerApplicationId,
      );
      const otherLearner = findDraftLearner(otherApplicationId);
      if (!sourceLearner || !otherLearner) return current;

      const sourceSectionId = sourceLearner.sectionId;
      const otherSectionId = otherLearner.sectionId;
      const rosters = current.rosters.map((roster) => {
        const swappedLearners = roster.learners.map((learner) => {
          if (learner.applicationId === sourceLearner.applicationId) {
            return {
              ...otherLearner,
              sectionId: sourceSectionId,
              isOverridden: true,
            };
          }
          if (learner.applicationId === otherLearner.applicationId) {
            return {
              ...sourceLearner,
              sectionId: otherSectionId,
              isOverridden: true,
            };
          }
          return learner;
        });
        return buildRoster(roster.section, swappedLearners);
      });

      return rebuildDraftPlacement({ ...current, rosters });
    });

    setDraftMoveAction(null);
    setSwapApplicationId("");
  };

  const commitDraftPlacement = async () => {
    if (!draftPlacement) return;

    const assignments: CommitDraftAssignment[] = draftPlacement.rosters
      .filter((roster) => roster.learners.length > 0)
      .map((roster) => ({
        sectionId: roster.section.id,
        applicationIds: roster.learners.map((learner) => learner.applicationId),
      }));
    const overrides = draftPlacement.rosters.reduce<Record<number, boolean>>(
      (accumulator, roster) => {
        for (const learner of roster.learners) {
          accumulator[learner.applicationId] = learner.isOverridden;
        }
        return accumulator;
      },
      {},
    );

    setCommitProcessing(true);
    try {
      const response = await api.post<CommitDraftResponse>(
        "/sectioning/commit-draft",
        {
          assignments,
          overrides,
          allowCapacityOverride,
        },
      );
      const skippedCount = response.data.skippedApplications.length;

      sileo.success({
        title: "Final Sectioning Committed",
        description:
          skippedCount > 0
            ? `${response.data.committedCount} learner(s) committed. ${skippedCount} learner(s) need review.`
            : `${response.data.committedCount} learner(s) committed to official class sections.`,
      });

      setCommitDialogOpen(false);
      discardDraft();
      void queryClient.invalidateQueries({
        queryKey: queryKeys.sectioningPool(),
      });
      void queryClient.invalidateQueries({
        queryKey: queryKeys.sectioningSections(),
      });
    } catch (error: unknown) {
      sileo.error({
        title: "Draft Commit Failed",
        description:
          (isAxiosError<ApiMessageResponse>(error)
            ? error.response?.data.message
            : undefined) ?? "Could not commit the draft sectioning placements.",
      });
    } finally {
      setCommitProcessing(false);
    }
  };

  if (masterlistModalSectionId !== null) {
    return (
      <ViewMasterlist
        sectionId={masterlistModalSectionId}
        onBack={() => setMasterlistModalSectionId(null)}
        mode="sectioning"
      />
    );
  }

  if (loading) {
    return <TwoPanelSkeleton />;
  }

  const displayedRosters =
    draftPlacement?.rosters ??
    currentGradeSections.map((section) => buildRoster(section, []));
  const selectedDraftLearner = draftMoveAction
    ? findDraftLearner(draftMoveAction.learnerApplicationId)
    : null;
  const compatibleMoveSections = selectedDraftLearner
    ? (draftPlacement?.rosters.filter(
      (roster) =>
        roster.section.id !== selectedDraftLearner.sectionId &&
        getAllowedSectionProgramsForPlacement(selectedDraftLearner).includes(
          roster.section.programType,
        ),
    ) ?? [])
    : [];
  const normalMoveSourceSection = normalMoveAction
    ? currentGradeSections.find(s => s.id === normalMoveAction.fromSectionId)
    : null;

  const normalMoveDestinationSections = normalMoveAction && normalMoveSourceSection
    ? currentGradeSections.filter((s) => s.id !== normalMoveAction.fromSectionId && s.programType === normalMoveSourceSection.programType)
    : [];
  const compatibleSwapLearners = selectedDraftLearner
    ? (draftPlacement?.rosters.flatMap((roster) =>
      roster.learners.filter(
        (learner) =>
          learner.applicationId !== selectedDraftLearner.applicationId &&
          getAllowedSectionProgramsForPlacement(selectedDraftLearner).includes(
            roster.section.programType,
          ),
      ),
    ) ?? [])
    : [];
  const draftSectionByApplicationId = new Map<number, string>(
    draftPlacement?.rosters.flatMap((roster) =>
      roster.learners.map(
        (learner) => [learner.applicationId, roster.section.name] as const,
      ),
    ) ?? [],
  );

  return (
    <div className="flex flex-col h-[calc(100vh-64px)] w-full overflow-hidden">
      <Tabs
        value={activeGradeLevelId}
        onValueChange={(val) => {
          if (isDraftActive) {
            guardedSetActiveGradeLevelId(val);
            return;
          }

          if (selectedAppIds.length === 0) {
            setActiveGradeLevelId(val);
          }
        }}
      >
        <TabsList className="w-full flex flex-wrap sm:flex-nowrap h-auto gap-1 mb-4 p-1 bg-muted border border-border rounded-xl relative shadow-sm">
          {gradeLevels.map((g) => (
            <TabsTrigger
              key={g.id}
              value={String(g.id)}
              disabled={
                selectedAppIds.length > 0 &&
                !isDraftActive &&
                activeGradeLevelId !== String(g.id)
              }
              className={cn(
                "flex-1 min-w-25 font-bold transition-all relative z-10 data-[state=active]:bg-transparent data-[state=active]:shadow-none rounded-md",
                selectedAppIds.length > 0 &&
                !isDraftActive &&
                activeGradeLevelId !== String(g.id) &&
                "opacity-40 cursor-not-allowed bg-muted/20",
              )}>
              {activeGradeLevelId === String(g.id) && (
                <motion.div
                  layoutId="enrollment-grade-pill"
                  className="absolute inset-0 bg-primary shadow-sm rounded-md"
                  transition={{ type: "spring", bounce: 0.15, duration: 0.5 }}
                />
              )}
              <span
                className={cn(
                  "relative z-20 text-base uppercase",
                  activeGradeLevelId === String(g.id)
                    ? "text-primary-foreground"
                    : "text-foreground",
                )}>
                {g.name.replace(/grade\s*/i, "Grade ")}
              </span>
            </TabsTrigger>
          ))}
        </TabsList>
      </Tabs>

      <AnimatePresence>
        {draftPlacement && (
          <motion.div
            initial={{ opacity: 0, y: -20, height: 0, marginBottom: 0 }}
            animate={{ opacity: 1, y: 0, height: "auto", marginBottom: "1rem" }}
            exit={{ opacity: 0, y: -20, height: 0, marginBottom: 0 }}
            transition={{ duration: 0.3, ease: "easeInOut" }}
            className="bg-white rounded-md shadow-sm"
          >
            <div className="overflow-hidden rounded-md border-2 border-primary bg-primary/5 px-4 py-3 text-primary">
              <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                <div>
                  <p className="text-base font-bold uppercase">
                    TEMPORARY SECTIONS PENDING REVIEW
                  </p>
                  <p className="text-sm text-primary">
                    {draftLearnerCount} learner(s) are currently assigned across{" "}
                    {
                      draftPlacement.rosters.filter(
                        (roster) => roster.learners.length > 0,
                      ).length
                    }{" "}
                    section(s) pending final approval
                  </p>
                </div>
                <Badge className="w-fit bg-primary text-primary-foreground hover:bg-primary/90">
                  Reviewing Temporary List
                </Badge>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ΓöÇΓöÇ Workspace ΓöÇΓöÇ */}
      <PageTransition key={activeGradeLevelId} className="flex-1 flex flex-col min-h-0 w-full overflow-hidden">
        <Card className="flex flex-col flex-1 min-h-0 h-full shadow-sm border-none bg-card overflow-hidden">
          <div className="flex flex-1 min-h-0 w-full overflow-hidden">
            {/* LEFT PANE: UNSECTIONED POOL */}
            <div className="flex-1 flex flex-col h-full overflow-y-auto border-r border-border bg-card text-card-foreground">
              <CardHeader className="border-b border-border bg-muted/20">
                <div className="flex items-center justify-between">
                  <div className="space-y-1">
                    <CardTitle className="text-lg font-bold uppercase tracking-wide flex items-center gap-2 text-foreground">
                      <Users className="h-5 w-5 text-primary" />
                      LEARNERS READY FOR SECTIONING
                    </CardTitle>
                    <CardDescription className="text-sm text-foreground">
                      Enrolled learners ready to be sectioned
                    </CardDescription>
                  </div>
                  {selectedAppIds.length > 0 && (
                    <Badge
                      variant="outline"
                      className="font-bold bg-background border-border">
                      {selectedAppIds.length} Selected
                    </Badge>
                  )}
                </div>
                <div className="flex gap-2 mt-4">
                  <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-foreground" />
                    <Input
                      placeholder="SEARCH LRN, FIRST NAME, LAST NAME..."
                      className="pl-9 h-10 border-border focus:ring-primary/20 bg-background font-bold uppercase"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                    />
                  </div>
                  <Select
                    isFilter
                    value={filterProgram}
                    onValueChange={setFilterProgram}>
                    <SelectTrigger className="w-full sm:w-48 h-10 border-border bg-background leading-tight font-bold transition-colors">
                      <SelectValue placeholder="All Programs">
                        {filterProgram === "SCIENCE_TECHNOLOGY_AND_ENGINEERING" ? "STE"
                          : filterProgram === "SPECIAL_PROGRAM_IN_THE_ARTS" ? "SPA"
                            : filterProgram === "SPECIAL_PROGRAM_IN_SPORTS" ? "SPS"
                              : filterProgram === "REGULAR" ? "BEC"
                                : "All Programs"}
                      </SelectValue>
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all" className="leading-tight font-bold">All Programs</SelectItem>
                      <SelectItem value="REGULAR" className="leading-tight font-bold">Basic Education Curriculum</SelectItem>
                      <SelectItem value="SCIENCE_TECHNOLOGY_AND_ENGINEERING" className="leading-tight font-bold">SCIENCE, TECHNOLOGY, AND ENGINEERING</SelectItem>
                      <SelectItem value="SPECIAL_PROGRAM_IN_THE_ARTS" className="leading-tight font-bold">Special Program in the Arts</SelectItem>
                      <SelectItem value="SPECIAL_PROGRAM_IN_SPORTS" className="leading-tight font-bold">Special Program in Sports</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </CardHeader>
              <div className="p-0 relative flex-1">
                <table className="w-full text-left border-collapse">
                  <thead className="sticky top-0 bg-muted z-10 border-b border-border">
                    <tr className="uppercase">
                      <th className="p-4 w-10">
                        <Checkbox
                          className="border-primary/50 data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground"
                          checked={
                            selectedAppIds.length === filteredPool.length &&
                            filteredPool.length > 0
                          }
                          disabled={
                            isDraftActive ||
                            (selectedProgramTypes.size === 0 &&
                              new Set(filteredPool.map((l) => l.programType)).size > 1)
                          }
                          onCheckedChange={(checked) => {
                            if (isDraftActive) return;
                            if (checked) {
                              const targetProgram =
                                selectedProgramTypes.size > 0
                                  ? Array.from(selectedProgramTypes)[0]
                                  : null;
                              setSelectedAppIds(
                                filteredPool
                                  .filter(
                                    (l) =>
                                      !targetProgram ||
                                      l.programType === targetProgram
                                  )
                                  .map((l) => l.applicationId)
                              );
                            } else setSelectedAppIds([]);
                          }}
                        />
                      </th>
                      <th className="p-4 font-bold">Learner Detail</th>
                      <th
                        className="p-4 cursor-pointer  select-none font-bold"
                        onClick={() => handleSort("genAve")}>
                        <div className="flex items-center gap-1 justify-center">
                          Final Gen Ave
                          {sortConfig?.key === "genAve" &&
                            (sortConfig.direction === "asc" ? (
                              <ChevronUp className="h-3 w-3 text-primary" />
                            ) : (
                              <ChevronDown className="h-3 w-3 text-primary" />
                            ))}
                        </div>
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border text-base leading-tight bg-card text-center">
                    {filteredAndSortedPool.length === 0 ? (
                      <tr>
                        <td colSpan={3} className="h-[400px] text-center text-muted-foreground ">
                          <div className="flex flex-col items-center justify-center h-full space-y-3">
                            {activeSearchQuery || filterProgram !== "all" ? (
                              <>
                                <Search className="h-8 w-8" />
                                <p className="text-foreground font-bold">No unsectioned learners match this search</p>
                              </>
                            ) : (
                              <>
                                <CheckCircle2 className="h-8 w-8 text-primary" />
                                <p className="text-foreground font-bold">All enrolled learners are sectioned</p>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    ) : (
                      (() => {
                        const scpLearners = filteredAndSortedPool.filter(l => l.programType !== "REGULAR").sort((a, b) => {
                          const order = { SCIENCE_TECHNOLOGY_AND_ENGINEERING: 1, SPECIAL_PROGRAM_IN_THE_ARTS: 2, SPECIAL_PROGRAM_IN_SPORTS: 3 };
                          const orderA = order[a.programType as keyof typeof order] || 4;
                          const orderB = order[b.programType as keyof typeof order] || 4;
                          return orderA - orderB;
                        });
                        const becLearners = filteredAndSortedPool.filter(l => l.programType === "REGULAR");

                        const groups = [
                          { title: "Special Curricular Programs (SCP)", learners: scpLearners },
                          { title: "Basic Education Curriculum (BEC)", learners: becLearners }
                        ].filter(g => g.learners.length > 0);

                        return groups.flatMap((group) => {
                          const headerRow = (
                            <tr key={`header-${group.title}`} className="bg-muted/50 border-y border-border">
                              <td colSpan={3} className="py-2.5 px-4 text-center font-bold text-foreground uppercase tracking-wider">
                                {group.title}
                              </td>
                            </tr>
                          );

                          const learnerRows = group.learners.map((l) => {
                            const isSelected = selectedAppIds.includes(
                              l.applicationId,
                            );
                            const isDisabled =
                              isDraftActive ||
                              (selectedProgramTypes.size > 0 &&
                                !selectedProgramTypes.has(l.programType));

                            return (
                              <tr
                                key={l.applicationId}
                                onClick={() => {
                                  if (isDisabled) return;
                                  setSelectedAppIds((prev) =>
                                    prev.includes(l.applicationId)
                                      ? prev.filter((id) => id !== l.applicationId)
                                      : [...prev, l.applicationId],
                                  );
                                }}
                                className={cn(
                                  "group transition-colors",
                                  isDisabled
                                    ? "opacity-50 cursor-not-allowed"
                                    : "cursor-pointer",
                                  isSelected && "bg-primary/5 hover:bg-primary/10",
                                )}>
                                <td
                                  className="p-4"
                                  onClick={(e) => e.stopPropagation()}>
                                  <Checkbox
                                    checked={isSelected}
                                    disabled={isDisabled}
                                    onCheckedChange={(checked) => {
                                      if (isDisabled) return;
                                      setSelectedAppIds((prev) =>
                                        checked
                                          ? [...prev, l.applicationId]
                                          : prev.filter(
                                            (id) => id !== l.applicationId,
                                          ),
                                      );
                                    }}
                                  />
                                </td>
                                <td className="p-4">
                                  <div className="flex items-center gap-4">
                                    <UserPhoto
                                      photo={l.studentPhoto}
                                      containerClassName="w-12 h-12 rounded-full shadow-sm border shrink-0 border-2 border-primary"
                                      className="w-full h-full object-cover"
                                      alt={`${l.firstName} ${l.lastName}`}
                                    />
                                    <div className="flex flex-col">
                                      <span className="font-bold text-foreground uppercase flex items-center gap-2">
                                        {l.lastName}, {l.firstName}{" "}
                                        {l.middleName?.charAt(0)
                                          ? `${l.middleName.charAt(0)}.`
                                          : ""}
                                        {l.duplicateFlag && (
                                          <Badge
                                            variant="destructive"
                                            className="text-sm px-1 py-0 h-4">
                                            DUPLICATE DETECTED - RESOLVE OVER COUNTER
                                          </Badge>
                                        )}
                                      </span>
                                      <div className="flex items-center gap-2 mt-1">
                                        <span className="text-sm font-bold uppercase text-foreground">
                                          {l.lrn || "NO LRN"}
                                        </span>
                                        <Badge
                                          className={cn(
                                            "text-sm uppercase font-bold",
                                            l.sex === "MALE" ? "bg-blue-600/10 text-blue-600 border-blue-600 border-2" : "bg-pink-600/10 text-pink-600 border-pink-600 border-2"
                                          )}>
                                          {l.sex}
                                        </Badge>
                                        <Badge
                                          variant="outline"
                                          className={cn(
                                            "text-sm uppercase font-bold",
                                            l.programType === "LATE_ENROLLEE" && "bg-amber-100 text-amber-700 border-amber-500 border-2"
                                          )}>
                                          {SCP_SHORT_LABELS[l.programType] ??
                                            l.programType}
                                        </Badge>
                                      </div>
                                      {draftPlacement &&
                                        draftSectionByApplicationId.has(
                                          l.applicationId,
                                        ) && (
                                          <span className="text-sm mt-2 font-bold uppercase text-primary text-left">
                                            Section:{" "}
                                            {draftSectionByApplicationId.get(
                                              l.applicationId,
                                            )}{" "}
                                            (Draft)
                                          </span>
                                        )}
                                    </div>
                                  </div>
                                </td>
                                <td className="p-4 font-bold text-foreground">
                                  {l.genAve ? (
                                    l.genAve.toFixed(2)
                                  ) : (
                                    <span className="text-foreground">--</span>
                                  )}
                                </td>
                              </tr>
                            );
                          });

                          return [headerRow, ...learnerRows];
                        });
                      })()
                    )}
                  </tbody>
                </table>
              </div>
            </div>

            {/* RIGHT PANE: AVAILABLE SECTIONS */}
            <div className="flex-1 flex flex-col h-full overflow-hidden bg-card text-card-foreground">
              <CardHeader className="border-b border-border bg-muted/20">
                <div className="flex items-center justify-between">
                  <div className="space-y-1">
                    <CardTitle className="text-lg font-bold uppercase tracking-wide flex items-center gap-2 text-foreground">
                      <LayoutGrid className="h-5 w-5 text-primary" />
                      {draftPlacement
                        ? "TEMPORARY CLASS LISTS"
                        : "Available Sections"}
                    </CardTitle>
                    <CardDescription className="text-foreground text-sm">
                      {draftPlacement
                        ? "Please review the temporary assignments before creating the official lists"
                        : `Select section to assign ${selectedAppIds.length || "0"} ${selectedAppIds.length <= 1 ? "learner" : "learners"}.`}
                    </CardDescription>
                  </div>
                </div>

                {!draftPlacement && (
                  <Button
                    size="sm"
                    variant="default"
                    disabled={
                      currentGradePool.length === 0 ||
                      processing ||
                      isDraftActive ||
                      isHistoricalReadOnly
                    }
                    onClick={() => setAutoAssignConfirmOpen(true)}
                    className="font-bold text-base uppercase tracking-normal gap-1 rounded-md">
                    AUTO ASSIGN SECTIONS
                  </Button>
                )}
              </CardHeader>
              <div className="p-4 space-y-3 relative flex-1 overflow-y-auto">
                {displayedRosters.length === 0 ? (
                  <div className="h-full flex items-center justify-center flex-col gap-3 text-foreground">
                    <Info className="h-8 w-8" />
                    <span className="font-bold text-base leading-tight">
                      No sections defined for this grade.
                    </span>
                  </div>
                ) : (
                  [
                    {
                      title: "Special Curricular Programs (SCP)",
                      rosters: displayedRosters
                        .filter((r) => r.section.programType !== "REGULAR")
                        .filter(
                          (r) =>
                            draftPlacement ||
                            selectedProgramTypes.size === 0 ||
                            selectedProgramTypes.has(r.section.programType)
                        )
                        .sort(
                          (a, b) =>
                            a.section.programType.localeCompare(
                              b.section.programType,
                            ) || a.section.name.localeCompare(b.section.name),
                        ),
                    },
                    {
                      title: "Basic Education Curriculum (BEC)",
                      rosters: displayedRosters
                        .filter((r) => r.section.programType === "REGULAR")
                        .filter(
                          (r) =>
                            draftPlacement ||
                            selectedProgramTypes.size === 0 ||
                            selectedProgramTypes.has(r.section.programType)
                        )
                        .sort((a, b) => {
                          if (selectedProgramTypes.has("REGULAR") || selectedProgramTypes.size === 0) {
                            if (a.section.isHomogeneous && !b.section.isHomogeneous) return -1;
                            if (!a.section.isHomogeneous && b.section.isHomogeneous) return 1;
                          }
                          return a.section.name.localeCompare(b.section.name);
                        }),
                    },
                  ]
                    .filter((group) => group.rosters.length > 0)
                    .map((group, groupIdx) => (
                      <div
                        key={group.title}
                        className={cn("space-y-3", groupIdx > 0 && "mt-6")}>
                        <h3 className="text-center font-bold text-foreground uppercase tracking-wider">
                          {group.title}
                        </h3>
                        {group.rosters.map((roster) => {
                          const s = roster.section;
                          const isOverCapacity =
                            roster.isOverCapacity || roster.totalCount >= s.maxCapacity;
                          const isSelected =
                            !draftPlacement && targetSectionId === s.id;
                          const isExpanded = expandedSectionIds.has(s.id);
                          const isProgramCompatible =
                            draftPlacement ||
                            selectedProgramTypes.size === 0 ||
                            (selectedProgramTypes.size === 1 &&
                              selectedProgramTypes.has(s.programType));

                          return (
                            <div
                              key={s.id}
                              onClick={() => {
                                if (draftPlacement) {
                                  toggleExpandedSection(s.id);
                                  return;
                                }

                                if (selectedAppIds.length > 0) {
                                  if (isProgramCompatible) {
                                    setTargetSectionId(s.id);
                                  }
                                } else {
                                  if (s.currentCount > 0) {
                                    setMasterlistModalSectionId(s.id);
                                  } else if (isProgramCompatible) {
                                    setTargetSectionId(s.id);
                                  }
                                }
                              }}
                              className={cn(
                                "group cursor-pointer rounded-xl border p-4 transition-all relative overflow-hidden",
                                !isProgramCompatible && "cursor-not-allowed opacity-45",
                                isSelected
                                  ? "bg-primary/5 border-primary shadow-sm"
                                  : "bg-background hover:bg-muted/50 border-border",
                                draftPlacement &&
                                isExpanded &&
                                "border-primary/50 bg-primary/5",
                              )}>
                              <div className="flex items-start justify-between gap-3 mb-3">
                                <div>
                                  <h4
                                    className={cn(
                                      "font-extrabold text-xl uppercase transition-colors flex items-center gap-2",
                                      isSelected ? "text-primary" : "text-foreground",
                                    )}>
                                    {s.name}
                                  </h4>
                                  <span className="text-sm uppercase text-foreground font-bold">
                                    Adviser: {s.adviser || "No Adviser Assigned"}
                                  </span>
                                </div>
                                <div className="flex flex-wrap justify-end gap-2">
                                  {draftPlacement && roster.isOverCapacity && (
                                    <Badge
                                      variant="destructive"
                                      className="text-sm font-bold uppercase">
                                      Over Capacity
                                    </Badge>
                                  )}
                                  {s.programType === "REGULAR" ? (
                                    <Badge
                                      variant="outline"
                                      className={cn(
                                        "text-sm font-bold uppercase bg-background",
                                        s.isHomogeneous
                                          ? "text-amber-600 border-amber-600/30"
                                          : "text-foreground border-border"
                                      )}>
                                      {s.isHomogeneous ? "TOP BEC" : "BEC"}
                                    </Badge>
                                  ) : (
                                    <TooltipProvider>
                                      <Tooltip>
                                        <TooltipTrigger asChild>
                                          <span className="cursor-help inline-block">
                                            <Badge
                                              variant="outline"
                                              className="text-sm font-bold uppercase bg-background text-primary border-primary/30">
                                              {SCP_SHORT_LABELS[s.programType] ?? s.programType}
                                            </Badge>
                                          </span>
                                        </TooltipTrigger>
                                        <TooltipContent className="bg-primary text-primary-foreground border-primary">
                                          <p className="text-sm font-bold">{SCP_LABELS[s.programType] || s.programType}</p>
                                        </TooltipContent>
                                      </Tooltip>
                                    </TooltipProvider>
                                  )}
                                </div>
                              </div>
                              <div className="space-y-2">
                                <div className="flex items-center justify-between text-sm font-bold">
                                  <span className="text-foreground uppercase">
                                    Capacity Fill
                                  </span>
                                  <span
                                    className={cn(
                                      isOverCapacity
                                        ? "text-destructive font-bold"
                                        : "text-foreground",
                                    )}>
                                    {roster.totalCount} / {s.maxCapacity}{" "}
                                    {isOverCapacity && (
                                      <AlertTriangle className="inline h-3 w-3 ml-1" />
                                    )}
                                  </span>
                                </div>
                                <div className="flex items-center gap-2 text-sm font-bold uppercase text-foreground">
                                  <Badge className="bg-blue-600/10 text-blue-600 border-blue-600 border-2">
                                    Male: {roster.genderCounts.boys}
                                  </Badge>
                                  <Badge className="bg-pink-600/10 text-pink-600 border-pink-600 border-2">
                                    Female: {roster.genderCounts.girls}
                                  </Badge>
                                  {draftPlacement && (
                                    <Badge variant="secondary">
                                      Draft: {roster.learners.length}
                                    </Badge>
                                  )}
                                </div>
                                <div className="h-2 rounded-full bg-card overflow-hidden">
                                  <div
                                    className={cn(
                                      "h-full rounded-full transition-all",
                                      roster.isOverCapacity
                                        ? "bg-destructive"
                                        : isSelected
                                          ? "bg-primary"
                                          : "bg-primary",
                                    )}
                                    style={{
                                      width: `${Math.min((roster.totalCount / s.maxCapacity) * 100, 100)}%`,
                                    }}
                                  />
                                </div>
                              </div>

                              {draftPlacement && isExpanded && (
                                <div
                                  className="mt-4 overflow-hidden rounded-md border bg-card"
                                  onClick={(event) => event.stopPropagation()}>
                                  <table className="w-full text-left text-sm">
                                    <thead className="bg-muted text-foreground">
                                      <tr className="uppercase">
                                        <th className="p-3 font-bold">Learner</th>
                                        <th className="p-3 text-center font-bold">Sex</th>
                                        <th className="p-3 text-center font-bold">Gen Ave</th>
                                        <th className="p-3 text-right font-bold">Action</th>
                                      </tr>
                                    </thead>
                                    <tbody className="divide-y">
                                      {roster.learners.length === 0 ? (
                                        <tr>
                                          <td
                                            colSpan={4}
                                            className="p-4 text-center font-bold text-foreground">
                                            No drafted learners in this section.
                                          </td>
                                        </tr>
                                      ) : (
                                        roster.learners.map((learner) => (
                                          <tr key={learner.applicationId}>
                                            <td className="p-3">
                                              <div className="flex flex-col">
                                                <span className="font-bold uppercase text-foreground">
                                                  {formatLearnerName(learner)}
                                                </span>
                                                <span className="font-bold uppercase text-foreground">
                                                  {learner.lrn ?? "NO LRN"}
                                                  {learner.isOverridden && (
                                                    <Badge className="ml-2 bg-amber-600 text-white hover:bg-amber-600">
                                                      Manual Override
                                                    </Badge>
                                                  )}
                                                </span>
                                              </div>
                                            </td>
                                            <td className="p-3 font-bold text-center">
                                              <Badge
                                                className={cn(
                                                  "uppercase",
                                                  learner.sex === "MALE"
                                                    ? "bg-blue-600/10 text-blue-600 border-blue-600 border-2"
                                                    : "bg-pink-600/10 text-pink-600 border-pink-600 border-2"
                                                )}>
                                                {learner.sex}
                                              </Badge>
                                            </td>
                                            <td className="p-3 font-bold text-center">
                                              {learner.genAve?.toFixed(2) ?? "--"}
                                            </td>
                                            <td className="p-3 text-center">
                                              <DropdownMenu>
                                                <DropdownMenuTrigger asChild>
                                                  <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-8 w-8">
                                                    <MoreHorizontal className="h-4 w-4" />
                                                  </Button>
                                                </DropdownMenuTrigger>
                                                <DropdownMenuContent align="end">
                                                  <DropdownMenuItem
                                                    onClick={() =>
                                                      openMoveDialog(
                                                        learner.applicationId,
                                                        s.id,
                                                      )
                                                    }>
                                                    <MoveRight className="mr-2 h-4 w-4" />
                                                    Move to Section
                                                  </DropdownMenuItem>
                                                  <DropdownMenuItem
                                                    onClick={() =>
                                                      openSwapDialog(
                                                        learner.applicationId,
                                                        s.id,
                                                      )
                                                    }>
                                                    <ArrowRightLeft className="mr-2 h-4 w-4" />
                                                    Swap Placement
                                                  </DropdownMenuItem>
                                                </DropdownMenuContent>
                                              </DropdownMenu>
                                            </td>
                                          </tr>
                                        ))
                                      )}
                                    </tbody>
                                  </table>
                                </div>
                              )}

                              {!draftPlacement && s.currentCount > 0 && (
                                <InlineSectionTable
                                  sectionId={s.id}
                                  onMoveLearner={!isHistoricalReadOnly ? openNormalMoveDialog : undefined}
                                />
                              )}
                            </div>
                          );
                        })
                        }
                      </div>
                    )))}
              </div>
              <AnimatePresence>
                {(draftPlacement || selectedAppIds.length > 0) && (
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: 20 }}
                    transition={{ duration: 0.2, ease: "easeOut" }}
                    className="p-4 border-t border-border bg-muted/20 w-full shrink-0">
                    {draftPlacement ? (
                      <div className="grid gap-4 sm:grid-cols-2">
                        <Button
                          variant="outline"
                          onClick={discardDraft}
                          disabled={commitProcessing}
                          className="h-12 text-base font-bold uppercase">
                          CANCEL TEMPORARY SECTIONS
                        </Button>
                        <Button
                          onClick={() => setCommitDialogOpen(true)}
                          disabled={
                            commitProcessing ||
                            draftLearnerCount === 0 ||
                            isHistoricalReadOnly
                          }
                          className="h-12 text-base font-bold uppercase">
                          FINALIZE OFFICIAL SECTIONS
                        </Button>
                      </div>
                    ) : (
                      <Button
                        onClick={assignLearners}
                        disabled={
                          selectedAppIds.length === 0 ||
                          !targetSectionId ||
                          processing ||
                          isHistoricalReadOnly
                        }
                        className={cn(
                          "w-full h-12 text-base leading-tight font-bold uppercase transition-all shadow-none",
                          selectedAppIds.length > 0 && targetSectionId
                            ? "bg-primary hover:bg-primary/90 text-primary-foreground"
                            : "bg-muted text-foreground hover:bg-muted",
                        )}>
                        {processing ? (
                          <>
                            <Loader2 className="mr-2 h-4 w-4 " />
                            Assigning...
                          </>
                        ) : (
                          `Assign to Section ${targetSectionId ? (sections.find(s => s.id === targetSectionId)?.name ?? '') : ''} (${selectedAppIds.length})`
                        )}
                      </Button>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>
        </Card>
      </PageTransition>

      <Dialog
        open={draftMoveAction?.type === "MOVE"}
        onOpenChange={(open) => !open && setDraftMoveAction(null)}>
        <DialogContent className="w-full max-w-3xl">
          <DialogHeader>
            <DialogTitle>Move to Section</DialogTitle>
            <DialogDescription>
              Move the learner to another compatible section in this draft.
            </DialogDescription>
          </DialogHeader>
          <Select
            value={moveDestinationSectionId}
            onValueChange={setMoveDestinationSectionId}>
            <SelectTrigger className="h-11 font-bold">
              <SelectValue placeholder="Select destination section" />
            </SelectTrigger>
            <SelectContent>
              {compatibleMoveSections.map((roster) => (
                <SelectItem
                  key={roster.section.id}
                  value={String(roster.section.id)}>
                  {roster.section.name} ({roster.totalCount}/
                  {roster.section.maxCapacity})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setDraftMoveAction(null)}>
              Cancel
            </Button>
            <Button
              onClick={executeMove}
              disabled={!moveDestinationSectionId}>
              Move to Section
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={!!normalMoveAction}
        onOpenChange={(open) => !open && setNormalMoveAction(null)}>
        <DialogContent className="w-full max-w-3xl">
          <DialogHeader>
            <DialogTitle>Move Assigned Learner</DialogTitle>
            <DialogDescription>
              Move the learner to another section in the current grade level.
            </DialogDescription>
          </DialogHeader>
          <Select
            value={moveDestinationSectionId}
            onValueChange={setMoveDestinationSectionId}>
            <SelectTrigger className="h-11 font-bold">
              <SelectValue placeholder="Select destination section" />
            </SelectTrigger>
            <SelectContent>
              {normalMoveDestinationSections.map((section) => (
                <SelectItem
                  key={section.id}
                  value={String(section.id)}>
                  {section.name} ({section.currentCount}/
                  {section.maxCapacity})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setNormalMoveAction(null)}
              disabled={processing}>
              Cancel
            </Button>
            <Button
              onClick={executeNormalMove}
              disabled={!moveDestinationSectionId || processing}>
              {processing ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Moving...
                </>
              ) : (
                "Move to Section"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={draftMoveAction?.type === "SWAP"}
        onOpenChange={(open) => !open && setDraftMoveAction(null)}>
        <DialogContent className="w-full max-w-3xl">
          <DialogHeader>
            <DialogTitle>Swap Placement</DialogTitle>
            <DialogDescription>
              Exchange this learner with another compatible learner in the
              draft.
            </DialogDescription>
          </DialogHeader>
          <Select
            value={swapApplicationId}
            onValueChange={setSwapApplicationId}>
            <SelectTrigger className="h-11 font-bold">
              <SelectValue placeholder="Select learner to swap" />
            </SelectTrigger>
            <SelectContent>
              {compatibleSwapLearners.map((learner) => (
                <SelectItem
                  key={learner.applicationId}
                  value={String(learner.applicationId)}>
                  {formatLearnerName(learner)} -{" "}
                  {learner.genAve?.toFixed(2) ?? "No Gen Ave"}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setDraftMoveAction(null)}>
              Cancel
            </Button>
            <Button
              onClick={executeSwap}
              disabled={!swapApplicationId}>
              Swap Placement
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <ConfirmationModal
        open={autoAssignConfirmOpen}
        onOpenChange={setAutoAssignConfirmOpen}
        title="AUTO ASSIGN TEMPORARY SECTIONS"
        description={
          <div className="space-y-4 text-left">
            <p className="text-center">
              This will create temporary class lists for the selected grade
              level. No official SF1 record will be saved yet.
            </p>
            <div className="space-y-3 rounded-md border bg-muted p-4">
              <p className="font-bold text-foreground">
                How the system will place learners:
              </p>
              <ul className="list-disc space-y-2 pl-5 text-sm leading-relaxed text-foreground">
                {(() => {
                  const availableScp = Array.from(
                    new Set(currentGradeSections.filter((s) => s.programType !== "REGULAR").map((s) => s.programType))
                  );

                  return (
                    <>
                      {availableScp.length > 0 ? (
                        <li>
                          Special Curricular Program learners go first to matching SCP
                          sections such as {availableScp.map((p) => SCP_SHORT_LABELS[p] || p).join(", ")}.
                        </li>
                      ) : (
                        <li>
                          Special Curricular Program learners go first to matching SCP
                          sections (none currently available).
                        </li>
                      )}
                      <li>
                        BEC Top learners are placed in BEC Top {homogeneousSectionCount} sections when
                        those sections are available.
                      </li>
                    </>
                  );
                })()}
                <li>
                  Regular BEC learners are placed in regular Basic Education
                  Curriculum sections.
                </li>
                <li>
                  The system balances male and female, uses the learner&apos;s
                  final general average, and checks available section capacity.
                </li>
                <li>
                  After this, you can still review, move, or swap learners
                  before clicking Finalize Official Sections.
                </li>
              </ul>
            </div>
            <p className="rounded-md border-2 border-primary bg-primary/5 p-3 font-bold text-primary">
              Please review the temporary class lists carefully before
              finalizing because finalization creates the official section
              records.
            </p>
          </div>
        }
        onConfirm={() => {
          setAutoAssignConfirmOpen(false);
          generateDraftPlacement();
        }}
        confirmText="Generate Temporary Sections"
        cancelText="Cancel"
        variant="primary"
      />

      <ConfirmationModal
        open={commitDialogOpen}
        onOpenChange={setCommitDialogOpen}
        title="FINALIZE OFFICIAL SECTIONS"
        description={
          <div className="space-y-4">
            <p>
              This action will lock the assignments and update the official school records
            </p>
            <div className="space-y-3 rounded-md border bg-muted p-4 text-left">
              <p className="text-base text-foreground text-center">
                {draftLearnerCount} learner(s) will be officially placed in their respective classes
              </p>
              {hasDraftOverflow && (
                <label className="flex items-start gap-3 rounded-md border border-amber-300 bg-amber-50 p-3 text-amber-950 cursor-pointer">
                  <Checkbox
                    checked={allowCapacityOverride}
                    onCheckedChange={(checked) =>
                      setAllowCapacityOverride(checked === true)
                    }
                    className="mt-1 bg-white"
                  />
                  <span className="text-sm font-bold">
                    Allow capacity override for sections marked over capacity.
                  </span>
                </label>
              )}
            </div>
          </div>
        }
        onConfirm={commitDraftPlacement}
        confirmText="Commit Final Sectioning"
        loading={commitProcessing}
        confirmDisabled={hasDraftOverflow && !allowCapacityOverride}
        variant="primary"
      />
    </div>
  );
}

import { useCallback, useEffect, useState } from "react";
import { useSearchParams } from "react-router";
import { useForm, type Resolver } from "react-hook-form";
import { zodResolver } from "@/shared/lib/zodResolver";
import { useQueryClient, useQuery } from "@tanstack/react-query";
import { queryKeys } from "@/shared/lib/queryKeys";
import { sileo } from "sileo";
import { isAxiosError } from "axios";
import {
  Sheet,
  SheetContent,
  _SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/shared/ui/sheet";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Checkbox } from "@/shared/ui/checkbox";
import { Label } from "@/shared/ui/label";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/shared/ui/form";
import { _Select, _SelectContent, _SelectItem, _SelectTrigger, _SelectValue } from "@/shared/ui/select";
import { HybridDatePicker } from "@/shared/components/HybridDatePicker";
import {
  useUnsavedChanges,
  useUnsavedChangesPrompt,
} from "@/shared/hooks/useUnsavedChanges";

import { Loader2, Plus, Search, User, FileText, Phone, CheckCircle2, AlertCircle, _X, Mars, Venus } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import { useSettingsStore } from "@/store/settings.slice";
import { useResizablePanel } from "@/shared/hooks/useResizablePanel";
import api from "@/shared/api/axiosInstance";
import { directEncodeWalkInSchema, type DirectEncodeWalkInPayload } from "@enrollpro/shared";

interface SchoolYearGradeLevel {
  id: number;
  name: string;
}

interface ActiveSchoolYearGradeLevelsResponse {
  gradeLevels?: SchoolYearGradeLevel[];
}

interface LearnerLookupResponse {
  firstName: string;
  lastName: string;
  middleName?: string | null;
  birthdate?: string | null;
  sex?: "MALE" | "FEMALE";
  previousSchool?: {
    schoolName?: string | null;
    generalAverage?: number | null;
  } | null;
  familyMembers?: Array<{
    firstName: string;
    lastName: string;
    contactNumber?: string | null;
  }>;
}

interface ApiErrorResponse {
  message?: string;
}

function getWalkInErrorMessage(error: unknown, fallback: string): string {
  if (isAxiosError<ApiErrorResponse>(error)) {
    return error.response?.data?.message ?? error.message ?? fallback;
  }

  if (error instanceof Error) {
    return error.message;
  }

  return fallback;
}

export function WalkInEncodePanel() {
  const [searchParams] = useSearchParams();
  const [open, setOpen] = useState(false);
  const [isLookingUp, setIsLookingUp] = useState(false);
  const [noLrn, setNoLrn] = useState(false);
  const queryClient = useQueryClient();
  const { confirmOrRun } = useUnsavedChangesPrompt();
  const { steEnabled, spaEnabled, spsEnabled } = useSettingsStore();
  const { panelPercentage, isDesktopViewport, startResizing } = useResizablePanel();

  const programOptions = [
    { val: "REGULAR", label: "BEC" },
    ...(steEnabled ? [{ val: "SCIENCE_TECHNOLOGY_AND_ENGINEERING", label: "STE" }] : []),
    ...(spaEnabled ? [{ val: "SPECIAL_PROGRAM_IN_THE_ARTS", label: "SPA" }] : []),
    ...(spsEnabled ? [{ val: "SPECIAL_PROGRAM_IN_SPORTS", label: "SPS" }] : []),
  ];

  const { data: activeSchoolYear } = useQuery({
    queryKey: ["schoolYear", "grade-levels"],
    queryFn: async () => {
      const res = await api.get<ActiveSchoolYearGradeLevelsResponse>("/school-years/grade-levels");
      return res.data;
    },
  });

  const form = useForm<DirectEncodeWalkInPayload>({
    resolver: zodResolver(directEncodeWalkInSchema) as Resolver<DirectEncodeWalkInPayload>,
    mode: "onChange",
    defaultValues: {
      learnerType: "NEW_ENROLLEE",
      lrn: "",
      firstName: "",
      lastName: "",
      middleName: "",
      birthdate: "",
      sex: "" as any,
      gradeLevelId: 0,
      assignedProgram: "" as any,
      previousSchoolName: "",
      previousGenAve: undefined,
      guardianName: "",
      guardianContact: "",
      hasSf9: false,
      hasPsa: false,
      originatingSchoolId: "",
      sf9EligibilityStatus: "" as any,
    },
  });
  const { isDirty, isSubmitting, isValid } = form.formState;

  useEffect(() => {
    if (searchParams.get("action") === "walk-in") {
      setOpen(true);
    }
  }, [searchParams]);

  const handleLrnLookup = async (lrn: string) => {
    if (lrn.length !== 12) return;

    setIsLookingUp(true);
    try {
      const res = await api.get<LearnerLookupResponse>(`/learner/lookup?lrn=${lrn}`);
      const data = res.data;

      form.setValue("firstName", data.firstName);
      form.setValue("lastName", data.lastName);
      if (data.middleName) form.setValue("middleName", data.middleName);
      if (data.birthdate) {
        // Handle format YYYY-MM-DD
        const d = new Date(data.birthdate);
        form.setValue("birthdate", d.toISOString().split('T')[0]);
      }
      if (data.sex) form.setValue("sex", data.sex);
      if (data.previousSchool) {
        form.setValue("previousSchoolName", data.previousSchool.schoolName || "");
        if (data.previousSchool.generalAverage) {
          form.setValue("previousGenAve", data.previousSchool.generalAverage);
        }
      }
      if (data.familyMembers && data.familyMembers.length > 0) {
        const primary = data.familyMembers[0];
        form.setValue("guardianName", `${primary.firstName} ${primary.lastName}`.trim());
        if (primary.contactNumber) {
          form.setValue("guardianContact", primary.contactNumber);
        }
      }

      sileo.success({ title: "Learner Found", description: "Profile auto-populated." });
    } catch (err: unknown) {
      if (isAxiosError(err) && err.response?.status === 404) {
        // Just silent for 404, it's a new learner. Or maybe a tiny toast.
        // sileo.info("New Learner", "No existing record found.");
      } else {
        sileo.error({ title: "Lookup Failed", description: "Could not fetch learner data." });
      }
    } finally {
      setIsLookingUp(false);
    }
  };

  const resetPanelState = useCallback(() => {
    form.reset();
    setNoLrn(false);
  }, [form]);

  const closePanel = useCallback(() => {
    resetPanelState();
    setOpen(false);
  }, [resetPanelState]);

  const requestClosePanel = useCallback(() => {
    confirmOrRun(closePanel);
  }, [closePanel, confirmOrRun]);

  useUnsavedChanges({
    id: "walk-in-encode-panel",
    label: "Walk-in learner form",
    isDirty: open && isDirty,
    isSubmitting,
    onDiscard: resetPanelState,
  });

  const onSubmit = async (values: DirectEncodeWalkInPayload) => {
    const payload = {
      ...values,
      firstName: values.firstName?.toUpperCase(),
      lastName: values.lastName?.toUpperCase(),
      middleName: values.middleName?.toUpperCase(),
      previousSchoolName: values.previousSchoolName?.toUpperCase(),
      guardianName: values.guardianName?.toUpperCase(),
    };
    try {
      await api.post("/enrollment/walk-in", payload);
      sileo.success({
        title: "Successfully Encoded",
        description: "Learner routed directly to unassigned sectioning pool.",
      });
      closePanel();
      void queryClient.invalidateQueries({ queryKey: queryKeys.sectioningPool() });
    } catch (err: unknown) {
      sileo.error({
        title: "Encoding Failed",
        description: getWalkInErrorMessage(err, "The learner was not encoded. Please review the form and try again."),
      });
    }
  };

  // The encoder is intentionally non-dismissible through outside clicks or Escape.
  // Closing is handled only through explicit Cancel, close, discard, or successful save.
  const handleOpenChange = (newOpen: boolean) => {
    if (newOpen) {
      setOpen(true);
      return;
    }
    requestClosePanel();
  };

  const hasSf9 = form.watch("hasSf9");
  const hasPsa = form.watch("hasPsa");
  const isCompleteDocs = hasSf9 && hasPsa;

  console.log("dirtyFields:", form.formState.dirtyFields);

  return (
    <Sheet open={open} onOpenChange={handleOpenChange}>
      <SheetTrigger asChild>
        <Button className="h-11 px-6 text-base font-bold gap-2">
          <Plus className="w-5 h-5" />
          Encode Walk-In
        </Button>
      </SheetTrigger>
      <SheetContent
        side="right"
        onPointerDownOutside={(e) => e.preventDefault()}
        onInteractOutside={(e) => e.preventDefault()}
        onEscapeKeyDown={(e) => e.preventDefault()}
        className="p-0 flex flex-col h-full border-l overflow-visible w-full sm:w-auto sm:max-w-none"
        style={
          isDesktopViewport ? { width: `${panelPercentage}vw` } : undefined
        }
      >
        {/* Resize Handle ΓÇö hidden on mobile */}
        <div
          onMouseDown={startResizing}
          className="absolute left-[-4px] top-0 bottom-0 w-[8px] cursor-col-resize z-50 hover:bg-primary/30 transition-colors hidden sm:flex items-center justify-center group">
          <div className="h-8 w-1.5 rounded-full bg-muted-foreground/20 group-hover:bg-primary/50" />
        </div>

        <div className="flex-1 flex flex-col h-full overflow-hidden bg-background">
          {/* ΓöÇΓöÇΓöÇ Header ΓöÇΓöÇΓöÇ */}
          <SheetHeader className="flex flex-row items-center justify-between p-3 sm:p-4 border-b shrink-0 bg-primary font-bold text-left space-y-0 mt-0">
            <div>
              <SheetTitle className="text-base sm:text-lg text-primary-foreground font-bold uppercase flex items-center gap-2">
                Walk-In Learner Enrollment
              </SheetTitle>
            </div>
          </SheetHeader>

          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="flex-1 flex flex-col min-h-0" autoComplete="off">
              <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6 bg-muted/10">

                <div className="space-y-4">
                  {/* LEARNER PROFILE BLOCK */}
                  <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                    <div className="px-5 py-4 font-bold uppercase text-base tracking-wide text-foreground bg-muted/5 border-b border-border">
                      <span className="flex items-center gap-2">
                        <User className="h-4 w-4 text-primary" />
                        Learner Profile
                      </span>
                    </div>
                    <div className="px-5 pt-5 pb-1">
                      <div className="grid grid-cols-3 gap-4 font-bold">
                        <button
                          type="button"
                          onClick={() => form.setValue("learnerType", "NEW_ENROLLEE", { shouldDirty: true })}
                          className={cn(
                            "flex flex-1 items-center justify-center rounded-lg border-2 px-4 py-2 transition-colors text-base leading-tight font-bold uppercase",
                            form.watch('learnerType') === "NEW_ENROLLEE"
                              ? "border-primary bg-primary/5 text-primary"
                              : "border-border hover:bg-muted/50 text-foreground"
                          )}
                        >
                          New Entrant
                        </button>
                        <button
                          type="button"
                          onClick={() => form.setValue("learnerType", "TRANSFEREE", { shouldDirty: true })}
                          className={cn(
                            "flex flex-1 items-center justify-center rounded-lg border-2 px-4 py-2 transition-colors text-base leading-tight font-bold uppercase",
                            form.watch('learnerType') === "TRANSFEREE"
                              ? "border-primary bg-primary/5 text-primary"
                              : "border-border hover:bg-muted/50 text-foreground"
                          )}
                        >
                          Transferee
                        </button>
                        <button
                          type="button"
                          onClick={() => form.setValue("learnerType", "RETURNING", { shouldDirty: true })}
                          className={cn(
                            "flex flex-1 items-center justify-center rounded-lg border-2 px-4 py-2 transition-colors text-base leading-tight font-bold uppercase",
                            form.watch('learnerType') === "RETURNING"
                              ? "border-primary bg-primary/5 text-primary"
                              : "border-border hover:bg-muted/50 text-foreground"
                          )}
                        >
                          Returnee
                        </button>
                      </div>
                    </div>
                    <div className="px-5 pb-5 pt-4">
                      <div className="space-y-4">

                        {form.watch('learnerType') === "TRANSFEREE" ? (
                          <FormField
                            control={form.control}
                            name="lrn"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="flex justify-between font-bold">
                                  <span>Learner Reference Number (LRN) <span className="text-destructive">*</span></span>
                                  {isLookingUp && <Loader2 className="w-4 h-4  text-primary" />}
                                </FormLabel>
                                <FormControl>
                                  <div className="relative">
                                    <Input
                                      placeholder="12-digit Learner Reference Number (LRN)"
                                      disabled={false}
                                      className="uppercase font-bold"
                                      value={field.value ?? ""}
                                      onChange={(e) => {
                                        const val = e.target.value.replace(/\D/g, '').slice(0, 12);
                                        field.onChange(val);
                                        if (val.length === 12) {
                                          handleLrnLookup(val);
                                        }
                                      }}
                                      onBlur={() => {
                                        field.onBlur();
                                        const value = field.value ?? "";
                                        if (value.length === 12) {
                                          handleLrnLookup(value);
                                        }
                                      }}
                                    />
                                    <Search className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-primary" />
                                  </div>
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        ) : (
                          <>
                            <FormField
                              control={form.control}
                              name="lrn"
                              render={({ field }) => (
                                <FormItem>
                                  <FormLabel className="flex justify-between font-bold">
                                    <span>Learner Reference Number (LRN)</span>
                                    {isLookingUp && <Loader2 className="w-4 h-4  text-primary" />}
                                  </FormLabel>
                                  <FormControl>
                                    <div className="relative">
                                      <Input
                                        placeholder="12-digit Learner Reference Number (LRN)"
                                        disabled={noLrn}
                                        className="uppercase font-bold"
                                        value={field.value ?? ""}
                                        onChange={(e) => {
                                          const val = e.target.value.replace(/\D/g, '').slice(0, 12);
                                          field.onChange(val);
                                          if (val.length === 12) {
                                            handleLrnLookup(val);
                                          }
                                        }}
                                        onBlur={() => {
                                          field.onBlur();
                                          const value = field.value ?? "";
                                          if (value.length === 12) {
                                            handleLrnLookup(value);
                                          }
                                        }}
                                      />
                                      <Search className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-primary" />
                                    </div>
                                  </FormControl>
                                  <FormMessage />
                                </FormItem>
                              )}
                            />
                            <div className="flex items-center space-x-2 -mt-2">
                              <Checkbox
                                id="noLrn"
                                checked={noLrn}
                                onCheckedChange={(checked) => {
                                  const isChecked = checked === true;
                                  setNoLrn(isChecked);
                                  if (isChecked) {
                                    form.setValue("lrn", "");
                                    form.clearErrors("lrn");
                                  }
                                }}
                              />
                              <label htmlFor="noLrn" className="text-base  leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 text-foreground font-bold">
                                Learner has no LRN yet
                              </label>
                            </div>
                          </>
                        )}

                        <div className="grid grid-cols-3 gap-4 font-bold">
                          <FormField
                            control={form.control}
                            name="firstName"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="font-bold">First Name <span className="text-destructive">*</span></FormLabel>
                                <FormControl><Input placeholder="e.g. JUAN" className="uppercase font-bold" {...field} value={field.value || ""} /></FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          <FormField
                            control={form.control}
                            name="middleName"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="font-bold">Middle Name</FormLabel>
                                <FormControl><Input placeholder="e.g. PEREZ" className="uppercase font-bold" {...field} value={field.value || ""} /></FormControl>
                              </FormItem>
                            )}
                          />
                          <FormField
                            control={form.control}
                            name="lastName"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="font-bold">Last Name <span className="text-destructive">*</span></FormLabel>
                                <FormControl><Input placeholder="e.g. DELA CRUZ" className="uppercase font-bold" {...field} value={field.value || ""} /></FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                          <FormField
                            control={form.control}
                            name="birthdate"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="font-bold">Birthdate <span className="text-destructive">*</span></FormLabel>
                                <FormControl>
                                  <HybridDatePicker value={field.value} onChange={field.onChange} />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          <FormField
                            control={form.control}
                            name="sex"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="font-bold">Sex <span className="text-destructive">*</span></FormLabel>
                                <div className="flex gap-4">
                                  {(
                                    [
                                      { val: "MALE", icon: Mars, label: "Male" },
                                      { val: "FEMALE", icon: Venus, label: "Female" },
                                    ] as const
                                  ).map((s) => (
                                    <button
                                      key={s.val}
                                      type="button"
                                      onClick={() => field.onChange(s.val)}
                                      className={cn(
                                        "flex flex-1 items-center justify-center gap-2 rounded-lg border-2 px-4 py-2 transition-colors text-base leading-tight font-bold uppercase",
                                        field.value === s.val
                                          ? "border-primary bg-primary/5 text-primary"
                                          : "border-border hover:bg-muted/50 text-foreground"
                                      )}>
                                      <s.icon
                                        className={cn(
                                          "w-4 h-4",
                                          field.value === s.val ? "text-primary" : "text-muted-foreground"
                                        )}
                                      />
                                      {s.label}
                                    </button>
                                  ))}
                                </div>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        </div>

                        <FormField
                          control={form.control}
                          name="gradeLevelId"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="font-bold">Incoming Grade Level <span className="text-destructive">*</span></FormLabel>
                              <div className="grid grid-cols-4 gap-4">
                                {activeSchoolYear?.gradeLevels?.map((gl) => (
                                  <button
                                    key={gl.id}
                                    type="button"
                                    onClick={() => field.onChange(gl.id)}
                                    className={cn(
                                      "flex items-center justify-center rounded-lg border-2 px-4 py-2 transition-colors text-base leading-tight font-bold uppercase",
                                      field.value === gl.id
                                        ? "border-primary bg-primary/5 text-primary"
                                        : "border-border hover:bg-muted/50 text-foreground"
                                    )}>
                                    {gl.name}
                                  </button>
                                ))}
                              </div>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="assignedProgram"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="font-bold">Curriculum Type <span className="text-destructive">*</span></FormLabel>
                              <div className="flex gap-4">
                                {programOptions.map((prog) => (
                                  <button
                                    key={prog.val}
                                    type="button"
                                    onClick={() => field.onChange(prog.val)}
                                    className={cn(
                                      "flex flex-1 items-center justify-center rounded-lg border-2 px-4 py-2 transition-colors text-base leading-tight font-bold uppercase",
                                      field.value === prog.val
                                        ? "border-primary bg-primary/5 text-primary"
                                        : "border-border hover:bg-muted/50 text-foreground"
                                    )}>
                                    {prog.label}
                                  </button>
                                ))}
                              </div>
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>
                  </div>

                  {/* PREVIOUS SCHOOL BLOCK */}
                  <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                    <div className="px-5 py-4 font-bold uppercase text-base tracking-wide text-foreground bg-muted/5 border-b border-border">
                      <span className="flex items-center gap-2">
                        <FileText className="h-4 w-4 text-primary" />
                        Previous School Data
                      </span>
                    </div>
                    <div className="px-5 pb-5 pt-4 space-y-4">
                      <div>
                        <FormField
                          control={form.control}
                          name="previousSchoolName"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="font-bold">
                                {form.watch('learnerType') === "TRANSFEREE" ? "Transferred From (Previous School)" : "School Name"}
                                <span className="text-destructive"> *</span>
                              </FormLabel>
                              <FormControl><Input placeholder="e.g. RIZAL ELEMENTARY SCHOOL" className="uppercase font-bold" {...field} value={field.value || ""} /></FormControl>
                            </FormItem>
                          )}
                        />
                      </div>
                      <div className={form.watch('learnerType') === "TRANSFEREE" ? "grid grid-cols-3 gap-4" : "flex gap-4"}>
                        <div className={form.watch('learnerType') === "TRANSFEREE" ? "" : "flex-1"}>
                          <FormField
                            control={form.control}
                            name="originatingSchoolId"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="font-bold">Originating School ID <span className="text-destructive">*</span></FormLabel>
                                <FormControl>
                                  <Input
                                    placeholder="e.g. 123456"
                                    className="font-bold"
                                    value={field.value ?? ""}
                                    onChange={(e) => {
                                      const val = e.target.value.replace(/\D/g, '').slice(0, 6);
                                      field.onChange(val);
                                    }}
                                    onBlur={field.onBlur}
                                    name={field.name}
                                    ref={field.ref}
                                  />
                                </FormControl>
                              </FormItem>
                            )}
                          />
                        </div>
                        {form.watch('learnerType') === "TRANSFEREE" && (
                          <div>
                            <FormField
                              control={form.control}
                              name="transferCertificateNo"
                              render={({ field }) => (
                                <FormItem>
                                  <FormLabel className="font-bold">Transfer Certificate No.</FormLabel>
                                  <FormControl>
                                    <Input
                                      placeholder="e.g. 98765"
                                      className="font-bold"
                                      {...field}
                                      value={field.value ?? ""}
                                    />
                                  </FormControl>
                                </FormItem>
                              )}
                            />
                          </div>
                        )}
                        <div className={form.watch('learnerType') === "TRANSFEREE" ? "" : "flex-1"}>
                          <FormField
                            control={form.control}
                            name="previousGenAve"
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel className="font-bold">Final Gen Ave</FormLabel>
                                <FormControl>
                                  <Input
                                    className="font-bold"
                                    type="number"
                                    step="0.01"
                                    placeholder="e.g. 85.50"
                                    value={field.value ?? ""}
                                    onChange={(e) => {
                                      field.onChange(
                                        e.target.value === ""
                                          ? undefined
                                          : Number(e.target.value),
                                      );
                                    }}
                                    onBlur={field.onBlur}
                                    name={field.name}
                                    ref={field.ref}
                                  />
                                </FormControl>
                              </FormItem>
                            )}
                          />
                        </div>
                      </div>
                      <div>
                        <FormField
                          control={form.control}
                          name="sf9EligibilityStatus"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="font-bold">SF9 Eligibility Status <span className="text-destructive">*</span></FormLabel>
                              <div className="flex gap-4">
                                {[
                                  { val: "PROMOTED", label: "Promoted" },
                                  { val: "CONDITIONALLY_PROMOTED", label: "Conditionally Promoted" },
                                  { val: "RETAINED", label: "Retained" },
                                ].map((s) => (
                                  <button
                                    key={s.val}
                                    type="button"
                                    onClick={() => field.onChange(s.val)}
                                    className={cn(
                                      "flex flex-1 items-center justify-center rounded-lg border-2 px-4 py-2 transition-colors text-base leading-tight font-bold uppercase",
                                      field.value === s.val
                                        ? "border-primary bg-primary/5 text-primary"
                                        : "border-border hover:bg-muted/50 text-foreground"
                                    )}
                                  >
                                    {s.label}
                                  </button>
                                ))}
                              </div>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>
                  </div>

                  {/* EMERGENCY CONTACT BLOCK */}
                  <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                    <div className="px-5 py-4 font-bold uppercase text-base tracking-wide text-foreground bg-muted/5 border-b border-border">
                      <span className="flex items-center gap-2">
                        <Phone className="h-4 w-4 text-primary" />
                        Emergency Contact
                      </span>
                    </div>
                    <div className="px-5 pb-5 pt-4">
                      <div className="space-y-4">
                        <FormField
                          control={form.control}
                          name="guardianName"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="font-bold">Parent/Guardian Name <span className="text-destructive">*</span></FormLabel>
                              <FormControl><Input placeholder="e.g. MARIA DELA CRUZ" className="uppercase font-bold" {...field} value={field.value || ""} /></FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="guardianContact"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="font-bold">Contact Number <span className="text-destructive">*</span></FormLabel>
                              <FormControl>
                                <Input
                                  className="font-bold"
                                  placeholder="e.g. 09123456789"
                                  {...field}
                                  value={field.value || ""}
                                  onChange={(e) => {
                                    const val = e.target.value.replace(/\D/g, '').slice(0, 11);
                                    field.onChange(val);
                                  }}
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>
                  </div>

                  {/* CHECKLIST */}
                  <div className="bg-amber-50/50 border border-amber-200/60 rounded-xl overflow-hidden shadow-sm">
                    <div className="px-5 py-4 font-bold uppercase text-base tracking-wide text-amber-900 bg-amber-100/50 border-b border-amber-200/50">
                      <span className="flex items-center gap-2">
                        <AlertCircle className="h-4 w-4 text-amber-600" />
                        Document Checklist
                      </span>
                    </div>
                    <div className="px-5 pb-5 pt-4">
                      <p className="text-base font-bold  text-amber-700 mb-4 mt-2">Leave unchecked if missing. Learner will be temporarily enrolled.</p>
                      <div className="space-y-2">

                        <FormField
                          control={form.control}
                          name="hasSf9"
                          render={({ field }) => (
                            <FormItem className="flex flex-row items-center space-x-3 space-y-0 p-2 hover:bg-amber-100 rounded-lg transition-colors">
                              <FormControl>
                                <Checkbox checked={field.value} onCheckedChange={field.onChange} />
                              </FormControl>
                              <Label className="font-bold cursor-pointer">SF9 (Report Card) Submitted</Label>
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="hasPsa"
                          render={({ field }) => (
                            <FormItem className="flex flex-row items-center space-x-3 space-y-0 p-2 hover:bg-amber-100 rounded-lg transition-colors">
                              <FormControl>
                                <Checkbox checked={field.value} onCheckedChange={field.onChange} />
                              </FormControl>
                              <Label className="font-bold cursor-pointer">PSA Birth Certificate Submitted</Label>
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="p-4 bg-white border-t border-border grid grid-cols-2 gap-3 shrink-0">
                <Button
                  variant="outline"
                  type="button"
                  onClick={requestClosePanel}
                  disabled={isSubmitting}
                  className="w-full font-bold uppercase text-base border-border px-6 cursor-pointer bg-background text-foreground hover:bg-muted"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={isSubmitting || !isValid}
                  className={`w-full font-bold uppercase text-base px-6 ${(!isValid || isSubmitting)
                      ? 'bg-muted text-muted-foreground cursor-not-allowed'
                      : isCompleteDocs
                        ? 'bg-primary hover:bg-primary/90 text-primary-foreground cursor-pointer'
                        : 'bg-amber-500 hover:bg-amber-600 text-white cursor-pointer'
                    }`}
                >
                  {isSubmitting ? (
                    <Loader2 className="h-4 w-4  mr-2" />
                  ) : (
                    isCompleteDocs ? <CheckCircle2 className="h-4 w-4 mr-2" /> : <AlertCircle className="h-4 w-4 mr-2" />
                  )}
                  {isCompleteDocs ? "Save & Officially Enroll" : "Save as Temporary"}
                </Button>
              </div>
            </form>
          </Form>
        </div>
      </SheetContent>
    </Sheet>
  );
}

import { motion, AnimatePresence } from "motion/react";
import { useState, useEffect, useCallback, useMemo, useRef } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { PreFlightBlockerModal } from "@/features/enrollment/components/PreFlightBlockerModal";
import { EosyOverrideModal } from "@/features/enrollment/components/EosyOverrideModal";
import { AtomicRolloverDialog } from "@/features/settings/components/AtomicRolloverDialog";
import { EosyUnlockModal } from "@/features/enrollment/components/EosyUnlockModal";
import { getBOSYReadiness } from "@/features/bosy/api/bosy.api";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  SelectGroup,
  SelectLabel,
} from "@/shared/ui/select";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/ui/dialog";
import { Tabs, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import {
  Unlock,
  Loader2,
  AlertTriangle,
  AlertCircle,
  Search,
  MapPin,
  RefreshCw,
  Save,
  ChevronDown,
  FileText,
  MoreHorizontal,
} from "lucide-react";
import api from "@/shared/api/axiosInstance";
import axios from "axios";
import { toastApiError } from "@/shared/hooks/useApiToast";
import { useSettingsStore } from "@/store/settings.slice";
import { useHistoricalReadOnly } from "@/shared/hooks/useHistoricalReadOnly";
import { useHeaderStore } from "@/store/header.slice";
import { useDelayedLoading } from "@/shared/hooks/useDelayedLoading";
