const getInitials = (firstName?: string | null, lastName?: string | null): string => {
  const f = String(firstName || "").trim().charAt(0).toUpperCase();
  const l = String(lastName || "").trim().charAt(0).toUpperCase();
  return `${f}${l}` || "?";
};

