import { useEffect, useState } from "react";
import { useNavigate, Outlet, Link, useLocation } from "react-router";
import {
  LayoutDashboard,
  LogOut,
  Menu,
  X,
  Users,
  Settings,
  Shield,
  Activity,
  Sliders,
  FileSpreadsheet,
  BookOpen,
  ChevronDown,
} from "lucide-react";
