import { useState, useEffect } from "react";
import { BookOpen, Plus, Trash2, RefreshCw, AlertTriangle, Loader2 } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/features/smart/components/ui/card";
import { Button } from "@/features/smart/components/ui/button";
import { Badge } from "@/features/smart/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/features/smart/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/features/smart/components/ui/select";
import { Label } from "@/features/smart/components/ui/label";
import { adminApi } from "@/features/smart/lib/api";
import api from "@/shared/api/axiosInstance";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/features/smart/components/ui/dialog";

function isFieldMatch(subjectName: string, major: string, minor: string) {
  if (!major && !minor) return false;
  const target = subjectName.toLowerCase();
  const m1 = (major || "").toLowerCase();
  const m2 = (minor || "").toLowerCase();

  const mappings: Record<string, string[]> = {
    "math": ["math", "mathematics"],
    "sci": ["science", "biology", "chemistry", "physics"],
    "eng": ["english", "linguistics", "literature"],
    "fil": ["filipino", "wika"],
    "ap": ["social studies", "history", "araling panlipunan"],
    "esp": ["values education", "edukasyon sa pagpapakatao", "esp"],
    "mapeh": ["mapeh", "music", "arts", "physical education", "health"],
    "tle": ["tle", "home economics", "industrial arts", "agri-fishery", "ict", "cookery", "dressmaking", "automotive", "drafting", "computer systems"],
  };

  let keywords = [target];
  for (const [key, aliases] of Object.entries(mappings)) {
    if (target.includes(key)) {
      keywords = aliases;
      break;
    }
  }

  return keywords.some(k => m1.includes(k) || m2.includes(k));
}

const SCHOOL_YEARS = ["2026-2027", "2025-2026"];

export default function ClassAssignments() {
  const [schoolYear, setSchoolYear] = useState("2026-2027");
  const [assignments, setAssignments] = useState<any[]>([]);
  const [workloadSummary, setWorkloadSummary] = useState<Array<{
    teacherId: string;
    teacherName: string;
    sectionId: string;
    sectionName: string;
    gradeLevel: string;
    hgMinutes: number;
    advisoryRoleMinutes: number;
    otherSubjectMinutes: number;
    totalMinutes: number;
  }>>([]);
  const [options, setOptions] = useState<{ teachers: any[]; subjects: any[]; sections: any[] }>({
    teachers: [],
    subjects: [],
    sections: [],
  });
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ teacherId: "", subjectId: "", sectionId: "" });
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  const [selectedTeacherProfile, setSelectedTeacherProfile] = useState<any>(null);
  const [isWarningOpen, setIsWarningOpen] = useState(false);
  const [warningData, setWarningData] = useState<any>(null);

  useEffect(() => {
    if (form.teacherId) {
      api.get(`/teachers/${form.teacherId}`)
        .then(res => setSelectedTeacherProfile(res.data))
        .catch(err => console.error("Failed to fetch teacher profile", err));
    } else {
      setSelectedTeacherProfile(null);
    }
  }, [form.teacherId]);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [assignRes, optRes] = await Promise.all([
        adminApi.getClassAssignments(schoolYear),
        adminApi.getClassAssignmentOptions(schoolYear),
      ]);
      setAssignments(assignRes.data?.assignments ?? []);
      setWorkloadSummary(assignRes.data?.workloadSummary ?? []);
      setOptions(optRes.data);
    } catch (e: any) {
      setError(e.message ?? "Failed to load class assignments");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [schoolYear]);

  const handleCreate = async () => {
    if (!form.teacherId || !form.subjectId || !form.sectionId) {
      setError("Please fill in all fields");
      return;
    }

    const subject = options.subjects.find(s => s.id === form.subjectId);
    const subjectName = subject?.name || subject?.code || "";
    const major = selectedTeacherProfile?.educationalBackground?.majorSpecialization || "";
    const minor = selectedTeacherProfile?.educationalBackground?.minorSpecialization || "";

    if (subjectName && selectedTeacherProfile && !isFieldMatch(subjectName, major, minor)) {
      setWarningData({
        teacherId: form.teacherId,
        subjectId: form.subjectId,
        sectionId: form.sectionId,
        subjectName,
        teacherMajor: major,
        teacherMinor: minor
      });
      setIsWarningOpen(true);
      return;
    }

    await executeCreate();
  };

  const executeCreate = async (isOverride = false) => {
    setCreating(true);
    setError(null);
    try {
      if (isOverride && warningData) {
        await api.post("/audit-logs/atlas-override", warningData);
      }
      await adminApi.createClassAssignment({ ...form, schoolYear });
      setForm({ teacherId: "", subjectId: "", sectionId: "" });
      setShowForm(false);
      setIsWarningOpen(false);
      setSuccess("Assignment created successfully");
      await loadData();
      setTimeout(() => setSuccess(null), 3000);
    } catch (e: any) {
      setError(e.response?.data?.message ?? e.message ?? "Failed to create assignment");
    } finally {
      setCreating(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Delete this class assignment?")) return;
    try {
      await adminApi.deleteClassAssignment(id);
      setSuccess("Assignment deleted");
      await loadData();
      setTimeout(() => setSuccess(null), 3000);
    } catch (e: any) {
      setError(e.response?.data?.message ?? "Failed to delete");
    }
  };

  const gradeLevelLabel = (gl: string) =>
    gl?.replace("GRADE_", "Grade ") ?? gl;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Class Assignments</h1>
          <p className="text-muted-foreground text-sm mt-1">
            Teaching load ΓÇö which teacher handles which subject in which section.
            Synced automatically from Atlas on teacher login.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Select value={schoolYear} onValueChange={setSchoolYear}>
            <SelectTrigger className="w-36">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {SCHOOL_YEARS.map((sy) => (
                <SelectItem key={sy} value={sy}>{sy}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button variant="outline" size="sm" onClick={loadData} disabled={loading}>
            <RefreshCw className={`h-4 w-4 mr-1 ${loading ? "animate-spin" : ""}`} />
            Refresh
          </Button>
          <Button size="sm" onClick={() => { setShowForm(!showForm); setError(null); }}>
            <Plus className="h-4 w-4 mr-1" />
            Add Assignment
          </Button>
        </div>
      </div>

      {/* Info banner about Atlas */}
      <Card className="border-blue-200 bg-blue-50 dark:border-blue-800 dark:bg-blue-950">
        <CardContent className="pt-4 pb-3">
          <div className="flex gap-2 text-sm text-blue-800 dark:text-blue-200">
            <BookOpen className="h-4 w-4 mt-0.5 shrink-0" />
            <span>
              <strong>Automatic sync:</strong> When a teacher logs in, SMART pulls their teaching load from Atlas and
              updates this list in real-time. If Atlas has no schedules configured yet, you can add assignments manually below.
            </span>
          </div>
        </CardContent>
      </Card>

      {/* Success / Error alerts */}
      {success && (
        <div className="rounded-md bg-green-50 border border-green-200 px-4 py-2 text-sm text-green-800 dark:bg-green-950 dark:text-green-200">
          {success}
        </div>
      )}
      {error && (
        <div className="flex items-center gap-2 rounded-md bg-red-50 border border-red-200 px-4 py-2 text-sm text-red-800 dark:bg-red-950 dark:text-red-200">
          <AlertTriangle className="h-4 w-4 shrink-0" />
          {error}
        </div>
      )}

      {/* Create Form */}
      {showForm && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base">New Class Assignment</CardTitle>
            <CardDescription>Manually assign a teacher to a subject and section for {schoolYear}.</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div>
                <Label className="mb-1 block">Teacher</Label>
                <Select value={form.teacherId} onValueChange={(v) => setForm((f) => ({ ...f, teacherId: v }))}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select teacher..." />
                  </SelectTrigger>
                  <SelectContent>
                    {options.teachers.map((t) => (
                      <SelectItem key={t.id} value={t.id}>
                        {t.lastName}, {t.firstName} ({t.employeeId})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="mb-1 block">Subject</Label>
                <Select value={form.subjectId} onValueChange={(v) => setForm((f) => ({ ...f, subjectId: v }))}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select subject..." />
                  </SelectTrigger>
                  <SelectContent>
                    {options.subjects.map((s) => (
                      <SelectItem key={s.id} value={s.id}>
                        {s.code} ΓÇö {s.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="mb-1 block">Section</Label>
                <Select value={form.sectionId} onValueChange={(v) => setForm((f) => ({ ...f, sectionId: v }))}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select section..." />
                  </SelectTrigger>
                  <SelectContent>
                    {options.sections.map((s) => (
                      <SelectItem key={s.id} value={s.id}>
                        {s.name} ({gradeLevelLabel(s.gradeLevel)})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="flex gap-2 mt-4">
              <Button onClick={handleCreate} disabled={creating}>
                {creating && <Loader2 className="h-4 w-4 mr-1 animate-spin" />}
                Save Assignment
              </Button>
              <Button variant="outline" onClick={() => { setShowForm(false); setError(null); }}>
                Cancel
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Assignments Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <BookOpen className="h-4 w-4" />
            Assignments ΓÇö {schoolYear}
            <Badge variant="secondary" className="ml-1">{assignments.length}</Badge>
          </CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-12 text-muted-foreground">
              <Loader2 className="h-5 w-5 animate-spin mr-2" />
              Loading assignments...
            </div>
          ) : assignments.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              <BookOpen className="h-8 w-8 mx-auto mb-2 opacity-40" />
              <p className="">No class assignments yet for {schoolYear}</p>
              <p className="text-sm mt-1">
                Assignments will appear here when teachers log in (Atlas sync) or when you add them manually above.
              </p>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Teacher</TableHead>
                  <TableHead>Subject</TableHead>
                  <TableHead>Section</TableHead>
                  <TableHead>Grade Level</TableHead>
                  <TableHead className="w-16"></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {assignments.map((a) => (
                  <TableRow key={a.id}>
                    <TableCell className="">
                      {a.teacher?.user?.lastName ?? ""}, {a.teacher?.user?.firstName ?? ""}
                      <span className="text-xs text-muted-foreground ml-1">
                        ({a.teacher?.employeeId ?? "ΓÇö"})
                      </span>
                    </TableCell>
                    <TableCell>
                      <span className="font-mono text-xs bg-muted px-1.5 py-0.5 rounded mr-1">
                        {a.subject?.code ?? "ΓÇö"}
                      </span>
                      {a.subject?.name ?? "ΓÇö"}
                    </TableCell>
                    <TableCell>{a.section?.name ?? "ΓÇö"}</TableCell>
                    <TableCell>{gradeLevelLabel(a.section?.gradeLevel ?? "")}</TableCell>
                    <TableCell>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="text-destructive hover:text-destructive"
                        onClick={() => handleDelete(a.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Workload Summary (DepEd Compliance)</CardTitle>
          <CardDescription>
            Line 1: HG minutes, Line 2: Advisory role credit, Line 3: Other subject minutes.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-sm text-muted-foreground">Loading workload summary...</div>
          ) : workloadSummary.length === 0 ? (
            <div className="text-sm text-muted-foreground">No workload summary entries yet for {schoolYear}.</div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Teacher</TableHead>
                  <TableHead>Section</TableHead>
                  <TableHead>Line 1: HG</TableHead>
                  <TableHead>Line 2: Advisory Role</TableHead>
                  <TableHead>Line 3: Other Subjects</TableHead>
                  <TableHead>Total</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {workloadSummary.map((row) => (
                  <TableRow key={`${row.teacherId}-${row.sectionId}`}>
                    <TableCell className="">{row.teacherName}</TableCell>
                    <TableCell>{row.sectionName} ({gradeLevelLabel(row.gradeLevel)})</TableCell>
                    <TableCell>{row.hgMinutes} min</TableCell>
                    <TableCell>{row.advisoryRoleMinutes} min</TableCell>
                    <TableCell>{row.otherSubjectMinutes} min</TableCell>
                    <TableCell className="">{row.totalMinutes} min</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Dialog open={isWarningOpen} onOpenChange={setIsWarningOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center text-red-600">
              <AlertTriangle className="mr-2 h-5 w-5" />
              Out-of-Field Assignment Warning
            </DialogTitle>
            <DialogDescription>
              The selected target subject (<strong>{warningData?.subjectName}</strong>) does not appear to match the recorded academic qualifications for this faculty member.
            </DialogDescription>
          </DialogHeader>
          <div className="text-sm">
            <p><strong>Teacher Major:</strong> {warningData?.teacherMajor || "None"}</p>
            <p><strong>Teacher Minor:</strong> {warningData?.teacherMinor || "None"}</p>
            <p className="mt-4 text-muted-foreground">
              Are you sure you want to proceed with this assignment? This override will be recorded in the system activity ledger.
            </p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsWarningOpen(false)}>
              Cancel
            </Button>
            <Button variant="destructive" onClick={() => executeCreate(true)} disabled={creating}>
              {creating ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : null}
              Acknowledge & Proceed
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

