            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg" style={{ backgroundColor: `${themeColors.primary}20` }}>
                <Shield className="w-5 h-5" style={{ color: themeColors.primary }} />
              </div>
              <div>
                <p className=" text-sm" style={{ color: '#111827' }}>Database Status</p>
                <p className="text-xs text-gray-500">Connected and operational</p>
              </div>
            </div>
            <Button variant="outline" size="sm" className="rounded-xl gap-2">
              <RefreshCw className="w-4 h-4" />
              Test Connection
            </Button>
          </div>
        </CardContent>
      </Card>

    </div>
  );
}

// @ts-nocheck
import React, { useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { Card } from '@/features/smart/components/ui/card';
import { Button } from '@/features/smart/components/ui/button';
import { Input } from '@/features/smart/components/ui/input';
import { Label } from '@/features/smart/components/ui/label';
import { Badge } from '@/features/smart/components/ui/badge';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/features/smart/components/ui/table';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/features/smart/components/ui/dialog';
import { Upload, FileSpreadsheet, Download, Trash2, Power, Info, AlertCircle, CheckCircle2, Eye, Search, RefreshCw, ZoomIn, ZoomOut } from 'lucide-react';
import ExcelRenderer from '@/features/smart/components/ExcelRenderer';

const SERVER_URL = import.meta.env.VITE_SERVER_URL || '';

interface ExcelTemplate {
  id: string;
  formType: string;
  formName: string;
  description: string | null;
  filePath: string;
  fileName: string;
  fileSize: number;
  sheetName: string | null;
  placeholders: string[] | null;
  instructions: string | null;
  isActive: boolean;
  uploadedBy: string;
  uploadedByName: string;
  createdAt: string;
  updatedAt: string;
}

interface TemplatePreviewSheet {
  sheetName: string;
  isMappedSheet: boolean;
  totalRows: number;
  previewRows: string[][];
}

interface TemplatePreviewData {
  templateId: string;
  formType: string;
  formName: string;
  fileName: string;
  mappedSheetName: string | null;
  maxRows: number;
  maxCols: number;
  sheets: TemplatePreviewSheet[];
}

const FORM_TYPES = [
  {
    value: 'SF1_7_BUNDLE',
    label: 'SF1-SF7 Bundle (All-in-One Workbook)',
    description: 'Upload one workbook containing sheets for SF1 to SF7',
    isBundle: true
  },
  {
    value: 'SF1_10_BUNDLE',
    label: 'SF1-SF10 Bundle (All-in-One Workbook)',
    description: 'Upload one workbook containing sheets for SF1 to SF10',
    isBundle: true
  },
  { value: 'SF1', label: 'SF1 - School Register (Student Master List)', description: 'Complete masterlist of all enrolled students' },
  { value: 'SF2', label: 'SF2 - Daily Attendance Record', description: 'Daily attendance tracking with P/A/L/E marks' },
  { value: 'SF3', label: 'SF3 - Individual Learner Monitoring', description: 'Track individual student progress' },
  { value: 'SF4', label: 'SF4 - Quarterly Assessment Report', description: 'Quarter exam results and assessments' },
  { value: 'SF5', label: 'SF5 - Promotion/Completion Report', description: 'End of year advancement report' },
  { value: 'SF6', label: 'SF6 - Learner Information System', description: 'Comprehensive learner data' },
  { value: 'SF7', label: 'SF7 - School Personnel Assignment List', description: 'Personnel assignments and profiles' },
  { value: 'SF8', label: 'SF8 - Learner Basic Health and Nutrition Report', description: 'Learner health and nutritional status reporting form' },
  { value: 'SF9', label: 'SF9 - Progress Report (JHS/SHS)', description: 'Report card for junior and senior high school students' },
  { value: 'SF10', label: 'SF10 - Learner\'s Permanent Record', description: 'Student transcript and permanent record' }
];

export default function TemplateManager() {
  const [templates, setTemplates] = useState<ExcelTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [bulkDeleting, setBulkDeleting] = useState(false);
  const [selectedTemplateIds, setSelectedTemplateIds] = useState<string[]>([]);
  const [uploadDialogOpen, setUploadDialogOpen] = useState(false);
  const [infoDialogOpen, setInfoDialogOpen] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<ExcelTemplate | null>(null);
  const [previewDialogOpen, setPreviewDialogOpen] = useState(false);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewError, setPreviewError] = useState('');
  const [previewData, setPreviewData] = useState<TemplatePreviewData | null>(null);
  const [selectedPreviewSheet, setSelectedPreviewSheet] = useState('');
  const [styledPreviewData, setStyledPreviewData] = useState<any>(null);
  const [previewScale, setPreviewScale] = useState(0.7);
  const [viewMode, setViewMode] = useState<'styled' | 'simple'>('styled');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'ACTIVE' | 'INACTIVE'>('ALL');
  const [formFilter, setFormFilter] = useState('ALL');

  // Upload form state
  const [uploadFormType, setUploadFormType] = useState('');
  const [uploadFormName, setUploadFormName] = useState('');
  const [uploadDescription, setUploadDescription] = useState('');
  const [uploadInstructions, setUploadInstructions] = useState('');
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState('');
  const [uploadSuccess, setUploadSuccess] = useState('');
  const [loadError, setLoadError] = useState('');

  useEffect(() => {
    fetchTemplates();
  }, []);

  const filteredTemplates = useMemo(() => {
    return templates.filter((template) => {
      const matchesSearch =
        !searchQuery.trim() ||
        template.formName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        template.formType.toLowerCase().includes(searchQuery.toLowerCase()) ||
        template.fileName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        template.uploadedByName.toLowerCase().includes(searchQuery.toLowerCase());

      const matchesStatus =
        statusFilter === 'ALL' ||
        (statusFilter === 'ACTIVE' && template.isActive) ||
        (statusFilter === 'INACTIVE' && !template.isActive);

      const matchesForm = formFilter === 'ALL' || template.formType === formFilter;
      return matchesSearch && matchesStatus && matchesForm;
    });
  }, [templates, searchQuery, statusFilter, formFilter]);

  const fetchTemplates = async () => {
    try {
      setLoading(true);
      setLoadError('');
      const token = sessionStorage.getItem('token');
      const response = await axios.get(`${SERVER_URL}/api/templates`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTemplates(response.data.data || []);
    } catch (error: any) {
      console.error('Failed to fetch templates:', error);
      const status = error?.response?.status;
      const message = error?.response?.data?.message || error?.response?.data?.error;
      if (status === 401 || status === 403) {
        setLoadError('Session expired or invalid token. Please log out and log in again, then refresh this page.');
      } else {
        setLoadError(message || 'Failed to load SF templates from server.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleUpload = async () => {
    if (!uploadFormType || !uploadFormName || !uploadFile) {
      setUploadError('Please fill in all required fields and select a file');
      return;
    }

    // Check for existing templates
    const existingTemplates: string[] = [];
    if (uploadFormType === 'SF1_10_BUNDLE' || uploadFormType === 'SF1_7_BUNDLE') {
      const bundleForms = uploadFormType === 'SF1_7_BUNDLE'
        ? ['SF1', 'SF2', 'SF3', 'SF4', 'SF5', 'SF6', 'SF7']
        : ['SF1', 'SF2', 'SF3', 'SF4', 'SF5', 'SF6', 'SF7', 'SF8', 'SF9', 'SF10'];
      bundleForms.forEach(formType => {
        if (templates.some(t => t.formType === formType)) {
          existingTemplates.push(formType);
        }
      });
    } else {
      if (templates.some(t => t.formType === uploadFormType)) {
        existingTemplates.push(uploadFormType);
      }
    }

    if (existingTemplates.length > 0) {
      const confirmed = window.confirm(
        `WARNING: The following form template(s) already exist: ${existingTemplates.join(', ')}\n\n` +
        `Uploading will REPLACE the existing template(s).\n\n` +
        `Do you want to continue and overwrite?`
      );
      if (!confirmed) {
        return;
      }
    }

    try {
      setUploading(true);
      setUploadError('');
      setUploadSuccess('');

      const formData = new FormData();
      formData.append('file', uploadFile);
      formData.append('formName', uploadFormName);

      if (uploadFormType === 'SF1_10_BUNDLE' || uploadFormType === 'SF1_7_BUNDLE') {
        const selectedBundleForms = uploadFormType === 'SF1_7_BUNDLE'
          ? ['SF1', 'SF2', 'SF3', 'SF4', 'SF5', 'SF6', 'SF7']
          : ['SF1', 'SF2', 'SF3', 'SF4', 'SF5', 'SF6', 'SF7', 'SF8', 'SF9', 'SF10'];
        formData.append('uploadMode', 'bundle');
        formData.append('formType', uploadFormType);
        formData.append('formTypes', JSON.stringify(selectedBundleForms));
      } else {
        formData.append('uploadMode', 'single');
        formData.append('formType', uploadFormType);
      }

      if (uploadDescription) formData.append('description', uploadDescription);
      if (uploadInstructions) formData.append('instructions', uploadInstructions);

      const token = sessionStorage.getItem('token');
      const response = await axios.post(`${SERVER_URL}/api/templates/upload`, formData, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });

      setUploadSuccess(response.data.message || 'Template uploaded successfully');

      // Refresh template list
      await fetchTemplates();

      // Reset form
      setTimeout(() => {
        setUploadDialogOpen(false);
        setUploadFormType('');
        setUploadFormName('');
        setUploadDescription('');
        setUploadInstructions('');
        setUploadFile(null);
        setUploadSuccess('');
      }, 2000);

    } catch (error: any) {
      console.error('Upload failed:', error);
      const errorData = error.response?.data;
      let errorMessage = errorData?.error || 'Failed to upload template';

      if (errorData?.missingForms && errorData?.availableSheets) {
        errorMessage += `\n\nCould not map: ${errorData.missingForms.join(', ')}`;
        errorMessage += `\n\nAvailable sheets in file: ${errorData.availableSheets.join(', ')}`;
        errorMessage += '\n\nPlease ensure your workbook sheet names clearly identify each form (e.g., "SF8", "Nutritional Status", "SF9", "front/back" for SF10).';
      }

      setUploadError(errorMessage);
    } finally {
      setUploading(false);
    }
  };

  const handleToggleActive = async (template: ExcelTemplate) => {
    try {
      const token = sessionStorage.getItem('token');
      await axios.post(`${SERVER_URL}/api/templates/${template.id}/toggle`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      await fetchTemplates();
    } catch (error: any) {
      console.error('Failed to toggle template:', error);
      alert(error.response?.data?.error || 'Failed to toggle template');
    }
  };

  const handleDelete = async (template: ExcelTemplate) => {
    if (!confirm(`Are you sure you want to delete the ${template.formName} template?`)) {
      return;
    }

    try {
      const token = sessionStorage.getItem('token');
      await axios.delete(`${SERVER_URL}/api/templates/${template.id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      await fetchTemplates();
    } catch (error: any) {
      console.error('Failed to delete template:', error);
      alert(error.response?.data?.error || 'Failed to delete template');
    }
  };

  const toggleTemplateSelection = (templateId: string) => {
    setSelectedTemplateIds((prev) =>
      prev.includes(templateId) ? prev.filter((id) => id !== templateId) : [...prev, templateId]
    );
  };

  const handleToggleSelectAll = () => {
    const filteredIds = filteredTemplates.map((template) => template.id);
    const allFilteredSelected = filteredIds.length > 0 && filteredIds.every((id) => selectedTemplateIds.includes(id));

    if (allFilteredSelected) {
      setSelectedTemplateIds((prev) => prev.filter((id) => !filteredIds.includes(id)));
      return;
    }

    setSelectedTemplateIds((prev) => Array.from(new Set([...prev, ...filteredIds])));
  };

  const handleDeleteSelected = async () => {
    if (selectedTemplateIds.length === 0) return;

    const confirmed = window.confirm(
      `Delete ${selectedTemplateIds.length} selected template(s)? This action cannot be undone.`
    );
    if (!confirmed) return;

    try {
      setBulkDeleting(true);
      const token = sessionStorage.getItem('token');
      await Promise.all(
        selectedTemplateIds.map((templateId) =>
          axios.delete(`${SERVER_URL}/api/templates/${templateId}`, {
            headers: { Authorization: `Bearer ${token}` }
          })
        )
      );
      setSelectedTemplateIds([]);
      await fetchTemplates();
    } catch (error: any) {
      console.error('Failed to delete selected templates:', error);
      alert(error.response?.data?.error || 'Failed to delete selected templates');
    } finally {
      setBulkDeleting(false);
    }
  };

  const handleDeleteAllTemplates = async () => {
    if (filteredTemplates.length === 0) return;

    const confirmed = window.confirm(
      `Delete ALL ${filteredTemplates.length} template(s) in current view? This action cannot be undone.`
    );
    if (!confirmed) return;

    try {
      setBulkDeleting(true);
      const token = sessionStorage.getItem('token');
      await Promise.all(
        filteredTemplates.map((template) =>
          axios.delete(`${SERVER_URL}/api/templates/${template.id}`, {
            headers: { Authorization: `Bearer ${token}` }
          })
        )
      );
      setSelectedTemplateIds([]);
      await fetchTemplates();
    } catch (error: any) {
      console.error('Failed to delete all templates:', error);
      alert(error.response?.data?.error || 'Failed to delete all templates');
    } finally {
      setBulkDeleting(false);
    }
  };

  const handleDownload = async (template: ExcelTemplate) => {
    try {
      const token = sessionStorage.getItem('token');
      const response = await axios.get(`${SERVER_URL}/api/templates/${template.formType}/download`, {
        headers: { Authorization: `Bearer ${token}` },
        responseType: 'blob'
      });

      // Create clean, descriptive filename
      const cleanFileName = `${template.formType}-${template.formName.replace(/[^a-zA-Z0-9\s-]/g, '').replace(/\s+/g, '_')}.xlsx`;

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', cleanFileName);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (error: any) {
      console.error('Failed to download template:', error);
      alert('Failed to download template');
    }
  };

  const showInfo = (template: ExcelTemplate) => {
    setSelectedTemplate(template);
    setInfoDialogOpen(true);
  };

  const handleViewTemplate = async (template: ExcelTemplate) => {
    try {
      setPreviewLoading(true);
      setPreviewError('');
      setPreviewData(null);
      setStyledPreviewData(null);
      setSelectedPreviewSheet('');
      setPreviewDialogOpen(true);
      setViewMode('styled');
      setPreviewScale(0.7);

      const token = sessionStorage.getItem('token');

      // Load styled preview first (pixel-perfect rendering)
      try {
        const styledResponse = await axios.get(`${SERVER_URL}/api/templates/${template.id}/styled-preview`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setStyledPreviewData(styledResponse.data.data);
        setSelectedPreviewSheet(styledResponse.data.data.parsedStructure.sheets[0]?.name || '');
      } catch (styledError) {
        console.warn('Styled preview not available, falling back to simple view:', styledError);
        setViewMode('simple');
      }

      // Also load simple preview as fallback
      const response = await axios.get(`${SERVER_URL}/api/templates/${template.id}/preview`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      const loadedData = response.data.data as TemplatePreviewData;
      setPreviewData(loadedData);
      if (!styledPreviewData) {
        setSelectedPreviewSheet(loadedData.sheets[0]?.sheetName || '');
      }
    } catch (error: any) {
      console.error('Failed to load template preview:', error);
      setPreviewError(error.response?.data?.error || 'Failed to load template preview');
    } finally {
      setPreviewLoading(false);
    }
  };

  const handleOpenExactWorkbook = async () => {
    if (!previewData) return;

    try {
      const token = sessionStorage.getItem('token');
      const response = await axios.get(`${SERVER_URL}/api/templates/${previewData.formType}/download`, {
        headers: { Authorization: `Bearer ${token}` },
        responseType: 'blob'
      });

      // Create clean, descriptive filename
      const cleanFileName = `${previewData.formType}-${previewData.formName.replace(/[^a-zA-Z0-9\s-]/g, '').replace(/\s+/g, '_')}.xlsx`;

      const blob = new Blob([response.data], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
      });
      const url = window.URL.createObjectURL(blob);

      // Try opening first so systems with Excel web handler can preview directly.
      const opened = window.open(url, '_blank');

      // Always provide a fallback download for exact desktop viewing/printing.
      if (!opened) {
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', cleanFileName);
        document.body.appendChild(link);
        link.click();
        link.remove();
      }

      window.setTimeout(() => window.URL.revokeObjectURL(url), 60000);
    } catch (error: any) {
      console.error('Failed to open exact workbook:', error);
      setPreviewError(error.response?.data?.error || 'Failed to open workbook file');
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const formatDate = (dateString: string): string => {
    return new Date(dateString).toLocaleDateString('en-US', {
      timeZone: 'Asia/Manila',
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="space-y-6 p-6">
      {/* Header Section */}
      <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <h1 className="text-3xl font-bold">Excel Template Manager</h1>
          <p className="text-muted-foreground mt-1">
            Upload, review, and maintain DepEd School Form templates
          </p>
        </div>
      </div>

      {/* Template System Benefits - Moved up */}
      <Card className="p-6 bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-blue-950 dark:to-indigo-950 border-blue-200 dark:border-blue-800">
        <div className="flex items-start gap-3">
          <Info className="w-5 h-5 text-blue-600 dark:text-blue-400 mt-0.5 flex-shrink-0" />
          <div className="space-y-2">
            <h3 className=" text-blue-900 dark:text-blue-100">Why Use Templates?</h3>
            <ul className="text-sm text-blue-800 dark:text-blue-200 space-y-1.5">
              <li>ΓÇó <strong>Automatic Form Filling:</strong> Upload your Excel format once, and the system fills it with student data automatically</li>
              <li>ΓÇó <strong>No Programming Needed:</strong> Change your form layout anytime by uploading a new templateΓÇöno code required</li>
              <li>ΓÇó <strong>Smart Placeholders:</strong> Use markers like <code className="bg-blue-100 dark:bg-blue-900 px-1.5 py-0.5 rounded text-xs">{'{{SCHOOL_NAME}}'}</code> that get replaced with real school information</li>
              <li>ΓÇó <strong>Bulk Student Data:</strong> List all students by wrapping with <code className="bg-blue-100 dark:bg-blue-900 px-1.5 py-0.5 rounded text-xs">{'{{#STUDENTS}}'}</code> and <code className="bg-blue-100 dark:bg-blue-900 px-1.5 py-0.5 rounded text-xs">{'{{/STUDENTS}}'}</code></li>
            </ul>
          </div>
        </div>
      </Card>

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <Card className="p-5 hover:shadow-md transition-shadow">
          <p className="text-xs  text-muted-foreground uppercase tracking-wide">Total Templates</p>
          <p className="text-3xl font-bold mt-2">{templates.length}</p>
        </Card>
        <Card className="p-5 hover:shadow-md transition-shadow">
          <p className="text-xs  text-muted-foreground uppercase tracking-wide">Active</p>
          <p className="text-3xl font-bold text-green-600 mt-2">{templates.filter((t) => t.isActive).length}</p>
        </Card>
        <Card className="p-5 hover:shadow-md transition-shadow">
          <p className="text-xs  text-muted-foreground uppercase tracking-wide">Filtered Results</p>
          <p className="text-3xl font-bold mt-2">{filteredTemplates.length}</p>
        </Card>
      </div>

      {/* Search and Filter Section */}
      <Card className="p-5">
        <div className="space-y-4">
          <div className="flex flex-wrap items-center gap-2">
            <Button
              variant="outline"
              onClick={handleDeleteSelected}
              disabled={bulkDeleting || selectedTemplateIds.length === 0}
              className="h-10 text-red-600 border-red-300 hover:text-red-700"
            >
              Delete Selected ({selectedTemplateIds.length})
            </Button>
            <Button
              variant="outline"
              onClick={handleDeleteAllTemplates}
              disabled={bulkDeleting || filteredTemplates.length === 0}
              className="h-10 text-red-700 border-red-400 hover:text-red-800"
            >
              Delete All (View)
            </Button>
            <Button onClick={() => setUploadDialogOpen(true)} disabled={bulkDeleting} className="h-10">
              <Upload className="w-4 h-4 mr-2" />
              Upload Template
            </Button>
            <Button
              variant="outline"
              onClick={fetchTemplates}
              disabled={loading || bulkDeleting}
              className="h-10"
            >
              <RefreshCw className="w-4 h-4 mr-2" />
              Refresh
            </Button>
          </div>

          <div className="flex flex-col gap-3 lg:flex-row lg:items-center">
            <div className="relative flex-1">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <Input
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search by form, template name, file, or uploader..."
                className="pl-9"
              />
            </div>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as 'ALL' | 'ACTIVE' | 'INACTIVE')}
              className="px-3 py-2 border rounded-md text-sm bg-muted"
            >
              <option value="ALL">All Status</option>
              <option value="ACTIVE">Active</option>
              <option value="INACTIVE">Inactive</option>
            </select>
            <select
              value={formFilter}
              onChange={(e) => setFormFilter(e.target.value)}
              className="px-3 py-2 border rounded-md text-sm bg-muted"
            >
              <option value="ALL">All Forms</option>
              {Array.from(new Set(templates.map((t) => t.formType))).sort().map((formType) => (
                <option key={formType} value={formType}>{formType}</option>
              ))}
            </select>
          </div>
        </div>
        <p className="text-xs text-muted-foreground mt-3">
          <strong>Tip:</strong> Select rows from filtered results, then click "Delete Selected" to remove multiple templates at once.
        </p>
      </Card>

      {/* Templates Table */}
      <Card className="overflow-hidden">
        {loadError && (
          <div className="m-4 flex items-start gap-3 p-3 bg-red-50 border border-red-200 rounded-lg text-red-700">
            <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
            <div className="text-sm">
              <p className="">Could not load templates</p>
              <p>{loadError}</p>
            </div>
          </div>
        )}
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-12 text-center">
                  <input
                    type="checkbox"
                    checked={
                      filteredTemplates.length > 0 &&
                      filteredTemplates.every((template) => selectedTemplateIds.includes(template.id))
                    }
                    onChange={handleToggleSelectAll}
                    disabled={filteredTemplates.length === 0 || bulkDeleting}
                    aria-label="Select all templates"
                  />
                </TableHead>
                <TableHead>Form Type</TableHead>
                <TableHead>Name</TableHead>
                <TableHead>File</TableHead>
                <TableHead>Size</TableHead>
                <TableHead>Uploaded By</TableHead>
                <TableHead>Updated</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={9} className="text-center py-8">
                    Loading templates...
                  </TableCell>
                </TableRow>
              ) : filteredTemplates.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={9} className="text-center py-8">
                    <FileSpreadsheet className="w-12 h-12 mx-auto mb-2 text-muted-foreground" />
                    <p className="text-muted-foreground">
                      {templates.length === 0 ? 'No templates uploaded yet' : 'No templates match your current filters'}
                    </p>
                    {templates.length === 0 ? (
                      <Button onClick={() => setUploadDialogOpen(true)} variant="link">
                        Upload your first template
                      </Button>
                    ) : (
                      <Button
                        onClick={() => {
                          setSearchQuery('');
                          setStatusFilter('ALL');
                          setFormFilter('ALL');
                        }}
                        variant="link"
                      >
                        Clear filters
                      </Button>
                    )}
                  </TableCell>
                </TableRow>
              ) : (
                filteredTemplates.map((template) => (
                  <TableRow key={template.id}>
                    <TableCell className="text-center">
                      <input
                        type="checkbox"
                        checked={selectedTemplateIds.includes(template.id)}
                        onChange={() => toggleTemplateSelection(template.id)}
                        disabled={bulkDeleting}
                        aria-label={`Select ${template.formType} template`}
                      />
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">{template.formType}</Badge>
                    </TableCell>
                    <TableCell className="">{template.formName}</TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      <div className="flex items-center gap-2">
                        <FileSpreadsheet className="w-4 h-4" />
                        {template.fileName}
                      </div>
                    </TableCell>
                    <TableCell className="text-sm">{formatFileSize(template.fileSize)}</TableCell>
                    <TableCell className="text-sm">{template.uploadedByName}</TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {formatDate(template.updatedAt)}
                    </TableCell>
                    <TableCell>
                      {template.isActive ? (
                        <Badge variant="default" className="bg-green-600">Active</Badge>
                      ) : (
                        <Badge variant="secondary">Inactive</Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-2">
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => handleViewTemplate(template)}
                          title="View Template"
                        >
                          <Eye className="w-4 h-4" />
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => showInfo(template)}
                          title="View Details"
                        >
                          <Info className="w-4 h-4" />
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => handleDownload(template)}
                          title="Download Template"
                        >
                          <Download className="w-4 h-4" />
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => handleToggleActive(template)}
                          title={template.isActive ? 'Deactivate' : 'Activate'}
                        >
                          <Power className={`w-4 h-4 ${template.isActive ? 'text-green-600' : 'text-gray-400'}`} />
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => handleDelete(template)}
                          title="Delete Template"
                          className="text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
      </Card>

      {/* Upload Dialog */}
      <Dialog open={uploadDialogOpen} onOpenChange={setUploadDialogOpen}>
        <DialogContent className="w-full max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Upload Excel Template</DialogTitle>
            <DialogDescription>
              Upload a DepEd School Form template with placeholders for dynamic data
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-5 py-4">
            {uploadError && (
              <div className="flex items-start gap-3 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
                <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                  <p className="text-sm  mb-1">Upload Failed</p>
                  <p className="text-sm whitespace-pre-line">{uploadError}</p>
                </div>
              </div>
            )}

            {uploadSuccess && (
              <div className="flex items-center gap-3 p-4 bg-green-50 border border-green-200 rounded-lg text-green-700">
                <CheckCircle2 className="w-5 h-5" />
                <p className="text-sm ">{uploadSuccess}</p>
              </div>
            )}

            <div className="space-y-2">
              <Label htmlFor="formType" className="text-sm ">Form Type *</Label>
              <select
                id="formType"
                value={uploadFormType}
                onChange={(e) => {
                  setUploadFormType(e.target.value);
                  const selectedForm = FORM_TYPES.find((f) => f.value === e.target.value);
                  if (selectedForm && !uploadFormName) {
                    setUploadFormName(selectedForm.label);
                  } else if (selectedForm?.value === 'SF1_10_BUNDLE' || selectedForm?.value === 'SF1_7_BUNDLE') {
                    setUploadFormName(
                      selectedForm.value === 'SF1_7_BUNDLE'
                        ? 'School Forms 1-7 Bundle Template'
                        : 'School Forms 1-10 Bundle Template'
                    );
                  }
                }}
                className="w-full px-3 py-2.5 border rounded-md text-sm bg-muted"
              >
                <option value="">Select a form type...</option>
                {FORM_TYPES.map((form) => (
                  <option key={form.value} value={form.value}>
                    {form.label}
                  </option>
                ))}
              </select>
              {uploadFormType && (
                <p className="text-sm text-muted-foreground">
                  {FORM_TYPES.find((f) => f.value === uploadFormType)?.description}
                </p>
              )}
              {(uploadFormType === 'SF1_10_BUNDLE' || uploadFormType === 'SF1_7_BUNDLE') && (
                <p className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded px-2 py-1">
                  {uploadFormType === 'SF1_7_BUNDLE'
                    ? 'The system will auto-map sheets to SF1-SF7 using sheet names (for example, "School Form 1 (SF1)").'
                    : 'The system will auto-map sheets to SF1-SF10 using sheet names (for example, "School Form 1 (SF1)").'}
                </p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="formName" className="text-sm ">Template Name *</Label>
              <Input
                id="formName"
                value={uploadFormName}
                onChange={(e) => setUploadFormName(e.target.value)}
                placeholder="e.g., School Form 2 - Daily Attendance Record"
                className="h-10"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description" className="text-sm ">Description (Optional)</Label>
              <Input
                id="description"
                value={uploadDescription}
                onChange={(e) => setUploadDescription(e.target.value)}
                placeholder="Brief description of this template"
                className="h-10"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="instructions" className="text-sm ">Usage Instructions (Optional)</Label>
              <textarea
                id="instructions"
                value={uploadInstructions}
                onChange={(e) => setUploadInstructions(e.target.value)}
                placeholder="How to use this template and what data it expects"
                rows={4}
                className="w-full px-3 py-2 border rounded-md text-sm resize-none"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="file" className="text-sm ">Excel File *</Label>
              <Input
                id="file"
                type="file"
                accept=".xlsx,.xls"
                onChange={(e) => setUploadFile(e.target.files?.[0] || null)}
              />
              <p className="text-sm text-muted-foreground">
                Upload an Excel file (.xlsx or .xls).
                {(uploadFormType === 'SF1_10_BUNDLE' || uploadFormType === 'SF1_7_BUNDLE')
                  ? uploadFormType === 'SF1_7_BUNDLE'
                    ? ' For all-in-one files, include separate sheets for SF1 to SF7.'
                    : ' For all-in-one files, include separate sheets for SF1 to SF10.'
                  : ` Use placeholders like {{SCHOOL_NAME}}, {{DATE}}, etc.`}
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setUploadDialogOpen(false)} disabled={uploading}>
              Cancel
            </Button>
            <Button onClick={handleUpload} disabled={uploading}>
              {uploading ? 'Uploading...' : 'Upload Template'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Info Dialog */}
      <Dialog open={infoDialogOpen} onOpenChange={setInfoDialogOpen}>
        <DialogContent className="w-full max-w-3xl">
          <DialogHeader>
            <DialogTitle>{selectedTemplate?.formName}</DialogTitle>
            <DialogDescription>{selectedTemplate?.formType}</DialogDescription>
          </DialogHeader>

          {selectedTemplate && (
            <div className="space-y-4 py-4">
              <div>
                <Label className="text-sm ">Description</Label>
                <p className="text-sm mt-1">{selectedTemplate.description || 'No description provided'}</p>
              </div>

              <div>
                <Label className="text-sm ">File Information</Label>
                <div className="mt-1 text-sm space-y-1">
                  <p>ΓÇó File: {selectedTemplate.fileName}</p>
                  <p>ΓÇó Size: {formatFileSize(selectedTemplate.fileSize)}</p>
                  {selectedTemplate.sheetName && <p>ΓÇó Sheet Mapping: {selectedTemplate.sheetName}</p>}
                  <p>ΓÇó Uploaded by: {selectedTemplate.uploadedByName}</p>
                  <p>ΓÇó Created: {formatDate(selectedTemplate.createdAt)}</p>
                  <p>ΓÇó Last updated: {formatDate(selectedTemplate.updatedAt)}</p>
                </div>
              </div>

              {selectedTemplate.placeholders && selectedTemplate.placeholders.length > 0 && (
                <div>
                  <Label className="text-sm ">Available Placeholders</Label>
                  <div className="flex flex-wrap gap-2 mt-2">
                    {selectedTemplate.placeholders.map((placeholder) => (
                      <code key={placeholder} className="text-xs bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded">
                        {`{{${placeholder}}}`}
                      </code>
                    ))}
                  </div>
                </div>
              )}

              {selectedTemplate.instructions && (
                <div>
                  <Label className="text-sm ">Instructions</Label>
                  <p className="text-sm mt-1 whitespace-pre-wrap">{selectedTemplate.instructions}</p>
                </div>
              )}
            </div>
          )}

          <DialogFooter>
            <Button onClick={() => setInfoDialogOpen(false)}>Close</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Template Preview Dialog */}
      <Dialog open={previewDialogOpen} onOpenChange={setPreviewDialogOpen}>
        <DialogContent className="w-full max-w-3xl max-h-[95vh] overflow-hidden flex flex-col">
          <DialogHeader>
            <DialogTitle>Template Preview</DialogTitle>
            <DialogDescription>
              {viewMode === 'styled' ? 'Pixel-perfect view matching Excel exactly' : 'Simple table view of worksheet data'}
            </DialogDescription>
          </DialogHeader>

          <div className="flex-1 overflow-y-auto space-y-4 py-2">
            {previewLoading && (
              <div className="flex items-center justify-center py-20">
                <div className="text-center">
                  <RefreshCw className="w-8 h-8 animate-spin mx-auto mb-2 text-blue-600" />
                  <p className="text-sm text-muted-foreground">Loading template...</p>
                </div>
              </div>
            )}

            {previewError && (
              <div className="flex items-start gap-3 p-4 rounded-md border border-red-200 bg-red-50 text-red-700 text-sm">
                <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="">Failed to load preview</p>
                  <p className="mt-1">{previewError}</p>
                </div>
              </div>
            )}

            {(styledPreviewData || previewData) && !previewLoading && (
              <>
                {/* Info and Controls */}
                <div className="space-y-3">
                  <Card className="p-3 bg-blue-50 border-blue-200">
                    <div className="flex items-start justify-between gap-3">
                      <div className="text-sm space-y-1 flex-1">
                        <p><span className="">Template:</span> {styledPreviewData?.formName || previewData?.formName}</p>
                        <p><span className="">Form Type:</span> {styledPreviewData?.formType || previewData?.formType}</p>
                        <p><span className="">File:</span> {styledPreviewData?.fileName || previewData?.fileName}</p>
                      </div>
                      <Button size="sm" onClick={handleOpenExactWorkbook} variant="outline">
                        <Download className="w-4 h-4 mr-2" />
                        Download Excel
                      </Button>
                    </div>
                  </Card>

                  {/* View Mode Toggle and Controls */}
                  <div className="flex flex-wrap items-center gap-3">
                    <div className="flex gap-2">
                      <Button
                        size="sm"
                        variant={viewMode === 'styled' ? 'default' : 'outline'}
                        onClick={() => setViewMode('styled')}
                        disabled={!styledPreviewData}
                      >
                        <Eye className="w-4 h-4 mr-2" />
                        Styled View
                      </Button>
                      <Button
                        size="sm"
                        variant={viewMode === 'simple' ? 'default' : 'outline'}
                        onClick={() => setViewMode('simple')}
                      >
                        <FileSpreadsheet className="w-4 h-4 mr-2" />
                        Simple View
                      </Button>
                    </div>

                    {viewMode === 'styled' && styledPreviewData && (
                      <div className="flex items-center gap-2 ml-auto">
                        <span className="text-xs text-muted-foreground">
                          Zoom: {Math.round(previewScale * 100)}%
                        </span>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => setPreviewScale(prev => Math.max(prev - 0.1, 0.3))}
                          disabled={previewScale <= 0.3}
                        >
                          <ZoomOut className="w-4 h-4" />
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => setPreviewScale(1)}
                        >
                          Reset
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => setPreviewScale(prev => Math.min(prev + 0.1, 1.5))}
                          disabled={previewScale >= 1.5}
                        >
                          <ZoomIn className="w-4 h-4" />
                        </Button>
                      </div>
                    )}
                  </div>

                  {/* Sheet Selection */}
                  {((viewMode === 'styled' && styledPreviewData?.parsedStructure.sheets.length > 1) ||
                    (viewMode === 'simple' && previewData?.sheets.length > 1)) && (
                      <div className="space-y-2">
                        <Label htmlFor="previewSheet" className="text-sm ">Worksheet</Label>
                        <select
                          id="previewSheet"
                          value={selectedPreviewSheet}
                          onChange={(e) => setSelectedPreviewSheet(e.target.value)}
                          className="w-full px-3 py-2 border rounded-md text-sm bg-muted"
                        >
                          {viewMode === 'styled' && styledPreviewData?.parsedStructure.sheets.map((sheet: any) => (
                            <option key={sheet.name} value={sheet.name}>
                              {sheet.name}
                              {styledPreviewData.mappedSheetName === sheet.name ? ' (Mapped)' : ''}
                            </option>
                          ))}
                          {viewMode === 'simple' && previewData?.sheets.map((sheet) => (
                            <option key={sheet.sheetName} value={sheet.sheetName}>
                              {sheet.sheetName}
                              {sheet.isMappedSheet ? ' (Mapped)' : ''}
                            </option>
                          ))}
                        </select>
                      </div>
                    )}
                </div>

                {/* Preview Content */}
                <Card className="p-0 overflow-hidden">
                  {viewMode === 'styled' && styledPreviewData ? (
                    (() => {
                      const activeSheet = styledPreviewData.parsedStructure.sheets.find((sheet: any) => sheet.name === selectedPreviewSheet) ||
                        styledPreviewData.parsedStructure.sheets[0];

                      if (!activeSheet) {
                        return <p className="p-4 text-sm text-muted-foreground">No worksheet data available.</p>;
                      }

                      return (
                        <div className="overflow-auto max-h-[60vh] p-4">
                          <ExcelRenderer
                            sheet={activeSheet}
                            scale={previewScale}
                            showGridlines={true}
                          />
                        </div>
                      );
                    })()
                  ) : (
                    (() => {
                      const activeSheet = previewData?.sheets.find((sheet) => sheet.sheetName === selectedPreviewSheet) ||
                        previewData?.sheets[0];

                      if (!activeSheet) {
                        return <p className="p-4 text-sm text-muted-foreground">No worksheet data available.</p>;
                      }

                      return (
                        <div className="space-y-2 p-4">
                          <div className="flex items-center gap-2">
                            <Badge variant={activeSheet.isMappedSheet ? 'default' : 'outline'}>
                              {activeSheet.isMappedSheet ? 'Mapped Sheet' : 'Unmapped Sheet'}
                            </Badge>
                            <p className="text-xs text-muted-foreground">
                              Total rows: {activeSheet.totalRows} |
                              Showing: {Math.min(activeSheet.previewRows.length, previewData?.maxRows || 0)} rows ├ù {previewData?.maxCols || 0} columns
                            </p>
                          </div>
                          <div className="overflow-auto border rounded-md max-h-[50vh]">
                            <table className="min-w-full text-xs border-collapse">
                              <thead className="sticky top-0 bg-gray-100 z-10">
                                <tr>
                                  <th className="border px-2 py-1 text-left">#</th>
                                  {Array.from({ length: previewData?.maxCols || 0 }).map((_, index) => (
                                    <th key={index} className="border px-2 py-1 text-left min-w-[90px]">
                                      {index + 1}
                                    </th>
                                  ))}
                                </tr>
                              </thead>
                              <tbody>
                                {activeSheet.previewRows.map((row, rowIndex) => (
                                  <tr key={rowIndex}>
                                    <td className="border px-2 py-1 bg-gray-50 ">{rowIndex + 1}</td>
                                    {row.map((cell, colIndex) => (
                                      <td key={colIndex} className="border px-2 py-1 align-top whitespace-pre-wrap">
                                        {cell}
                                      </td>
                                    ))}
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        </div>
                      );
                    })()
                  )}
                </Card>
              </>
            )}
          </div>

          <DialogFooter className="mt-4">
            <Button variant="outline" onClick={() => setPreviewDialogOpen(false)}>Close</Button>
            <Button onClick={() => window.print()}>
              <Download className="w-4 h-4 mr-2" />
              Print Preview
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// @ts-nocheck
import { useState, useEffect } from "react";
import {
  Users,
  Search,
  Plus,
  Eye,
  Edit,
  _MoreHorizontal,
  Shield,
  UserCheck,
  ClipboardList,
  CheckCircle2,
  XCircle,
  Mail,
  Calendar,
  Loader2,
  AlertTriangle,
  RefreshCw,
  Trash2,
  Save,
} from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/features/smart/components/ui/card";
import { Badge } from "@/features/smart/components/ui/badge";
import { Button } from "@/features/smart/components/ui/button";
import { Input } from "@/features/smart/components/ui/input";
import { Label } from "@/features/smart/components/ui/label";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/features/smart/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/features/smart/components/ui/select";
import {
  _DropdownMenu,
  _DropdownMenuContent,
  _DropdownMenuItem,
  _DropdownMenuSeparator,
  _DropdownMenuTrigger,
} from "@/features/smart/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/features/smart/components/ui/dialog";
import { Avatar, AvatarFallback } from "@/features/smart/components/ui/avatar";
import { adminApi } from "@/features/smart/lib/api";
import type { AdminUser } from "@/features/smart/lib/api";
import { useTheme } from "@/features/smart/contexts/ThemeContext";

const roleLabels: Record<string, string> = {
  ADMIN: "Administrator",
  TEACHER: "Teacher",
  REGISTRAR: "Registrar",
};

const roleOpacity: Record<string, string> = {
  ADMIN: "18",
  TEACHER: "28",
  REGISTRAR: "38",
};

const roleIcons: Record<string, React.ReactNode> = {
  ADMIN: <Shield className="w-3.5 h-3.5" />,
  TEACHER: <UserCheck className="w-3.5 h-3.5" />,
  REGISTRAR: <ClipboardList className="w-3.5 h-3.5" />,
};

interface UserFormData {
  username: string;
  password: string;
  role: string;
  firstName: string;
  lastName: string;
  email: string;
  employeeId: string;
  specialization: string;
}

const initialFormData: UserFormData = {
  username: "",
  password: "",
  role: "TEACHER",
  firstName: "",
  lastName: "",
  email: "",
  employeeId: "",
  specialization: "",
};

export default function UserManagement() {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { colors } = useTheme();
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedRole, setSelectedRole] = useState("all");
  const [selectedStatus, setSelectedStatus] = useState("all");

  // Dialog states
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [isDeleteOpen, setIsDeleteOpen] = useState(false);
  const [isViewOpen, setIsViewOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [formData, setFormData] = useState<UserFormData>(initialFormData);
  const [saving, setSaving] = useState(false);

  const fetchUsers = async () => {
    try {
      setLoading(true);
      const response = await adminApi.getUsers({ role: selectedRole !== "all" ? selectedRole : undefined });
      setUsers(response.data.users);
      setError(null);
    } catch (err) {
      console.error("Failed to fetch users:", err);
      setError("Failed to load users");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const filteredUsers = users.filter((user) => {
    const fullName = `${user.firstName || ""} ${user.lastName || ""}`.toLowerCase();
    const matchesSearch =
      fullName.includes(searchQuery.toLowerCase()) ||
      user.username.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (user.email?.toLowerCase().includes(searchQuery.toLowerCase()) ?? false);
    const matchesRole = selectedRole === "all" || user.role === selectedRole;
    const matchesStatus = selectedStatus === "all" || user.status === selectedStatus;
    return matchesSearch && matchesRole && matchesStatus;
  });

  const userCounts = {
    total: users.length,
    admin: users.filter((u) => u.role === "ADMIN").length,
    teacher: users.filter((u) => u.role === "TEACHER").length,
    registrar: users.filter((u) => u.role === "REGISTRAR").length,
    active: users.filter((u) => u.status === "Active").length,
  };

  const handleCreate = async () => {
    try {
      setSaving(true);
      await adminApi.createUser({
        username: formData.username,
        password: formData.password,
        role: formData.role,
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email || undefined,
        employeeId: formData.role === "TEACHER" ? formData.employeeId : undefined,
        specialization: formData.role === "TEACHER" ? formData.specialization : undefined,
      });
      setIsCreateOpen(false);
      setFormData(initialFormData);
      fetchUsers();
    } catch (err: any) {
      alert(err.response?.data?.message || "Failed to create user");
    } finally {
      setSaving(false);
    }
  };

  const handleUpdate = async () => {
    if (!selectedUser) return;
    try {
      setSaving(true);
      await adminApi.updateUser(selectedUser.id, {
        username: formData.username,
        password: formData.password || undefined,
        role: formData.role,
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email || undefined,
        employeeId: formData.role === "TEACHER" ? formData.employeeId : undefined,
        specialization: formData.role === "TEACHER" ? formData.specialization : undefined,
      });
      setIsEditOpen(false);
      setSelectedUser(null);
      setFormData(initialFormData);
      fetchUsers();
    } catch (err: any) {
      alert(err.response?.data?.message || "Failed to update user");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!selectedUser) return;
    try {
      setSaving(true);
      await adminApi.deleteUser(selectedUser.id);
      setIsDeleteOpen(false);
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      alert(err.response?.data?.message || "Failed to delete user");
    } finally {
      setSaving(false);
    }
  };

  const _openEditDialog = (user: AdminUser) => {
    setSelectedUser(user);
    setFormData({
      username: user.username,
      password: "",
      role: user.role,
      firstName: user.firstName || "",
      lastName: user.lastName || "",
      email: user.email || "",
      employeeId: user.teacher?.employeeId || "",
      specialization: user.teacher?.specialization || "",
    });
    setIsEditOpen(true);
  };

  const openViewDialog = (user: AdminUser) => {
    setSelectedUser(user);
    setIsViewOpen(true);
  };

  const _openDeleteDialog = (user: AdminUser) => {
    setSelectedUser(user);
    setIsDeleteOpen(true);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="flex flex-col items-center gap-3">
          <Loader2 className="w-8 h-8 animate-spin" style={{ color: colors.primary }} />
          <p className="text-gray-500">Loading users...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="flex flex-col items-center gap-3 text-center">
          <AlertTriangle className="w-12 h-12 text-amber-500" />
          <p className="text-gray-700 ">{error}</p>
          <Button onClick={fetchUsers} variant="outline" className="gap-2">
            <RefreshCw className="w-4 h-4" />
            Retry
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold" style={{ color: '#111827' }}>
            User Management
          </h1>
          <p style={{ color: '#6b7280' }} className="mt-1">
            Manage system users and their access permissions
          </p>
        </div>
      </div>

      {/* Stats Row */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        <Card className="border-0 shadow-lg shadow-gray-200/50 rounded-xl bg-muted p-0">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs  text-gray-500">Total Users</p>
                <p className="text-2xl font-bold" style={{ color: '#111827' }}>{userCounts.total}</p>
              </div>
              <div className="p-2 rounded-lg bg-gray-100">
                <Users className="w-5 h-5 text-gray-600" />
              </div>
            </div>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-lg shadow-gray-200/50 rounded-xl bg-muted p-0">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs  text-gray-500">Admins</p>
                <p className="text-2xl font-bold" style={{ color: colors.primary }}>{userCounts.admin}</p>
              </div>
              <div className="p-2 rounded-lg" style={{ backgroundColor: `${colors.primary}15` }}>
                <Shield className="w-5 h-5" style={{ color: colors.primary }} />
              </div>
            </div>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-lg shadow-gray-200/50 rounded-xl bg-muted p-0">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs  text-gray-500">Teachers</p>
                <p className="text-2xl font-bold" style={{ color: colors.secondary }}>{userCounts.teacher}</p>
              </div>
              <div className="p-2 rounded-lg" style={{ backgroundColor: `${colors.secondary}15` }}>
                <UserCheck className="w-5 h-5" style={{ color: colors.secondary }} />
              </div>
            </div>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-lg shadow-gray-200/50 rounded-xl bg-muted p-0">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs  text-gray-500">Registrars</p>
                <p className="text-2xl font-bold" style={{ color: colors.accent }}>{userCounts.registrar}</p>
              </div>
              <div className="p-2 rounded-lg" style={{ backgroundColor: `${colors.accent}15` }}>
                <ClipboardList className="w-5 h-5" style={{ color: colors.accent }} />
              </div>
            </div>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-lg shadow-gray-200/50 rounded-xl bg-muted p-0">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs  text-gray-500">Active</p>
                <p className="text-2xl font-bold" style={{ color: colors.secondary }}>{userCounts.active}</p>
              </div>
              <div className="p-2 rounded-lg" style={{ backgroundColor: `${colors.secondary}15` }}>
                <CheckCircle2 className="w-5 h-5" style={{ color: colors.secondary }} />
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Users Table */}
      <Card className="border-0 shadow-xl shadow-gray-200/50 rounded-2xl bg-muted p-0">
        <CardHeader className="border-b border-gray-100">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div>
              <CardTitle className="text-lg" style={{ color: '#111827' }}>All Users</CardTitle>
              <CardDescription>View and manage all system users</CardDescription>
            </div>
            <div className="flex flex-wrap items-center gap-3">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="Search users..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-9 w-64 rounded-xl border-gray-200"
                />
              </div>
              <Select value={selectedRole} onValueChange={(val) => val && setSelectedRole(val)}>
                <SelectTrigger className="w-36 rounded-xl border-gray-200">
                  <SelectValue>
                    {selectedRole === "all" ? "All Roles" : roleLabels[selectedRole]}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Roles</SelectItem>
                  <SelectItem value="ADMIN">Administrator</SelectItem>
                  <SelectItem value="TEACHER">Teacher</SelectItem>
                  <SelectItem value="REGISTRAR">Registrar</SelectItem>
                </SelectContent>
              </Select>
              <Select value={selectedStatus} onValueChange={(val) => val && setSelectedStatus(val)}>
                <SelectTrigger className="w-32 rounded-xl border-gray-200">
                  <SelectValue>
                    {selectedStatus === "all" ? "All Status" : selectedStatus}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="Active">Active</SelectItem>
                  <SelectItem value="Inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow className="bg-gray-50/80">
                  <TableHead className="font-bold text-gray-700">User</TableHead>
                  <TableHead className="font-bold text-gray-700">Employee ID</TableHead>
                  <TableHead className="font-bold text-gray-700">Role</TableHead>
                  <TableHead className="font-bold text-gray-700">Status</TableHead>
                  <TableHead className="font-bold text-gray-700">Last Active</TableHead>
                  <TableHead className="font-bold text-gray-700 text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredUsers.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} className="h-32 text-center">
                      <div className="flex flex-col items-center gap-2 text-gray-500">
                        <Users className="w-8 h-8 text-gray-300" />
                        <p>No users found</p>
                      </div>
                    </TableCell>
                  </TableRow>
                ) : (
                  filteredUsers.map((user) => (
                    <TableRow key={user.id} className="hover:bg-gray-50/50">
                      <TableCell>
                        <div className="flex items-center gap-3">
                          <Avatar className={`h-10 w-10 ring-2 ring-offset-2 ring-gray-200`}>
                            <AvatarFallback className="text-white " style={{ backgroundColor: colors.primary }}>
                              {(user.firstName?.[0] || "U")}{(user.lastName?.[0] || "")}
                            </AvatarFallback>
                          </Avatar>
                          <div>
                            <p className="" style={{ color: '#111827' }}>
                              {user.firstName || ""} {user.lastName || ""}
                            </p>
                            {user.email && (
                              <div className="flex items-center gap-1 text-xs text-gray-500">
                                <Mail className="w-3 h-3" />
                                {user.email}
                              </div>
                            )}
                          </div>
                        </div>
                      </TableCell>
                      <TableCell className="font-mono text-sm text-gray-600">
                        {user.teacher?.employeeId || user.username}
                      </TableCell>
                      <TableCell>
                        <Badge className="border-0  flex items-center gap-1 w-fit" style={{ backgroundColor: `${colors.primary}${roleOpacity[user.role] || '18'}`, color: colors.primary }}>
                          {roleIcons[user.role]}
                          {roleLabels[user.role]}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {user.status === "Active" ? (
                          <Badge className="border-0 " style={{ backgroundColor: `${colors.primary}15`, color: colors.primary }}>
                            <CheckCircle2 className="w-3 h-3 mr-1" />
                            Active
                          </Badge>
                        ) : (
                          <Badge className="bg-gray-100 text-gray-600 border-0 ">
                            <XCircle className="w-3 h-3 mr-1" />
                            Inactive
                          </Badge>
                        )}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1 text-sm text-gray-500">
                          <Calendar className="w-3.5 h-3.5" />
                          {user.lastActive}
                        </div>
                      </TableCell>
                      <TableCell className="text-right">
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-8 rounded-lg gap-1.5 px-3  hover:bg-slate-100 transition-colors"
                          onClick={() => openViewDialog(user)}
                        >
                          <Eye className="w-4 h-4 text-slate-500" />
                          View Details
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Create User Dialog */}
      <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
        <DialogContent className="w-full max-w-3xl rounded-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <div className="p-2 rounded-lg" style={{ backgroundColor: `${colors.primary}15` }}>
                <Plus className="w-5 h-5" style={{ color: colors.primary }} />
              </div>
              Create New User
            </DialogTitle>
            <DialogDescription>
              Add a new user to the system. Fill in all required fields.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="firstName">First Name *</Label>
                <Input
                  id="firstName"
                  value={formData.firstName}
                  onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                  placeholder="Juan"
                  className="rounded-xl"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="lastName">Last Name *</Label>
                <Input
                  id="lastName"
                  value={formData.lastName}
                  onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                  placeholder="Dela Cruz"
                  className="rounded-xl"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="username">Username *</Label>
              <Input
                id="username"
                value={formData.username}
                onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                placeholder="jdelacruz"
                className="rounded-xl"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">Password *</Label>
              <Input
                id="password"
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                className="rounded-xl"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                placeholder="jdelacruz@school.edu.ph"
                className="rounded-xl"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="role">Role *</Label>
              <Select value={formData.role} onValueChange={(val) => val && setFormData({ ...formData, role: val })}>
                <SelectTrigger className="rounded-xl">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="TEACHER">Teacher</SelectItem>
                  <SelectItem value="REGISTRAR">Registrar</SelectItem>
                  <SelectItem value="ADMIN">Administrator</SelectItem>
                </SelectContent>
              </Select>
            </div>
            {formData.role === "TEACHER" && (
              <>
                <div className="space-y-2">
                  <Label htmlFor="employeeId">Employee ID *</Label>
                  <Input
                    id="employeeId"
                    value={formData.employeeId}
                    onChange={(e) => setFormData({ ...formData, employeeId: e.target.value })}
                    placeholder="EMP-2025-001"
                    className="rounded-xl"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="specialization">Specialization</Label>
                  <Input
                    id="specialization"
                    value={formData.specialization}
                    onChange={(e) => setFormData({ ...formData, specialization: e.target.value })}
                    placeholder="e.g., Mathematics, English"
                    className="rounded-xl"
                  />
                </div>
              </>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsCreateOpen(false)} className="rounded-xl">
              Cancel
            </Button>
            <Button
              onClick={handleCreate}
              disabled={saving || !formData.username || !formData.password || !formData.firstName || !formData.lastName || (formData.role === "TEACHER" && !formData.employeeId)}
              className="gap-2 text-white rounded-xl"
              style={{ backgroundColor: colors.primary }}
            >
              {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
              Create User
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Edit User Dialog */}
      <Dialog open={isEditOpen} onOpenChange={setIsEditOpen}>
        <DialogContent className="w-full max-w-3xl rounded-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <div className="p-2 rounded-lg" style={{ backgroundColor: `${colors.primary}15` }}>
                <Edit className="w-5 h-5" style={{ color: colors.primary }} />
              </div>
              Edit User
            </DialogTitle>
            <DialogDescription>
              Update user information. Leave password empty to keep current password.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="editFirstName">First Name *</Label>
                <Input
                  id="editFirstName"
                  value={formData.firstName}
                  onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                  className="rounded-xl"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="editLastName">Last Name *</Label>
                <Input
                  id="editLastName"
                  value={formData.lastName}
                  onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                  className="rounded-xl"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="editUsername">Username *</Label>
              <Input
                id="editUsername"
                value={formData.username}
                onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                className="rounded-xl"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="editPassword">New Password (leave empty to keep current)</Label>
              <Input
                id="editPassword"
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                className="rounded-xl"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="editEmail">Email</Label>
              <Input
                id="editEmail"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="rounded-xl"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="editRole">Role *</Label>
              <Select value={formData.role} onValueChange={(val) => val && setFormData({ ...formData, role: val })}>
                <SelectTrigger className="rounded-xl">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="TEACHER">Teacher</SelectItem>
                  <SelectItem value="REGISTRAR">Registrar</SelectItem>
                  <SelectItem value="ADMIN">Administrator</SelectItem>
                </SelectContent>
              </Select>
            </div>
            {formData.role === "TEACHER" && (
              <>
                <div className="space-y-2">
                  <Label htmlFor="editEmployeeId">Employee ID *</Label>
                  <Input
                    id="editEmployeeId"
                    value={formData.employeeId}
                    onChange={(e) => setFormData({ ...formData, employeeId: e.target.value })}
                    className="rounded-xl"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="editSpecialization">Specialization</Label>
                  <Input
                    id="editSpecialization"
                    value={formData.specialization}
                    onChange={(e) => setFormData({ ...formData, specialization: e.target.value })}
                    className="rounded-xl"
                  />
                </div>
              </>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsEditOpen(false)} className="rounded-xl">
              Cancel
            </Button>
            <Button
              onClick={handleUpdate}
              disabled={saving || !formData.username || !formData.firstName || !formData.lastName}
              className="gap-2 text-white rounded-xl"
              style={{ backgroundColor: colors.primary }}
            >
              {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
              Save Changes
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View User Dialog */}
      <Dialog open={isViewOpen} onOpenChange={setIsViewOpen}>
        <DialogContent className="w-full max-w-3xl rounded-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <div className="p-2 rounded-lg" style={{ backgroundColor: `${colors.secondary}15` }}>
                <Eye className="w-5 h-5" style={{ color: colors.secondary }} />
              </div>
              User Details
            </DialogTitle>
          </DialogHeader>
          {selectedUser && (
            <div className="space-y-4 py-4">
              <div className="flex items-center gap-4">
                <Avatar className="h-16 w-16">
                  <AvatarFallback className="text-white text-xl " style={{ backgroundColor: colors.primary }}>
                    {(selectedUser.firstName?.[0] || "U")}{(selectedUser.lastName?.[0] || "")}
                  </AvatarFallback>
                </Avatar>
                <div>
                  <h3 className="text-xl font-bold" style={{ color: '#111827' }}>
                    {selectedUser.firstName} {selectedUser.lastName}
                  </h3>
                  <Badge className="border-0 mt-1" style={{ backgroundColor: `${colors.primary}${roleOpacity[selectedUser.role] || '18'}`, color: colors.primary }}>
                    {roleIcons[selectedUser.role]}
                    <span className="ml-1">{roleLabels[selectedUser.role]}</span>
                  </Badge>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4 pt-4 border-t">
                <div>
                  <p className="text-xs text-gray-500">Employee ID</p>
                  <p className="font-mono ">{selectedUser.teacher?.employeeId || selectedUser.username}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">Email</p>
                  <p className="">{selectedUser.email || "ΓÇö"}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">Status</p>
                  <Badge className={selectedUser.status === "Active" ? "border-0" : "bg-gray-100 text-gray-600 border-0"} style={selectedUser.status === "Active" ? { backgroundColor: `${colors.primary}15`, color: colors.primary } : undefined}>
                    {selectedUser.status}
                  </Badge>
                </div>
                <div>
                  <p className="text-xs text-gray-500">Last Active</p>
                  <p className="">{selectedUser.lastActive}</p>
                </div>
                {selectedUser.teacher?.specialization && (
                  <div className="col-span-2">
                    <p className="text-xs text-gray-500">Specialization</p>
                    <p className="">{selectedUser.teacher.specialization}</p>
                  </div>
                )}
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewOpen(false)} className="rounded-xl">
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={isDeleteOpen} onOpenChange={setIsDeleteOpen}>
        <DialogContent className="w-full max-w-3xl rounded-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-red-600">
              <div className="p-2 rounded-lg bg-red-100">
                <Trash2 className="w-5 h-5 text-red-600" />
              </div>
              Delete User
            </DialogTitle>
            <DialogDescription>
              Are you sure you want to delete this user? This action cannot be undone.
            </DialogDescription>
          </DialogHeader>
          {selectedUser && (
            <div className="py-4">
              <div className="flex items-center gap-3 p-3 rounded-xl bg-gray-50">
                <Avatar className="h-10 w-10">
                  <AvatarFallback className="text-white " style={{ backgroundColor: colors.primary }}>
                    {(selectedUser.firstName?.[0] || "U")}{(selectedUser.lastName?.[0] || "")}
                  </AvatarFallback>
                </Avatar>
                <div>
                  <p className="">{selectedUser.firstName} {selectedUser.lastName}</p>
                  <p className="text-sm text-gray-500">@{selectedUser.username}</p>
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDeleteOpen(false)} className="rounded-xl">
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleDelete}
              disabled={saving}
              className="gap-2 rounded-xl"
            >
              {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
              Delete User
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// @ts-nocheck
import { useState, useEffect } from "react";
import { usePaginationLimit } from '@/shared/hooks/usePaginationLimit';
import { ClipboardList, Loader2, AlertTriangle, RefreshCw, Search, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/features/smart/components/ui/card";
import { Badge } from "@/features/smart/components/ui/badge";
import { Button } from "@/features/smart/components/ui/button";
import { Input } from "@/features/smart/components/ui/input";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/features/smart/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/features/smart/components/ui/select";
import { registrarApi } from "@/features/smart/lib/api";
import { Breadcrumb } from "@/features/smart/components/ui/breadcrumb";
import { useTheme } from "@/features/smart/contexts/ThemeContext";

const STATUS_COLORS: Record<string, string> = {
  PENDING: "bg-amber-100 text-amber-700",
  VERIFIED: "bg-blue-100 text-blue-700",
  ENROLLED: "bg-emerald-100 text-emerald-700",
  REJECTED: "bg-red-100 text-red-700",
};

const _GRADE_LABELS: Record<string, string> = {
  GRADE_7: "Grade 7",
  GRADE_8: "Grade 8",
  GRADE_9: "Grade 9",
  GRADE_10: "Grade 10",
};

const _STATUS_LABELS: Record<string, string> = {
  PENDING: "Pending",
  VERIFIED: "Verified",
  ENROLLED: "Enrolled",
  REJECTED: "Rejected",
};

export default function ApplicationTracker() {
  const { colors } = useTheme();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [applications, setApplications] = useState<any[]>([]);
  const [meta, setMeta] = useState<any>(null);
  const [statusFilter, setStatusFilter] = useState("all");
  const [gradeFilter, setGradeFilter] = useState("all");
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [limit, setLimit] = usePaginationLimit(50);

  const load = async (p = 1, l = limit, s = search, silent = false) => {
    if (!silent) setLoading(true);
    setError(null);
    console.log("[ApplicationTracker] calling getApplications with params:", {
      status: statusFilter !== "all" ? statusFilter : undefined,
      gradeLevel: gradeFilter !== "all" ? gradeFilter : undefined,
      page: p,
      limit: l,
      search: s.trim() || undefined,
    });
    try {
      const res = await registrarApi.getApplications({
        status: statusFilter !== "all" ? statusFilter : undefined,
        gradeLevel: gradeFilter !== "all" ? gradeFilter : undefined,
        page: p,
        limit: l,
        search: s.trim() || undefined,
      });
      const payload = res.data as any;
      console.log("[ApplicationTracker] payload received:", payload);
      const apps = payload.applications ?? payload.data ?? payload.items ?? [];
      setApplications(apps);

      // The backend now returns a normalized meta object, but we handle fallbacks just in case
      setMeta(payload.meta ?? payload.pagination ?? {
        total: payload.total ?? apps.length,
        page: p,
        limit: l,
        totalPages: payload.totalPages ?? Math.ceil((payload.total ?? apps.length) / l)
      });
    } catch (err: any) {
      setError(err?.response?.data?.message ?? "Failed to load applications from EnrollPro.");
      setApplications([]);
      setMeta(null);
    } finally {
      if (!silent) setLoading(false);
    }
  };

  // Single effect: reset to page 1 when filters change, then load
  useEffect(() => {
    setPage(1);
    const timer = setTimeout(() => {
      void load(1, limit, search);
    }, search ? 500 : 0);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [statusFilter, gradeFilter, limit, search]);

  // Separate effect: reload when page changes (but not when filters change)
  useEffect(() => {
    void load(page, limit, search);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page]);

  // Keep client-side filter as a secondary "instant" filter for the current page
  const filtered = search
    ? applications.filter((a) => {
      const name = `${a.learner?.firstName ?? a.firstName ?? ""} ${a.learner?.lastName ?? a.lastName ?? ""}`.toLowerCase();
      const lrn = String(a.learner?.lrn ?? a.lrn ?? "");
      return name.includes(search.toLowerCase()) || lrn.includes(search);
    })
    : applications;

  return (
    <div className="space-y-6 animate-fade-in">
      <Breadcrumb items={[{ label: "Dashboard", href: "/registrar" }, { label: "Applications" }]} />

      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Enrollment Applications</h1>
          <p className="text-gray-600 mt-1">
            Enrollment application tracker ΓÇö read from EnrollPro. Verification actions must be done in EnrollPro directly.
          </p>
        </div>
        <Button onClick={() => void load(page, limit)} variant="outline" className="rounded-xl">
          <RefreshCw className="w-4 h-4 mr-2" /> Refresh
        </Button>
      </div>

      <Card className="border border-slate-200">
        <CardHeader className="border-b border-slate-100 pb-4">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
            <div className="flex items-center gap-3 flex-1">
              <div className="p-2 rounded-xl text-white" style={{ backgroundColor: colors.primary }}>
                <ClipboardList className="w-5 h-5" />
              </div>
              <div>
                <CardTitle>Applications</CardTitle>
                <CardDescription>{meta?.total ?? filtered.length} total</CardDescription>
              </div>
            </div>
            <div className="flex flex-wrap gap-2">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="SEARCH LRN, FIRST NAME, LAST NAME... or LRN..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="pl-9 w-56 rounded-xl border-gray-200"
                />
              </div>
              <Select value={gradeFilter} onValueChange={setGradeFilter}>
                <SelectTrigger className="w-40 rounded-xl border-gray-200">
                  <SelectValue placeholder="All Grades" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Grades</SelectItem>
                  <SelectItem value="GRADE_7">Grade 7</SelectItem>
                  <SelectItem value="GRADE_8">Grade 8</SelectItem>
                  <SelectItem value="GRADE_9">Grade 9</SelectItem>
                  <SelectItem value="GRADE_10">Grade 10</SelectItem>
                </SelectContent>
              </Select>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-40 rounded-xl border-gray-200">
                  <SelectValue placeholder="All Statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Statuses</SelectItem>
                  <SelectItem value="PENDING">Pending</SelectItem>
                  <SelectItem value="VERIFIED">Verified</SelectItem>
                  <SelectItem value="ENROLLED">Enrolled</SelectItem>
                  <SelectItem value="REJECTED">Rejected</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-0">
          {loading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="w-8 h-8 animate-spin" style={{ color: colors.primary }} />
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center py-16 text-center px-4">
              <AlertTriangle className="w-10 h-10 text-amber-500 mb-3" />
              <p className="text-gray-700 ">Unable to load applications</p>
              <p className="text-gray-500 text-sm mt-1">{error}</p>
              <Button onClick={() => void load(page, limit)} variant="outline" className="mt-4 rounded-xl">
                Try Again
              </Button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="bg-gray-50/80">
                    <TableHead className="font-bold text-gray-700">Applicant</TableHead>
                    <TableHead className="font-bold text-gray-700">LRN</TableHead>
                    <TableHead className="font-bold text-gray-700">Grade Applied</TableHead>
                    <TableHead className="font-bold text-gray-700">Type</TableHead>
                    <TableHead className="font-bold text-gray-700">Status</TableHead>
                    <TableHead className="font-bold text-gray-700">Submitted</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filtered.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={6} className="text-center py-12 text-gray-500">
                        No applications found
                      </TableCell>
                    </TableRow>
                  ) : (
                    filtered.map((app, i) => {
                      const learner = app.learner ?? app;
                      const status = app.status ?? "PENDING";
                      return (
                        <TableRow key={app.id ?? i}>
                          <TableCell className=" text-gray-900">
                            {learner.lastName}, {learner.firstName} {learner.middleName ?? ""}
                          </TableCell>
                          <TableCell className="font-mono text-sm text-gray-600">{learner.lrn ?? "ΓÇö"}</TableCell>
                          <TableCell>{app.gradeLevel?.name ?? app.gradeLevelName ?? "ΓÇö"}</TableCell>
                          <TableCell>
                            <Badge variant="outline" className="capitalize text-xs">
                              {(app.applicantType ?? app.learnerType ?? "ΓÇö").replace(/_/g, " ").toLowerCase()}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <Badge className={STATUS_COLORS[status] ?? "bg-gray-100 text-gray-600"}>
                              {status}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-sm text-gray-600">
                            {app.createdAt ? new Date(app.createdAt).toLocaleDateString("en-PH", { timeZone: 'Asia/Manila', timeZone: 'Asia/Manila' }) : "ΓÇö"}
                          </TableCell>
                        </TableRow>
                      );
                    })
                  )}
                </TableBody>
              </Table>
            </div>
          )}

          {/* Pagination */}
          {!loading && !error && meta && (
            <div className="border-t border-gray-100 px-6 py-4 flex items-center justify-between bg-gray-50/30">
              <div className="flex items-center gap-4 text-sm  text-slate-800">
                <span>
                  Showing {meta.total === 0 ? 0 : (page - 1) * limit + 1} to {Math.min(page * limit, meta.total)} of {meta.total} Learners
                </span>
                <div className="h-4 w-px bg-slate-300 mx-2" />
                <div className="flex items-center gap-2">
                  <span>Rows per page:</span>
                  <Select value={String(limit)} onValueChange={(v) => setLimit(Number(v))}>
                    <SelectTrigger className="h-9 w-20 rounded-lg border-slate-200 bg-muted">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="25">25</SelectItem>
                      <SelectItem value="50">50</SelectItem>
                      <SelectItem value="100">100</SelectItem>
                      <SelectItem value="250">250</SelectItem>
                      <SelectItem value="500">500</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex items-center gap-1">
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-9 w-9 rounded-lg border border-slate-200 bg-muted text-slate-400"
                  disabled={page <= 1}
                  onClick={() => setPage(1)}
                >
                  <ChevronsLeft className="h-4 w-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-9 w-9 rounded-lg border border-slate-200 bg-muted text-slate-400"
                  disabled={page <= 1}
                  onClick={() => setPage((p) => p - 1)}
                >
                  <ChevronLeft className="h-4 w-4" />
                </Button>

                <Button
                  variant="default"
                  size="sm"
                  className="h-9 w-9 rounded-lg bg-[#800000] hover:bg-[#600000] text-white font-bold shadow-sm"
                >
                  {page}
                </Button>

                <Button
                  variant="ghost"
                  size="icon"
                  className="h-9 w-9 rounded-lg border border-slate-200 bg-muted text-slate-400"
                  disabled={page >= meta.totalPages}
                  onClick={() => setPage((p) => p + 1)}
                >
                  <ChevronRight className="h-4 w-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-9 w-9 rounded-lg border border-slate-200 bg-muted text-slate-400"
                  disabled={page >= meta.totalPages}
                  onClick={() => setPage(meta.totalPages)}
                >
                  <ChevronsRight className="h-4 w-4" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

// @ts-nocheck
import { useState, useEffect } from "react";
import { usePaginationLimit } from '@/shared/hooks/usePaginationLimit';
import { CalendarCheck, Loader2, AlertTriangle, RefreshCw, Users, Search, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/features/smart/components/ui/card";
import { Badge } from "@/features/smart/components/ui/badge";
import { Button } from "@/features/smart/components/ui/button";
import { Input } from "@/features/smart/components/ui/input";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/features/smart/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/features/smart/components/ui/select";
import { registrarApi } from "@/features/smart/lib/api";
import { Breadcrumb } from "@/features/smart/components/ui/breadcrumb";
import { useTheme } from "@/features/smart/contexts/ThemeContext";

type QueueTab = "pending" | "expected";

export default function BOSYQueue() {
  const { colors } = useTheme();
  const [tab, setTab] = useState<QueueTab>("pending");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [items, setItems] = useState<any[]>([]);
  const [meta, setMeta] = useState<any>(null);
  const [search, setSearch] = useState("");
  const [gradeFilter, setGradeFilter] = useState("all");
  const [page, setPage] = useState(1);
  const [limit, setLimit] = usePaginationLimit(50);

  const load = async (p = 1, l = limit, s = search, g = gradeFilter, silent = false) => {
    if (!silent) setLoading(true);
    setError(null);
    try {
      let res: any;
      const params = {
        page: p,
        limit: l,
        search: s.trim() || undefined,
        gradeLevel: g !== "all" ? g : undefined
      };
      if (tab === "pending") {
        res = await registrarApi.getBosyQueue(params);
      } else {
        res = await registrarApi.getBosyExpectedQueue(params);
      }
      const payload = res.data as any;
      const rawItems: any[] = payload.items ?? payload.learners ?? payload.data ?? [];

      // Normalize: map the actual flat OR nested API field names from EnrollPro BOSY queue
      const normalized = rawItems.map((item: any) => {
        const l = item.learner ?? item;
        const rawSex = (l.sex ?? item.sex ?? "").toString().trim().toUpperCase();
        const sex = rawSex === "MALE" || rawSex === "M" ? "Male" : rawSex === "FEMALE" || rawSex === "F" ? "Female" : "";

        // Helper to extract nested names robustly
        const getName = (obj: any, flatKey: string) => {
          if (typeof obj === "string") return obj;
          if (obj && typeof obj === "object" && obj.name) return obj.name;
          return item[flatKey] ?? "";
        };

        return {
          enrollmentRecordId: item.applicationId ?? item.enrollmentRecordId ?? item.id,
          learnerId: l.id ?? item.learnerId,
          lrn: l.lrn ?? item.lrn ?? "",
          firstName: l.firstName ?? item.firstName ?? "",
          lastName: l.lastName ?? item.lastName ?? "",
          middleName: l.middleName ?? item.middleName ?? "",
          sex,
          status: item.status,
          // BOSY queue can use flat or nested field names depending on EnrollPro version/endpoint
          gradeLevelName: getName(item.priorGradeLevel ?? item.gradeLevel, "gradeLevelName"),
          priorSectionName: getName(item.priorSection ?? item.section, "priorSectionName"),
          priorAdviserName: getName(item.priorAdviser ?? item.adviser, "priorAdviserName"),
          finalAverage: item.finalAverage ?? item.previousGenAve ?? item.priorFinalAverage ?? null,
        };
      });

      setItems(normalized);
      setMeta(payload.meta ?? payload.pagination ?? {
        total: payload.total ?? normalized.length,
        page: p,
        limit: l,
        totalPages: payload.totalPages ?? Math.ceil((payload.total ?? normalized.length) / l)
      });
    } catch (err: any) {
      setError(err?.response?.data?.message ?? "Failed to load BOSY data from EnrollPro.");
      setItems([]);
      setMeta(null);
    } finally {
      if (!silent) setLoading(false);
    }
  };

  // Reset to page 1 when filters change
  useEffect(() => {
    setPage(1);
  }, [tab, limit, search, gradeFilter]);

  // Load data when page or other dependencies change
  useEffect(() => {
    const timer = setTimeout(() => {
      void load(page, limit, search, gradeFilter);
    }, search ? 500 : 0); // Debounce search
    return () => clearTimeout(timer);
  }, [page, tab, limit, search, gradeFilter]);

  // Keep client-side filter as a secondary "instant" filter for the current page
  const filtered = search
    ? items.filter((item) => {
      const name = `${item.firstName} ${item.lastName}`.toLowerCase();
      const lrn = String(item.lrn);
      return name.includes(search.toLowerCase()) || lrn.includes(search);
    })
    : items;

  return (
    <div className="space-y-6 animate-fade-in">
      <Breadcrumb items={[{ label: "Dashboard", href: "/registrar" }, { label: "BOSY Queue" }]} />

      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">BOSY Queue</h1>
          <p className="text-gray-600 mt-1">
            Beginning of School Year ΓÇö learner return confirmation tracking. Read-only from EnrollPro.
          </p>
        </div>
        <Button onClick={() => void load(page, limit, search)} variant="outline" className="rounded-xl">
          <RefreshCw className="w-4 h-4 mr-2" /> Refresh
        </Button>
      </div>

      {/* Tab switcher */}
      <div className="flex gap-2">
        <Button
          variant={tab === "pending" ? "default" : "outline"}
          onClick={() => setTab("pending")}
          className="rounded-xl shadow-sm"
          style={tab === "pending" ? { backgroundColor: colors.primary } : {}}
        >
          Pending Confirmation
        </Button>
        <Button
          variant={tab === "expected" ? "default" : "outline"}
          onClick={() => setTab("expected")}
          className="rounded-xl shadow-sm"
          style={tab === "expected" ? { backgroundColor: colors.primary } : {}}
        >
          Expected (Not Yet in Pipeline)
        </Button>
      </div>

      <Card className="border border-slate-200 shadow-sm">
        <CardHeader className="border-b border-slate-100 pb-4">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
            <div className="flex items-center gap-3 flex-1">
              <div className="p-2 rounded-xl text-white shadow-sm" style={{ backgroundColor: colors.primary }}>
                <CalendarCheck className="w-5 h-5" />
              </div>
              <div>
                <CardTitle>{tab === "pending" ? "Pending Confirmation Queue" : "Expected Return Queue"}</CardTitle>
                <CardDescription>{meta?.total ?? filtered.length} Learners Found</CardDescription>
              </div>
            </div>
            <div className="flex flex-wrap gap-2">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="SEARCH LRN, FIRST NAME, LAST NAME... or LRN..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="pl-9 w-64 rounded-xl border-gray-200"
                />
              </div>
              <Select value={gradeFilter} onValueChange={setGradeFilter}>
                <SelectTrigger className="w-40 rounded-xl border-gray-200 shadow-sm">
                  <SelectValue placeholder="All Grades" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Grades</SelectItem>
                  <SelectItem value="GRADE_7">Grade 7</SelectItem>
                  <SelectItem value="GRADE_8">Grade 8</SelectItem>
                  <SelectItem value="GRADE_9">Grade 9</SelectItem>
                  <SelectItem value="GRADE_10">Grade 10</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {loading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="w-8 h-8 animate-spin" style={{ color: colors.primary }} />
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center py-16 text-center px-4">
              <AlertTriangle className="w-10 h-10 text-amber-500 mb-3" />
              <p className="text-gray-700 ">Unable to load BOSY data</p>
              <p className="text-gray-500 text-sm mt-1">{error}</p>
              <Button onClick={() => void load(page, limit, search)} variant="outline" className="mt-4 rounded-xl">Try Again</Button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="bg-gray-50/80">
                    <TableHead className="font-bold text-gray-700">LRN</TableHead>
                    <TableHead className="font-bold text-gray-700">Learner Name</TableHead>
                    <TableHead className="font-bold text-gray-700">Sex</TableHead>
                    <TableHead className="font-bold text-gray-700">Prior Grade</TableHead>
                    <TableHead className="font-bold text-gray-700">Prior Section</TableHead>
                    {tab === "expected" && (
                      <TableHead className="font-bold text-gray-700">Final Avg</TableHead>
                    )}
                    {tab === "pending" && (
                      <TableHead className="font-bold text-gray-700">Status</TableHead>
                    )}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filtered.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={tab === "expected" ? 6 : 6} className="text-center py-12">
                        <Users className="w-10 h-10 mx-auto text-gray-300 mb-2" />
                        <p className="text-gray-500">No learners found matching your criteria</p>
                      </TableCell>
                    </TableRow>
                  ) : (
                    filtered.map((item, i) => (
                      <TableRow key={item.enrollmentRecordId ?? item.learnerId ?? i} className="hover:bg-slate-50/50">
                        <TableCell className="font-mono text-sm text-gray-600">{item.lrn ?? "ΓÇö"}</TableCell>
                        <TableCell className=" text-gray-900">
                          {item.lastName}, {item.firstName} {item.middleName ?? ""}
                        </TableCell>
                        <TableCell>
                          {item.sex
                            ? <Badge className={`${item.sex?.toUpperCase() === "MALE" ? "bg-blue-600/10 text-blue-600 border-blue-600 border-2" : "bg-pink-600/10 text-pink-600 border-pink-600 border-2"} uppercase`}>{item.sex}</Badge>
                            : <span className="text-gray-400">N/A</span>}
                        </TableCell>
                        <TableCell>{item.gradeLevelName || "ΓÇö"}</TableCell>
                        <TableCell>{item.priorSectionName || "ΓÇö"}</TableCell>
                        {tab === "expected" && (
                          <TableCell className=" text-slate-700">
                            {item.finalAverage != null ? item.finalAverage.toFixed(1) : "ΓÇö"}
                          </TableCell>
                        )}
                        {tab === "pending" && (
                          <TableCell>
                            <Badge className="bg-amber-100 text-amber-700">
                              {item.status ?? "PENDING"}
                            </Badge>
                          </TableCell>
                        )}
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </div>
          )}

          {/* Pagination Footer */}
          {!loading && !error && meta && (
            <div className="border-t border-gray-100 px-6 py-4 flex items-center justify-between bg-gray-50/30">
              <div className="flex items-center gap-4 text-sm  text-slate-800">
                <span>
                  Showing {meta.total === 0 ? 0 : (page - 1) * limit + 1} to {Math.min(page * limit, meta.total)} of {meta.total} Learners
                </span>
                <div className="h-4 w-px bg-slate-300 mx-2" />
                <div className="flex items-center gap-2">
                  <span>Rows per page:</span>
                  <Select value={String(limit)} onValueChange={(v) => setLimit(Number(v))}>
                    <SelectTrigger className="h-9 w-20 rounded-lg border-slate-200 bg-muted shadow-sm">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="25">25</SelectItem>
                      <SelectItem value="50">50</SelectItem>
                      <SelectItem value="100">100</SelectItem>
                      <SelectItem value="250">250</SelectItem>
                      <SelectItem value="500">500</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex items-center gap-1">
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-9 w-9 rounded-lg border border-slate-200 bg-muted text-slate-400"
                  disabled={page <= 1}
                  onClick={() => setPage(1)}
                >
                  <ChevronsLeft className="h-4 w-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-9 w-9 rounded-lg border border-slate-200 bg-muted text-slate-400"
                  disabled={page <= 1}
                  onClick={() => setPage((p) => p - 1)}
                >
                  <ChevronLeft className="h-4 w-4" />
                </Button>

                <Button
                  variant="default"
                  size="sm"
                  className="h-9 min-w-[36px] px-2 rounded-lg font-bold shadow-sm"
                  style={{ backgroundColor: colors.primary }}
                >
                  {page}
                </Button>

                <Button
                  variant="ghost"
                  size="icon"
                  className="h-9 w-9 rounded-lg border border-slate-200 bg-muted text-slate-400"
                  disabled={page >= meta.totalPages}
                  onClick={() => setPage((p) => p + 1)}
                >
                  <ChevronRight className="h-4 w-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-9 w-9 rounded-lg border border-slate-200 bg-muted text-slate-400"
                  disabled={page >= meta.totalPages}
                  onClick={() => setPage(meta.totalPages)}
                >
                  <ChevronsRight className="h-4 w-4" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

