                </td>
                <td className={`border-r border-gray-600 p-2 text-center  ${(sg.T3 ?? 0) < 75 && sg.T3 ? 'text-red-600' : 'text-gray-900'}`}>
                  {sg.T3 ?? ''}
                </td>
