          <div className="text-center mt-4 text-xs text-gray-600 italic">
            <p>(School Seal)</p>
            <p className="mt-2">Not valid without official seal</p>
          </div>
        </div>
      </div>
    );
  }

  // Loading or fallback
  return (
    <div className="flex items-center justify-center h-64">
      <p className="text-gray-500">Loading...</p>
    </div>
  );
}

