}

// @ts-nocheck
import { useState, useEffect } from "react";
import { BarChart3, Loader2, AlertTriangle, RefreshCw, BookOpen, User, WifiOff } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/features/smart/components/ui/card";
import { Badge } from "@/features/smart/components/ui/badge";
import { Button } from "@/features/smart/components/ui/button";
import { Input } from "@/features/smart/components/ui/input";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/features/smart/components/ui/table";
import { registrarApi } from "@/features/smart/lib/api";
import { Breadcrumb } from "@/features/smart/components/ui/breadcrumb";
import { useTheme } from "@/features/smart/contexts/ThemeContext";

export default function TeachingLoad() {
  const { colors } = useTheme();
  const [loadLoading, setLoadLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [faculty, setFaculty] = useState<any[]>([]);

  const [coverageLoading, setCoverageLoading] = useState(true);
  const [coverageError, setCoverageError] = useState<string | null>(null);
  const [coverage, setCoverage] = useState<any>(null);

  const [search, setSearch] = useState("");
  const [isLocalDbFallback, setIsLocalDbFallback] = useState(false);

  const loadAll = async (silent = false) => {
    if (!silent) { setLoadLoading(true); setCoverageLoading(true); }
    setLoadError(null);
    setCoverageError(null);
    setIsLocalDbFallback(false);

    void (async () => {
      try {
        const res = await registrarApi.getAtlasTeachingLoads();
        const payload = res.data as any;
        setFaculty(payload.faculty ?? payload.teachers ?? payload.data ?? []);
        if (payload.source === "smart-local-db") setIsLocalDbFallback(true);
      } catch (err: any) {
        const detail = err?.response?.data?.error ?? err?.response?.data?.message ?? err?.message ?? "";
        setLoadError(`Failed to load teaching loads: ${detail}`);
        setFaculty([]);
      } finally {
        setLoadLoading(false);
      }
    })();

    void (async () => {
      try {
        const res = await registrarApi.getAtlasSubjectCoverage();
        setCoverage(res.data);
      } catch (err: any) {
        const detail = err?.response?.data?.error ?? err?.response?.data?.message ?? err?.message ?? "";
        setCoverageError(`Failed to load subject coverage: ${detail}`);
        setCoverage(null);
      } finally {
        setCoverageLoading(false);
      }
    })();
  };

  useEffect(() => { void loadAll(); }, []);

  const filtered = search
    ? faculty.filter((f) => {
      const name = `${f.firstName ?? ""} ${f.lastName ?? ""}`.toLowerCase();
      return name.includes(search.toLowerCase());
    })
    : faculty;

  const minutesToHours = (m: number) => `${Math.floor(m / 60)}h ${m % 60}m`;

  return (
    <div className="space-y-6 animate-fade-in">
      <Breadcrumb items={[{ label: "Dashboard", href: "/registrar" }, { label: "Teaching Load" }]} />

      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Teaching Load</h1>
          <p className="text-gray-600 mt-1 flex items-center gap-2">
            Faculty teaching assignments and subject coverage ΓÇö read-only from ATLAS.
            <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-100 ">
              AY 2026-2027
            </Badge>
          </p>
        </div>
        <Button onClick={() => void loadAll()} variant="outline" className="rounded-xl">
          <RefreshCw className="w-4 h-4 mr-2" /> Refresh
        </Button>
      </div>

      {/* Local DB fallback banner */}
      {isLocalDbFallback && (
        <div className="flex items-center gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          <WifiOff className="w-4 h-4 shrink-0 text-amber-600" />
          <span>
            <strong>ATLAS is currently offline.</strong> Showing last synced data from SMART's local database. Data may not reflect the latest assignments.
          </span>
        </div>
      )}

      {/* Stats bar */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card className="border border-slate-200">
          <CardContent className="pt-5">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl text-white" style={{ backgroundColor: colors.primary }}>
                <User className="w-5 h-5" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900">{loadLoading ? "ΓÇª" : faculty.length}</p>
                <p className="text-sm text-gray-500">Faculty Members</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card className="border border-slate-200">
          <CardContent className="pt-5">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl bg-emerald-500 text-white">
                <BookOpen className="w-5 h-5" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900">
                  {coverageLoading ? "ΓÇª" : coverage ? (coverage.count ?? 0) - (coverage.unassignedCount ?? 0) : "ΓÇö"}
                </p>
                <p className="text-sm text-gray-500">Subjects Assigned</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card className="border border-slate-200">
          <CardContent className="pt-5">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl bg-amber-500 text-white">
                <AlertTriangle className="w-5 h-5" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900">
                  {coverageLoading ? "ΓÇª" : coverage?.unassignedCount ?? "ΓÇö"}
                </p>
                <p className="text-sm text-gray-500">Unassigned Subjects</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Teaching Load Table */}
      <Card className="border border-slate-200">
        <CardHeader className="border-b border-slate-100 pb-4">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
            <div className="flex items-center gap-3 flex-1">
              <div className="p-2 rounded-xl text-white" style={{ backgroundColor: colors.primary }}>
                <BarChart3 className="w-5 h-5" />
              </div>
              <div>
                <CardTitle>Faculty Teaching Loads</CardTitle>
                <CardDescription>Subject assignments per faculty member</CardDescription>
              </div>
            </div>
            <Input
              placeholder="Search facultyΓÇª"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-52 rounded-xl border-gray-200"
            />
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {loadLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="w-8 h-8 animate-spin" style={{ color: colors.primary }} />
            </div>
          ) : loadError ? (
            <div className="flex flex-col items-center justify-center py-16 text-center px-4">
              <AlertTriangle className="w-10 h-10 text-amber-500 mb-3" />
              <p className="text-gray-700 ">Unable to load teaching loads</p>
              <p className="text-gray-500 text-sm mt-1">{loadError}</p>
              <Button onClick={() => void loadAll()} variant="outline" className="mt-4 rounded-xl">Try Again</Button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="bg-gray-50/80">
                    <TableHead className="font-bold text-gray-700">Personnel Name</TableHead>
                    <TableHead className="font-bold text-gray-700 text-center">Subjects</TableHead>
                    <TableHead className="font-bold text-gray-700">Weekly Load</TableHead>
                    <TableHead className="font-bold text-gray-700 text-center">Load %</TableHead>
                    <TableHead className="font-bold text-gray-700">Assigned Subjects</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filtered.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={5} className="text-center py-12 text-gray-500">
                        No faculty found
                      </TableCell>
                    </TableRow>
                  ) : (
                    filtered.map((f: any, i: number) => {
                      // Pure teaching load percentage = ((Total Subject Hours - Advisory Equivalent) / Max Hours) * 100
                      const rawSubjectHours = f.subjectHours ?? f.weeklyHours ?? 0;
                      const advHours = f.isClassAdviser ? (f.advisoryEquivalentHours ?? 0) : 0;
                      const pureTeachingHours = Math.max(0, rawSubjectHours - advHours);

                      const loadPct = f.maxHoursPerWeek
                        ? Math.round((pureTeachingHours / f.maxHoursPerWeek) * 100)
                        : (f.loadPercentage ?? 0);

                      return (
                        <TableRow key={f.facultyId ?? i}>
                          <TableCell className=" text-gray-900">
                            {f.firstName && f.lastName
                              ? `${f.lastName}, ${f.firstName}`
                              : f.name ?? "ΓÇö"}
                          </TableCell>
                          <TableCell className="text-center">
                            <Badge
                              className={
                                (f.assignedSubjects?.length ?? f.subjectCount ?? 0) > 0
                                  ? "bg-emerald-100 text-emerald-700"
                                  : "bg-gray-100 text-gray-500"
                              }
                            >
                              {f.subjectCount ?? f.assignedSubjects?.length ?? 0}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <div className="flex flex-col">
                              <span className=" text-gray-900">
                                {f.subjectHours != null
                                  ? `${f.subjectHours}h`
                                  : f.totalMinutesPerWeek != null
                                    ? minutesToHours(f.totalMinutesPerWeek)
                                    : f.weeklyHours != null
                                      ? `${f.weeklyHours}h`
                                      : "ΓÇö"}
                              </span>
                              {f.maxHoursPerWeek != null && (
                                <span className="text-[10px] text-gray-400">Max: {f.maxHoursPerWeek}h</span>
                              )}
                            </div>
                          </TableCell>
                          <TableCell className="text-center">
                            <div className="flex flex-col items-center gap-1">
                              <span className={`text-sm font-bold ${loadPct > 100 ? 'text-red-600' : 'text-emerald-600'}`}>
                                {loadPct}%
                              </span>
                              <div className="w-16 h-1 bg-gray-100 rounded-full overflow-hidden">
                                <div
                                  className={`h-full ${loadPct > 100 ? 'bg-red-500' : 'bg-emerald-500'}`}
                                  style={{ width: `${Math.min(loadPct, 100)}%` }}
                                />
                              </div>
                            </div>
                          </TableCell>
                          <TableCell className="text-sm text-gray-600 max-w-xs">
                            {Array.isArray(f.assignments)
                              ? f.assignments.map((a: any) => a.subject?.name ?? a.subject?.code ?? a.subjectCode ?? "").filter(Boolean).join(", ") || "ΓÇö"
                              : Array.isArray(f.assignedSubjects)
                                ? f.assignedSubjects.map((s: any) => s.name ?? s.code ?? s).join(", ")
                                : f.subjects ?? "ΓÇö"}
                          </TableCell>
                        </TableRow>
                      );
                    })
                  )}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Unassigned Subjects */}
      {!coverageLoading && coverage?.unassigned?.length > 0 && (
        <Card className="border border-amber-200 bg-amber-50/50">
          <CardHeader className="border-b border-amber-100 pb-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl bg-amber-500 text-white">
                <AlertTriangle className="w-5 h-5" />
              </div>
              <div>
                <CardTitle className="text-amber-800">Unassigned Subjects ({coverage.unassignedCount})</CardTitle>
                <CardDescription className="text-amber-600">Subjects without a faculty assignment in ATLAS</CardDescription>
              </div>
            </div>
          </CardHeader>
          <CardContent className="pt-4">
            <div className="flex flex-wrap gap-2">
              {coverage.unassigned.map((s: any) => (
                <Badge key={s.id} variant="outline" className="border-amber-300 text-amber-700 bg-amber-100">
                  {s.code ? `${s.code} ΓÇö ` : ""}{s.name}
                </Badge>
              ))}
            </div>
            {coverageError && <p className="text-red-500 text-sm mt-3">{coverageError}</p>}
          </CardContent>
        </Card>
      )}

      {coverageError && !coverage && (
        <div className="text-center py-4 text-amber-600 text-sm">
          <AlertTriangle className="w-4 h-4 inline mr-1" /> {coverageError}
        </div>
      )}
    </div>
  );
}

// @ts-nocheck
import { useEffect, useState } from "react";
import { Calendar as CalendarIcon, Users, Check, X, Clock, FileText, Save, CheckCircle2, AlertCircle, ClipboardCheck, RefreshCw } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/features/smart/components/ui/card";
import { Button } from "@/features/smart/components/ui/button";
import { Input } from "@/features/smart/components/ui/input";
import { Label } from "@/features/smart/components/ui/label";
import { _Badge } from "@/features/smart/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/features/smart/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/features/smart/components/ui/select";
import { useTheme } from "@/features/smart/contexts/ThemeContext";
import { SERVER_URL } from "@/features/smart/lib/api";
import axios from "axios";

interface Student {
  studentId: string;
  lrn: string;
  firstName: string;
  middleName?: string;
  lastName: string;
  status: "PRESENT" | "ABSENT" | "LATE" | "EXCUSED";
  remarks?: string;
  attendanceId?: string | null;
}

interface Section {
  id: string;
  name: string;
  gradeLevel: string;
}

interface AttendanceData {
  section: Section;
  date: string;
  attendance: Student[];
}

const gradeLevelLabels: Record<string, string> = {
  GRADE_7: "Grade 7",
  GRADE_8: "Grade 8",
  GRADE_9: "Grade 9",
  GRADE_10: "Grade 10",
};

export default function Attendance() {
  const { _colors } = useTheme();
  const [sections, setSections] = useState<Section[]>([]);
  const [selectedSection, setSelectedSection] = useState<string>("");
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split("T")[0]);
  const [attendanceData, setAttendanceData] = useState<AttendanceData | null>(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);

  // Fetch teacher's sections
  useEffect(() => {
    const fetchSections = async () => {
      try {
        const token = sessionStorage.getItem("token");

        // Get class assignments
        const classResponse = await axios.get(`${SERVER_URL}/api/grades/my-classes`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        // Get advisory section
        const advisoryResponse = await axios.get(`${SERVER_URL}/api/advisory/my-advisory`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        const sectionsMap = new Map<string, Section>();

        // Add sections from class assignments (API returns array directly)
        if (Array.isArray(classResponse.data)) {
          classResponse.data.forEach((assignment: any) => {
            if (assignment.section && !sectionsMap.has(assignment.section.id)) {
              sectionsMap.set(assignment.section.id, {
                id: assignment.section.id,
                name: assignment.section.name,
                gradeLevel: assignment.section.gradeLevel,
              });
            }
          });
        }

        // Add advisory section if exists (API returns object with section property)
        if (advisoryResponse.data?.hasAdvisory && advisoryResponse.data?.section) {
          const advisorySection = advisoryResponse.data.section;
          if (!sectionsMap.has(advisorySection.id)) {
            sectionsMap.set(advisorySection.id, {
              id: advisorySection.id,
              name: advisorySection.name,
              gradeLevel: advisorySection.gradeLevel,
            });
          }
        }

        const sectionsList = Array.from(sectionsMap.values());
        setSections(sectionsList);

        // Auto-select advisory section if available
        if (advisoryResponse.data?.hasAdvisory && advisoryResponse.data?.section) {
          setSelectedSection(advisoryResponse.data.section.id);
        } else if (sectionsList.length > 0) {
          setSelectedSection(sectionsList[0].id);
        }
      } catch (error) {
        console.error("Error fetching sections:", error);
      }
    };

    fetchSections();
  }, []);

  // Fetch attendance when section or date changes
  useEffect(() => {
    if (selectedSection && selectedDate) {
      fetchAttendance();
    }
  }, [selectedSection, selectedDate]);

  const fetchAttendance = async () => {
    setLoading(true);
    setMessage(null);
    try {
      const token = sessionStorage.getItem("token");
      const response = await axios.get(
        `${SERVER_URL}/api/attendance/section/${selectedSection}?date=${selectedDate}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setAttendanceData(response.data.data);
    } catch (error: any) {
      setMessage({ type: "error", text: error.response?.data?.message || "Failed to load attendance" });
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = (studentId: string, status: "PRESENT" | "ABSENT" | "LATE" | "EXCUSED") => {
    if (!attendanceData) return;
    setAttendanceData({
      ...attendanceData,
      attendance: attendanceData.attendance.map((student) =>
        student.studentId === studentId ? { ...student, status } : student
      ),
    });
  };

  const handleRemarksChange = (studentId: string, remarks: string) => {
    if (!attendanceData) return;
    setAttendanceData({
      ...attendanceData,
      attendance: attendanceData.attendance.map((student) =>
        student.studentId === studentId ? { ...student, remarks } : student
      ),
    });
  };

  const markAllPresent = () => {
    if (!attendanceData) return;
    setAttendanceData({
      ...attendanceData,
      attendance: attendanceData.attendance.map((student) => ({
        ...student,
        status: "PRESENT",
        remarks: "",
      })),
    });
  };

  const saveAttendance = async () => {
    if (!attendanceData) return;

    setSaving(true);
    setMessage(null);
    try {
      const token = sessionStorage.getItem("token");
      await axios.post(
        `${SERVER_URL}/api/attendance/bulk`,
        {
          sectionId: selectedSection,
          date: selectedDate,
          attendance: attendanceData.attendance.map((s) => ({
            studentId: s.studentId,
            status: s.status,
            remarks: s.remarks || null,
          })),
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setMessage({ type: "success", text: "Attendance saved successfully!" });
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      setMessage({ type: "error", text: error.response?.data?.message || "Failed to save attendance" });
    } finally {
      setSaving(false);
    }
  };

  const getStatusStats = () => {
    if (!attendanceData) return { present: 0, absent: 0, late: 0, excused: 0 };
    return {
      present: attendanceData.attendance.filter((s) => s.status === "PRESENT").length,
      absent: attendanceData.attendance.filter((s) => s.status === "ABSENT").length,
      late: attendanceData.attendance.filter((s) => s.status === "LATE").length,
      excused: attendanceData.attendance.filter((s) => s.status === "EXCUSED").length,
    };
  };

  const stats = getStatusStats();

  return (
    <div className="space-y-8 animate-fade-in max-w-7xl mx-auto pb-12">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 rounded-xl bg-indigo-600 text-white shadow-lg">
              <ClipboardCheck className="w-5 h-5" />
            </div>
            <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Daily Attendance</h1>
          </div>
          <p className="text-slate-500 ">Manage and track student attendance records</p>
        </div>
      </div>

      {/* Control Panel - Refined Glass Style */}
      <Card className="border-0 shadow-xl shadow-slate-200/50 rounded-[2rem] overflow-hidden bg-muted/90 backdrop-blur-md">
        <CardContent className="p-8">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
            <div className="space-y-2">
              <Label htmlFor="section" className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-1">Target Section</Label>
              <Select value={selectedSection} onValueChange={setSelectedSection}>
                <SelectTrigger id="section" className="h-12 bg-slate-50 border-slate-100 rounded-xl text-xs font-bold shadow-sm focus:ring-2 focus:ring-indigo-100 transition-all">
                  <SelectValue placeholder="Select section">
                    {selectedSection && sections.length > 0 ? (
                      (() => {
                        const selected = sections.find(s => s.id === selectedSection);
                        return selected ? `${gradeLevelLabels[selected.gradeLevel]} - ${selected.name}` : 'Select section';
                      })()
                    ) : 'Select section'}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent className="rounded-xl border-slate-200 shadow-xl">
                  {sections.map((section) => (
                    <SelectItem key={section.id} value={section.id} className="text-xs font-bold uppercase">
                      {gradeLevelLabels[section.gradeLevel]} - {section.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="date" className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-1">Attendance Date</Label>
              <div className="relative">
                <Input
                  id="date"
                  type="date"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  max={new Date().toISOString().split("T")[0]}
                  className="h-12 bg-slate-50 border-slate-100 rounded-xl text-xs font-bold shadow-sm focus:ring-2 focus:ring-indigo-100 transition-all pl-10"
                />
                <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
              </div>
            </div>

            <div className="md:col-span-2 flex flex-col sm:flex-row gap-3">
              <Button
                onClick={markAllPresent}
                variant="outline"
                className="flex-1 h-12 rounded-xl border-slate-200 text-slate-700 hover:bg-slate-50 font-bold transition-all"
                disabled={!attendanceData || loading}
              >
                <CheckCircle2 className="w-4 h-4 mr-2 text-emerald-500" />
                MARK ALL PRESENT
              </Button>
              <Button
                onClick={saveAttendance}
                disabled={saving || !attendanceData}
                className="flex-1 h-12 rounded-xl bg-slate-900 hover:bg-slate-800 text-white shadow-xl shadow-slate-200 font-bold text-[10px] tracking-widest uppercase transition-all"
              >
                {saving ? (
                  <>
                    <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                    SYNCING...
                  </>
                ) : (
                  <>
                    <Save className="w-4 h-4 mr-2" />
                    COMMIT CHANGES
                  </>
                )}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Messaging */}
      {message && (
        <div
          className={`p-5 rounded-2xl border-0 shadow-lg animate-slide-up ${message.type === "success"
            ? "bg-emerald-50 text-emerald-700 shadow-emerald-100"
            : "bg-rose-50 text-rose-700 shadow-rose-100"
            }`}
        >
          <div className="flex items-center gap-3">
            {message.type === "success" ? (
              <CheckCircle2 className="w-5 h-5" />
            ) : (
              <AlertCircle className="w-5 h-5" />
            )}
            <span className="font-bold text-sm tracking-tight">{message.text}</span>
          </div>
        </div>
      )}

      {/* Quick Stats Grid */}
      {attendanceData && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
          {[
            { label: "PRESENT", value: stats.present, icon: CheckCircle2, color: "emerald" },
            { label: "ABSENT", value: stats.absent, icon: X, color: "rose" },
            { label: "LATE", value: stats.late, icon: Clock, color: "amber" },
            { label: "EXCUSED", value: stats.excused, icon: FileText, color: "indigo" },
          ].map((stat) => (
            <Card key={stat.label} className="border-0 shadow-lg shadow-slate-200/50 rounded-3xl bg-muted overflow-hidden">
              <CardContent className="p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">{stat.label}</p>
                    <p className={`text-3xl font-bold text-${stat.color}-600`}>{stat.value}</p>
                  </div>
                  <div className={`p-3 rounded-2xl bg-${stat.color}-50 text-${stat.color}-500`}>
                    <stat.icon className="w-6 h-6" />
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Main Table - Modern Corporate List */}
      <Card className="border-0 shadow-2xl shadow-slate-200/40 rounded-[2.5rem] overflow-hidden bg-muted">
        <CardHeader className="p-8 border-b border-slate-50 bg-slate-50/30">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-xl font-bold text-slate-900">
                {attendanceData?.section
                  ? `${gradeLevelLabels[attendanceData.section.gradeLevel]} - ${attendanceData.section.name}`
                  : "Attendance Masterlist"
                }
              </CardTitle>
              <CardDescription className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">
                {attendanceData ? `${attendanceData.attendance.length} Learners Enrolled` : "Select filters to view list"}
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {loading ? (
            <div className="py-24 text-center">
              <RefreshCw className="w-12 h-12 text-indigo-500 animate-spin mx-auto mb-4" />
              <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Pulling Records...</p>
            </div>
          ) : attendanceData ? (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="bg-slate-50/50 hover:bg-transparent border-0">
                    <TableHead className="px-8 text-[10px] font-bold text-slate-400 uppercase tracking-widest">LRN</TableHead>
                    <TableHead className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Learner Name</TableHead>
                    <TableHead className="text-[10px] font-bold text-slate-400 uppercase tracking-widest text-center">Attendance Status</TableHead>
                    <TableHead className="px-8 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Notes / Remarks</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {attendanceData.attendance.map((student) => (
                    <TableRow key={student.studentId} className="hover:bg-slate-50/50 transition-all border-slate-50 group">
                      <TableCell className="px-8 font-mono text-xs text-slate-400 font-bold group-hover:text-slate-900 transition-colors">
                        {student.lrn}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-xs">
                            {student.lastName.charAt(0)}
                          </div>
                          <span className="font-bold text-slate-900 tracking-tight">
                            {student.lastName}, {student.firstName}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex justify-center gap-1">
                          {[
                            { id: "PRESENT", icon: Check, color: "emerald", label: "P" },
                            { id: "ABSENT", icon: X, color: "rose", label: "A" },
                            { id: "LATE", icon: Clock, color: "amber", label: "L" },
                            { id: "EXCUSED", icon: FileText, color: "indigo", label: "E" }
                          ].map((option) => (
                            <button
                              key={option.id}
                              onClick={() => handleStatusChange(student.studentId, option.id as any)}
                              className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${student.status === option.id
                                ? `bg-${option.color}-500 text-white shadow-lg shadow-${option.color}-200 scale-110`
                                : `bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-600`
                                }`}
                              title={option.id}
                            >
                              <option.icon className="w-4 h-4" />
                            </button>
                          ))}
                        </div>
                      </TableCell>
                      <TableCell className="px-8">
                        <Input
                          placeholder="Add remark..."
                          value={student.remarks || ""}
                          onChange={(e) => handleRemarksChange(student.studentId, e.target.value)}
                          className="h-10 bg-transparent border-0 border-b border-transparent hover:border-slate-200 focus:border-indigo-500 focus:ring-0 rounded-md text-xs  transition-all"
                        />
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          ) : (
            <div className="py-32 text-center bg-slate-50/50">
              <div className="w-20 h-20 bg-muted rounded-[2rem] shadow-sm flex items-center justify-center mx-auto mb-6">
                <Users className="w-8 h-8 text-slate-200" />
              </div>
              <h3 className="text-slate-900 font-bold text-sm uppercase tracking-widest mb-2">No Records Selected</h3>
              <p className="text-slate-400 text-xs ">Configure section and date to begin tracking attendance</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

// @ts-nocheck
import { useState } from "react";
import { Download, Calendar, Filter, FileSpreadsheet, Eye } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/features/smart/components/ui/card";
import { Button } from "@/features/smart/components/ui/button";
import { Input } from "@/features/smart/components/ui/input";
import { Label } from "@/features/smart/components/ui/label";
import { Badge } from "@/features/smart/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/features/smart/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/features/smart/components/ui/select";
import { useTheme } from "@/features/smart/contexts/ThemeContext";
import { SERVER_URL } from "@/features/smart/lib/api";
import axios from "axios";

interface Section {
  id: string;
  name: string;
  gradeLevel: string;
}

interface AttendanceSummary {
  studentId: string;
  lrn: string;
  firstName: string;
  middleName?: string;
  lastName: string;
  present: number;
  absent: number;
  late: number;
  excused: number;
  total: number;
}

const gradeLevelLabels: Record<string, string> = {
  GRADE_7: "Grade 7",
  GRADE_8: "Grade 8",
  GRADE_9: "Grade 9",
  GRADE_10: "Grade 10",
};

export default function AttendanceReports() {
  const { colors } = useTheme();
  const [sections, setSections] = useState<Section[]>([]);
  const [selectedSection, setSelectedSection] = useState<string>("");
  const [startDate, setStartDate] = useState<string>("");
  const [endDate, setEndDate] = useState<string>(new Date().toISOString().split("T")[0]);
  const [summary, setSummary] = useState<AttendanceSummary[]>([]);
  const [loading, setLoading] = useState(false);
  const [downloading, setDownloading] = useState(false);

  // Fetch sections on mount
  useState(() => {
    const fetchSections = async () => {
      try {
        const token = sessionStorage.getItem("token");
        const [classResponse, advisoryResponse] = await Promise.all([
          axios.get(`${SERVER_URL}/api/grades/my-classes`, {
            headers: { Authorization: `Bearer ${token}` },
          }),
          axios.get(`${SERVER_URL}/api/advisory/my-advisory`, {
            headers: { Authorization: `Bearer ${token}` },
          }),
        ]);

        const sectionsMap = new Map<string, Section>();

        if (Array.isArray(classResponse.data)) {
          classResponse.data.forEach((assignment: any) => {
            if (assignment.section && !sectionsMap.has(assignment.section.id)) {
              sectionsMap.set(assignment.section.id, {
                id: assignment.section.id,
                name: assignment.section.name,
                gradeLevel: assignment.section.gradeLevel,
              });
            }
          });
        }

        if (advisoryResponse.data?.hasAdvisory && advisoryResponse.data?.section) {
          const advisorySection = advisoryResponse.data.section;
          if (!sectionsMap.has(advisorySection.id)) {
            sectionsMap.set(advisorySection.id, {
              id: advisorySection.id,
              name: advisorySection.name,
              gradeLevel: advisorySection.gradeLevel,
            });
          }
        }

        const sectionsList = Array.from(sectionsMap.values());
        setSections(sectionsList);

        if (advisoryResponse.data?.hasAdvisory && advisoryResponse.data?.section) {
          setSelectedSection(advisoryResponse.data.section.id);
        } else if (sectionsList.length > 0) {
          setSelectedSection(sectionsList[0].id);
        }

        // Set default start date to 30 days ago
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        setStartDate(thirtyDaysAgo.toISOString().split("T")[0]);
      } catch (error) {
        console.error("Error fetching sections:", error);
      }
    };

    fetchSections();
  });

  const fetchReport = async () => {
    if (!selectedSection || !startDate || !endDate) return;

    setLoading(true);
    try {
      const token = sessionStorage.getItem("token");
      const response = await axios.get(
        `${SERVER_URL}/api/attendance/summary/${selectedSection}`,
        {
          params: { startDate, endDate },
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      setSummary(response.data.data.summary);
    } catch (error) {
      console.error("Error fetching report:", error);
    } finally {
      setLoading(false);
    }
  };

  const downloadExcel = async () => {
    if (!selectedSection || !startDate || !endDate) return;

    setDownloading(true);
    try {
      const token = sessionStorage.getItem("token");
      const response = await axios.get(
        `${SERVER_URL}/api/attendance/export/${selectedSection}`,
        {
          params: { startDate, endDate },
          headers: { Authorization: `Bearer ${token}` },
          responseType: "blob",
        }
      );

      // Create download link
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;

      const section = sections.find(s => s.id === selectedSection);
      const sectionName = section ? `${gradeLevelLabels[section.gradeLevel]}-${section.name}` : "Attendance";
      link.setAttribute("download", `${sectionName}_${startDate}_to_${endDate}.xlsx`);

      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Error downloading Excel:", error);
    } finally {
      setDownloading(false);
    }
  };

  const getAttendanceRate = (present: number, total: number) => {
    if (total === 0) return 0;
    return ((present / total) * 100).toFixed(1);
  };

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Attendance Reports</h1>
          <p className="text-gray-500 mt-1">View and download attendance summaries</p>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Filter className="w-5 h-5" />
            Report Filters
          </CardTitle>
          <CardDescription>Select section and date range to generate report</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
            <div className="md:col-span-2">
              <Label htmlFor="section">Section</Label>
              <Select value={selectedSection} onValueChange={setSelectedSection}>
                <SelectTrigger id="section" className="w-full truncate">
                  <SelectValue placeholder="Select section">
                    {selectedSection && sections.length > 0 ? (
                      (() => {
                        const selected = sections.find(s => s.id === selectedSection);
                        return selected ? `${gradeLevelLabels[selected.gradeLevel]} - ${selected.name}` : 'Select section';
                      })()
                    ) : 'Select section'}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent>
                  {sections.map((section) => (
                    <SelectItem key={section.id} value={section.id}>
                      {gradeLevelLabels[section.gradeLevel]} - {section.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="startDate">Start Date</Label>
              <Input
                id="startDate"
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                max={endDate}
              />
            </div>

            <div>
              <Label htmlFor="endDate">End Date</Label>
              <Input
                id="endDate"
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                min={startDate}
                max={new Date().toISOString().split("T")[0]}
              />
            </div>

            <div className="flex items-end gap-2">
              <Button
                onClick={fetchReport}
                disabled={!selectedSection || !startDate || !endDate || loading}
                className="flex-1"
                style={{ backgroundColor: colors.primary }}
              >
                {loading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin mr-2" />
                    Loading...
                  </>
                ) : (
                  <>
                    <Eye className="w-4 h-4 mr-2" />
                    View Report
                  </>
                )}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Summary Stats */}
      {summary.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Card>
            <CardContent className="pt-6">
              <div className="text-center">
                <p className="text-sm text-gray-500">Total Students</p>
                <p className="text-3xl font-bold" style={{ color: colors.primary }}>
                  {summary.length}
                </p>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-6">
              <div className="text-center">
                <p className="text-sm text-gray-500">Avg. Attendance</p>
                <p className="text-3xl font-bold text-green-600">
                  {summary.length > 0
                    ? (
                      (summary.reduce((acc, s) => acc + s.present, 0) /
                        summary.reduce((acc, s) => acc + s.total, 0)) *
                      100
                    ).toFixed(1)
                    : 0}
                  %
                </p>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-6">
              <div className="text-center">
                <p className="text-sm text-gray-500">Total Days</p>
                <p className="text-3xl font-bold" style={{ color: colors.secondary }}>
                  {summary[0]?.total || 0}
                </p>
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="pt-6">
              <div className="text-center">
                <Button
                  onClick={downloadExcel}
                  disabled={downloading}
                  variant="outline"
                  className="w-full"
                  style={{ borderColor: colors.accent, color: colors.accent }}
                >
                  {downloading ? (
                    <>
                      <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin mr-2" />
                      Exporting...
                    </>
                  ) : (
                    <>
                      <Download className="w-4 h-4 mr-2" />
                      Download Excel
                    </>
                  )}
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Report Table */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Attendance Summary</CardTitle>
              <CardDescription>
                {summary.length > 0
                  ? `Showing ${summary.length} students from ${startDate} to ${endDate}`
                  : "Select filters and click 'View Report' to see data"}
              </CardDescription>
            </div>
            {summary.length > 0 && (
              <Badge variant="outline" className="text-sm">
                <FileSpreadsheet className="w-3 h-3 mr-1" />
                {summary.length} Records
              </Badge>
            )}
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="text-center">
                <div
                  className="w-12 h-12 mx-auto mb-4 border-[3px] border-t-transparent rounded-full animate-spin"
                  style={{ borderColor: colors.primary, borderTopColor: "transparent" }}
                />
                <p className="text-gray-500">Loading report...</p>
              </div>
            </div>
          ) : summary.length > 0 ? (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>LRN</TableHead>
                    <TableHead>Student Name</TableHead>
                    <TableHead className="text-center">Present</TableHead>
                    <TableHead className="text-center">Absent</TableHead>
                    <TableHead className="text-center">Late</TableHead>
                    <TableHead className="text-center">Excused</TableHead>
                    <TableHead className="text-center">Total Days</TableHead>
                    <TableHead className="text-center">Attendance Rate</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {summary.map((student) => (
                    <TableRow key={student.studentId}>
                      <TableCell className="font-mono text-sm">{student.lrn}</TableCell>
                      <TableCell className="">
                        {student.lastName}, {student.firstName} {student.middleName?.[0]}.
                      </TableCell>
                      <TableCell className="text-center">
                        <Badge className="bg-green-100 text-green-700 border-green-200">
                          {student.present}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-center">
                        <Badge className="bg-red-100 text-red-700 border-red-200">
                          {student.absent}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-center">
                        <Badge className="bg-amber-100 text-amber-700 border-amber-200">
                          {student.late}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-center">
                        <Badge className="bg-blue-100 text-blue-700 border-blue-200">
                          {student.excused}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-center ">{student.total}</TableCell>
                      <TableCell className="text-center">
                        <span
                          className={`font-bold ${parseFloat(getAttendanceRate(student.present, student.total)) >= 90
                            ? "text-green-600"
                            : parseFloat(getAttendanceRate(student.present, student.total)) >= 75
                              ? "text-amber-600"
                              : "text-red-600"
                            }`}
                        >
                          {getAttendanceRate(student.present, student.total)}%
                        </span>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          ) : (
            <div className="text-center py-12 text-gray-500">
              <Calendar className="w-12 h-12 mx-auto mb-3 text-gray-300" />
              <p>No attendance data available</p>
              <p className="text-sm mt-1">Select a section and date range to view the report</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

// @ts-nocheck
import React, { useEffect, useState, useRef, useMemo } from "react";
import { useParams } from "react-router";
import {
  AlertCircle,
  CheckCircle,
  Loader2,
  X,
} from "lucide-react";
import {
  gradesApi,
  SERVER_URL,
  type ClassAssignment,
  type ClassRecord,
  type ScoreItem,
} from "@/features/smart/lib/api";
import { ClassRecordTable } from "./components/ClassRecordTable";
import { ClassRecordMobileList } from "./components/ClassRecordMobileList";
import { GradeEditModal } from "./components/GradeEditModal";
import { AssessmentHeader } from "./components/AssessmentHeader";
import { ClassRecordHero } from "./components/ClassRecordHero";
import { ClassRecordStats } from "./components/ClassRecordStats";
import { EcrGenerationDialog } from "./components/EcrGenerationDialog";
import { executeHpsUpdate, executeRemoveTask, executeScoreUpdate } from "./components/classRecordActions";
import { HGDescriptorPanel } from "./components/HGDescriptorPanel";
import {
  getDisplayFinalGrade as computeDisplayFinalGrade,
  getMobileDraftKey,
  getScoreFromGrade as computeScoreFromGrade,
} from "./components/classRecordMobileUtils";

const HG_DESCRIPTORS = [
  'No Improvement',
  'Needs Improvement',
  'Developing',
  'Sufficiently Developed',
] as const;

interface AssessmentTaskMeta {
  description: string;
  date: string;
}

function getGradeColor(grade: number | null): string {
  if (grade === null) return "text-slate-300";
  if (grade >= 90) return "text-emerald-600";
  if (grade >= 85) return "text-blue-600";
  if (grade >= 80) return "text-amber-600";
  if (grade >= 75) return "text-orange-600";
  return "text-rose-600";
}


export default function ClassRecordView() {
  const { classAssignmentId } = useParams();
  const [classAssignment, setClassAssignment] = useState<ClassAssignment | null>(null);
  const [classRecord, setClassRecord] = useState<ClassRecord[]>([]);
  const [effectiveWeights, setEffectiveWeights] = useState<{
    ww: number;
    pt: number;
    qa: number;
    source: "subject" | "generic-fallback";
    hasExactEcrTemplate: boolean;
  } | null>(null);
  const [selectedTerm, setSelectedTerm] = useState<string>("T1");
  const [termInitialized, setTermInitialized] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [savingDescriptorStudentId, setSavingDescriptorStudentId] = useState<string | null>(null);
  const [showAssessmentDetails, setShowAssessmentDetails] = useState(false);
  const [wwMeta, setWwMeta] = useState<AssessmentTaskMeta[]>([]);
  const [ptMeta, setPtMeta] = useState<AssessmentTaskMeta[]>([]);
  const [qaMeta, setQaMeta] = useState<{ description: string; date: string }>({ description: '', date: '' });
  const [invalidCells, setInvalidCells] = useState<Record<string, string>>({});
  const [selectedColumn, setSelectedColumn] = useState<{ type: 'WW' | 'PT' | 'QA'; number: number } | null>(null);
  const [metaEditorDraft, setMetaEditorDraft] = useState<{ description: string; date: string }>({ description: '', date: '' });
  const [savingMeta, setSavingMeta] = useState(false);
  const [mobileEditorOpen, setMobileEditorOpen] = useState(false);
  const [mobileEditorStudentId, setMobileEditorStudentId] = useState<string | null>(null);
  const [mobileEditorTab, setMobileEditorTab] = useState<'WW' | 'PT' | 'QA' | 'HG'>('WW');
  const [mobileScoreDraft, setMobileScoreDraft] = useState<Record<string, string>>({});

  const [separateByGender, setSeparateByGender] = useState(false);
  const ecrFileInputRef = useRef<HTMLInputElement>(null);
  const isHGClass = (classAssignment?.subject?.code ?? '').startsWith('HG');
  const ledgerHeaderRef = useRef<HTMLDivElement | null>(null);
  const [ledgerHeaderHeight, setLedgerHeaderHeight] = useState(0);
  const assessmentDetailsRef = useRef<HTMLDivElement | null>(null);
  const [assessmentDetailsHeight, setAssessmentDetailsHeight] = useState(0);
  const metaEditorRef = useRef<HTMLDivElement | null>(null);
  const [metaEditorHeight, setMetaEditorHeight] = useState(0);

  // Dynamic Column Counts
  const wwCount = useMemo(() => {
    let max = 1;
    classRecord.forEach(r => {
      const grade = r.grades.find(g => g.term === selectedTerm);
      if (grade?.writtenWorkScores) max = Math.max(max, (grade.writtenWorkScores as any[]).length);
    });
    return max;
  }, [classRecord, selectedTerm]);

  const ptCount = useMemo(() => {
    let max = 1;
    classRecord.forEach(r => {
      const grade = r.grades.find(g => g.term === selectedTerm);
      if (grade?.perfTaskScores) max = Math.max(max, (grade.perfTaskScores as any[]).length);
    });
    return max;
  }, [classRecord, selectedTerm]);

  const hpsData = useMemo(() => {
    const wwScores: ScoreItem[] = Array.from({ length: wwCount }, (_, i) => ({
      name: `WW ${i + 1}`,
      score: 0,
      maxScore: 0,
    }));
    const ptScores: ScoreItem[] = Array.from({ length: ptCount }, (_, i) => ({
      name: `PT ${i + 1}`,
      score: 0,
      maxScore: 0,
    }));

    let qaMax = 0;

    classRecord.forEach((record) => {
      const grade = record.grades.find((g) => g.term === selectedTerm);
      if (!grade) return;

      const ww = (grade.writtenWorkScores || []) as ScoreItem[];
      const pt = (grade.perfTaskScores || []) as ScoreItem[];

      ww.forEach((item, i) => {
        if (i < wwScores.length) {
          wwScores[i].maxScore = Math.max(wwScores[i].maxScore || 0, Number(item.maxScore) || 0);
        }
      });

      pt.forEach((item, i) => {
        if (i < ptScores.length) {
          ptScores[i].maxScore = Math.max(ptScores[i].maxScore || 0, Number(item.maxScore) || 0);
        }
      });

      qaMax = Math.max(qaMax, Number(grade.quarterlyAssessMax) || 0);
    });

    return {
      wwScores,
      ptScores,
      qaMax: qaMax || 100,
    };
  }, [classRecord, selectedTerm, wwCount, ptCount]);

  useEffect(() => {
    const gradeSamples = classRecord
      .map((record) => record.grades.find((g) => g.term === selectedTerm))
      .filter(Boolean) as Array<any>;

    const wwSample = gradeSamples.find((g) => Array.isArray(g.writtenWorkScores) && g.writtenWorkScores.length > 0);
    const ptSample = gradeSamples.find((g) => Array.isArray(g.perfTaskScores) && g.perfTaskScores.length > 0);

    const wwSource = ((wwSample?.writtenWorkScores || []) as ScoreItem[]);
    const ptSource = ((ptSample?.perfTaskScores || []) as ScoreItem[]);

    setWwMeta((prev) =>
      Array.from({ length: wwCount }, (_, i) => ({
        description: wwSource[i]?.description || wwSource[i]?.name || prev[i]?.description || `WW ${i + 1}`,
        date: wwSource[i]?.date || prev[i]?.date || '',
      }))
    );

    setPtMeta((prev) =>
      Array.from({ length: ptCount }, (_, i) => ({
        description: ptSource[i]?.description || ptSource[i]?.name || prev[i]?.description || `PT ${i + 1}`,
        date: ptSource[i]?.date || prev[i]?.date || '',
      }))
    );

    setQaMeta((prev) => {
      const qaSample = gradeSamples.find((g) => g.qaDescription || g.qaDate);
      return {
        description: qaSample?.qaDescription || prev.description || '',
        date: qaSample?.qaDate || prev.date || '',
      };
    });
  }, [classRecord, selectedTerm, wwCount, ptCount]);

  const applyMetaToScores = (
    scores: ScoreItem[],
    category: 'WW' | 'PT',
    minLength = 0,
    metaOverride?: AssessmentTaskMeta[],
  ): ScoreItem[] => {
    const meta = metaOverride || (category === 'WW' ? wwMeta : ptMeta);
    const targetLength = Math.max(scores.length, minLength);

    return Array.from({ length: targetLength }, (_, i) => {
      const existing = scores[i] || ({ score: 0, maxScore: 10 } as ScoreItem);
      const description = meta[i]?.description?.trim() || `${category} ${i + 1}`;
      const date = meta[i]?.date || '';
      return {
        ...existing,
        name: description,
        description,
        date: date || undefined,
        maxScore: Number(existing.maxScore ?? 10),
        score: Number(existing.score ?? 0),
      };
    });
  };

  const getCellKey = (sid: string, cat: 'WW' | 'PT' | 'QA', idx: number) => `${sid}:${cat}:${idx}`;

  const getMaxForCell = (cat: 'WW' | 'PT' | 'QA', idx: number): number => {
    if (cat === 'WW') return Number(hpsData.wwScores[idx]?.maxScore ?? 0);
    if (cat === 'PT') return Number(hpsData.ptScores[idx]?.maxScore ?? 0);
    return Number(hpsData.qaMax ?? 0);
  };

  const openMetaEditor = (type: 'WW' | 'PT' | 'QA', index: number) => {
    setSelectedColumn({ type, number: index + 1 });
    if (type === 'WW') {
      setMetaEditorDraft({
        description: wwMeta[index]?.description || `WW ${index + 1}`,
        date: wwMeta[index]?.date || '',
      });
      return;
    }
    if (type === 'PT') {
      setMetaEditorDraft({
        description: ptMeta[index]?.description || `PT ${index + 1}`,
        date: ptMeta[index]?.date || '',
      });
      return;
    }
    setMetaEditorDraft({
      description: qaMeta.description || 'Term Assessment',
      date: qaMeta.date || '',
    });
  };

  const saveColumnMeta = async () => {
    if (!classAssignmentId || !selectedColumn) return;
    const nextWwMeta = [...wwMeta];
    const nextPtMeta = [...ptMeta];
    const nextQaMeta = { ...qaMeta };

    const index = selectedColumn.number - 1;

    if (selectedColumn.type === 'WW') {
      while (nextWwMeta.length <= index) {
        nextWwMeta.push({ description: `WW ${nextWwMeta.length + 1}`, date: '' });
      }
      nextWwMeta[index] = {
        description: metaEditorDraft.description || `WW ${selectedColumn.number}`,
        date: metaEditorDraft.date || '',
      };
    } else if (selectedColumn.type === 'PT') {
      while (nextPtMeta.length <= index) {
        nextPtMeta.push({ description: `PT ${nextPtMeta.length + 1}`, date: '' });
      }
      nextPtMeta[index] = {
        description: metaEditorDraft.description || `PT ${selectedColumn.number}`,
        date: metaEditorDraft.date || '',
      };
    } else {
      nextQaMeta.description = metaEditorDraft.description;
      nextQaMeta.date = metaEditorDraft.date;
    }

    setWwMeta(nextWwMeta);
    setPtMeta(nextPtMeta);
    setQaMeta(nextQaMeta);

    setSavingMeta(true);
    try {
      const updatePromises = classRecord.map((record) => {
        const grade = record.grades.find((g) => g.term === selectedTerm);
        const wwScores = applyMetaToScores([...(grade?.writtenWorkScores || []) as ScoreItem[]], 'WW', wwCount, nextWwMeta);
        const ptScores = applyMetaToScores([...(grade?.perfTaskScores || []) as ScoreItem[]], 'PT', ptCount, nextPtMeta);

        return gradesApi.saveGrade({
          studentId: record.student.id,
          classAssignmentId,
          term: selectedTerm,
          writtenWorkScores: wwScores,
          perfTaskScores: ptScores,
          qaDescription: nextQaMeta.description || undefined,
          qaDate: nextQaMeta.date || undefined,
        });
      });

      await Promise.all(updatePromises);
      setSuccess('Assessment metadata applied to the selected column');
      fetchClassRecord(true);
      setSelectedColumn(null);
    } catch (err: any) {
      console.error('Failed to save column metadata:', err);
      setError(err?.response?.data?.message || 'Failed to save assessment metadata');
      fetchClassRecord(true);
    } finally {
      setSavingMeta(false);
    }
  };

  const applyColumnMetaFromMobile = async (
    category: 'WW' | 'PT' | 'QA',
    index: number,
    description: string,
    date: string,
  ) => {
    if (!classAssignmentId) return;

    const nextWwMeta = [...wwMeta];
    const nextPtMeta = [...ptMeta];
    const nextQaMeta = { ...qaMeta };

    if (category === 'WW') {
      while (nextWwMeta.length <= index) {
        nextWwMeta.push({ description: `WW ${nextWwMeta.length + 1}`, date: '' });
      }
      nextWwMeta[index] = {
        description: description || `WW ${index + 1}`,
        date: date || '',
      };
    } else if (category === 'PT') {
      while (nextPtMeta.length <= index) {
        nextPtMeta.push({ description: `PT ${nextPtMeta.length + 1}`, date: '' });
      }
      nextPtMeta[index] = {
        description: description || `PT ${index + 1}`,
        date: date || '',
      };
    } else {
      nextQaMeta.description = description;
      nextQaMeta.date = date;
    }

    setWwMeta(nextWwMeta);
    setPtMeta(nextPtMeta);
    setQaMeta(nextQaMeta);

    try {
      const updatePromises = classRecord.map((record) => {
        const grade = record.grades.find((g) => g.term === selectedTerm);
        const wwScores = applyMetaToScores([...(grade?.writtenWorkScores || []) as ScoreItem[]], 'WW', wwCount, nextWwMeta);
        const ptScores = applyMetaToScores([...(grade?.perfTaskScores || []) as ScoreItem[]], 'PT', ptCount, nextPtMeta);

        return gradesApi.saveGrade({
          studentId: record.student.id,
          classAssignmentId,
          term: selectedTerm,
          writtenWorkScores: wwScores,
          perfTaskScores: ptScores,
          qaDescription: nextQaMeta.description || undefined,
          qaDate: nextQaMeta.date || undefined,
        });
      });

      await Promise.all(updatePromises);
      setSuccess('Assessment metadata synced for the class');
      fetchClassRecord(true);
    } catch (err: any) {
      console.error('Failed to sync mobile column metadata:', err);
      setError(err?.response?.data?.message || 'Failed to sync assessment metadata');
      fetchClassRecord(true);
    }
  };

  const isCellInvalid = (sid: string, cat: 'WW' | 'PT' | 'QA', idx: number) => Boolean(invalidCells[getCellKey(sid, cat, idx)]);

  const commitScoreInput = (
    inputEl: HTMLInputElement,
    studentId: string,
    category: 'WW' | 'PT' | 'QA',
    index: number,
  ): boolean => {
    const rawValue = inputEl.value;
    const parsed = rawValue === '' ? 0 : Number(rawValue);
    const key = getCellKey(studentId, category, index);
    const maxAllowed = getMaxForCell(category, index);

    if (Number.isNaN(parsed) || parsed < 0 || parsed > maxAllowed) {
      const prevValue = inputEl.dataset.prev ?? '';
      inputEl.value = prevValue;
      setInvalidCells((prev) => ({ ...prev, [key]: `Score cannot exceed ${maxAllowed}.` }));
      setError(`${category} ${category === 'QA' ? '' : index + 1} score cannot exceed MAX (${maxAllowed}).`.trim());
      return false;
    }

    setInvalidCells((prev) => {
      if (!prev[key]) return prev;
      const next = { ...prev };
      delete next[key];
      return next;
    });

    inputEl.dataset.prev = String(parsed);
    handleScoreUpdate(studentId, category, index, parsed);
    return true;
  };

  useEffect(() => {
    fetchClassRecord();
  }, [classAssignmentId, selectedTerm]);

  useEffect(() => {
    if (classAssignmentId && !isHGClass) {
      fetchEcrStatus();
    }
  }, [classAssignmentId, isHGClass]);

  useEffect(() => {
    if (error || success) {
      const timer = setTimeout(() => {
        setError(null);
        setSuccess(null);
      }, 4000);
      return () => clearTimeout(timer);
    }
  }, [error, success]);

  useEffect(() => {
    const node = ledgerHeaderRef.current;
    if (!node) {
      setLedgerHeaderHeight(0);
      return;
    }
    const update = () => setLedgerHeaderHeight(node.offsetHeight || 0);
    update();

    let observer: ResizeObserver | null = null;
    if (typeof ResizeObserver !== 'undefined') {
      observer = new ResizeObserver(update);
      observer.observe(node);
    }
    window.addEventListener('resize', update);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', update);
    };
  }, [classAssignment?.id]);

  useEffect(() => {
    if (!showAssessmentDetails) {
      setAssessmentDetailsHeight(0);
      return;
    }
    const node = assessmentDetailsRef.current;
    if (!node) return;
    const update = () => setAssessmentDetailsHeight(node.offsetHeight || 0);
    update();

    let observer: ResizeObserver | null = null;
    if (typeof ResizeObserver !== 'undefined') {
      observer = new ResizeObserver(update);
      observer.observe(node);
    }
    window.addEventListener('resize', update);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', update);
    };
  }, [showAssessmentDetails, wwCount, ptCount]);

  useEffect(() => {
    if (!selectedColumn) {
      setMetaEditorHeight(0);
      return;
    }
    const node = metaEditorRef.current;
    if (!node) return;
    const update = () => setMetaEditorHeight(node.offsetHeight || 0);
    update();

    let observer: ResizeObserver | null = null;
    if (typeof ResizeObserver !== 'undefined') {
      observer = new ResizeObserver(update);
      observer.observe(node);
    }
    window.addEventListener('resize', update);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', update);
    };
  }, [selectedColumn]);


  const fetchClassRecord = async (silent = false) => {
    if (!classAssignmentId) return;
    try {
      if (!silent) setLoading(true);
      const response = await gradesApi.getClassRecord(classAssignmentId, selectedTerm);

      // Align initial term to system current term to avoid saving/viewing grades in the wrong term.
      if (!termInitialized && response.data.currentTerm) {
        setTermInitialized(true);
        if (response.data.currentTerm !== selectedTerm) {
          setSelectedTerm(response.data.currentTerm);
          return;
        }
      }

      setClassAssignment(response.data.classAssignment);
      setClassRecord(response.data.classRecord);
      setEffectiveWeights(response.data.effectiveWeights ?? null);
    } catch (err) {
      console.error("Failed to fetch class record:", err);
      if (!silent) setError("Failed to load class record");
    } finally {
      if (!silent) setLoading(false);
    }
  };

  const fetchEcrStatus = async () => {
    if (!classAssignmentId) return;
    try {
      await gradesApi.getEcrStatus(classAssignmentId);
    } catch (err) {
      console.error("Failed to fetch ECR status:", err);
    }
  };

  const handleEcrFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      handleEcrImport(file);
    }
  };

  const handleEcrImport = async (file: File) => {
    if (!classAssignmentId) return;
    try {
      const response = await gradesApi.importEcr(classAssignmentId, file);
      setSuccess(`Successfully imported ${response.data.importedGrades} grades from ECR.`);
      fetchClassRecord();
    } catch (err: any) {
      console.error("Failed to import ECR:", err);
      setError(err.response?.data?.message || "Failed to import ECR grades");
    }
  };

  const handleScoreUpdate = async (
    studentId: string,
    category: 'WW' | 'PT' | 'QA',
    index: number,
    newValue: number
  ) => {
    await executeScoreUpdate({
      classAssignmentId,
      classRecord,
      selectedTerm,
      studentId,
      category,
      index,
      newValue,
      qaMeta,
      getCellKey,
      getMaxForCell,
      applyMetaToScores,
      setClassRecord,
      setInvalidCells,
      setError,
      fetchClassRecord,
    });
  };

  const handleHpsUpdate = async (
    category: 'WW' | 'PT' | 'QA',
    index: number,
    newMax: number
  ) => {
    await executeHpsUpdate({
      classAssignmentId,
      classRecord,
      selectedTerm,
      category,
      index,
      newMax,
      qaMeta,
      applyMetaToScores,
      setClassRecord,
      setError,
      fetchClassRecord,
    });
  };

  const handleDescriptorUpdate = async (studentId: string, descriptor: string) => {
    if (!classAssignmentId) return;
    try {
      setSavingDescriptorStudentId(studentId);
      await gradesApi.saveGrade({
        studentId,
        classAssignmentId,
        term: selectedTerm,
        qualitativeDescriptor: descriptor,
      });
      setSuccess('Descriptor saved');
      fetchClassRecord(true);
    } catch (err: any) {
      setError(err?.response?.data?.message || 'Failed to save descriptor');
    } finally {
      setSavingDescriptorStudentId(null);
    }
  };

  const addTask = async (category: 'WW' | 'PT') => {
    const targetIdx = category === 'WW' ? wwCount : ptCount;
    if (category === 'WW') {
      setWwMeta((prev) => [...prev, { description: `WW ${targetIdx + 1}`, date: '' }]);
    } else {
      setPtMeta((prev) => [...prev, { description: `PT ${targetIdx + 1}`, date: '' }]);
    }
    handleHpsUpdate(category, targetIdx, 10);
  };

  const removeTask = async (category: 'WW' | 'PT') => {
    await executeRemoveTask({
      classAssignmentId,
      classRecord,
      selectedTerm,
      category,
      wwCount,
      ptCount,
      qaMeta,
      applyMetaToScores,
      setClassRecord,
      setWwMeta,
      setPtMeta,
      setSuccess,
      setError,
      fetchClassRecord,
    });
  };

  const sortedRecords = useMemo(
    () =>
      [...classRecord].sort((a, b) => {
        const nameA = `${a.student.lastName}, ${a.student.firstName}`.toLowerCase();
        const nameB = `${b.student.lastName}, ${b.student.firstName}`.toLowerCase();
        return nameA.localeCompare(nameB);
      }),
    [classRecord]
  );

  const saveAssessmentDetails = async () => {
    if (!classAssignmentId) return;

    try {
      const updatePromises = classRecord.map((record) => {
        const grade = record.grades.find((g) => g.term === selectedTerm);
        const wwScores = applyMetaToScores([...(grade?.writtenWorkScores || []) as ScoreItem[]], 'WW', wwCount);
        const ptScores = applyMetaToScores([...(grade?.perfTaskScores || []) as ScoreItem[]], 'PT', ptCount);

        return gradesApi.saveGrade({
          studentId: record.student.id,
          classAssignmentId,
          term: selectedTerm,
          writtenWorkScores: wwScores,
          perfTaskScores: ptScores,
          qaDescription: qaMeta.description || undefined,
          qaDate: qaMeta.date || undefined,
        });
      });

      if (updatePromises.length === 0) {
        setSuccess('No learners to update yet.');
        return;
      }

      await Promise.all(updatePromises);
      setSuccess('Assessment details saved');
      fetchClassRecord(true);
    } catch (err: any) {
      console.error('Failed to save assessment details:', err);
      setError(err?.response?.data?.message || 'Failed to save assessment details');
    }
  };

  const handleClearScores = async () => {
    if (!classAssignmentId) return;
    try {
      setLoading(true);
      await gradesApi.clearScores(classAssignmentId, selectedTerm);
      setSuccess("Successfully cleared all scores for the current term.");
      await fetchClassRecord();
    } catch (err: any) {
      console.error("Failed to clear scores:", err);
      setError(err?.response?.data?.message || "Failed to clear scores");
      await fetchClassRecord();
    } finally {
      setLoading(false);
    }
  };

  const maleRecords = useMemo(() => sortedRecords.filter(r => r.student.gender?.toLowerCase() === 'male'), [sortedRecords]);
  const femaleRecords = useMemo(() => sortedRecords.filter(r => r.student.gender?.toLowerCase() === 'female'), [sortedRecords]);

  const activeWeights = useMemo(() => ({
    ww: effectiveWeights?.ww ?? classAssignment?.subject?.writtenWorkWeight ?? 0,
    pt: effectiveWeights?.pt ?? classAssignment?.subject?.perfTaskWeight ?? 0,
    qa: effectiveWeights?.qa ?? classAssignment?.subject?.quarterlyAssessWeight ?? 0,
  }), [effectiveWeights, classAssignment?.subject?.writtenWorkWeight, classAssignment?.subject?.perfTaskWeight, classAssignment?.subject?.quarterlyAssessWeight]);

  const getDisplayFinalGrade = (record: ClassRecord): number | null =>
    computeDisplayFinalGrade(record, selectedTerm, activeWeights);

  const stats = useMemo(() => {
    if (classRecord.length === 0) return null;
    const grades = classRecord
      .map((record) => getDisplayFinalGrade(record))
      .filter((g): g is number => g !== undefined && g !== null);
    if (grades.length === 0) return { avg: 0, passed: 0, highest: 0, lowest: 0 };
    return {
      avg: grades.reduce((a, b) => a + b, 0) / grades.length,
      passed: grades.filter((g) => g >= 75).length,
      highest: Math.max(...grades),
      lowest: Math.min(...grades),
    };
  }, [classRecord, selectedTerm, activeWeights]);

  const openMobileEditor = (studentId: string) => {
    setMobileEditorStudentId(studentId);
    setMobileEditorOpen(true);
    setMobileScoreDraft({});
    setMobileEditorTab(isHGClass ? 'HG' : 'WW');
  };

  const selectedMobileRecord = useMemo(
    () => sortedRecords.find((record) => record.student.id === mobileEditorStudentId) ?? null,
    [sortedRecords, mobileEditorStudentId]
  );

  const handleMobileDraftChange = (
    studentId: string,
    category: 'WW' | 'PT' | 'QA',
    index: number,
    value: string,
  ) => {
    const key = getMobileDraftKey(studentId, category, index);
    if (value === '') {
      setMobileScoreDraft((prev) => ({ ...prev, [key]: '' }));
      return;
    }

    const parsed = Number(value);
    const maxAllowed = getMaxForCell(category, index);
    if (Number.isNaN(parsed) || parsed < 0 || parsed > maxAllowed) {
      setMobileScoreDraft((prev) => ({ ...prev, [key]: '' }));
      setInvalidCells((prev) => ({ ...prev, [getCellKey(studentId, category, index)]: `Score cannot exceed ${maxAllowed}.` }));
      return;
    }

    setMobileScoreDraft((prev) => ({ ...prev, [key]: value }));
    setInvalidCells((prev) => {
      const cellKey = getCellKey(studentId, category, index);
      if (!prev[cellKey]) return prev;
      const next = { ...prev };
      delete next[cellKey];
      return next;
    });
  };

  const commitMobileScore = (
    record: ClassRecord,
    category: 'WW' | 'PT' | 'QA',
    index: number,
  ) => {
    const key = getMobileDraftKey(record.student.id, category, index);
    const value = mobileScoreDraft[key] ?? computeScoreFromGrade(record, selectedTerm, category, index);
    const normalized = value.trim() === '' ? 0 : Number(value);
    const maxAllowed = getMaxForCell(category, index);

    if (Number.isNaN(normalized) || normalized < 0 || normalized > maxAllowed) {
      setMobileScoreDraft((prev) => ({ ...prev, [key]: '' }));
      setError(`${category} ${category === 'QA' ? '' : index + 1} score cannot exceed MAX (${maxAllowed}).`.trim());
      setInvalidCells((prev) => ({ ...prev, [getCellKey(record.student.id, category, index)]: `Score cannot exceed ${maxAllowed}.` }));
      return;
    }

    setMobileScoreDraft((prev) => ({ ...prev, [key]: normalized === 0 ? '' : String(normalized) }));
    handleScoreUpdate(record.student.id, category, index, normalized);
  };

  const [ecrProgress, setEcrProgress] = useState<string>('');
  const [ecrPercentage, setEcrPercentage] = useState<number>(0);
  const [showEcrGenerationDialog, setShowEcrGenerationDialog] = useState(false);

  const downloadECR = async () => {
    if (!classAssignment) return;
    try {
      setShowEcrGenerationDialog(true);
      setEcrPercentage(0);
      setEcrProgress('Initializing compilation...');
      setEcrPercentage(20);
      await new Promise(resolve => setTimeout(resolve, 500));

      const token = sessionStorage.getItem("token");
      const response = await fetch(`${SERVER_URL}/api/ecr-templates/generate/${classAssignment.id}`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ term: selectedTerm }),
      });

      if (!response.ok) throw new Error('Failed to generate ECR');

      setEcrPercentage(60);
      setEcrProgress('Injecting records...');
      const blob = await response.blob();

      setEcrPercentage(90);
      setEcrProgress('Finalizing workbook...');
      await new Promise(resolve => setTimeout(resolve, 500));

      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `ECR_${classAssignment.subject.name}_${classAssignment.section.name}.xlsx`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);

      setEcrPercentage(100);
      setEcrProgress('Download started!');
      setTimeout(() => setShowEcrGenerationDialog(false), 1500);
    } catch (error: any) {
      setError(error.message);
      setShowEcrGenerationDialog(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="text-center">
          <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-sm">
            <Loader2 className="w-10 h-10 text-indigo-600 animate-spin" />
          </div>
          <p className="text-slate-500 font-bold text-xs uppercase tracking-widest">Fetching Class Records...</p>
        </div>
      </div>
    );
  }

  if (!classAssignment) return null;
  const topNavHeight = 64;
  // metaEditorTop: where the quick-column editor sticks (below top nav + ledger card header)
  const metaEditorTop = topNavHeight + Math.ceil(ledgerHeaderHeight);
  // assessmentDetailsTop: below the meta editor (if open)
  const metaEditorOffset = selectedColumn ? Math.ceil(metaEditorHeight) : 0;
  const assessmentDetailsTop = metaEditorTop + metaEditorOffset;
  // stickyOffset: total px above the table column headers ΓÇö passed to ClassRecordTable
  // ClassRecordTable internally adds its own group-row and sub-row heights for the HPS row.
  const assessmentPanelOffset = showAssessmentDetails ? Math.ceil(assessmentDetailsHeight) : 0;
  const stickyOffset = assessmentDetailsTop + assessmentPanelOffset;

  return (
    <div className="space-y-8 animate-fade-in w-full px-6 pb-12">
      {/* Toast Messages */}
      {(error || success) && (
        <div className={`fixed top-20 right-6 z-[100] flex items-center gap-4 px-6 py-4 rounded-[1.5rem] shadow-2xl border-0 animate-slide-in-right ${error ? "bg-rose-500 text-white" : "bg-emerald-500 text-white"}`}>
          {error ? <AlertCircle className="w-5 h-5" /> : <CheckCircle className="w-5 h-5" />}
          <span className="text-sm font-bold uppercase tracking-widest">{error || success}</span>
          <button onClick={() => { setError(''); setSuccess(''); }} className="ml-4 p-1 hover:bg-muted/20 rounded-lg transition-colors"><X className="w-4 h-4" /></button>
        </div>
      )}

      <ClassRecordHero
        classAssignment={classAssignment}
        isHGClass={isHGClass}
        effectiveWeightsSource={effectiveWeights?.source ?? null}
        onExportEcr={downloadECR}
        onOpenImport={() => ecrFileInputRef.current?.click()}
        onImportSelect={handleEcrFileSelect}
        fileInputRef={ecrFileInputRef}
      />

      {isHGClass && (
        <>
          <ClassRecordMobileList
            records={sortedRecords}
            selectedTerm={selectedTerm}
            isHGClass
            onTermChange={setSelectedTerm}
            onOpenEditor={openMobileEditor}
            getDisplayFinalGrade={getDisplayFinalGrade}
            getGradeColor={getGradeColor}
          />
          <HGDescriptorPanel
            records={sortedRecords}
            selectedTerm={selectedTerm}
            onTermChange={setSelectedTerm}
            savingDescriptorStudentId={savingDescriptorStudentId}
            descriptors={HG_DESCRIPTORS}
            onDescriptorUpdate={handleDescriptorUpdate}
          />
        </>
      )}

      {/* Analytics Insights */}
      {!isHGClass && stats && (
        <ClassRecordStats
          avg={stats.avg}
          passed={stats.passed}
          total={classRecord.length}
          highest={stats.highest}
        />
      )}

      {/* Main Ledger Table */}
      {!isHGClass && (
        <>
          <ClassRecordMobileList
            records={sortedRecords}
            selectedTerm={selectedTerm}
            isHGClass={false}
            onTermChange={setSelectedTerm}
            onOpenEditor={openMobileEditor}
            getDisplayFinalGrade={getDisplayFinalGrade}
            getGradeColor={getGradeColor}
          />

          <ClassRecordTable
            classAssignment={classAssignment}
            effectiveWeights={effectiveWeights}
            selectedTerm={selectedTerm}
            onTermChange={setSelectedTerm}
            separateByGender={separateByGender}
            onSeparateByGenderChange={setSeparateByGender}
            showAssessmentDetails={showAssessmentDetails}
            onToggleAssessmentDetails={() => setShowAssessmentDetails((prev) => !prev)}
            onClearScores={handleClearScores}
            ledgerHeaderRef={ledgerHeaderRef}
            topNavHeight={topNavHeight}
            ledgerHeaderHeight={Math.ceil(ledgerHeaderHeight)}
            stickyOffset={stickyOffset}
            wwCount={wwCount}
            ptCount={ptCount}
            hpsData={hpsData}
            sortedRecords={sortedRecords}
            maleRecords={maleRecords}
            femaleRecords={femaleRecords}
            onRemoveTask={removeTask}
            onAddTask={addTask}
            onHpsUpdate={handleHpsUpdate}
            onScoreCommit={commitScoreInput}
            onCellFocus={openMetaEditor}
            isCellInvalid={isCellInvalid}
            assessmentHeaderNode={
              <AssessmentHeader
                showAssessmentDetails={showAssessmentDetails}
                assessmentDetailsRef={assessmentDetailsRef}
                metaEditorRef={metaEditorRef}
                wwCount={wwCount}
                ptCount={ptCount}
                wwMeta={wwMeta}
                ptMeta={ptMeta}
                qaMeta={qaMeta}
                setWwMeta={setWwMeta}
                setPtMeta={setPtMeta}
                setQaMeta={setQaMeta}
                saveAssessmentDetails={saveAssessmentDetails}
                savingMeta={savingMeta}
                selectedColumn={selectedColumn}
                setSelectedColumn={setSelectedColumn}
                metaEditorDraft={metaEditorDraft}
                setMetaEditorDraft={setMetaEditorDraft}
                saveColumnMeta={saveColumnMeta}
              />
            }
          />
        </>
      )}

      <GradeEditModal
        open={mobileEditorOpen}
        onOpenChange={(open) => {
          setMobileEditorOpen(open);
          if (!open) {
            setMobileEditorStudentId(null);
            setMobileScoreDraft({});
          }
        }}
        selectedRecord={selectedMobileRecord}
        isHGClass={isHGClass}
        selectedTerm={selectedTerm}
        hgDescriptors={HG_DESCRIPTORS}
        mobileEditorTab={mobileEditorTab}
        onTabChange={setMobileEditorTab}
        wwCount={wwCount}
        ptCount={ptCount}
        wwMeta={wwMeta}
        ptMeta={ptMeta}
        qaMeta={qaMeta}
        mobileScoreDraft={mobileScoreDraft}
        invalidCells={invalidCells}
        getCellKey={getCellKey}
        getMobileDraftKey={getMobileDraftKey}
        getScoreFromGrade={(record, category, index) => computeScoreFromGrade(record, selectedTerm, category, index)}
        getMaxForCell={getMaxForCell}
        onMobileScoreDraftChange={handleMobileDraftChange}
        onMobileScoreCommit={commitMobileScore}
        onDescriptorUpdate={handleDescriptorUpdate}
        onApplyColumnMeta={applyColumnMetaFromMobile}
      />

      <EcrGenerationDialog
        open={showEcrGenerationDialog}
        percentage={ecrPercentage}
        progress={ecrProgress}
      />
    </div>
  );
}

// @ts-nocheck
import { useEffect, useState } from "react";
import { Link } from "react-router";
import {
  Archive,
  ArrowUpRight,
  BookOpen,
  ChevronDown,
  ChevronRight,
  ChevronUp,
  Filter,
  LayoutGrid,
  List,
  Search,
  Trash2,
  Users,
} from "lucide-react";
import { Card, CardContent, CardHeader } from "@/features/smart/components/ui/card";
import { Badge } from "@/features/smart/components/ui/badge";
import { Input } from "@/features/smart/components/ui/input";
import { Button } from "@/features/smart/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/features/smart/components/ui/dialog";
import { gradesApi, advisoryApi, type ClassAssignment, type GradeDeadlineInfo } from "@/features/smart/lib/api";
import { useTheme } from "@/features/smart/contexts/ThemeContext";
import { useSyncStream } from "@/features/smart/hooks/useSyncStream";
import { GradeDeadlineBanner } from "@/features/smart/components/GradeDeadlineBanner";

const gradeLevelLabels: Record<string, string> = {
  GRADE_7: "Grade 7",
  GRADE_8: "Grade 8",
  GRADE_9: "Grade 9",
  GRADE_10: "Grade 10",
};

function getGradeColors(gradeLevel: string) {
  switch (gradeLevel) {
    case "GRADE_7": return {
      badge: "bg-emerald-50 text-emerald-700 border-emerald-100",
      circle: "bg-emerald-400",
      decor: "bg-emerald-50/50 group-hover:bg-emerald-50",
      button: "bg-emerald-50 text-emerald-400 group-hover:bg-emerald-600 group-hover:text-white"
    };
    case "GRADE_8": return {
      badge: "bg-amber-50 text-amber-700 border-amber-100",
      circle: "bg-amber-400",
      decor: "bg-amber-50/50 group-hover:bg-amber-50",
      button: "bg-amber-50 text-amber-400 group-hover:bg-amber-600 group-hover:text-white"
    };
    case "GRADE_9": return {
      badge: "bg-rose-50 text-rose-700 border-rose-100",
      circle: "bg-rose-400",
      decor: "bg-rose-50/50 group-hover:bg-rose-50",
      button: "bg-rose-50 text-rose-400 group-hover:bg-rose-600 group-hover:text-white"
    };
    case "GRADE_10": return {
      badge: "bg-blue-50 text-blue-700 border-blue-100",
      circle: "bg-blue-400",
      decor: "bg-blue-50/50 group-hover:bg-blue-50",
      button: "bg-blue-50 text-blue-400 group-hover:bg-blue-600 group-hover:text-white"
    };
    default: return {
      badge: "bg-indigo-50 text-indigo-700 border-indigo-100",
      circle: "bg-indigo-400",
      decor: "bg-indigo-50/50 group-hover:bg-indigo-50",
      button: "bg-indigo-50 text-indigo-400 group-hover:bg-indigo-600 group-hover:text-white"
    };
  }
}

function AssignmentCard({
  assignment,
  archived,
  onDelete
}: {
  assignment: ClassAssignment;
  archived: boolean;
  onDelete?: (id: string, name: string) => void;
}) {
  const titleHover = archived ? "group-hover:text-rose-600" : "group-hover:text-indigo-600";
  const colors = getGradeColors(assignment.section.gradeLevel);
  const badgeClass = archived
    ? "bg-rose-100 text-rose-700 border-rose-200"
    : colors.badge;
  const circleClass = archived ? "bg-rose-400" : colors.circle;
  const containerClass = archived
    ? "border border-rose-200 shadow-xl shadow-rose-100/50 hover:shadow-2xl hover:shadow-rose-200"
    : "border-0 shadow-xl shadow-slate-200/50 hover:shadow-2xl hover:shadow-indigo-100";
  const cardBg = "bg-muted";
  const sectionText = archived ? "text-rose-500" : "text-slate-500";
  const mutedText = archived ? "text-rose-400" : "text-slate-400";
  const iconClass = archived
    ? "w-8 h-8 rounded-lg bg-rose-50 text-rose-500 group-hover:bg-rose-600 group-hover:text-white"
    : "w-10 h-10 rounded-xl bg-slate-50 text-slate-300 group-hover:bg-indigo-600 group-hover:text-white";
  const chevronClass = archived
    ? "w-10 h-10 rounded-xl bg-rose-100 text-rose-400"
    : "w-12 h-12 rounded-2xl bg-slate-50 text-slate-300";
  const displayWwWeight = assignment.effectiveWeights?.ww ?? assignment.subject.writtenWorkWeight;
  const displayPtWeight = assignment.effectiveWeights?.pt ?? assignment.subject.perfTaskWeight;
  const displayQaWeight = assignment.effectiveWeights?.qa ?? assignment.subject.quarterlyAssessWeight;

  return (
    <div className="relative group/card h-full">
      <Link to={`/teacher/records/${assignment.id}`} className="animate-slide-up group block h-full">
        <Card className={`h-full ${containerClass} transition-all duration-500 ${archived ? 'rounded-[2rem]' : 'rounded-[2.5rem]'} ${cardBg} overflow-hidden flex flex-col relative group-hover:-translate-y-2`}>
          <div
            className={
              archived
                ? "absolute top-0 right-0 w-24 h-24 bg-rose-50 rounded-bl-[3rem] -mr-8 -mt-8 group-hover:bg-rose-100 transition-colors"
                : `absolute top-0 right-0 w-32 h-32 ${colors.decor} rounded-bl-[4rem] -mr-10 -mt-10 transition-colors`
            }
          />
          <CardHeader className={`${archived ? 'p-6 pb-3' : 'p-8 pb-4'} relative z-10`}>
            <div className={`flex items-start justify-between ${archived ? 'mb-4' : 'mb-8'}`}>
              <Badge className={`${badgeClass} text-[10px] font-bold uppercase tracking-[0.1em] ${archived ? 'px-3 py-1' : 'px-4 py-1.5'} rounded-full`}>
                {archived ? "ARCHIVED" : gradeLevelLabels[assignment.section.gradeLevel]}
              </Badge>
              <div className={`${archived ? 'w-8 h-8 rounded-lg' : 'w-10 h-10 rounded-xl'} ${archived ? "bg-rose-50 text-rose-500 group-hover:bg-rose-600 group-hover:text-white" : colors.button} flex items-center justify-center transition-all duration-500 shadow-sm`}>
                <ArrowUpRight className={`${archived ? 'w-4 h-4' : 'w-5 h-5'}`} />
              </div>
            </div>

            <div className="space-y-1">
              <p className={`text-[10px] font-bold uppercase tracking-[0.2em] ${mutedText}`}>Subject Title</p>
              <h3 className={`${archived ? 'text-lg' : 'text-2xl'} font-bold text-slate-900 ${titleHover} transition-colors leading-tight`}>
                {assignment.subject.name}
              </h3>
            </div>

            <div className={`${archived ? 'pt-3' : 'pt-4'} flex items-center gap-2`}>
              <div className={`w-1.5 h-1.5 rounded-full ${circleClass} animate-pulse`} />
              <p className={`${archived ? 'text-xs' : 'text-sm'} font-bold ${sectionText}`}>
                Section {assignment.section.name} &bull; {assignment.schoolYear}
              </p>
            </div>

            {archived && assignment.archivedReason && (
              <p className="mt-3 text-[10px] font-bold text-rose-600 bg-rose-50 rounded-xl px-3 py-2 border border-rose-100 leading-relaxed line-clamp-2">
                {assignment.archivedReason}
              </p>
            )}
          </CardHeader>

          <CardContent className={`${archived ? 'p-6 pt-4' : 'p-8 pt-6'} mt-auto relative z-10`}>
            <div className={`flex items-center justify-between ${archived ? 'pt-4' : 'pt-6'} border-t ${archived ? "border-rose-100" : "border-slate-50"}`}>
              <div className={`flex items-center ${archived ? 'gap-2' : 'gap-3'}`}>
                <div className={`${iconClass} flex items-center justify-center transition-colors shadow-sm`}>
                  <Users className={`${archived ? 'w-4 h-4' : 'w-5 h-5'}`} />
                </div>
                <div>
                  <p className={`text-[10px] font-bold uppercase tracking-widest ${mutedText}`}>Enrolled</p>
                  <p className={`${archived ? 'text-xs' : 'text-sm'} font-bold text-slate-900`}>{assignment.section.enrollments?.length || 0} Learners</p>
                </div>
              </div>

              <div className="text-right">
                <p className={`text-[10px] font-bold uppercase tracking-widest ${mutedText}`}>Weights</p>
                <p className={`${archived ? 'text-[10px]' : 'text-xs'} font-bold text-slate-900 font-mono tracking-tighter`}>
                  {displayWwWeight}/{displayPtWeight}/{displayQaWeight} (TA)
                </p>
              </div>
            </div>

            <div className={`${archived ? 'mt-3' : 'mt-4'} flex items-center justify-between`}>
              <Badge className={`${archived ? "bg-rose-100 text-rose-700 border-rose-200" : "bg-slate-100 text-slate-500 border-0"} text-[10px] font-bold uppercase tracking-widest ${archived ? 'px-2' : 'px-3'}`}>
                {archived ? "Backup" : "Active Record"}
              </Badge>
              <div className={`${chevronClass} flex items-center justify-center transition-all group-hover:translate-x-2`}>
                <ChevronRight className={`${archived ? 'w-5 h-5' : 'w-6 h-6'}`} />
              </div>
            </div>
          </CardContent>
        </Card>
      </Link>
      {archived && onDelete && (
        <Button
          variant="destructive"
          size="icon"
          className="absolute -top-3 -right-3 w-10 h-10 rounded-full bg-rose-600 text-white shadow-lg opacity-0 group-hover/card:opacity-100 transition-all z-20 hover:scale-110 active:scale-95"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            onDelete(assignment.id, assignment.subject.name);
          }}
        >
          <Trash2 className="w-5 h-5" />
        </Button>
      )}
    </div>
  );
}

export default function ClassRecordsList() {
  const { colors } = useTheme();
  const { syncVersion } = useSyncStream();
  const [classes, setClasses] = useState<ClassAssignment[]>([]);
  const [loading, setLoading] = useState(true);
  const [gradeDeadline, setGradeDeadline] = useState<GradeDeadlineInfo | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
  const [isArchivedExpanded, setIsArchivedExpanded] = useState(false);
  const [assignmentToDelete, setAssignmentToDelete] = useState<{ id: string; name: string } | null>(null);
  const [confirmDeleteAll, setConfirmDeleteAll] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Silent background sync on every page load ΓÇö pulls fresh data from Atlas
  useEffect(() => {
    advisoryApi.syncFromEnrollPro().catch(() => {/* silent fallback */ });
  }, []);

  useEffect(() => {
    const fetchClasses = async () => {
      try {
        const [classesRes, deadlineRes] = await Promise.all([
          gradesApi.getMyClasses(),
          gradesApi.getDeadlineStatus().catch(() => ({ data: { gradeDeadline: null } })),
        ]);
        setClasses(classesRes.data);
        setGradeDeadline(deadlineRes.data.gradeDeadline);
      } catch (err) {
        console.error("Failed to fetch classes:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchClasses();
  }, [syncVersion]);

  const handleDelete = async () => {
    if (!assignmentToDelete) return;
    setIsDeleting(true);
    try {
      await gradesApi.deleteClassAssignment(assignmentToDelete.id);
      setClasses(classes.filter((c) => c.id !== assignmentToDelete.id));
      setAssignmentToDelete(null);
    } catch (err) {
      console.error("Failed to delete class:", err);
      alert("Failed to delete class record. Please try again.");
    } finally {
      setIsDeleting(false);
    }
  };

  const handleDeleteAll = async () => {
    setIsDeleting(true);
    try {
      await gradesApi.deleteAllArchivedClassAssignments();
      setClasses(classes.filter((c) => c.isActive !== false && !c.archivedAt));
      setConfirmDeleteAll(false);
    } catch (err) {
      console.error("Failed to delete all archived classes:", err);
      alert("Failed to delete all archived records. Please try again.");
    } finally {
      setIsDeleting(false);
    }
  };

  const filteredClasses = classes.filter(
    (c) =>
      c.subject.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.section.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      gradeLevelLabels[c.section.gradeLevel].toLowerCase().includes(searchTerm.toLowerCase())
  );

  const activeClasses = filteredClasses.filter((assignment) => assignment.isActive !== false && !assignment.archivedAt);
  const archivedClasses = filteredClasses.filter((assignment) => assignment.isActive === false || !!assignment.archivedAt);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="text-center">
          <div
            className="w-20 h-20 mx-auto mb-6 rounded-2xl flex items-center justify-center shadow-lg animate-pulse"
            style={{ backgroundColor: `${colors.primary}15` }}
          >
            <div
              className="w-10 h-10 border-[3px] border-t-transparent rounded-full animate-spin"
              style={{ borderColor: colors.primary, borderTopColor: "transparent" }}
            />
          </div>
          <p className="text-gray-500  text-lg">Loading class masterlists...</p>
        </div>
      </div>
    );
  }

  const hasArchived = archivedClasses.length > 0;

  return (
    <div className="space-y-10 animate-fade-in max-w-7xl mx-auto pb-12">
      {/* Grade Submission Deadline Banner */}
      {gradeDeadline && (
