                    <Archive className="w-6 h-6" />
                  </div>
                  <div>
                    <h2 className="text-2xl font-bold text-slate-900">Archived Class Records</h2>
                    <p className="text-slate-500 ">Backup data from previous syncs or manual archives</p>
