                                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mb-1 text-center">WW / PT / TA</p>
                                <p className="text-sm text-slate-900 font-bold font-mono tracking-tighter text-center">
                                  {assignment.subject.writtenWorkWeight} / {assignment.subject.perfTaskWeight} / {assignment.subject.quarterlyAssessWeight}
