                                variant="destructive"
                                size="icon"
                                className="w-12 h-12 rounded-2xl bg-rose-600 text-white opacity-0 group-hover:opacity-100 transition-all shadow-lg shadow-rose-100 hover:scale-110 active:scale-95"
