                    ))}
                  </div>
                </Card>
              )}
            </div>
          )}
        </div>
      )}

      {activeClasses.length === 0 && archivedClasses.length === 0 && (
        <Card className="border-0 shadow-2xl shadow-slate-200/40 rounded-[2.5rem] bg-muted overflow-hidden">
          <CardContent className="py-32 text-center">
            <div className="w-24 h-24 bg-slate-50 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-sm">
              <BookOpen className="w-10 h-10 text-slate-200" />
            </div>
            <h3 className="font-bold text-slate-900 text-2xl mb-3">No Classes Found</h3>
            <p className="text-slate-400 max-w-sm mx-auto  text-lg leading-relaxed">
              {searchTerm
                ? "We couldn't find any classes matching your current search parameters."
                : "You don't have any assigned classes for this academic year yet."}
            </p>
          </CardContent>
        </Card>
      )}

      <Dialog open={!!assignmentToDelete} onOpenChange={(open) => !open && setAssignmentToDelete(null)}>
        <DialogContent className="w-full max-w-3xl rounded-[2rem] border-0 shadow-2xl p-0 overflow-hidden">
          <div className="bg-rose-600 p-8 text-white">
            <div className="w-16 h-16 bg-muted/20 rounded-[1.5rem] flex items-center justify-center mb-6 backdrop-blur-md">
              <Trash2 className="w-8 h-8 text-white" />
            </div>
            <DialogHeader className="p-0 text-left">
              <DialogTitle className="text-2xl font-bold text-white leading-tight">Are You sure to delete this Subject?</DialogTitle>
              <DialogDescription className="text-rose-100  text-base mt-2">
                Permanently removing <span className="font-bold text-white underline decoration-2 underline-offset-4">{assignmentToDelete?.name}</span> will erase all student grades and synchronization history for this record.
              </DialogDescription>
            </DialogHeader>
          </div>
          <DialogFooter className="p-8 bg-muted flex flex-col sm:flex-row gap-4">
            <Button
              variant="outline"
              onClick={() => setAssignmentToDelete(null)}
              className="h-14 rounded-2xl border-slate-200 font-bold hover:bg-slate-50 hover:text-slate-900 transition-all flex-1"
              disabled={isDeleting}
            >
              CANCEL
            </Button>
            <Button
              variant="destructive"
              onClick={handleDelete}
              className="h-14 rounded-2xl bg-rose-600 hover:bg-rose-700 text-white font-bold shadow-xl shadow-rose-100 transition-all flex-1"
              disabled={isDeleting}
            >
              {isDeleting ? (
                "DELETING..."
              ) : (
                <div className="flex items-center justify-center gap-2">
                  <Trash2 className="w-5 h-5" />
                  <span>YES, DELETE RECORD</span>
                </div>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <Dialog open={confirmDeleteAll} onOpenChange={setConfirmDeleteAll}>
        <DialogContent className="w-full max-w-3xl rounded-[2rem] border-0 shadow-2xl p-0 overflow-hidden">
          <div className="bg-rose-600 p-8 text-white">
            <div className="w-16 h-16 bg-muted/20 rounded-[1.5rem] flex items-center justify-center mb-6 backdrop-blur-md">
              <Trash2 className="w-8 h-8 text-white" />
            </div>
            <DialogHeader className="p-0 text-left">
              <DialogTitle className="text-2xl font-bold text-white leading-tight">Delete All Archived Records?</DialogTitle>
              <DialogDescription className="text-rose-100  text-base mt-2">
                This will permanently remove all <span className="font-bold text-white underline decoration-2 underline-offset-4">{archivedClasses.length} archived subjects</span>. This action cannot be undone and all historical grades for these records will be lost.
              </DialogDescription>
            </DialogHeader>
          </div>
          <DialogFooter className="p-8 bg-muted flex flex-col sm:flex-row gap-4">
            <Button
              variant="outline"
              onClick={() => setConfirmDeleteAll(false)}
              className="h-14 rounded-2xl border-slate-200 font-bold hover:bg-slate-50 hover:text-slate-900 transition-all flex-1"
              disabled={isDeleting}
            >
              CANCEL
            </Button>
            <Button
              variant="destructive"
              onClick={handleDeleteAll}
              className="h-14 rounded-2xl bg-rose-600 hover:bg-rose-700 text-white font-bold shadow-xl shadow-rose-100 transition-all flex-1"
              disabled={isDeleting}
            >
              {isDeleting ? (
                "DELETING ALL..."
              ) : (
                <div className="flex items-center justify-center gap-2">
                  <Trash2 className="w-5 h-5" />
                  <span>YES, DELETE ALL</span>
                </div>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// @ts-nocheck
import { useEffect, useState } from "react";
import { useSyncStream } from "@/features/smart/hooks/useSyncStream";
import { Link, useLocation } from "react-router";
import {
  Users,
  BookOpen,
  TrendingUp,
  AlertTriangle,
  CheckCircle2,
  BarChart3,
  Target,
  FileCheck,
  Star,
  Medal,
  Calendar,
  Sparkles,
} from "lucide-react";
import { Card, CardContent, CardHeader } from "@/features/smart/components/ui/card";
import { Badge } from "@/features/smart/components/ui/badge";
import { Button } from "@/features/smart/components/ui/button";
import { Avatar, AvatarFallback } from "@/features/smart/components/ui/avatar";
import { ScrollArea, _ScrollBar } from "@/features/smart/components/ui/scroll-area";
import { gradesApi, type ClassAssignment, type GradeDeadlineInfo } from "@/features/smart/lib/api";
import { useTheme } from "@/features/smart/contexts/ThemeContext";
import { GradeDeadlineBanner } from "@/features/smart/components/GradeDeadlineBanner";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/features/smart/components/ui/select";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
} from "recharts";

interface AdvisoryHonorsData {
  advisoryHonors: { id: string; name: string; grade: number; honor: string; class: string }[];
  withHonors: { id: string; name: string; grade: number; honor: string; class: string }[];
  hasAdvisory: boolean;
}

interface DashboardData {
  teacher: {
    name: string;
    employeeId: string;
    specialization?: string;
  };
  stats: {
    totalClasses: number;
    totalStudents: number;
    subjects: string[];
    archivedClassesCount?: number;
  };
  classAssignments: ClassAssignment[];
  archivedClassesCount?: number;
  currentTerm: string;
  gradeDeadline?: GradeDeadlineInfo | null;
}

interface ClassStats {
  id: string;
  subjectName: string;
  sectionName: string;
  gradeLevel: string;
  totalStudents: number;
  gradedCount: number;
  avgGrade: number | null;
  passingRate: number;
  studentsAtRisk: { id: string; name: string; grade: number; class: string }[];
  honorsStudents: { id: string; name: string; grade: number; honor: string }[];
  withHonorsStudents: { id: string; name: string; grade: number; honor: string }[];
}

interface DashboardStats {
  classStats: ClassStats[];
  summary: {
    totalClasses: number;
    totalStudents: number;
    totalGraded: number;
    gradeSubmissionRate: number;
    overallPassingRate: number;
    studentsAtRisk: { id: string; name: string; grade: number; class: string }[];
    studentsAtRiskCount: number;
  };
  archivedClassesCount?: number;
}

interface MasteryDistribution {
  distribution: {
    outstanding: number;
    verySatisfactory: number;
    satisfactory: number;
    fairlySatisfactory: number;
    didNotMeet: number;
  };
  totalStudents: number;
  filters: {
    gradeLevels: string[];
    sections: { id: string; name: string; gradeLevel: string }[];
  };
}

const gradeLevelLabels: Record<string, string> = {
  GRADE_7: "Grade 7",
  GRADE_8: "Grade 8",
  GRADE_9: "Grade 9",
  GRADE_10: "Grade 10",
};

export default function TeacherDashboard() {
  const { colors } = useTheme();
  const { syncVersion } = useSyncStream();
  const location = useLocation();
  const [data, setData] = useState<DashboardData | null>(null);
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [masteryData, setMasteryData] = useState<MasteryDistribution | null>(null);
  const [advisoryHonors, setAdvisoryHonors] = useState<AdvisoryHonorsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedHonorsTerm, setSelectedHonorsTerm] = useState<string>("all");
  const [selectedGradeLevel, setSelectedGradeLevel] = useState<string>("all");
  const [selectedSection, setSelectedSection] = useState<string>("all");

  // Fetch mastery distribution with filters
  const fetchMasteryDistribution = async (gradeLevel?: string, sectionId?: string) => {
    try {
      const res = await gradesApi.getMasteryDistribution(
        gradeLevel === "all" ? undefined : gradeLevel,
        sectionId === "all" ? undefined : sectionId
      );
      setMasteryData(res.data);
    } catch (err) {
      console.error("Error fetching mastery distribution:", err);
    }
  };

  useEffect(() => {
    const fetchDashboard = async () => {
      try {
        const [dashboardRes, statsRes, masteryRes, advisoryHonorsRes] = await Promise.all([
          gradesApi.getDashboard(),
          gradesApi.getDashboardStats(),
          gradesApi.getMasteryDistribution(),
          gradesApi.getAdvisoryHonors(),
        ]);
        setData(dashboardRes.data);
        setStats(statsRes.data);
        setMasteryData(masteryRes.data);
        setAdvisoryHonors(advisoryHonorsRes.data);
        setSelectedHonorsTerm(dashboardRes.data.currentTerm);
      } catch (err) {
        setError("Failed to load dashboard data");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchDashboard();
  }, [syncVersion, location.key]);

  // Update mastery data when filters change
  useEffect(() => {
    if (!loading) {
      fetchMasteryDistribution(selectedGradeLevel, selectedSection);
    }
  }, [selectedGradeLevel, selectedSection]);

  // Update honors data when term changes
  useEffect(() => {
    if (!loading && selectedHonorsTerm && selectedHonorsTerm !== "all") {
      const fetchHonors = async () => {
        try {
          const res = await gradesApi.getAdvisoryHonors(selectedHonorsTerm);
          setAdvisoryHonors(res.data);
        } catch (err) {
          console.error("Error fetching honors:", err);
        }
      };
      fetchHonors();
    }
  }, [selectedHonorsTerm]);

  // Get filtered sections based on selected grade level
  const filteredSections = selectedGradeLevel === "all"
    ? masteryData?.filters.sections || []
    : masteryData?.filters.sections.filter(s => s.gradeLevel === selectedGradeLevel) || [];

  // Prepare chart data with more vibrant colors
  const chartData = masteryData ? [
    {
      name: "Outstanding",
      range: "90-100",
      students: masteryData.distribution.outstanding,
      fill: "#10b981", // Emerald 500
      secondary: "#059669" // Emerald 600
    },
    {
      name: "Very Satisfactory",
      range: "85-89",
      students: masteryData.distribution.verySatisfactory,
      fill: "#3b82f6", // Blue 500
      secondary: "#2563eb" // Blue 600
    },
    {
      name: "Satisfactory",
      range: "80-84",
      students: masteryData.distribution.satisfactory,
      fill: "#f59e0b", // Amber 500
      secondary: "#d97706" // Amber 600
    },
    {
      name: "Fairly Satisfactory",
      range: "75-79",
      students: masteryData.distribution.fairlySatisfactory,
      fill: "#f97316", // Orange 500
      secondary: "#ea580c" // Orange 600
    },
    {
      name: "Did Not Meet",
      range: "<75",
      students: masteryData.distribution.didNotMeet,
      fill: "#ef4444", // Red 500
      secondary: "#dc2626" // Red 600
    },
  ] : [];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[80vh]">
        <div className="text-center">
          <div className="relative w-24 h-24 mx-auto mb-6">
            <div className="absolute inset-0 rounded-full border-4 border-slate-100" />
            <div className="absolute inset-0 rounded-full border-4 border-indigo-500 border-t-transparent animate-spin" />
            <div className="absolute inset-0 flex items-center justify-center">
              <Sparkles className="w-8 h-8 text-indigo-500 animate-pulse" />
            </div>
          </div>
          <p className="text-slate-500  text-lg animate-pulse">Igniting your dashboard...</p>
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="flex items-center justify-center h-[60vh] p-4">
        <Card className="max-w-md w-full border-0 shadow-2xl rounded-3xl overflow-hidden">
          <div className="h-2 bg-red-500" />
          <CardContent className="p-10 text-center">
            <div className="w-20 h-20 mx-auto mb-6 rounded-2xl bg-red-50 flex items-center justify-center text-red-500">
              <AlertTriangle className="w-10 h-10" />
            </div>
            <h3 className="font-bold text-slate-900 text-2xl mb-2">Oops! Something's wrong</h3>
            <p className="text-slate-500 mb-8">{error || "We couldn't load your dashboard data right now."}</p>
            <Button
              onClick={() => window.location.reload()}
              className="w-full h-12 rounded-xl bg-slate-900 hover:bg-slate-800 text-white shadow-lg transition-all"
            >
              Try to Refresh
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in max-w-7xl mx-auto pb-12">
      {/* Grade Submission Deadline Banner */}
      {data.gradeDeadline && (
        <GradeDeadlineBanner deadline={data.gradeDeadline} />
      )}

      {/* Hero Welcome Section - Refined for "Professional Settings" */}
      <div className="relative overflow-hidden rounded-[2.5rem] bg-muted border border-slate-200 p-8 md:p-12 shadow-xl shadow-slate-200/50">
        <div className="absolute top-0 right-0 w-1/3 h-full bg-slate-50/50 -skew-x-12 translate-x-1/2" />
        <div className="absolute top-0 right-1/4 w-px h-full bg-slate-100" />

        <div className="relative z-10 flex flex-col lg:flex-row lg:items-center justify-between gap-10">
          <div className="max-w-2xl">
            <div className="flex items-center gap-3 mb-6">
              <Badge variant="secondary" className="px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-widest border"
                style={{ backgroundColor: `${colors.primary}15`, color: colors.primary, borderColor: `${colors.primary}30` }}>
                <Target className="w-3 h-3 mr-2" />
                {data.currentTerm === 'T1' ? 'Term 1' :
                  data.currentTerm === 'T2' ? 'Term 2' :
                    data.currentTerm === 'T3' ? 'Term 3' :
                      'Teacher Portal v2.0'}
              </Badge>
              <div className="h-4 w-px bg-slate-200" />
              <div className="flex items-center gap-1.5 text-slate-400 text-[10px] font-bold uppercase tracking-widest">
                <Calendar className="w-3 h-3" />
                S.Y. {data.classAssignments[0]?.schoolYear || "2026-2027"}
              </div>
            </div>

            <h1 className="text-4xl md:text-5xl font-bold text-slate-900 leading-[1.1] tracking-tight">
              Good day, <br />
              <span className="font-bold" style={{ color: colors.primary }}>
                Teacher {data.teacher.name.split(',')[0]}
              </span>
            </h1>

            <p className="text-slate-500 text-lg mt-6 max-w-lg leading-relaxed ">
              You're currently managing <span className="text-slate-900 font-bold underline decoration-indigo-200 decoration-4 underline-offset-4">{data.stats.totalStudents} students</span> across <span className="text-slate-900 font-bold underline decoration-emerald-200 decoration-4 underline-offset-4">{data.stats.totalClasses} classes</span>.
            </p>

            <div className="flex flex-wrap items-center gap-4 mt-10">
              <Link to="/teacher/advisory">
                <Button className="h-14 px-8 rounded-2xl text-white shadow-xl border-0 transition-all active:scale-95 group font-bold"
                  style={{ backgroundColor: colors.primary, boxShadow: `0 20px 25px -5px ${colors.primary}40` }}>
                  <Users className="w-5 h-5 mr-3 group-hover:rotate-12 transition-transform" />
                  My Advisory
                </Button>
              </Link>
              <Link to="/teacher/classes">
                <Button variant="outline" className="h-14 px-8 rounded-2xl bg-muted border-slate-200 text-slate-700 hover:bg-slate-50 hover:border-slate-300 shadow-sm transition-all active:scale-95 font-bold">
                  <BookOpen className="w-5 h-5 mr-3" />
                  Class Records
                </Button>
              </Link>
            </div>
          </div>

          <div className="hidden lg:flex flex-col gap-4 min-w-[300px]">
            <div className="p-6 rounded-3xl bg-slate-50 border border-slate-100 flex items-center justify-between group hover:border-indigo-200 transition-all">
              <div>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Overall Passing</p>
                <p className="text-4xl font-bold text-slate-900">{stats?.summary.overallPassingRate.toFixed(0)}%</p>
              </div>
              <div className="w-14 h-14 rounded-2xl bg-muted shadow-sm flex items-center justify-center group-hover:scale-110 transition-all">
                <TrendingUp className="w-7 h-7 text-emerald-500" />
              </div>
            </div>
            <div className="p-6 rounded-3xl bg-slate-50 border border-slate-100 flex items-center justify-between group hover:border-indigo-200 transition-all">
              <div>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Grade Submission</p>
                <p className="text-4xl font-bold text-slate-900">{stats?.summary.gradeSubmissionRate.toFixed(0)}%</p>
              </div>
              <div className="w-14 h-14 rounded-2xl bg-muted shadow-sm flex items-center justify-center group-hover:scale-110 transition-all">
                <FileCheck className="w-7 h-7 text-indigo-500" />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Stats Cards - Refined Professional Look */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          {
            label: "Active Students",
            value: data.stats.totalStudents,
            icon: Users,
            bg: "bg-indigo-50", fg: "text-indigo-600",
            desc: "Currently enrolled"
          },
          {
            label: "Handled Classes",
            value: data.stats.totalClasses,
            icon: BookOpen,
            bg: "bg-emerald-50", fg: "text-emerald-600",
            desc: "Teaching assignments"
          },
          {
            label: "Critical Cases",
            value: stats?.summary.studentsAtRiskCount || 0,
            icon: AlertTriangle,
            bg: "bg-rose-50", fg: "text-rose-600",
            desc: "Requires immediate attention"
          },
          {
            label: "Graded Items",
            value: stats?.summary.totalGraded || 0,
            icon: FileCheck,
            bg: "bg-amber-50", fg: "text-amber-600",
            desc: "Successful submissions"
          },
        ].map((stat) => (
          <Card key={stat.label} className="border-0 shadow-lg shadow-slate-200/50 rounded-3xl overflow-hidden group hover:-translate-y-1 transition-all duration-300 bg-muted">
            <CardContent className="p-6">
              <div className="flex items-center gap-4 mb-4">
                <div className={`p-3 rounded-2xl ${stat.bg} ${stat.fg} group-hover:scale-110 transition-transform`}>
                  <stat.icon className="w-5 h-5" />
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{stat.label}</p>
                  <p className="text-2xl font-bold text-slate-900 mt-0.5">{stat.value}</p>
                </div>
              </div>
              <p className="text-[10px]  text-slate-400 pl-1">{stat.desc}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {(data.archivedClassesCount || stats?.archivedClassesCount || 0) > 0 && (
        <Card className="border-0 shadow-2xl shadow-rose-100/40 rounded-[2.5rem] overflow-hidden bg-rose-50/70 border border-rose-100">
          <CardContent className="p-6 md:p-8 flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-[0.25em] text-rose-600">Atlas removal detected</p>
              <h3 className="text-lg font-bold text-slate-900 mt-1">{data.archivedClassesCount || stats?.archivedClassesCount || 0} subject assignment(s) were removed from the current Atlas load</h3>
              <p className="text-sm text-slate-600  mt-1">SMART keeps the grade history, but these assignments are hidden from active dashboard counts. Contact the EnrollPro/Atlas admin if this was not intended.</p>
            </div>
            <Badge className="bg-rose-600 text-white font-bold px-4 py-2 rounded-xl border-0 shadow-lg shadow-rose-300/50 text-sm self-start md:self-center">
              CONTACT ADMIN
            </Badge>
          </CardContent>
        </Card>
      )}

      {/* ΓöÇΓöÇ Performance Mastery ΓöÇΓöÇ Full Width */}
      <Card className="border-0 shadow-2xl shadow-slate-200/40 rounded-[2.5rem] overflow-hidden flex flex-col bg-muted">
        <CardHeader className="p-8 pb-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl bg-slate-900 text-white">
                <BarChart3 className="w-5 h-5" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-slate-900">Performance Mastery</h2>
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-1">Distribution of student ratings</p>
              </div>
            </div>

            <div className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
              <Select value={selectedGradeLevel} onValueChange={(val) => {
                if (val) setSelectedGradeLevel(val);
                setSelectedSection("all");
              }}>
                <SelectTrigger className="h-9 w-[110px] bg-muted border-slate-200 rounded-xl text-[10px] font-bold uppercase tracking-wider shadow-sm focus:ring-2 focus:ring-slate-100 transition-all">
                  <SelectValue placeholder="Grade" />
                </SelectTrigger>
                <SelectContent className="rounded-xl border-slate-200 shadow-xl">
                  <SelectItem value="all" className="text-xs font-bold uppercase">All Grades</SelectItem>
                  {masteryData?.filters.gradeLevels.map(gl => (
                    <SelectItem key={gl} value={gl} className="text-xs font-bold uppercase">{gradeLevelLabels[gl] || gl}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={selectedSection} onValueChange={(val) => val && setSelectedSection(val)}>
                <SelectTrigger className="h-9 w-[130px] bg-muted border-slate-200 rounded-xl text-[10px] font-bold uppercase tracking-wider shadow-sm focus:ring-2 focus:ring-slate-100 transition-all">
                  <SelectValue placeholder="Section" />
                </SelectTrigger>
                <SelectContent className="rounded-xl border-slate-200 shadow-xl">
                  <SelectItem value="all" className="text-xs font-bold uppercase">All Sections</SelectItem>
                  {filteredSections.map(s => (
                    <SelectItem key={s.id} value={s.id} className="text-xs font-bold uppercase">{s.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-8 pt-0 flex-1">
          <div className="h-[320px] w-full mt-6">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  {chartData.map((entry, index) => (
                    <linearGradient key={`gradient-${index}`} id={`barGradient-${index}`} x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor={entry.fill} stopOpacity={1} />
                      <stop offset="100%" stopColor={entry.secondary} stopOpacity={0.8} />
                    </linearGradient>
                  ))}
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis
                  dataKey="name"
                  tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 800 }}
                  axisLine={false}
                  tickLine={false}
                  interval={0}
                  dy={10}
                />
                <YAxis
                  tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 800 }}
                  axisLine={false}
                  tickLine={false}
                />
                <Tooltip
                  cursor={{ fill: '#f8fafc', radius: 12 }}
                  contentStyle={{
                    border: 'none',
                    borderRadius: '20px',
                    boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)',
                    padding: '16px',
                    backgroundColor: '#fff'
                  }}
                  itemStyle={{ fontWeight: 900, fontSize: '14px' }}
                />
                <Bar dataKey="students" radius={[12, 12, 0, 0]} maxBarSize={60}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={`url(#barGradient-${index})`} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>

      {/* ΓöÇΓöÇ Grading Status ΓöÇΓöÇ Full Width Big Card */}
      <Card className="border-0 shadow-2xl shadow-slate-200/40 rounded-[2.5rem] overflow-hidden bg-muted">
        <CardHeader className="p-8 pb-6">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-slate-100 text-slate-900">
              <FileCheck className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-slate-900">Grading Status</h2>
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-1">Submission progress per class</p>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-8 pt-0">
          {stats?.classStats && stats.classStats.length > 0 ? (
            <ScrollArea className="h-[520px] pr-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 pb-6">
                {stats.classStats.map((classStat, idx) => {
                  const percentage = classStat.totalStudents > 0
                    ? Math.round((classStat.gradedCount / classStat.totalStudents) * 100)
                    : 0;
                  const barColorList = [colors.primary, '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4'];
                  const barColor = barColorList[idx % barColorList.length];
                  return (
                    <div key={classStat.id} className="p-6 rounded-3xl bg-slate-50 border border-slate-100 hover:border-slate-200 transition-all">
                      <div className="flex items-center justify-between mb-4">
                        <div>
                          <p className="text-sm font-bold text-slate-900 leading-tight">{classStat.sectionName}</p>
                          <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">{classStat.subjectName}</p>
                        </div>
                        <span className="text-xl font-bold" style={{ color: barColor }}>{percentage}%</span>
                      </div>
                      <div className="h-3 bg-muted rounded-full overflow-hidden shadow-inner">
                        <div
                          className="h-full rounded-full transition-all duration-1000 ease-out"
                          style={{ width: `${percentage}%`, backgroundColor: barColor }}
                        />
                      </div>
                      <div className="flex justify-between mt-3">
                        <p className="text-[9px] font-bold text-slate-400">{classStat.gradedCount} graded</p>
                        <p className="text-[9px] font-bold text-slate-400">{classStat.totalStudents} total</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </ScrollArea>
          ) : (
            <div className="py-16 text-center text-slate-300">
              <FileCheck className="w-12 h-12 mx-auto mb-3 opacity-30" />
              <p className="font-bold text-sm uppercase tracking-widest">No class records found</p>
            </div>
          )}
          <div className="mt-8">
            <Link to="/teacher/classes">
              <Button className="w-full h-14 rounded-2xl bg-slate-900 hover:bg-slate-800 text-white shadow-xl shadow-slate-200 transition-all font-bold text-[10px] tracking-[0.2em] uppercase">
                VIEW DETAILED REPORTS
              </Button>
            </Link>
          </div>
        </CardContent>
      </Card>

      {/* ΓöÇΓöÇ Academic Honors ΓöÇΓöÇ Full Width */}
      <Card className="border-0 shadow-2xl shadow-slate-200/40 rounded-[2.5rem] overflow-hidden bg-muted">
        <CardHeader className="p-8 pb-4 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-amber-50 text-amber-600">
              <Medal className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-slate-900">Academic Honors</h2>
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-1">Leading advisory achievements</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {advisoryHonors?.hasAdvisory && (
              <Badge variant="secondary" className="bg-slate-50 text-slate-400 border-slate-100 font-bold px-4 py-2 rounded-xl text-[10px] tracking-widest uppercase">
                ADVISORY CLASS
              </Badge>
            )}

            <Select value={selectedHonorsTerm} onValueChange={(val) => val && setSelectedHonorsTerm(val)}>
              <SelectTrigger className="h-9 w-[130px] bg-slate-50 border-slate-100 rounded-xl text-[10px] font-bold uppercase tracking-wider shadow-sm">
                <SelectValue placeholder="Select Term" />
              </SelectTrigger>
              <SelectContent className="rounded-xl border-slate-200 shadow-xl">
                <SelectItem value="T1" className="text-xs font-bold uppercase">Term 1</SelectItem>
                <SelectItem value="T2" className="text-xs font-bold uppercase">Term 2</SelectItem>
                <SelectItem value="T3" className="text-xs font-bold uppercase">Term 3</SelectItem>
                <SelectItem value="FINAL" className="text-xs font-bold uppercase">Final Grade</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="max-h-[420px] overflow-y-auto px-8 pb-8">
            {(() => {
              const allHonors = [
                ...(advisoryHonors?.advisoryHonors || []),
                ...(advisoryHonors?.withHonors || []),
              ].sort((a, b) => b.grade - a.grade);

              if (allHonors.length === 0) {
                return (
                  <div className="py-20 text-center text-slate-300 bg-slate-50 rounded-[2rem] mt-4 border-2 border-dashed border-slate-100">
                    <Star className="w-12 h-12 mx-auto mb-4 opacity-20" />
                    <p className="font-bold text-sm uppercase tracking-widest">No advisory honors yet</p>
                    <p className="text-[10px] font-bold mt-2">Students with grades of 85 and above will appear here.</p>
                  </div>
                );
              }

              return (
                <div className="overflow-hidden rounded-3xl border border-slate-100 mt-4">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="bg-slate-50/50 border-b border-slate-100">
                        <th className="px-6 py-4 text-left text-[10px] font-bold text-slate-400 uppercase tracking-widest">Student</th>
                        <th className="px-6 py-4 text-left text-[10px] font-bold text-slate-400 uppercase tracking-widest">Section</th>
                        <th className="px-6 py-4 text-center text-[10px] font-bold text-slate-400 uppercase tracking-widest">Grade</th>
                        <th className="px-6 py-4 text-right text-[10px] font-bold text-slate-400 uppercase tracking-widest">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {allHonors.map((student, idx) => (
                        <tr key={idx} className="hover:bg-slate-50/50 transition-all">
                          <td className="px-6 py-5">
                            <div className="flex items-center gap-3">
                              <Avatar className="w-12 h-12 border-2 border-white shadow-sm">
                                <AvatarFallback className="font-bold text-xs text-white" style={{ backgroundColor: colors.primary }}>
                                  {student.name.charAt(0)}
                                </AvatarFallback>
                              </Avatar>
                              <span className="font-bold text-slate-900 text-sm tracking-tight">{student.name}</span>
                            </div>
                          </td>
                          <td className="px-6 py-5 text-slate-500 font-bold text-xs">{student.class}</td>
                          <td className="px-6 py-5 text-center">
                            <span className="font-bold text-xs px-3 py-1.5 rounded-xl" style={{ color: colors.primary, backgroundColor: `${colors.primary}15` }}>
                              {typeof student.grade === 'number' ? student.grade.toFixed(2) : student.grade}
                            </span>
                          </td>
                          <td className="px-6 py-5 text-right">
                            <Badge className="bg-emerald-500 text-white border-0 text-[9px] font-bold uppercase px-3 py-1 rounded-lg shadow-lg shadow-emerald-500/20">
                              {student.honor}
                            </Badge>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              );
            })()}
          </div>
        </CardContent>
      </Card>

      {/* ΓöÇΓöÇ Students Needing Attention ΓöÇΓöÇ Full Width Big Card */}
      <Card className="border-0 shadow-2xl shadow-slate-200/40 rounded-[2.5rem] overflow-hidden bg-muted border-t-[8px] border-t-rose-500">
        <CardHeader className="p-8 pb-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="p-3 rounded-2xl bg-rose-50 text-rose-500">
                <AlertTriangle className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-2xl font-bold text-slate-900">Students Needing Attention</h2>
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-1">Immediate intervention required</p>
              </div>
            </div>
            <Badge className="bg-rose-500 text-white font-bold px-4 py-2 rounded-xl border-0 shadow-lg shadow-rose-500/30 text-sm">
              {stats?.summary.studentsAtRisk.length || 0} students
            </Badge>
          </div>
        </CardHeader>
        <CardContent className="p-8 pt-0">
          {stats?.summary.studentsAtRisk && stats.summary.studentsAtRisk.length > 0 ? (
            <ScrollArea className="h-[350px] pr-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 pb-4">
                {stats.summary.studentsAtRisk.map((student, idx) => (
                  <div key={idx} className="p-6 rounded-3xl bg-rose-50/40 border border-rose-100 hover:bg-rose-50 hover:border-rose-200 transition-all flex flex-col gap-4">
                    <div className="flex items-center gap-3">
                      <div className="w-12 h-12 rounded-2xl bg-muted shadow-sm flex items-center justify-center text-rose-500 shrink-0">
                        <Users className="w-6 h-6" />
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-bold text-slate-900 truncate">{student.name}</p>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5 truncate">{student.class}</p>
                      </div>
                    </div>
                    <div className="flex items-center justify-between pt-2 border-t border-rose-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Grade</p>
                      <div className="flex items-center gap-2">
                        <span className="text-2xl font-bold text-rose-600 leading-none">
                          {typeof student.grade === 'number' ? student.grade.toFixed(2) : student.grade}
                        </span>
                        <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-lg"
                          style={{ backgroundColor: student.grade <= 72 ? '#fef2f2' : '#fff7ed', color: student.grade <= 72 ? '#dc2626' : '#ea580c' }}>
                          {student.grade <= 72 ? 'INC' : 'FAILED'}
                        </span>
                      </div>
                    </div>                  </div>
                ))}
              </div>
            </ScrollArea>
          ) : (
            <div className="py-24 flex flex-col items-center justify-center text-center bg-emerald-50/50 rounded-[2.5rem] border-2 border-dashed border-emerald-100">
              <CheckCircle2 className="w-16 h-16 mb-4 text-emerald-400" />
              <p className="font-bold text-emerald-800 text-lg uppercase tracking-widest">All students passed!</p>
              <p className="text-[10px] text-emerald-600 font-bold px-8 mt-3 leading-relaxed max-w-md text-center">
                Great job maintaining academic performance across all classes!
              </p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

// @ts-nocheck
import { useEffect, useState, useCallback } from "react";
import { useSyncStream } from "@/features/smart/hooks/useSyncStream";
import { Link, useLocation } from "react-router";
import {
  Users,
  GraduationCap,
  ChevronRight,
  Search,
  UserCircle,
  ClipboardList,
  SplitSquareHorizontal,
  RefreshCw,
} from "lucide-react";
import { Card, CardContent, CardHeader } from "@/features/smart/components/ui/card";
import { Badge } from "@/features/smart/components/ui/badge";
import { Button } from "@/features/smart/components/ui/button";
import { Input } from "@/features/smart/components/ui/input";
import { Avatar, AvatarFallback } from "@/features/smart/components/ui/avatar";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/features/smart/components/ui/table";
import { advisoryApi, type AdvisoryData } from "@/features/smart/lib/api";
import { useTheme } from "@/features/smart/contexts/ThemeContext";
import { cn } from "@/features/smart/lib/utils";

const gradeLevelLabels: Record<string, string> = {
  GRADE_7: "Grade 7",
  GRADE_8: "Grade 8",
  GRADE_9: "Grade 9",
  GRADE_10: "Grade 10",
};

export default function MyAdvisory() {
  const location = useLocation();
  const { colors } = useTheme();
  const { syncVersion } = useSyncStream();
  const [data, setData] = useState<AdvisoryData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [separateByGender, setSeparateByGender] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string | null>(null);

  const handleSync = async () => {
    setSyncing(true);
    setSyncMessage(null);
    try {
      const res = await advisoryApi.syncFromEnrollPro();
      const { studentsFound, advisorySection: foundSection } = (res.data as any);
      if (!foundSection) {
        setSyncMessage("Sync complete ΓÇö no advisory section found. If you are assigned an advisory class, please contact the admin.");
      } else {
        setSyncMessage(`Sync complete ΓÇö ${studentsFound} student${studentsFound !== 1 ? 's' : ''} found for ${foundSection}.`);
      }
      await fetchAdvisory();
    } catch {
      setSyncMessage("Sync failed. Please try again.");
    } finally {
      setSyncing(false);
    }
  };

  const fetchAdvisory = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    if (!silent) setError(null);
    try {
      const res = await advisoryApi.getMyAdvisory();
      setData(res.data);
    } catch (err) {
      if (!silent) setError("Failed to load advisory data");
      console.error(err);
    } finally {
      if (!silent) setLoading(false);
    }
  }, []);

  // Re-fetch when navigating to the page (location.key changes) or after background sync
  useEffect(() => {
    fetchAdvisory();
  }, [fetchAdvisory, location.key, syncVersion]);

  // Silent background sync on every page load ΓÇö pulls fresh data from EnrollPro
  // then re-fetches advisory so new students appear automatically
  useEffect(() => {
    advisoryApi.syncFromEnrollPro()
      .then(() => fetchAdvisory(true)) // silent=true: no spinner, no error toast
      .catch(() => {/* silent ΓÇö manual button still available */ });
  }, [location.key]); // eslint-disable-line react-hooks/exhaustive-deps

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="text-center">
          <div
            className="w-20 h-20 mx-auto mb-6 rounded-2xl flex items-center justify-center shadow-lg animate-pulse"
            style={{ backgroundColor: `${colors.primary}10` }}
          >
            <div
              className="w-10 h-10 border-[3px] border-t-transparent rounded-full animate-spin"
              style={{ borderColor: colors.primary, borderTopColor: 'transparent' }}
            />
          </div>
          <p className="text-slate-500  text-lg">Loading advisory records...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-[60vh] p-4">
        <div className="text-center max-w-sm p-10 bg-muted rounded-[2.5rem] shadow-2xl shadow-slate-200/50 border border-slate-100">
          <div className="w-20 h-20 mx-auto mb-6 rounded-3xl bg-rose-50 flex items-center justify-center">
            <UserCircle className="w-10 h-10 text-rose-500" />
          </div>
          <h3 className="font-bold text-slate-900 text-2xl mb-2">Access Denied</h3>
          <p className="text-slate-500 mb-8 text-sm leading-relaxed">{error}</p>
          <Button
            onClick={() => window.location.reload()}
            className="w-full h-12 rounded-2xl bg-slate-900 hover:bg-slate-800 text-white font-bold transition-all"
          >
            Try to Reconnect
          </Button>
        </div>
      </div>
    );
  }

  if (!data?.hasAdvisory) {
    return (
      <div className="flex items-center justify-center h-[60vh] p-4">
        <div className="text-center max-w-md p-10 bg-muted rounded-[2.5rem] border border-slate-100 shadow-2xl shadow-slate-200/50">
          <div className="w-20 h-20 mx-auto mb-6 rounded-3xl bg-slate-50 flex items-center justify-center text-slate-300">
            <ClipboardList className="w-10 h-10" />
          </div>
          <h3 className="font-bold text-slate-900 text-2xl mb-3">No Advisory Assigned</h3>
          <p className="text-slate-500 mb-8 text-sm leading-relaxed">
            You are not currently designated as an adviser for any section. Please contact the registrar or system administrator for assignment.
          </p>
          <div className="flex flex-col gap-3">
            <Button
              onClick={handleSync}
              disabled={syncing}
              className="w-full h-12 rounded-2xl font-bold transition-all"
              style={{ backgroundColor: syncing ? undefined : colors.primary }}
            >
              <RefreshCw className={`w-4 h-4 mr-2 ${syncing ? 'animate-spin' : ''}`} />
              {syncing ? 'Syncing from EnrollPro...' : 'Sync from EnrollPro'}
            </Button>
            {syncMessage && <p className="text-xs text-slate-500 text-center">{syncMessage}</p>}
            <Link to="/teacher" className="w-full">
              <Button variant="outline" className="w-full h-12 rounded-2xl border-slate-200 text-slate-600 font-bold hover:bg-slate-50 transition-all">
                Return to Dashboard
              </Button>
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // Filter students based on search query
  const filteredStudents = data.students?.filter((student) => {
    const fullName = `${student.lastName}, ${student.firstName} ${student.middleName || ""}`.toLowerCase();
    const lrn = student.lrn.toLowerCase();
    const query = searchQuery.toLowerCase();
    return fullName.includes(query) || lrn.includes(query);
  }) || [];

  // Separate by gender if enabled
  const maleStudents = filteredStudents
    .filter((s) => s.gender?.toLowerCase() === "male")
    .sort((a, b) => {
      const nameA = `${a.lastName}, ${a.firstName}`.toLowerCase();
      const nameB = `${b.lastName}, ${b.firstName}`.toLowerCase();
      return nameA.localeCompare(nameB);
    });

  const femaleStudents = filteredStudents
    .filter((s) => s.gender?.toLowerCase() === "female")
    .sort((a, b) => {
      const nameA = `${a.lastName}, ${a.firstName}`.toLowerCase();
      const nameB = `${b.lastName}, ${b.firstName}`.toLowerCase();
      return nameA.localeCompare(nameB);
    });

  // Combined list (alphabetically sorted)
  const sortedStudents = [...filteredStudents].sort((a, b) => {
    const nameA = `${a.lastName}, ${a.firstName}`.toLowerCase();
    const nameB = `${b.lastName}, ${b.firstName}`.toLowerCase();
    return nameA.localeCompare(nameB);
  });

  return (
    <div className="space-y-8 animate-fade-in max-w-7xl mx-auto pb-12">
      {/* Header Section - Refined Glass Style */}
      <div className="relative overflow-hidden rounded-[2.5rem] bg-muted border border-slate-100 p-8 shadow-xl shadow-slate-200/50">
        <div
          className="absolute top-0 right-0 w-64 h-64 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"
          style={{ backgroundColor: `${colors.primary}15` }}
        />

        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-8">
          <div className="flex items-center gap-6">
            <div
              className="w-20 h-20 rounded-[2rem] text-white flex items-center justify-center shadow-xl transition-all duration-500"
              style={{
                backgroundColor: colors.primary,
                boxShadow: `0 20px 25px -5px ${colors.primary}40, 0 10px 10px -5px ${colors.primary}20`
              }}
            >
              <GraduationCap className="w-10 h-10" />
            </div>
            <div>
              <div className="flex items-center gap-3 mb-1.5">
                <Badge
                  variant="secondary"
                  className="text-[10px] font-bold uppercase tracking-widest px-3 border"
                  style={{
                    backgroundColor: `${colors.primary}10`,
                    color: colors.primary,
                    borderColor: `${colors.primary}20`
                  }}
                >
                  Class Adviser
                </Badge>
                <div className="h-4 w-px bg-slate-200" />
                <span className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">S.Y. {data.section?.schoolYear}</span>
              </div>
              <h1 className="text-3xl font-bold text-slate-900 tracking-tight">
                {gradeLevelLabels[data.section?.gradeLevel || ""] || data.section?.gradeLevel} &mdash; {data.section?.name}
              </h1>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1.5 flex items-center gap-1.5">
                <Users className="w-3.5 h-3.5" />
                {data.stats?.totalStudents || 0} Learners Managed
              </p>
            </div>
          </div>

          <div className="flex flex-col items-end gap-3">
            <div className="flex items-center gap-4 bg-slate-50/80 backdrop-blur-sm px-6 py-4 rounded-[2rem] border border-slate-100 shadow-sm">
              <Avatar className="w-12 h-12 border-2 border-white shadow-md">
                <AvatarFallback
                  className="text-white font-bold text-lg"
                  style={{ backgroundColor: colors.primary }}
                >
                  {data.teacher.name.charAt(0)}
                </AvatarFallback>
              </Avatar>
              <div>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none mb-1.5">Assigned Teacher</p>
                <p className="text-base font-bold text-slate-800 tracking-tight">{data.teacher.name}</p>
              </div>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={handleSync}
              disabled={syncing}
              className="h-10 px-5 rounded-2xl border-slate-200 text-slate-600 font-bold text-[10px] uppercase tracking-widest transition-all group/sync"
            >
              <RefreshCw className={`w-3.5 h-3.5 mr-2 ${syncing ? 'animate-spin' : ''} group-hover/sync:text-primary`} />
              <span className="group-hover/sync:text-slate-900">{syncing ? 'SYNCING...' : 'SYNC FROM ENROLLPRO'}</span>
              <style dangerouslySetInnerHTML={{
                __html: `
                .group\\/sync:hover {
                  background-color: ${colors.primary}10 !important;
                  border-color: ${colors.primary}30 !important;
                  color: ${colors.primary} !important;
                }
              `}} />
            </Button>
            {syncMessage && (
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{syncMessage}</p>
            )}
          </div>
        </div>
      </div>

      {/* Quick Insights Grid */}
      <div className="grid grid-cols-2 lg:grid-cols-3 gap-6">
        {[
          { label: "TOTAL CLASS", value: data.stats?.totalStudents || 0, icon: Users, color: "theme" },
          { label: "MALE LEARNERS", value: data.stats?.maleCount || 0, icon: UserCircle, color: "blue" },
          { label: "FEMALE LEARNERS", value: data.stats?.femaleCount || 0, icon: UserCircle, color: "pink" },
        ].map((stat) => (
          <Card key={stat.label} className="border-0 shadow-lg shadow-slate-200/50 overflow-hidden rounded-[2rem] bg-muted group hover:-translate-y-1 transition-all duration-300">
            <CardContent className="p-6 flex items-center gap-5">
              <div
                className={cn(
                  "p-3.5 rounded-2xl group-hover:scale-110 transition-transform",
                  stat.color === "blue" ? "bg-blue-50 text-blue-600" :
                    stat.color === "pink" ? "bg-pink-50 text-pink-600" : ""
                )}
                style={stat.color === "theme" ? {
                  backgroundColor: `${colors.primary}15`,
                  color: colors.primary
                } : {}}
              >
                <stat.icon className="w-6 h-6" />
              </div>
              <div>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">{stat.label}</p>
                <p className="text-2xl font-bold text-slate-900 leading-none">{stat.value}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Main Directory Table */}
      <Card className="border-0 shadow-2xl shadow-slate-200/40 bg-muted rounded-[2.5rem] overflow-hidden">
        <CardHeader className="border-b border-slate-50 p-8 pb-6 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
          <div className="flex items-center gap-5">
            <h2 className="text-xl font-bold text-slate-900 tracking-tight uppercase">Student Directory</h2>
            <div className="h-6 w-px bg-slate-100 hidden sm:block" />
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setSeparateByGender(!separateByGender)}
              className={cn(
                "h-9 px-4 rounded-xl text-[10px] font-bold uppercase tracking-[0.1em] transition-all border",
                separateByGender ? "bg-slate-900 text-white border-slate-900" : "text-slate-400 hover:text-slate-900 hover:bg-slate-50 border-slate-100"
              )}
            >
              <SplitSquareHorizontal className="w-4 h-4 mr-2" />
              {separateByGender ? "GENDER SEPARATED" : "BY GENDER"}
            </Button>
          </div>

          <div className="relative w-full sm:w-80 group">
            <div
              className="absolute left-4 top-1/2 -translate-y-1/2 p-1.5 rounded-lg bg-slate-100 text-slate-400 group-focus-within:text-white transition-all"
              style={{
                // We'll handle background color via style for focus-within if possible, or just use a custom class
              } as any}
            >
              <Search className="w-3.5 h-3.5" />
              <style dangerouslySetInnerHTML={{
                __html: `
                .group:focus-within .absolute.left-4 {
                  background-color: ${colors.primary} !important;
                }
              `}} />
            </div>
            <Input
              type="text"
              placeholder="SEARCH LRN, FIRST NAME, LAST NAME... or LRN..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-14 h-12 text-xs font-bold bg-slate-50 border-0 rounded-2xl transition-all placeholder:text-slate-400"
              style={{
                // focus ring color
                outlineColor: `${colors.primary}20`
              } as any}
            />
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow className="bg-slate-50/50 hover:bg-transparent border-0">
                  <TableHead className="w-16 text-center text-[10px] font-bold text-slate-400 uppercase tracking-widest px-8">#</TableHead>
                  <TableHead className="w-40 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Learner Reference (LRN)</TableHead>
                  <TableHead className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Full Legal Name</TableHead>
                  {!separateByGender && <TableHead className="text-center w-32 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Gender</TableHead>}
                  <TableHead className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Parent / Guardian</TableHead>
                  <TableHead className="w-32 text-right pr-8 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {(() => {
                  const renderRow = (student: any, idx: number) => (
                    <TableRow key={student.id} className="hover:bg-slate-50/50 transition-all border-slate-50 group">
                      <TableCell className="text-center text-slate-300 font-bold text-[10px] px-8">{idx + 1}</TableCell>
                      <TableCell className="font-mono text-xs text-slate-400 font-bold tracking-tighter group-hover:text-slate-900 transition-colors">{student.lrn}</TableCell>
                      <TableCell>
                        <div className="flex items-center gap-4">
                          <Avatar className="w-12 h-12 border-2 border-white shadow-sm ring-1 ring-slate-100">
                            <AvatarFallback className={cn(
                              "text-white font-bold text-xs",
                              student.gender?.toLowerCase() === "male" ? "bg-blue-500" : "bg-pink-500"
                            )}>
                              {student.lastName.charAt(0)}
                            </AvatarFallback>
                          </Avatar>
                          <div>
                            <p className="font-bold text-slate-900 text-sm tracking-tight">{student.lastName}, {student.firstName}</p>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{student.middleName || ""}</p>
                          </div>
                        </div>
                      </TableCell>
                      {!separateByGender && (
                        <TableCell className="text-center">
                          <Badge
                            variant="secondary"
                            className={cn(
                              "text-[9px] font-bold uppercase px-3 h-6 rounded-lg",
                              student.gender?.toLowerCase() === "male" ? "bg-blue-600/10 text-blue-600 border-blue-600 border-2" : "bg-pink-600/10 text-pink-600 border-pink-600 border-2"
                            )}
                          >
                            {student.gender || 'N/A'}
                          </Badge>
                        </TableCell>
                      )}
                      <TableCell className="text-xs text-slate-500 font-bold italic">
                        {student.guardianName || <span className="text-slate-200">UNSPECIFIED</span>}
                      </TableCell>
                      <TableCell className="text-right pr-8">
                        <Link to={`/teacher/advisory/student/${student.id}`}>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-10 px-4 rounded-xl text-slate-400 font-bold text-[10px] tracking-widest uppercase transition-all group/profile"
                          >
                            <span className="group-hover/profile:text-primary">PROFILE</span>
                            <ChevronRight className="w-4 h-4 ml-2 group-hover/profile:translate-x-1 transition-transform" />
                            <style dangerouslySetInnerHTML={{
                              __html: `
                              .group\\/profile:hover {
                                background-color: ${colors.primary}10 !important;
                                color: ${colors.primary} !important;
                              }
                            `}} />
                          </Button>
                        </Link>
                      </TableCell>
                    </TableRow>
                  );

                  if (separateByGender) {
                    return (
                      <>
                        {maleStudents.length > 0 && (
                          <>
                            <TableRow className="bg-blue-50/20 hover:bg-blue-50/20 border-y border-blue-100/30">
                              <TableCell colSpan={6} className="py-3 px-8">
                                <span className="text-[11px] font-bold text-blue-600 uppercase tracking-[0.2em] flex items-center gap-2">
                                  <div className="w-2 h-2 rounded-full bg-blue-500" />
                                  MALE STUDENTS ({maleStudents.length})
                                </span>
                              </TableCell>
                            </TableRow>
                            {maleStudents.map((s, i) => renderRow(s, i))}
                          </>
                        )}
                        {femaleStudents.length > 0 && (
                          <>
                            <TableRow className="bg-pink-50/20 hover:bg-pink-50/20 border-y border-pink-100/30">
                              <TableCell colSpan={6} className="py-3 px-8">
                                <span className="text-[11px] font-bold text-pink-600 uppercase tracking-[0.2em] flex items-center gap-2">
                                  <div className="w-2 h-2 rounded-full bg-pink-500" />
                                  FEMALE STUDENTS ({femaleStudents.length})
                                </span>
                              </TableCell>
                            </TableRow>
                            {femaleStudents.map((s, i) => renderRow(s, i))}
                          </>
                        )}
                      </>
                    );
                  }

                  if (sortedStudents.length === 0) {
                    return (
                      <TableRow>
                        <TableCell colSpan={6} className="py-24 text-center">
                          <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center mx-auto mb-4">
                            <Search className="w-8 h-8 text-slate-200" />
                          </div>
                          <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">
                            {searchQuery ? "No matching records found" : "No enrolled students yet"}
                          </p>
                          {!searchQuery && (
                            <p className="text-slate-300 text-xs mt-2">
                              Enrollment for this school year has not yet opened in EnrollPro.
                            </p>
                          )}
                        </TableCell>
                      </TableRow>
                    );
                  }

                  return sortedStudents.map((s, i) => renderRow(s, i));
                })()}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

// @ts-nocheck
import { useEffect, useState, useCallback } from "react";
import { Link, useParams, useLocation } from "react-router";
import {
  ArrowLeft,
  User,
  GraduationCap,
  Calendar,
  Award,
  BookOpen,
  CheckCircle2,
  XCircle,
  Clock,
  Phone,
  MapPin,
  Medal,
} from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/features/smart/components/ui/card";
import { Badge } from "@/features/smart/components/ui/badge";
import { Button } from "@/features/smart/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/features/smart/components/ui/table";
import { advisoryApi, type StudentGradeProfile } from "@/features/smart/lib/api";
import { useTheme } from "@/features/smart/contexts/ThemeContext";

const gradeLevelLabels: Record<string, string> = {
  GRADE_7: "Grade 7",
  GRADE_8: "Grade 8",
  GRADE_9: "Grade 9",
  GRADE_10: "Grade 10",
};

// DepEd mastery level helper
function getMasteryLevel(grade: number | null): { label: string; color: string; bgColor: string } {
  if (grade === null) return { label: "Not Graded", color: "text-gray-500", bgColor: "bg-gray-100" };
  if (grade >= 90) return { label: "Outstanding", color: "text-emerald-700", bgColor: "bg-emerald-100" };
  if (grade >= 85) return { label: "Very Satisfactory", color: "text-blue-700", bgColor: "bg-blue-100" };
  if (grade >= 80) return { label: "Satisfactory", color: "text-amber-700", bgColor: "bg-amber-100" };
  if (grade >= 75) return { label: "Fairly Satisfactory", color: "text-orange-700", bgColor: "bg-orange-100" };
  return { label: "Did Not Meet", color: "text-red-700", bgColor: "bg-red-100" };
}

// Format date helper
function formatDate(dateString?: string): string {
  if (!dateString) return "N/A";
  return new Date(dateString).toLocaleDateString("en-PH", {
    timeZone: 'Asia/Manila',
    year: "numeric",
    month: "long",
    day: "numeric",
  });
}

export default function StudentGradeProfilePage() {
  const { studentId } = useParams<{ studentId: string }>();
  const location = useLocation();
  const { colors } = useTheme();
  const [data, setData] = useState<StudentGradeProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchStudentGrades = useCallback(async () => {
    if (!studentId) return;
    setLoading(true);
    setError(null);
    try {
      const res = await advisoryApi.getStudentGrades(studentId);
      setData(res.data);
    } catch (err) {
      setError("Failed to load student grades");
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [studentId]);

  // Re-fetch when studentId changes OR when navigating to the page (location.key changes)
  useEffect(() => {
    fetchStudentGrades();
  }, [fetchStudentGrades, location.key]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="text-center">
          <div
            className="w-20 h-20 mx-auto mb-6 rounded-2xl flex items-center justify-center shadow-lg animate-pulse"
            style={{ backgroundColor: `${colors.primary}15` }}
          >
            <div
              className="w-10 h-10 border-[3px] border-t-transparent rounded-full animate-spin"
              style={{ borderColor: colors.primary, borderTopColor: 'transparent' }}
            />
          </div>
          <p className="text-gray-500 ">Loading student profile...</p>
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="text-center max-w-sm">
          <div className="w-20 h-20 mx-auto mb-6 rounded-2xl bg-gradient-to-br from-red-100 to-rose-100 flex items-center justify-center shadow-lg">
            <span className="text-4xl">≡ƒÿò</span>
          </div>
          <h3 className=" text-gray-900 text-lg mb-2">Something went wrong</h3>
          <p className="text-gray-500 mb-6">{error || "Failed to load student data"}</p>
          <Link to="/teacher/advisory">
            <Button variant="outline" className="rounded-xl">
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Advisory
            </Button>
          </Link>
        </div>
      </div>
    );
  }

  const { student, enrollment, subjectGrades, summary } = data;
  const fullName = `${student.lastName}, ${student.firstName} ${student.middleName ? `${student.middleName.charAt(0)}.` : ""} ${student.suffix || ""}`.trim();

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header with Back Button */}
      <div className="flex items-center gap-4">
        <Link to="/teacher/advisory">
          <Button variant="outline" size="icon" className="rounded-xl border-gray-300 hover:bg-gray-100">
            <ArrowLeft className="w-5 h-5 text-gray-900" />
          </Button>
        </Link>
        <div>
          <h1 className="text-2xl font-bold" style={{ color: '#111827' }}>Student Grade Profile</h1>
          <p style={{ color: '#4b5563' }}>Complete academic record</p>
        </div>
      </div>

      {/* Student Info Card */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Info */}
        <Card className="lg:col-span-2 border-0 shadow-xl shadow-gray-200/50 bg-muted overflow-hidden rounded-2xl p-0">
          <CardHeader className="border-b border-gray-100 px-6 py-5" style={{ backgroundColor: `${colors.primary}08` }}>
            <div className="flex items-center gap-4">
              <div
                className="w-16 h-16 rounded-2xl flex items-center justify-center text-white text-2xl font-bold shadow-lg"
                style={{ backgroundColor: colors.primary }}
              >
                {student.lastName.charAt(0)}
              </div>
              <div>
                <CardTitle className="text-xl font-bold text-gray-900">{fullName}</CardTitle>
                <div className="flex items-center gap-2 mt-1">
                  <Badge style={{ backgroundColor: `${colors.primary}15`, color: colors.primary }}>
                    LRN: {student.lrn}
                  </Badge>
                  <Badge className={`${student.gender?.toLowerCase() === "male"
                    ? "bg-blue-100 text-blue-700"
                    : "bg-pink-100 text-pink-700"
                    }`}>
                    {student.gender || "N/A"}
                  </Badge>
                </div>
              </div>
            </div>
          </CardHeader>
          <CardContent className="p-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div className="space-y-4">
                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-gray-100">
                    <GraduationCap className="w-5 h-5 text-gray-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">Grade & Section</p>
                    <p className=" text-gray-900">
                      {gradeLevelLabels[enrollment.gradeLevel] || enrollment.gradeLevel} - {enrollment.sectionName}
                    </p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-gray-100">
                    <Calendar className="w-5 h-5 text-gray-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">School Year</p>
                    <p className=" text-gray-900">{enrollment.schoolYear}</p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-gray-100">
                    <Calendar className="w-5 h-5 text-gray-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">Birth Date</p>
                    <p className=" text-gray-900">{formatDate(student.birthDate)}</p>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-gray-100">
                    <MapPin className="w-5 h-5 text-gray-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">Address</p>
                    <p className=" text-gray-900">{student.address || "N/A"}</p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-gray-100">
                    <User className="w-5 h-5 text-gray-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">Guardian</p>
                    <p className=" text-gray-900">{student.guardianName || "N/A"}</p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-gray-100">
                    <Phone className="w-5 h-5 text-gray-600" />
                  </div>
                  <div>
                    <p className="text-sm text-gray-500">Contact Number</p>
                    <p className=" text-gray-900">{student.guardianContact || "N/A"}</p>
                  </div>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Summary Card */}
        <Card className="border-0 shadow-xl shadow-gray-200/50 overflow-hidden rounded-2xl text-white p-0" style={{ backgroundColor: colors.primary }}>
          <CardContent className="p-6 h-full flex flex-col">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2.5 rounded-xl bg-muted/20 backdrop-blur-sm">
                <Award className="w-5 h-5" />
              </div>
              <h3 className="font-bold text-lg">Academic Summary</h3>
            </div>

            <div className="space-y-4 flex-1">
              <div className="p-4 rounded-xl bg-muted/10 backdrop-blur-sm">
                <p className="text-white/70 text-sm mb-1">General Average</p>
                <p className="text-4xl font-bold">
                  {summary.generalAverage !== null ? summary.generalAverage.toFixed(2) : "N/A"}
                </p>
                {summary.generalAverage !== null && (
                  <Badge className={`mt-2 ${getMasteryLevel(summary.generalAverage).bgColor} ${getMasteryLevel(summary.generalAverage).color}`}>
                    {getMasteryLevel(summary.generalAverage).label}
                  </Badge>
                )}
              </div>

              {summary.honors && (
                <div className="p-4 rounded-xl backdrop-blur-sm border" style={{ backgroundColor: `${colors.accent}30`, borderColor: `${colors.accent}40` }}>
                  <div className="flex items-center gap-2">
                    <Medal className="w-5 h-5" style={{ color: colors.accent }} />
                    <p className="font-bold text-white">{summary.honors}</p>
                  </div>
                </div>
              )}

              <div className="p-4 rounded-xl bg-muted/10 backdrop-blur-sm">
                <p className="text-white/70 text-sm mb-1">Status</p>
                <Badge className={`${summary.promotionStatus === "PROMOTED" ? "text-white" :
                  summary.promotionStatus === "CONDITIONALLY PROMOTED" ? "bg-amber-400/30 text-amber-100" :
                    summary.promotionStatus === "RETAINED" ? "bg-red-400/30 text-red-100" :
                      "bg-gray-400/30 text-gray-100"
                  }`}
                  style={summary.promotionStatus === "PROMOTED" ? { backgroundColor: `${colors.primary}50`, color: 'white' } : undefined}
                >
                  {summary.promotionStatus || "Pending"}
                </Badge>
              </div>

              <div className="p-4 rounded-xl bg-muted/10 backdrop-blur-sm">
                <p className="text-white/70 text-sm mb-1">Progress</p>
                <p className="text-lg ">
                  {summary.completedSubjects} / {summary.totalSubjects} Subjects Graded
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Grades Table */}
      <Card className="border-0 shadow-xl shadow-gray-200/50 bg-muted overflow-hidden rounded-2xl p-0">
        <CardHeader className="border-b border-gray-100 bg-gradient-to-r from-gray-50 to-slate-50 px-6 py-5">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div
                className="p-2.5 rounded-xl text-white shadow-lg"
                style={{ backgroundColor: colors.primary }}
              >
                <BookOpen className="w-5 h-5" />
              </div>
              <div>
                <CardTitle className="text-lg font-bold text-gray-900">Subject Grades</CardTitle>
                <CardDescription className="text-gray-500 text-sm">
                  Term grades and final rating per subject
                </CardDescription>
              </div>
            </div>
            <Badge style={{ backgroundColor: `${colors.primary}15`, color: colors.primary }}>
              S.Y. {enrollment.schoolYear}
            </Badge>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow className="bg-gray-50/80">
                  <TableHead className="font-bold text-gray-700 min-w-[200px]">Subject</TableHead>
                  <TableHead className="font-bold text-gray-700 text-center">T1</TableHead>
                  <TableHead className="font-bold text-gray-700 text-center">T2</TableHead>
                  <TableHead className="font-bold text-gray-700 text-center">T3</TableHead>
                  <TableHead className="font-bold text-gray-700 text-center" style={{ backgroundColor: `${colors.primary}08` }}>Final Grade</TableHead>
                  <TableHead className="font-bold text-gray-700 text-center">Remarks</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {subjectGrades.map((subject) => (
                  <TableRow key={subject.subjectId} className="hover:bg-gray-50/50">
                    <TableCell>
                      <div>
                        <p className=" text-gray-900">{subject.subjectName}</p>
                        <p className="text-xs text-gray-500">{subject.teacher}</p>
                      </div>
                    </TableCell>
                    {(["T1", "T2", "T3"] as const).map((term) => {
                      const grade = subject.grades[term]?.quarterlyGrade;
                      const descriptor = subject.grades[term]?.qualitativeDescriptor;
                      const isHG = subject.subjectCode.startsWith("HG");
                      return (
                        <TableCell key={term} className="text-center">
                          {grade !== null && grade !== undefined ? (
                            <span className={` ${grade >= 75 ? "text-gray-900" : "text-red-600"}`}>
                              {grade}
                            </span>
                          ) : isHG && descriptor ? (
                            <Badge className="bg-emerald-50 text-emerald-700 border border-emerald-100 text-[10px]">
                              {descriptor}
                            </Badge>
                          ) : (
                            <span className="text-gray-400">-</span>
                          )}
                        </TableCell>
                      );
                    })}
                    <TableCell className="text-center" style={{ backgroundColor: `${colors.primary}06` }}>
                      {subject.finalGrade !== null ? (
                        <span className={`text-lg font-bold ${subject.finalGrade >= 75 ? "" : "text-red-600"}`} style={subject.finalGrade >= 75 ? { color: colors.primary } : undefined}>
                          {subject.finalGrade}
                        </span>
                      ) : (
                        <span className="text-gray-400">-</span>
                      )}
                    </TableCell>
                    <TableCell className="text-center">
                      {subject.remarks ? (
                        <Badge className={`${subject.remarks === "PASSED"
                          ? "bg-emerald-100 text-emerald-700"
                          : subject.remarks === "QUALITATIVE"
                            ? "bg-sky-100 text-sky-700"
                            : "bg-red-100 text-red-700"
                          }`}>
                          {subject.remarks === "PASSED" ? (
                            <CheckCircle2 className="w-3 h-3 mr-1" />
                          ) : subject.remarks === "QUALITATIVE" ? (
                            <BookOpen className="w-3 h-3 mr-1" />
                          ) : (
                            <XCircle className="w-3 h-3 mr-1" />
                          )}
                          {subject.remarks === "QUALITATIVE" ? "Descriptor-Based" : subject.remarks}
                        </Badge>
                      ) : (
                        <Badge className="bg-gray-100 text-gray-500">
                          <Clock className="w-3 h-3 mr-1" />
                          Pending
                        </Badge>
                      )}
                    </TableCell>
                  </TableRow>
                ))}

                {/* General Average Row */}
                <TableRow className="border-t-2" style={{ backgroundColor: `${colors.primary}10`, borderColor: `${colors.primary}30` }}>
                  <TableCell colSpan={5} className="font-bold text-right pr-8" style={{ color: colors.primary }}>
                    General Average:
                  </TableCell>
                  <TableCell className="text-center">
                    <span className="text-2xl font-bold" style={{ color: colors.primary }}>
                      {summary.generalAverage !== null ? summary.generalAverage.toFixed(2) : "N/A"}
                    </span>
                  </TableCell>
                  <TableCell className="text-center">
                    {summary.promotionStatus && (
                      <Badge className={`${summary.promotionStatus === "PROMOTED" ? "text-white" :
                        summary.promotionStatus === "CONDITIONALLY PROMOTED" ? "bg-amber-500 text-white" :
                          "bg-red-500 text-white"
                        }`}
                        style={summary.promotionStatus === "PROMOTED" ? { backgroundColor: colors.primary } : undefined}
                      >
                        {summary.promotionStatus}
                      </Badge>
                    )}
                  </TableCell>
                </TableRow>
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* DepEd Grading Legend */}
      <Card className="border-0 shadow-lg shadow-gray-200/50 bg-muted overflow-hidden rounded-2xl p-0">
        <CardHeader className="border-b border-gray-100 px-6 py-4">
          <CardTitle className="text-sm font-bold text-gray-700">DepEd Grading Scale</CardTitle>
        </CardHeader>
        <CardContent className="p-6">
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
            {[
              { label: "Outstanding", range: "90-100", opacity: "18" },
              { label: "Very Satisfactory", range: "85-89", opacity: "28" },
              { label: "Satisfactory", range: "80-84", opacity: "38" },
              { label: "Fairly Satisfactory", range: "75-79", opacity: "48" },
              { label: "Did Not Meet Expectations", range: "Below 75", color: "bg-red-100 text-red-700 border-red-200" },
            ].map((level) => (
              <div key={level.label} className={`p-3 rounded-xl border ${level.color || ''}`}
                style={!level.color ? { backgroundColor: `${colors.primary}${level.opacity}`, color: colors.primary, borderColor: `${colors.primary}30` } : undefined}
              >
                <p className=" text-sm">{level.label}</p>
                <p className="text-xs opacity-80">{level.range}</p>
              </div>
            ))}
          </div>

          <div className="mt-6 pt-6 border-t border-gray-100">
            <h4 className="font-bold text-gray-700 text-sm mb-3">Academic Honors (Based on General Average):</h4>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              {[
                { label: "With Highest Honors", range: "98-100", icon: "≡ƒÅå" },
                { label: "With High Honors", range: "95-97", icon: "≡ƒÑç" },
                { label: "With Honors", range: "90-94", icon: "≡ƒÑê" },
              ].map((honor) => (
                <div key={honor.label} className="flex items-center gap-3 p-3 rounded-xl border" style={{ backgroundColor: `${colors.primary}08`, borderColor: `${colors.primary}25` }}>
                  <span className="text-2xl">{honor.icon}</span>
                  <div>
                    <p className=" text-sm" style={{ color: colors.primary }}>{honor.label}</p>
                    <p className="text-xs" style={{ color: `${colors.primary}aa` }}>{honor.range}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

// @ts-nocheck
import React from "react";
import { Button } from "@/features/smart/components/ui/button";

interface AssessmentTaskMeta {
  description: string;
  date: string;
}

interface AssessmentHeaderProps {
  showAssessmentDetails: boolean;
  wwCount: number;
  ptCount: number;
  wwMeta: AssessmentTaskMeta[];
  ptMeta: AssessmentTaskMeta[];
  qaMeta: { description: string; date: string };
  setWwMeta: React.Dispatch<React.SetStateAction<AssessmentTaskMeta[]>>;
  setPtMeta: React.Dispatch<React.SetStateAction<AssessmentTaskMeta[]>>;
  setQaMeta: React.Dispatch<React.SetStateAction<{ description: string; date: string }>>;
  saveAssessmentDetails: () => void;
  savingMeta: boolean;
  selectedColumn: { type: "WW" | "PT" | "QA"; number: number } | null;
  setSelectedColumn: React.Dispatch<React.SetStateAction<{ type: "WW" | "PT" | "QA"; number: number } | null>>;
  metaEditorDraft: { description: string; date: string };
  setMetaEditorDraft: React.Dispatch<React.SetStateAction<{ description: string; date: string }>>;
  saveColumnMeta: () => void;
  metaEditorRef?: React.RefObject<HTMLDivElement | null>;
  assessmentDetailsRef?: React.RefObject<HTMLDivElement | null>;
}

export function AssessmentHeader({
  showAssessmentDetails,
  wwCount,
  ptCount,
  wwMeta,
  ptMeta,
  qaMeta,
  setWwMeta,
  setPtMeta,
  setQaMeta,
  saveAssessmentDetails,
  savingMeta,
  selectedColumn,
  setSelectedColumn,
  metaEditorDraft,
  setMetaEditorDraft,
  saveColumnMeta,
  metaEditorRef,
  assessmentDetailsRef,
}: AssessmentHeaderProps) {
  const categoryLabel = selectedColumn
    ? `${selectedColumn.type === "QA" ? "TA" : selectedColumn.type}${selectedColumn.type === "QA" ? "" : ` ${selectedColumn.number}`}`
    : "";

  return (
    <>
      {/* ΓöÇΓöÇ Per-column Quick Meta Editor ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {selectedColumn && (
        <div ref={metaEditorRef} className="bg-muted w-full border-b border-slate-100">
          <div className="px-5 py-2">
            <div className="bg-muted border border-slate-100 rounded-2xl shadow-sm animate-fade-in">
              <div className="flex items-end gap-4 px-5 py-3">
                {/* Inputs */}
                <div className="flex-1 grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5">
                      {categoryLabel} Description (optional)
                    </label>
                    <input
                      type="text"
                      value={metaEditorDraft.description}
                      onChange={(e) =>
                        setMetaEditorDraft((prev) => ({ ...prev, description: e.target.value }))
                      }
                      placeholder={`e.g., Quiz ${selectedColumn.number}`}
                      className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm  text-slate-800 placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-indigo-400/40 focus:border-indigo-300 transition-all"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5">
                      Column Date (applies to all students)
                    </label>
                    <input
                      type="date"
                      value={metaEditorDraft.date}
                      onChange={(e) =>
                        setMetaEditorDraft((prev) => ({ ...prev, date: e.target.value }))
                      }
                      className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm  text-slate-800 focus:outline-none focus:ring-2 focus:ring-indigo-400/40 focus:border-indigo-300 transition-all"
                    />
                  </div>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-2 shrink-0">
                  <button
                    onClick={() => setSelectedColumn(null)}
                    className="px-5 py-2.5 border border-slate-200 text-slate-600 text-sm  rounded-xl hover:bg-slate-50 hover:border-slate-300 transition-all"
                  >
                    Close
                  </button>
                  <button
                    onClick={saveColumnMeta}
                    disabled={savingMeta}
                    className="px-6 py-2.5 bg-slate-900 text-white text-sm font-bold rounded-xl hover:bg-slate-700 transition-all disabled:opacity-50 shadow-sm"
                  >
                    {savingMeta ? "Applying\u2026" : "Apply"}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ΓöÇΓöÇ Optional Assessment Details (bulk editor) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {showAssessmentDetails && (
        <div ref={assessmentDetailsRef} className="bg-muted w-full border-b border-slate-100">
          <div className="px-4 py-1.5">
            <div className="rounded-2xl border border-slate-100 bg-muted shadow-sm overflow-hidden">
