                  <p className="text-sm font-bold text-slate-900 uppercase tracking-tight truncate">
                    {record.student.lastName}, {record.student.firstName}
                  </p>
                  <p className="text-[10px] text-slate-500  mt-0.5 font-mono">{record.student.lrn}</p>

                  {!isHGClass && hasScores && (
                    <div className="flex items-center gap-3 mt-2">
                      <div className="flex items-center gap-1">
                        <span className="text-[9px] font-bold text-indigo-400 uppercase tracking-widest">WW</span>
                        <span className="text-[10px] font-bold text-indigo-600">
                          {wwMax > 0 ? `${wwTotal}/${wwMax}` : "ΓÇö"}
                        </span>
                      </div>
                      <div className="w-px h-3 bg-slate-200" />
                      <div className="flex items-center gap-1">
                        <span className="text-[9px] font-bold text-purple-400 uppercase tracking-widest">PT</span>
                        <span className="text-[10px] font-bold text-purple-600">
                          {ptMax > 0 ? `${ptTotal}/${ptMax}` : "ΓÇö"}
                        </span>
                      </div>
                      <div className="w-px h-3 bg-slate-200" />
                      <div className="flex items-center gap-1">
                        <span className="text-[9px] font-bold text-amber-400 uppercase tracking-widest">TA</span>
                        <span className="text-[10px] font-bold text-amber-600">
                          {qaScore !== null ? (qaMax ? `${qaScore}/${qaMax}` : String(qaScore)) : "ΓÇö"}
                        </span>
                      </div>
                    </div>
                  )}
                </div>

                <div className="text-right flex-shrink-0">
                  {isHGClass ? (
                    <>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Descriptor</p>
                      <p className="text-xs font-bold text-slate-700 mt-1">{descriptor}</p>
                    </>
                  ) : (
                    <>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Grade</p>
                      <p className={`text-xl font-bold ${getGradeColor(finalGrade)}`}>{finalGrade ?? "ΓÇö"}</p>
                    </>
                  )}
                  <ChevronRight className="w-4 h-4 text-slate-300 ml-auto mt-1" />
                </div>
              </div>
            </button>
          );
        })}
      </CardContent>
    </Card>
  );
}

