} from "@/features/smart/components/ui/table";
import type { ClassAssignment, ClassRecord, ScoreItem } from "@/features/smart/lib/api";

const terms = ["T1", "T2", "T3"] as const;

function getGradeColor(grade: number | null): string {
  if (grade === null) return "text-slate-300";
  if (grade >= 90) return "text-emerald-600";
  if (grade >= 85) return "text-blue-600";
  if (grade >= 80) return "text-amber-600";
  if (grade >= 75) return "text-orange-600";
  return "text-rose-600";
}

function transmuteGrade(initialGrade: number): number {
  const roundedGrade = Math.round(initialGrade * 100) / 100;
  if (roundedGrade >= 99.5) return 100;

  const transmutationTable: [number, number, number][] = [
    [97.5, 99.49, 99],
    [96.0, 97.49, 98],
    [95.0, 95.99, 97],
    [94.0, 94.99, 96],
    [93.0, 93.99, 95],
    [92.0, 92.99, 94],
    [91.0, 91.99, 93],
    [90.0, 90.99, 92],
    [89.0, 89.99, 91],
    [88.0, 88.99, 90],
    [87.0, 87.99, 89],
    [86.0, 86.99, 88],
    [85.0, 85.99, 87],
    [84.0, 84.99, 86],
    [83.0, 83.99, 85],
    [82.0, 82.99, 84],
    [81.0, 81.99, 83],
    [80.0, 80.99, 82],
    [79.0, 79.99, 81],
    [78.0, 78.99, 80],
    [77.0, 77.99, 79],
    [76.0, 76.99, 78],
    [75.0, 75.99, 77],
    [73.0, 74.99, 76],
    [70.0, 72.99, 75],
    [68.0, 69.99, 74],
    [66.0, 67.99, 73],
    [64.0, 65.99, 72],
    [62.0, 63.99, 71],
    [60.0, 61.99, 70],
    [58.0, 59.99, 69],
    [56.0, 57.99, 68],
    [54.0, 55.99, 67],
    [52.0, 53.99, 66],
    [50.0, 51.99, 65],
    [48.0, 49.99, 64],
    [46.0, 47.99, 63],
    [43.0, 45.99, 62],
    [40.0, 42.99, 61],
    [25.0, 39.99, 60],
    [0.0, 24.99, 60],
  ];

  for (const [min, max, grade] of transmutationTable) {
    if (roundedGrade >= min && roundedGrade <= max) {
      return grade;
    }
  }

  return 60; // Minimum grade
}

// ΓöÇΓöÇΓöÇ LedgerRow ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface LedgerRowProps {
