      sortBy,
      sortOrder,
    };

    if (ayId && activeTab !== "completers") {
      params.schoolYearId = ayId;
    }

    if (activeTab === "completers") {
      params.learnerStatus = "JHS_COMPLETER";
    } else if (activeTab === "inactive") {
      params.learnerStatus = statusFilter !== "all" ? statusFilter : "DROPPED,TRANSFERRED_OUT";
    }

    if (debouncedSearch) params.search = debouncedSearch;
    if (gradeLevelFilter !== "all") params.gradeLevelId = gradeLevelFilter;
    if (sectionFilter !== "all") params.sectionId = sectionFilter;

    if (programFilter !== "all") {
      if (programFilter === "REGULAR_TOP") {
        params.programType = "REGULAR";
        params.isHomogeneous = "true";
      } else if (programFilter === "REGULAR") {
        params.programType = "REGULAR";
      } else {
        params.programType = programFilter;
      }
    }

    return params;
  }, [
    page,
    limit,
    sortBy,
    sortOrder,
    activeTab,
    ayId,
    debouncedSearch,
    gradeLevelFilter,
    programFilter,
    sectionFilter,
    statusFilter,
  ]);

  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const studentsQuery = useQuery({
    queryKey: queryKeys.studentsList(studentsQueryParams),
    queryFn: async () => {
      if (!ayId && activeTab !== "completers") {
        return { students: [] as Student[], pagination: { total: 0 } };
      }

      const res = await api.get("/students", { params: studentsQueryParams });
      return {
        students: (res.data.students || []) as Student[],
        pagination: res.data.pagination as { total: number },
      };
    },
    enabled: Boolean(ayId || activeTab === "completers"),
    placeholderData: keepPreviousData,
  });

  const students = studentsQuery.data?.students ?? [];
  const total = studentsQuery.data?.pagination.total ?? 0;
  const loading = studentsQuery.isPending || studentsQuery.isFetching;

  useEffect(() => {
    if (studentsQuery.data) {
      setIsInitialLoad(false);
    }
  }, [studentsQuery.data]);

  const programOptionsQuery = useQuery({
    queryKey: queryKeys.activeAcademicPrograms,
    queryFn: async (): Promise<ProgramOptionsResponse> => {
      const response = await api.get<ProgramOptionsResponse>(
        "/settings/programs",
      );
      return response.data;
    },
    enabled: Boolean(ayId),
  });

  // Fetch grade levels and sections
  useEffect(() => {
    const fetchFilters = async () => {
      if (!ayId) return;
      try {
        const [glRes, secRes] = await Promise.all([
          api.get(`/school-years/grade-levels`),
          api.get(`/sections/${ayId}`),
        ]);
        setGradeLevels(glRes.data.gradeLevels || []);

        // Flatten sections from grade levels in the response
        const allSections = (secRes.data.gradeLevels || []).flatMap(
          (gl: ApiGradeLevelGroup) =>
            (gl.sections || []).map((s: ApiSection) => ({
              ...s,
              gradeLevelId: gl.gradeLevelId,
            })),
        );
        setSections(allSections);
      } catch (err) {
        console.error("Failed to fetch filters:", err);
      }
    };
    fetchFilters();
  }, [ayId]);

  // Filter sections by grade level
  useEffect(() => {
    if (gradeLevelFilter === "all") {
      setFilteredSections(
        programFilter === "all"
          ? sections
          : sections.filter((section) =>
            matchesProgramFilter(section, programFilter),
          ),
      );
    } else {
      setFilteredSections(
        sections.filter((s) => {
          const isGradeMatch =
            s.gradeLevelId === parseInt(gradeLevelFilter, 10);
          const isProgramMatch = matchesProgramFilter(s, programFilter);
          return isGradeMatch && isProgramMatch;
        }),
      );
    }
    setSectionFilter("all");
  }, [gradeLevelFilter, programFilter, sections]);

  const availablePrograms = useMemo<ProgramFilterOption[]>(
    () => {
      const programs = programOptionsQuery.data?.programs ?? [];
      const opts: ProgramFilterOption[] = [];
      const hasTopBecSection = sections.some(
        (section) =>
          section.programType === "REGULAR" &&
          section.isHomogeneous === true,
      );
      programs.forEach((programType) => {
        if (programType === "REGULAR") {
          if (
            hasTopBecSection ||
            (enableHomogeneousSections && homogeneousSectionCount > 0)
          ) {
            opts.push({
              value: "REGULAR_TOP",
              label: `BEC (Top ${homogeneousSectionCount || 5})`,
            });
          }
          opts.push({
            value: "REGULAR",
            label: "BEC",
          });
        } else {
          opts.push({
            value: programType,
            label: SCP_ACRONYMS[programType] ?? formatScpType(programType),
          });
        }
      });
      return opts;
    },
    [
      programOptionsQuery.data?.programs,
      enableHomogeneousSections,
      homogeneousSectionCount,
      sections,
    ],
  );

  useEffect(() => {
    if (
      programFilter !== "all" &&
      programOptionsQuery.data &&
      !programOptionsQuery.data.programs.includes(
        programFilter === "REGULAR_TOP" ? "REGULAR" : programFilter,
      )
    ) {
      setProgramFilter("all");
    }
  }, [programFilter, programOptionsQuery.data]);

  useEffect(() => {
    void queryClient.invalidateQueries({
      queryKey: queryKeys.studentsList(studentsQueryParams),
    });
  }, [queryClient, studentsQueryParams]);

  useEffect(() => {
    if (ayId) {
      void queryClient.invalidateQueries({ queryKey: queryKeys.studentsSummary(ayId) });
    }
  }, [queryClient, ayId]);

  const handleViewDetails = useCallback(
    (identifier: string | number) => {
      // If we use string for LRN, we might need to change selectedStudentId type 
      // or resolve it. But typically selectedStudentId is number. 
      // If selectedStudentId is number, we should pass student.id here instead of LRN.
      // Wait, handleViewDetails is used to open the Quick View Modal which uses StudentDetailPanel!
      // StudentDetailPanel accepts id as a number. So let's keep handleViewDetails receiving id.
      setSelectedStudentId(Number(identifier));
    },
    [],
  );

  const renderLearnerStatus = (student: Student) => {
    let status = student.learnerStatus || "ACTIVE";

    // Override with lifecycle outcome if present and tab is active/inactive
    if (activeTab !== "completers") {
      if (student.lifecycleOutcome === "DROPPED_OUT") status = "DROPPED";
      else if (student.lifecycleOutcome === "TRANSFERRED_OUT") status = "TRANSFERRED_OUT";
    }

    const label = status
      .replaceAll("_", " ")
      .toLowerCase()
      .replace(/^\w/, (c) => c.toUpperCase());

    const isEnrolled = status === "ENROLLED" || status === "ACTIVE";
    const isDropped = status === "DROPPED" || status === "DROPPED_OUT";

    return (
      <Badge
        variant="outline"
        className={cn(
          "font-bold text-sm px-2.5 py-0.5 rounded-md uppercase tracking-wider",
          isEnrolled
            ? "bg-emerald-50 text-emerald-700 border-emerald-100"
            : isDropped
              ? "bg-red-50 text-red-700 border-red-100"
              : "bg-primary text-primary-foreground"
        )}>
        {label}
      </Badge>
    );
  };

  const formatDate = (dateString: string) => {
    return formatManilaDate(dateString, {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
  };

  const handleOpenProfilePage = useCallback(
    (identifier: string | number) => {
      navigate(`/learner/${identifier}`);
    },
    [navigate],
  );

  const toDateInputValue = useCallback((value?: string | null): string => {
    const sourceDate = value ? new Date(value) : new Date();
    if (Number.isNaN(sourceDate.getTime())) {
      return "";
    }

    const tzAdjusted = new Date(
      sourceDate.getTime() - sourceDate.getTimezoneOffset() * 60_000,
    );
    return tzAdjusted.toISOString().slice(0, 10);
  }, []);

  const refreshTables = useCallback(async () => {
    await Promise.all([
      queryClient.invalidateQueries({ queryKey: queryKeys.studentsList(studentsQueryParams) }),
      ayId
        ? queryClient.invalidateQueries({ queryKey: queryKeys.studentsSummary(ayId) })
        : Promise.resolve(),
    ]);
  }, [queryClient, studentsQueryParams, ayId]);

  const refreshDetailIfOpen = useCallback(
    async (studentId: number) => {
      if (selectedStudentId !== studentId) {
        return;
      }
    },
    [selectedStudentId],
  );

  /** Helper to map detail from panel to local Student interface */
  const mapPanelDetailToStudent = (detail: PanelStudentDetail): Student => {
    return {
      ...detail,
      learnerStatus: detail.learnerStatus,
      learningProgram: "REGULAR", // Default fallback, though ideally fetched
      dateEnrolled: detail.enrollment?.enrolledAt || detail.createdAt,
      lifecycleOutcome: detail.enrollment?.eosyStatus || null,
      dropOutReason: detail.enrollment?.dropOutReason || null,
      dropOutDate: detail.enrollment?.dropOutDate || null,
      transferOutDate: detail.enrollment?.transferOutDate || null,
      transferOutSchoolName: detail.enrollment?.transferOutSchoolName || null,
      transferOutReason: detail.enrollment?.transferOutReason || null,
      section: detail.enrollment?.section || null,
      sectionId: detail.enrollment?.sectionId || null,
    };
  };

  const openTransferOutDialog = useCallback(
    (student: Student | PanelStudentDetail) => {
      const s =
        "learningProgram" in student
          ? student
          : mapPanelDetailToStudent(student);
      setActionStudent(s);
      setTransferOutDate(toDateInputValue());
      setTransferOutSchoolName("");
      setTransferOutReason("");
      setShowTransferOutDialog(true);
    },
    [toDateInputValue],
  );

  const openDropoutDialog = useCallback(
    (student: Student | PanelStudentDetail) => {
      const s =
        "learningProgram" in student
          ? student
          : mapPanelDetailToStudent(student);
      setActionStudent(s);
      setDropoutDate(toDateInputValue());
      setDropoutReasonCode("LACK_OF_INTEREST");
      setDropoutReasonDetails("");
      setShowDropoutDialog(true);
    },
    [toDateInputValue],
  );


  const handlePanelTransferOut = async (payload: StudentTransferOutPayload) => {
    setActionSubmitting(true);
    try {
      await api.post(`/students/${payload.student.id}/lifecycle/transfer-out`, {
        transferDate: payload.transferDate,
        destinationSchool: payload.destinationSchool,
        reasonNote: payload.reasonNote || undefined,
      });

      sileo.success({
        title: "Transferred out",
        description: "Learner lifecycle was updated successfully.",
      });
      await refreshTables();
      await refreshDetailIfOpen(payload.student.id);
    } catch (err: unknown) {
      toastApiError(err as never);
    } finally {
      setActionSubmitting(false);
    }
  };

  const handlePanelDropout = async (payload: StudentDropoutPayload) => {
    setActionSubmitting(true);
    try {
      await api.post(`/students/${payload.student.id}/lifecycle/dropout`, {
        dropOutDate: payload.dropOutDate,
        reasonCode: payload.reasonCode,
        reasonNote: payload.interventionNotes || undefined,
      });

      sileo.success({
        title: "Dropped out",
        description: "Learner lifecycle was updated successfully.",
      });
      await refreshTables();
      await refreshDetailIfOpen(payload.student.id);
    } catch (err: unknown) {
      toastApiError(err as never);
    } finally {
      setActionSubmitting(false);
    }
  };

  const openAssignLrnDialog = useCallback(
    (student: Student | PanelStudentDetail) => {
      const s =
        "learningProgram" in student
          ? student
          : mapPanelDetailToStudent(student);
      setActionStudent(s);
      setLrnForm({
        lrn: /^\d{12}$/.test(s.lrn || "") ? s.lrn : "",
      });
      setShowLrnDialog(true);
    },
    [],
  );

  const handleTabChange = (val: string) => {
    useSettingsStore.getState().updateUiPreference("studentsTab", val);
    setPage(1);
  };

  const submitTransferOut = useCallback(async () => {
    if (!actionStudent) return;
    if (!transferOutDate || !transferOutSchoolName.trim()) {
      sileo.warning({
        title: "Missing transfer details",
        description: "Transfer date and destination school are required.",
      });
      return;
    }

    setActionSubmitting(true);
    try {
      await api.post(`/students/${actionStudent.id}/lifecycle/transfer-out`, {
        transferDate: transferOutDate,
        destinationSchool: transferOutSchoolName.trim(),
        reasonNote: transferOutReason.trim() || undefined,
      });

      sileo.success({
        title: "Transferred out",
        description: "Learner lifecycle was updated successfully.",
      });
      setShowTransferOutDialog(false);
      await refreshTables();
      await refreshDetailIfOpen(actionStudent.id);
    } catch (err) {
      toastApiError(err as never);
    } finally {
      setActionSubmitting(false);
    }
  }, [
    actionStudent,
    transferOutDate,
    transferOutSchoolName,
    transferOutReason,
    refreshTables,
    refreshDetailIfOpen,
  ]);

  const submitDropout = useCallback(async () => {
    if (!actionStudent) return;
    if (!dropoutDate) {
      sileo.warning({
        title: "Missing dropout date",
        description: "Dropout date is required.",
      });
      return;
    }
    if (dropoutReasonCode === "OTHER" && !dropoutReasonDetails.trim()) {
      sileo.warning({
        title: "Missing reason details",
        description: "Provide details when reason code is OTHER.",
      });
      return;
    }

    setActionSubmitting(true);
    try {
      await api.post(`/students/${actionStudent.id}/lifecycle/dropout`, {
        dropOutDate: dropoutDate,
        reasonCode: dropoutReasonCode,
        reasonNote: dropoutReasonDetails.trim() || undefined,
      });

      sileo.success({
        title: "Dropped out",
        description: "Learner lifecycle was updated successfully.",
      });
      setShowDropoutDialog(false);
      await refreshTables();
      await refreshDetailIfOpen(actionStudent.id);
    } catch (err) {
      toastApiError(err as never);
    } finally {
      setActionSubmitting(false);
    }
  }, [
    actionStudent,
    dropoutDate,
    dropoutReasonCode,
    dropoutReasonDetails,
    refreshTables,
    refreshDetailIfOpen,
  ]);



  const submitAssignLrn = useCallback(async () => {
    if (!actionStudent) return;
    const normalizedLrn = lrnForm.lrn.trim();
    if (!/^\d{12}$/.test(normalizedLrn)) {
      sileo.warning({
        title: "Invalid LRN",
        description: "LRN must be exactly 12 digits.",
      });
      return;
    }

    setActionSubmitting(true);
    try {
      await api.post(`/students/${actionStudent.id}/lrn`, {
        lrn: normalizedLrn,
      });

      sileo.success({
        title: "LRN saved",
        description: "Learner reference number was assigned successfully.",
      });
      setShowLrnDialog(false);
      await refreshTables();
      await refreshDetailIfOpen(actionStudent.id);
    } catch (err) {
      toastApiError(err as never);
    } finally {
      setActionSubmitting(false);
    }
  }, [actionStudent, lrnForm.lrn, refreshTables, refreshDetailIfOpen]);



  const columns = useMemo<ColumnDef<Student>[]>(
    () => {
      const allColumns: ColumnDef<Student>[] = [
        {
          id: "lastName",
          accessorKey: "lastName",
          size: 350,
          minSize: 260,
          maxSize: 500,
          meta: { skeletonClassName: "w-[200px]" },
          header: ({ column }) => (
            <DataTableColumnHeader
              column={column}
              title="LEARNER NAME"
            />
          ),
          cell: ({ row }) => {
            const initials = getInitials(row.original.firstName, row.original.lastName);
            return (
              <div className="flex min-w-0 items-center gap-3 py-3 pl-2">
                <UserPhoto
                  photo={row.original.studentPhoto}
                  containerClassName="w-12 h-12 rounded-full shadow-sm border shrink-0 border-2 border-primary border-solid"
                  className="w-full h-full object-cover"
                  alt={row.original.fullName}
                  fallbackIcon={
                    <div className="w-full h-full rounded-full flex items-center justify-center text-white  text-sm bg-primary">
                      {initials}
                    </div>
                  }
                />
                <div className="flex min-w-0 flex-col text-left">
                  <span className="break-words font-bold uppercase leading-tight">
                    {row.original.fullName}
                  </span>
                  <div className="flex flex-wrap items-center gap-2 mt-0.5">
                    <span>
                      LRN: {row.original.lrn}
                    </span>
                    {row.original.applicantType === "LATE_ENROLLEE" && (
                      <Badge className="h-4 px-1 text-sm bg-amber-100 text-amber-700 hover:bg-amber-100 border-amber-200 uppercase font-bold">
                        Late Enrollee
                      </Badge>
                    )}
                  </div>
                </div>
              </div>
            );
          },
        },
        {
          id: "gradeLevel",
          accessorKey: "gradeLevel",
          size: 180,
          minSize: 150,
          maxSize: 180,
          meta: { skeletonClassName: "w-[120px] mx-auto", className: "text-center", headerClassName: "text-center" },
          header: ({ column }) => (
            <DataTableColumnHeader
              column={column}
              title="GRADE LEVEL & SECTION"
              className="justify-center [&_button]:!m-0 text-center"
            />
          ),
          cell: ({ row }) => (
            <TooltipProvider delayDuration={200}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <div className="flex flex-col items-center justify-center py-2 gap-1 w-full">
                    <Badge
                      variant="outline"
                      className={cn(
                        "font-bold px-2.5 py-0.5 rounded-md uppercase",
                        getGradeLevelBadgeStyles(row.original.gradeLevel)
                      )}
                    >
                      {formatGradeLevel(row.original.gradeLevel) || "Grade"}
                    </Badge>
                    <span className="font-bold text-sm leading-tight text-center uppercase cursor-help">
                      {formatSectionLabel(row.original.section)}
                    </span>
                    {activeTab === "completers" && (() => {
                      const sy = row.original.schoolYear
                      const label = !sy ? null : typeof sy === "string" ? sy : sy.yearLabel
                      return label ? (
                        <span className="text-sm text-foreground font-bold leading-tight">
                          {label}
                        </span>
                      ) : null
                    })()}
                  </div>
                </TooltipTrigger>
                {row.original.sectionAdviser && (
                  <TooltipContent className={cn("px-3 py-2 border", getGradeLevelBadgeStyles(row.original.gradeLevel))}>
                    <p className="font-bold">ADVISER: {row.original.sectionAdviser}</p>
                    <p className="font-bold">EMPLOYEE ID: {row.original.sectionAdviserEmployeeId}</p>
                  </TooltipContent>
                )}
              </Tooltip>
            </TooltipProvider>
          ),
        },
        {
          id: "status",
          size: 150,
          minSize: 140,
          maxSize: 170,
          meta: { className: "text-center", headerClassName: "text-center" },
          header: ({ column }) => (
            <DataTableColumnHeader
              column={column}
              title="STATUS"
              className="justify-center [&_button]:!m-0"
            />
          ),
          cell: ({ row }) => (
            <div className="flex w-full justify-center py-3">
              {renderLearnerStatus(row.original)}
            </div>
          ),
        },
        {
          id: "curriculumProgram",
          accessorKey: "learningProgram",
          size: 160,
          minSize: 150,
          maxSize: 180,
          meta: { skeletonClassName: "w-[140px] mx-auto", className: "text-center", headerClassName: "text-center" },
          header: ({ column }) => (
            <DataTableColumnHeader
              column={column}
              title="Curricular Program"
              className="justify-center [&_button]:!m-0"
            />
          ),
          cell: ({ row }) => {
            const normalizedProgram = String(row.original.learningProgram || "REGULAR")
              .trim()
              .toUpperCase();
            const displayName = formatScpType(normalizedProgram).replace("Tech-Voc Education", "Tech-Voc");
            let acronym = SCP_ACRONYMS[normalizedProgram] || displayName;

            if (normalizedProgram === "REGULAR" && row.original.sectionId) {
              const isTopBecSection = row.original.sectionIsHomogeneous === true;
              if (isTopBecSection) {
                acronym = `BEC (Top ${homogeneousSectionCount || 5})`;
              }
            }

            return (
              <div className="flex w-full justify-center py-3">
                <TooltipProvider delayDuration={100}>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="leading-tight font-bold text-center block cursor-help">
                        {acronym}
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="top" className={cn("px-3 py-2 border", getGradeLevelBadgeStyles(row.original.gradeLevel))}>
                      <p className="font-bold text-sm">{displayName}</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </div>
            );
          },
        },
        {
          id: "actions",
          size: 150,
          minSize: 140,
          maxSize: 170,
          meta: { className: "text-center hover:bg-transparent", headerClassName: "text-center" },
          header: ({ column }) => (
            <DataTableColumnHeader
              column={column}
              title="Actions"
              className="justify-center [&_button]:!m-0"
            />
          ),
          cell: ({ row }) => (
            <div className="flex w-full justify-center py-3">
              <Button
                variant="outline"
                size="sm"
                className="h-9 items-center justify-center rounded-lg border bg-primary/5 px-4 text-sm text-primary transition-all border-2 border-primary hover:bg-primary hover:text-primary-foreground font-bold cursor-pointer"
                onClick={(e) => {
                  e.stopPropagation();
                  handleViewDetails(row.original.lrn || row.original.id);
                }}
              >
                <Eye className="w-4 h-4 mr-2" />
                Profile
              </Button>
            </div>
          ),
        },
      ];
      return activeTab === "active" ? allColumns.filter(col => col.id !== "status") : allColumns;
    }, [
    activeTab,
    enableHomogeneousSections,
    homogeneousSectionCount,
  ]);

  const renderContent = () => (
    <div className="space-y-6">

      {/* Student List */}
      <Card className="border-none shadow-sm bg-[hsl(var(--card))]">
        {/* Control Bar (Filters) */}
        <div className="bg-gray-50 border-b border-gray-200 p-2 sm:p-3 shrink-0">
          <div className="flex flex-col xl:flex-row items-start xl:items-center justify-between gap-4">
            <div className="flex-1 w-full min-w-[200px]">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="SEARCH LRN, FIRST NAME, LAST NAME..."
                  className="w-full h-10 pl-9 bg-muted border-gray-300 uppercase font-bold"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
              </div>
            </div>

            <div className="flex flex-row flex-wrap items-center justify-start xl:justify-end gap-3 w-full xl:w-auto shrink-0">
              <Select
                isFilter
                value={gradeLevelFilter}
                onValueChange={(value) => {
                  startTransition(() => {
                    setGradeLevelFilter(value);
                    setPage(1);
                  });
                }}>
                <SelectTrigger className="h-10 w-full leading-tight font-bold sm:w-40">
                  <SelectValue placeholder="All Grade Level" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all" className="leading-tight font-bold uppercase">
                    All Grade Level
                  </SelectItem>
                  {gradeLevels.map((gl) => (
                    <SelectItem
                      key={gl.id}
                      value={gl.id.toString()}
                      className="leading-tight font-bold uppercase">
                      <div className="flex items-center gap-2">
                        <span>{gl.name}</span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <Select
                isFilter
                value={programFilter}
                onValueChange={(value) => {
                  startTransition(() => {
                    setProgramFilter(value);
                    setPage(1);
                  });
                }}>
                <SelectTrigger className="h-10 w-full leading-tight font-bold sm:w-48">
                  <SelectValue placeholder="All Programs" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all" className="leading-tight font-bold">
                    All Programs
                  </SelectItem>
                  {programOptionsQuery.isPending && (
                    <SelectItem value="__loading" disabled>
                      Loading programs...
                    </SelectItem>
                  )}
                  {programOptionsQuery.isError && (
                    <SelectItem value="__error" disabled>
                      Programs could not be loaded
                    </SelectItem>
                  )}
                  {availablePrograms.map((option) => (
                    <SelectItem
                      key={option.value}
                      value={option.value}
                      className="leading-tight font-bold">
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <Select
                isFilter
                value={sectionFilter}
                onValueChange={(value) => {
                  startTransition(() => {
                    setSectionFilter(value);
                    setPage(1);
                  });
                }}>
                <SelectTrigger className="h-10 w-full leading-tight font-bold transition-colors sm:w-48">
                  <SelectValue placeholder="All Sections" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all" className="leading-tight font-bold">
                    All Sections
                  </SelectItem>
                  {gradeLevelFilter === "all" ? (
                    gradeLevels.map((gl) => {
                      const glSections = filteredSections.filter((s) => s.gradeLevelId === gl.id);
                      if (glSections.length === 0) return null;
                      return (
                        <SelectGroup key={gl.id}>
                          <SelectLabel className={cn("uppercase font-bold", getGradeLevelTextClass(gl.name))}>{gl.name}</SelectLabel>
                          {glSections.map((sec) => (
                            <SelectItem
                              key={sec.id}
                              value={sec.id.toString()}
                              className="leading-tight font-bold">
                              {formatSectionLabel(sec.name)}
                            </SelectItem>
                          ))}
                        </SelectGroup>
                      );
                    })
                  ) : (
                    filteredSections.map((sec) => (
                      <SelectItem
                        key={sec.id}
                        value={sec.id.toString()}
                        className="leading-tight font-bold">
                        {formatSectionLabel(sec.name)}
                      </SelectItem>
                    ))
                  )}
                </SelectContent>
              </Select>

              {activeTab === "inactive" && (
                <Select
                  isFilter
                  value={statusFilter}
                  onValueChange={(value) => {
                    startTransition(() => {
                      setStatusFilter(value);
                      setPage(1);
                    });
                  }}>
                  <SelectTrigger className="h-10 w-full leading-tight font-bold transition-colors sm:w-48">
                    <SelectValue placeholder="All Inactive" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all" className="leading-tight font-bold">
                      All Inactive
                    </SelectItem>
                    <SelectItem value="DROPPED" className="leading-tight font-bold text-red-600">
                      Dropped Out
                    </SelectItem>
                    <SelectItem value="TRANSFERRED_OUT" className="leading-tight font-bold text-amber-600">
                      Transferred Out
                    </SelectItem>
                  </SelectContent>
                </Select>
              )}

              {/* Vertical Divider (Hidden on small screens when wrapped) */}
              <div className="hidden xl:block w-px h-6 bg-border mx-1" />

              {/* Action Buttons */}
              <Button
                className="h-10 px-3 text-gray-600 hover:text-gray-900 shrink-0 font-bold"
                variant="ghost"
                onClick={() => {
                  startTransition(() => {
                    clearSearch();
                    setGradeLevelFilter("all");
                    setProgramFilter("all");
                    setSectionFilter("all");
                    setStatusFilter("all");
                    setSortBy("dateEnrolled");
                    setSortOrder("desc");
                    setPage(1);
                  });
                }}>
                <FilterXIcon className="w-4 h-4 mr-2" /> Clear
              </Button>
            </div>
          </div>
        </div>
        <CardContent className="p-0 flex-1 overflow-hidden flex flex-col min-h-0">
          <motion.div
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="flex-1 flex flex-col overflow-hidden">
            <div className="md:hidden space-y-3 p-3 overflow-y-auto flex-1 bg-muted/5">
              {students.length === 0 ? (
                <div className="rounded-xl border p-6 text-center leading-tight font-bold">
                  No learners found for the selected filters.
                </div>
              ) : (
                students.map((student, index) => (
                  <div
                    key={`${student.id}-${index}`}
                    className="rounded-xl border bg-[hsl(var(--card))] p-3">
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex items-center gap-3 min-w-0">
                        <UserPhoto
                          photo={student.studentPhoto}
                          containerClassName="w-10 h-10 rounded-full shadow-sm border shrink-0"
                          className="w-full h-full object-cover"
                          alt={student.fullName}
                          fallbackIcon={
                            <div className="w-full h-full rounded-full flex items-center justify-center text-white  text-sm bg-primary">
                              {getInitials(student.firstName, student.lastName)}
                            </div>
                          }
                        />
                        <div className="min-w-0">
                          <p className="font-bold uppercase leading-tight break-words">
                            {student.fullName}
                          </p>
                          <div className="flex items-center gap-2 mt-0.5">
                            <p className="font-bold text-foreground leading-snug">
                              {formatLearningProgramLabel(
                                student.learningProgram,
                              )}
                            </p>
                            {student.applicantType === "LATE_ENROLLEE" && (
                              <Badge className="h-4 px-1 text-sm bg-amber-100 text-amber-700 hover:bg-amber-100 border-amber-200 uppercase font-bold">
                                Late Enrolled
                              </Badge>
                            )}
                          </div>
                        </div>
                      </div>
                      {renderLearnerStatus(student)}
                    </div>

                    <div className="mt-2 grid grid-cols-2 gap-2 text-base">
                      <div>
                        <p className="uppercase  font-bold text-foreground">
                          LRN
                        </p>
                        <p className="font-bold">{student.lrn}</p>
                      </div>
                      <div>
                        <p className="uppercase  font-bold text-foreground">
                          Sex
                        </p>
                        <p className="font-bold uppercase">
                          {student.sex === "MALE" || student.sex === "M"
                            ? "M"
                            : student.sex === "FEMALE" ||
                              student.sex === "F"
                              ? "F"
                              : student.sex || "ΓÇö"}
                        </p>
                      </div>
                      <div>
                        <p className="uppercase font-bold text-foreground">
                          Grade Level
                        </p>
                        <Badge
                          variant="outline"
                          className={cn(
                            "font-bold px-2.5 py-0.5 mt-0.5 rounded-md",
                            getGradeLevelBadgeStyles(student.gradeLevel)
                          )}
                        >
                          {formatGradeLevel(student.gradeLevel)}
                        </Badge>
                      </div>
                      <div>
                        <p className="uppercase  font-bold text-foreground">
                          Section
                        </p>
                        <p className="font-bold">
                          {formatSectionLabel(student.section)}
                        </p>
                      </div>
                    </div>

                    <p className="mt-2 text-sm font-bold text-foreground">
                      {activeTab === "active" ? "Enrolled " : "Updated "}
                      {formatDate(
                        student.dateEnrolled || student.createdAt,
                      )}
                    </p>

                    <div className="mt-3 flex items-center gap-2">
                      <Button
                        variant="secondary"
                        size="sm"
                        className="h-9 flex-1 font-bold bg-primary/10 hover:bg-primary border-2 border-primary/20 hover:text-primary-foreground"
                        onClick={() => handleViewDetails(student.lrn || student.id)}>
                        <Eye className="h-3.5 w-3.5 mr-1.5" />
                        View
                      </Button>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button
                            variant="secondary"
                            size="sm"
                            className="h-9 w-10 px-0 font-bold bg-primary/10 hover:bg-primary border-2 border-primary/20 hover:text-primary-foreground"
                            aria-label={`Open actions for ${student.fullName}`}>
                            <MoreHorizontal className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent
                          align="end"
                          className="w-56 font-bold">
                          <DropdownMenuItem
                            onClick={() =>
                              handleOpenProfilePage(student.lrn || student.id)
                            }
                            className="cursor-pointer">
                            <Eye className="mr-2 h-4 w-4" />
                            Open Full Profile
                          </DropdownMenuItem>

                          {canMutate && (
                            <DropdownMenuItem
                              onClick={() => openAssignLrnDialog(student)}
                              className="cursor-pointer">
                              <Fingerprint className="mr-2 h-4 w-4" />
                              Update LIS LRN
                            </DropdownMenuItem>
                          )}
                          {canMutate && (
                            <DropdownMenuItem
                              onClick={() => openTransferOutDialog(student)}
                              className="cursor-pointer text-amber-700 focus:text-amber-700">
                              <FileBadge2 className="mr-2 h-4 w-4" />
                              Mark as Transferred Out
                            </DropdownMenuItem>
                          )}
                          {canMutate && (
                            <DropdownMenuItem
                              onClick={() => openDropoutDialog(student)}
                              className="cursor-pointer text-rose-700 focus:text-rose-700">
                              <BadgeAlert className="mr-2 h-4 w-4" />
                              Mark as Dropped Out
                            </DropdownMenuItem>
                          )}
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </div>
                  </div>
                ))
              )}
            </div>

            <div className="hidden md:block flex-1 overflow-auto bg-muted/5 relative">
              <DataTable<Student, unknown>
                columns={columns}
                data={students}
                loading={loading && isInitialLoad}
                loadingBehavior="delayed"
                forceEmptyState={isSearching}
                virtualize={true}
                estimatedRowHeight={60}
                className="border-none rounded-md h-full"
                tableClassName="min-w-[1200px] table-fixed"
                containerHeight="100%"
                prependBodyRow={
                  isSearching ? (
                    <TableSearchIndicator colSpan={8} />
                  ) : null
                }
                noResultsMessage="No learners found for the selected filters."
                sorting={sorting}
                onSortingChange={onSortingChange}
                getRowClassName={() => "group"}
              />
            </div>
          </motion.div>

          <PaginationBar
            page={page}
            total={total}
            limit={limit}
            onPageChange={setPage}
            onLimitChange={setLimit}
            itemName="Learners"
          />
        </CardContent>
      </Card>
    </div>
  );

  if (!ayId) {
    return (
      <div className="flex h-[calc(100vh-12rem)] w-full items-center justify-center">
        <Card className="max-w-md w-full border-dashed shadow-none bg-muted/20">
          <CardContent className="pt-10 pb-10 text-center space-y-3">
            <div className="mx-auto w-12 h-12 rounded-full bg-muted flex items-center justify-center">
              <CalendarDays className="h-6 w-6 text-foreground" />
            </div>
            <div className="space-y-1">
              <p className="font-bold text-foreground">
                No School Year Selected
              </p>
              <p className="text-foreground leading-relaxed px-4">
                Please set an active year or choose one from the header switcher
                to manage records for this period.
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  const setTitle = useHeaderStore((s) => s.setTitle);

  useEffect(() => {
    setTitle("Learner Directory");
    return () => setTitle(null);
  }, [setTitle]);

  return (
    <div className="flex flex-1 h-full w-full min-h-0 flex-col">


      {/* Tabs */}
      <Tabs
        value={activeTab}
        onValueChange={handleTabChange}
        className="w-full">
        <TabsList className="w-full flex flex-wrap sm:flex-nowrap h-auto gap-1 mb-4 p-1 bg-muted border border-border rounded-xl relative shadow-sm">
          <TabsTrigger
            value="active"
            className="flex-1 min-w-25 font-bold transition-all relative z-10 data-[state=active]:bg-transparent data-[state=active]:shadow-none rounded-lg">
            {activeTab === "active" && (
              <motion.div
                layoutId="students-active-pill"
                className="absolute inset-0 bg-primary shadow-sm rounded-lg"
                transition={{ type: "spring", bounce: 0.15, duration: 0.5 }}
              />
            )}
            <span className={cn("relative z-20 uppercase", activeTab === "active" ? "text-primary-foreground" : "text-foreground")}>
              <span className="hidden sm:inline">Active Masterlist</span>
              <span className="sm:hidden">Active</span>
            </span>
          </TabsTrigger>
          <TabsTrigger
            value="completers"
            className="flex-1 min-w-25 font-bold transition-all relative z-10 data-[state=active]:bg-transparent data-[state=active]:shadow-none rounded-lg">
            {activeTab === "completers" && (
              <motion.div
                layoutId="students-active-pill"
                className="absolute inset-0 bg-primary shadow-sm rounded-lg"
                transition={{ type: "spring", bounce: 0.15, duration: 0.5 }}
              />
            )}
            <span className={cn("relative z-20 uppercase", activeTab === "completers" ? "text-primary-foreground" : "text-foreground")}>
              <span className="hidden sm:inline">Completers / Alumni</span>
              <span className="sm:hidden">Alumni</span>
            </span>
          </TabsTrigger>
          <TabsTrigger
            value="inactive"
            className="flex-1 min-w-25 font-bold transition-all relative z-10 data-[state=active]:bg-transparent data-[state=active]:shadow-none rounded-lg">
            {activeTab === "inactive" && (
              <motion.div
                layoutId="students-active-pill"
                className="absolute inset-0 bg-primary shadow-sm rounded-lg"
                transition={{ type: "spring", bounce: 0.15, duration: 0.5 }}
              />
            )}
            <span className={cn("relative z-20 uppercase", activeTab === "inactive" ? "text-primary-foreground" : "text-foreground")}>
              <span className="hidden sm:inline">Inactive (Transferred / Dropped)</span>
              <span className="sm:hidden">Inactive</span>
            </span>
          </TabsTrigger>
        </TabsList>

        <AnimatePresence mode="wait" onExitComplete={() => window.scrollTo(0, 0)}>
          {activeTab === "active" && (
            <motion.div
              key="active"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="w-full">
              <TabsContent
                value="active"
                forceMount
                className="mt-0 focus-visible:outline-none ring-0">
                {renderContent()}
              </TabsContent>
            </motion.div>
          )}
          {activeTab === "completers" && (
            <motion.div
              key="completers"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="w-full">
              <TabsContent
                value="completers"
                forceMount
                className="mt-0 focus-visible:outline-none ring-0">
                {renderContent()}
              </TabsContent>
            </motion.div>
          )}
          {activeTab === "inactive" && (
            <motion.div
              key="inactive"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="w-full">
              <TabsContent
                value="inactive"
                forceMount
                className="mt-0 focus-visible:outline-none ring-0">
                {renderContent()}
              </TabsContent>
            </motion.div>
          )}
        </AnimatePresence>
      </Tabs>

      {/* Student Detail Panel */}
      <Sheet
        open={selectedStudentId !== null}
        onOpenChange={(open) => {
          if (!open) {
            confirmOrRun(() => setSelectedStudentId(null));
          }
        }}>
        <SheetContent
          side="right"
          aria-describedby={undefined}
          className="p-0 flex flex-row border-l overflow-visible w-full sm:w-auto sm:max-w-none"
          style={
            isDesktopViewport ? { width: `${panelPercentage}vw` } : undefined
          }>
          {/* Resize Handle ΓÇö hidden on mobile */}
          <div
            onMouseDown={startResizing}
            className="absolute left-[-4px] top-0 bottom-0 w-[8px] cursor-col-resize z-50 hover:bg-primary/30 transition-colors hidden sm:flex items-center justify-center group">
            <div className="h-8 w-1.5 rounded-full bg-muted-foreground/20 group-hover:bg-primary/50" />
          </div>

          {retainedStudentId && (
            <div className="flex-1 flex flex-col h-full overflow-hidden">
              <StudentDetailPanel
                id={retainedStudentId}
                schoolYearId={ayId}
                onClose={() => setSelectedStudentId(null)}
                onRefreshData={refreshTables}
                onTransferOut={handlePanelTransferOut}
                onDropout={handlePanelDropout}
                onExpand={(identifier) => navigate(`/learner/${identifier || retainedStudentId}`)}
                canEditProfile={false}
              />
            </div>
          )}
        </SheetContent>
      </Sheet>

      <Dialog
        open={showTransferOutDialog}
        onOpenChange={setShowTransferOutDialog}>
        <DialogContent className="w-full max-w-3xl">
          <DialogHeader>
            <DialogTitle>Mark Learner as Transferred Out</DialogTitle>
            <DialogDescription>
              Update transfer-out details for {actionStudent?.fullName}.
            </DialogDescription>
          </DialogHeader>

          <Alert className="bg-amber-50 border-amber-200 text-amber-800 py-2">
            <AlertTriangle className="h-4 w-4 text-amber-600" />
            <AlertDescription className="font-bold">
              Warning: This action will permanently alter the student's status
              on the official School Form 1 (SF1) and School Form 4 (SF4)
              reports.
            </AlertDescription>
          </Alert>

          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="transferOutDate">Transfer Date</Label>
              <HybridDatePicker
                value={transferOutDate}
                onChange={setTransferOutDate}
                placeholder="Select date"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="transferOutSchool">Destination School</Label>
              <Input
                id="transferOutSchool"
                value={transferOutSchoolName}
                onChange={(event) =>
                  setTransferOutSchoolName(event.target.value)
                }
                placeholder="Enter receiving school"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="transferOutReason">Reason (Optional)</Label>
              <Textarea
                id="transferOutReason"
                value={transferOutReason}
                onChange={(event) => setTransferOutReason(event.target.value)}
                placeholder="State reason for transfer"
                rows={3}
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowTransferOutDialog(false)}
              disabled={actionSubmitting}>
              Cancel
            </Button>
            <Button
              className="bg-orange-600 hover:bg-orange-700 text-white font-bold"
              onClick={() => void submitTransferOut()}
              disabled={actionSubmitting}>
              {actionSubmitting ? "Saving..." : "Confirm Transfer Out"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={showDropoutDialog}
        onOpenChange={setShowDropoutDialog}>
        <DialogContent className="w-full max-w-3xl">
          <DialogHeader>
            <DialogTitle>Mark Learner as Dropped Out</DialogTitle>
            <DialogDescription>
              Update dropout details for {actionStudent?.fullName}.
            </DialogDescription>
          </DialogHeader>

          <Alert className="bg-amber-50 border-amber-200 text-amber-800 py-2">
            <AlertTriangle className="h-4 w-4 text-amber-600" />
            <AlertDescription className="font-bold">
              Warning: This action will permanently alter the student's status
              on the official School Form 1 (SF1) and School Form 4 (SF4)
              reports.
            </AlertDescription>
          </Alert>

          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="dropOutDate">Dropout Date</Label>
              <HybridDatePicker
                value={dropoutDate}
                onChange={setDropoutDate}
                placeholder="Select date"
              />
            </div>
            <div className="space-y-2">
              <Label>Dropout Reason</Label>
              <Select
                value={dropoutReasonCode}
                onValueChange={(value) =>
                  setDropoutReasonCode(value as DropoutReasonCode)
                }>
                <SelectTrigger>
                  <SelectValue placeholder="Select reason" />
                </SelectTrigger>
                <SelectContent>
                  {DROPOUT_REASON_OPTIONS.map((option) => (
                    <SelectItem
                      key={option.value}
                      value={option.value}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="dropOutNote">Reason Details</Label>
              <Textarea
                id="dropOutNote"
                value={dropoutReasonDetails}
                onChange={(event) =>
                  setDropoutReasonDetails(event.target.value)
                }
                placeholder={
                  dropoutReasonCode === "OTHER"
                    ? "Required for OTHER reason"
                    : "Additional context (optional)"
                }
                rows={3}
              />
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowDropoutDialog(false)}
              disabled={actionSubmitting}>
              Cancel
            </Button>
            <Button
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground font-bold"
              onClick={() => void submitDropout()}
              disabled={actionSubmitting}>
              {actionSubmitting ? "Saving..." : "Confirm Dropout"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>



      <Dialog
        open={showLrnDialog}
        onOpenChange={setShowLrnDialog}>
        <DialogContent className="w-full max-w-3xl">
          <DialogHeader>
            <DialogTitle>Input Official DepEd LRN</DialogTitle>
            <DialogDescription>
              Enter the 12-digit Learner Reference Number generated by the
              national DepEd LIS portal for {actionStudent?.fullName}. This will
              clear the student's \"Pending LRN\" status.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3">
            <div className="space-y-2">
              <Label
                htmlFor="assignLrn"
                className="font-bold">
                Learner Reference Number (LRN)
              </Label>
              <Input
                id="assignLrn"
                value={lrnForm.lrn}
                onChange={(event) =>
                  setLrnForm({
                    lrn: event.target.value.replace(/[^0-9]/g, "").slice(0, 12),
                  })
                }
                placeholder="e.g., 101234567890"
                className="h-12 text-lg font-bold  text-center"
                inputMode="numeric"
                maxLength={12}
              />
              <p className="text-sm text-foreground font-bold text-center">
                Must be exactly 12 digits as found in the DepEd LIS portal.
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowLrnDialog(false)}
              disabled={actionSubmitting}>
              Cancel
            </Button>
            <Button
              className="bg-primary hover:bg-primary/90 font-bold"
              onClick={() => void submitAssignLrn()}
              disabled={actionSubmitting || lrnForm.lrn.length !== 12}>
              {actionSubmitting ? "Saving..." : "Save LRN"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { AnimatedError } from "@/shared/components/AnimatedError";
import { memo, useCallback, useState, useEffect, useMemo } from "react";
import { useForm, Controller } from "react-hook-form";
import { z } from "zod";
import { zodResolver } from "@/shared/lib/zodResolver";
import {
  Briefcase,
  GraduationCap,
  _RefreshCw,
  User as UserIcon,
  UserRoundPen,
  Smartphone,
  Mars,
  Venus,
  ShieldAlert,
  _Clock,
  _Plus,
  _Trash2,
} from "lucide-react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  _SheetDescription,
} from "@/shared/ui/sheet";
import { Badge } from "@/shared/ui/badge";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/ui/select";
import { Checkbox } from "@/shared/ui/checkbox";
import { ConfirmationModal } from "@/shared/ui/confirmation-modal";
import { Textarea } from "@/shared/ui/textarea";
import { HybridDatePicker } from "@/shared/components/HybridDatePicker";
import { SearchableCombobox } from "@/shared/ui/searchable-combobox";
import { MultiSearchableCombobox } from "@/shared/ui/multi-searchable-combobox";
import { UserPhoto } from "@/shared/components/UserPhoto";
import {
  cn,
} from "@/shared/lib/utils";
import type {
  Teacher,
  TeacherFundingSource,
  TeacherNatureOfAppointment,
} from "../types";
import { _formatAdvisorySectionSummary, formatTeacherName, _toSentenceCase } from "../utils";
import api from "@/shared/api/axiosInstance";
import { sileo } from "sileo";
import { useSettingsStore } from "@/store/settings.slice";
import { useSchoolYearContext } from "@/shared/hooks/useSchoolYearContext";
import { useResizablePanel } from "@/shared/hooks/useResizablePanel";
import {
  DEPED_TEACHER_DEPARTMENT_OPTIONS,
  TEACHER_FUNDING_SOURCE_OPTIONS,
  TEACHER_NATURE_OF_APPOINTMENT_OPTIONS,
  getDesignationPool,
  DEPED_TEACHER_PLANTILLA_POSITION_OPTIONS,
  DEPED_TEACHER_ANCILLARY_ROLE_OPTIONS,
  TEACHER_UNDERGRADUATE_DEGREE_OPTIONS,
  TEACHER_POSTGRADUATE_DEGREE_OPTIONS,
  TEACHER_JHS_SPECIALIZATION_OPTIONS,
  TEACHER_JHS_MINOR_SPECIALIZATION_OPTIONS,
  IP_COMMUNITY_OPTIONS,
  IP_COMMUNITY_VALUES,
} from "@enrollpro/shared";
import {
  useUnsavedChanges,
  useUnsavedChangesPrompt,
} from "@/shared/hooks/useUnsavedChanges";

interface TeacherDetailPanelProps {
  teacher: Teacher | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaveSuccess?: () => void;
}

interface ApiErrorResponse {
  response?: {
    data?: {
      message?: string;
    };
  };
}



const formSchema = z
  .object({
    firstName: z.string().min(1, "Enter the first name."),
    lastName: z.string().min(1, "Enter the last name."),
    middleName: z.string().optional().nullable(),
    suffix: z.string().optional().nullable(),
    sex: z.enum(["MALE", "FEMALE"], { message: "Select the sex." }),
    birthdate: z.string().min(1, "Select the date of birth.").nullable(),

    personnelType: z.enum(["TEACHING", "NON_TEACHING"]).nullable(),
    employeeId: z
      .string()
      .trim()
      .regex(/^\d{7}$/, "Enter the 7-digit DepEd Employee ID.")
      .nullable(),
    plantillaPosition: z.string().min(1, "Select the DepEd position (plantilla)."),
    departments: z.array(z.string()).default([]),
    functionalAssignment: z.string().optional().nullable(),
    specialization: z.string().optional().nullable(),
    undergraduateDegree: z.string().optional().nullable(),
    postgraduateDegree: z.string().optional().nullable(),
    majorSpecialization: z.string().optional().nullable(),
    minorSpecialization: z.string().optional().nullable(),
    indigenousCommunity: z.enum(IP_COMMUNITY_VALUES).optional().nullable().default("NOT APPLICABLE"),
    natureOfAppointment: z.enum([
      "REGULAR_PERMANENT",
      "PROVISIONAL",
      "SUBSTITUTE",
      "CONTRACTUAL",
      "VOLUNTEER",
      "LOCAL_SCHOOL_BOARD",
      "OTHER",
    ]).optional().nullable(),
    fundingSource: z.enum([
      "NATIONAL",
      "SPECIAL_EDUCATION_FUND",
      "LOCAL_SCHOOL_BOARD",
      "PTA",
      "NGO",
      "OTHER",
    ]).optional().nullable(),
    ancillaryRoles: z.array(z.string()).default([]),
    roles: z.array(z.string()),

    contactNumber: z
      .string()
      .trim()
      .regex(/^09\d{2}-\d{3}-\d{4}$/, "Enter an 11-digit mobile number in the format 09XX-XXX-XXXX."),

    serviceStatus: z
      .enum([
        "ACTIVE",
        "ON_LEAVE",
        "TRANSFERRED",
        "RETIRED_RESIGNED",
        "DROPPED_FROM_ROLLS",
      ])
      .optional(),
    serviceEffectiveDate: z.string().optional().nullable(),
    serviceRemarks: z.string().optional().nullable(),
    portalActive: z.boolean().optional(),
  })
  .superRefine((data, ctx) => {
    const isMRF = data.roles.includes("MRF");
    const isTeacherRole = data.roles.includes("TEACHER") || data.roles.includes("CLASS_ADVISER");
    const shouldRequireSF7 = !(isMRF && !isTeacherRole);

    if (shouldRequireSF7) {
      if (!data.undergraduateDegree || data.undergraduateDegree.trim().length === 0) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "Enter the undergraduate degree.",
          path: ["undergraduateDegree"],
        });
      }
      if (!data.natureOfAppointment) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "Select the nature of appointment.",
          path: ["natureOfAppointment"],
        });
      }
      if (!data.fundingSource) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "Select the fund source.",
          path: ["fundingSource"],
        });
      }
    }
  });

type FormValues = z.infer<typeof formSchema>;
type PersonnelType = FormValues["personnelType"];

function toPersonnelType(value: string | null): PersonnelType {
  return value === "TEACHING" || value === "NON_TEACHING" ? value : null;
}

function formatDateInput(value: string | null | undefined): string {
  return value ? new Date(value).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10);
}

function getApiErrorMessage(error: unknown, fallback: string): string {
  if (!error || typeof error !== "object") {
    return fallback;
  }

  const apiError = error as ApiErrorResponse;
  return apiError.response?.data?.message ?? fallback;
}



export const TeacherDetailPanel = memo(function TeacherDetailPanel({
  teacher,
  open,
  onOpenChange,
  onSaveSuccess,
}: TeacherDetailPanelProps) {
  const { panelPercentage, isDesktopViewport, startResizing } = useResizablePanel();
  const { confirmOrRun } = useUnsavedChangesPrompt();
  const { _ayId } = useSchoolYearContext();

  const _isTeachingStaff = useMemo(() => {
    return teacher?.userAccount?.roles?.some(r => ["TEACHER", "CLASS_ADVISER"].includes(r)) ?? false;
  }, [teacher]);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showResetPasswordConfirm, setShowResetPasswordConfirm] = useState(false);
  const [isPortalActionSubmitting, setIsPortalActionSubmitting] = useState(false);
  const [defaultPasswordInput, setDefaultPasswordInput] = useState("");

  const globalDefaultPassword = useSettingsStore((s) => s.globalDefaultPassword);

  useEffect(() => {
    setDefaultPasswordInput(globalDefaultPassword || "");
  }, [globalDefaultPassword]);

  const handleResetPassword = () => {
    setShowResetPasswordConfirm(true);
  };

  const handleResetPasswordConfirm = async () => {
    if (!teacher) return;
    if (!defaultPasswordInput.trim()) {
      sileo.error({
        title: "Validation Error",
        description: "Default password cannot be empty.",
      });
      return;
    }
    setShowResetPasswordConfirm(false);
    setIsPortalActionSubmitting(true);
    try {
      await api.post(`/teachers/${teacher.id}/reset-password`, { password: defaultPasswordInput });
      sileo.success({
        title: "Password Reset Success",
        description: "Teacher portal password has been reset.",
      });
    } catch (err: unknown) {
      sileo.error({
        title: "Failed to Reset Password",
        description: getApiErrorMessage(err, "An error occurred while resetting password."),
      });
    } finally {
      setIsPortalActionSubmitting(false);
    }
  };

  const {
    control,
    handleSubmit,
    reset,
    watch,
    setValue,
    formState: { isDirty, errors },
  } = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      firstName: "",
      lastName: "",
      middleName: "",
      suffix: "",
      sex: undefined as any,
      birthdate: null,
      personnelType: null,
      employeeId: null,
      plantillaPosition: "",
      departments: [],
      functionalAssignment: "",
      specialization: "",
      undergraduateDegree: "",
      postgraduateDegree: "",
      majorSpecialization: "",
      minorSpecialization: "",
      indigenousCommunity: "NOT APPLICABLE",
      natureOfAppointment: "REGULAR_PERMANENT",
      fundingSource: "NATIONAL",
      roles: [],
      ancillaryRoles: [],
      contactNumber: "",
      serviceStatus: "ACTIVE",
      serviceEffectiveDate: new Date().toISOString().slice(0, 10),
      serviceRemarks: "",
      portalActive: true,
    },
  });

  const formRoles = watch("roles");
  const formPersonnelType = watch("personnelType");

  const isFormTeachingStaff = useMemo(() => {
    return formRoles?.some(r => ["TEACHER", "CLASS_ADVISER"].includes(r)) ?? false;
  }, [formRoles]);

  useEffect(() => {
    setValue("personnelType", isFormTeachingStaff ? "TEACHING" : "NON_TEACHING", { shouldValidate: true });
    if (!isFormTeachingStaff) {
      setValue("departments", []);
    }
  }, [isFormTeachingStaff, setValue]);

  const formPlantillaPosition = watch("plantillaPosition");
  const formServiceStatus = watch("serviceStatus");
  const formFirstName = watch("firstName");
  const formLastName = watch("lastName");
  const formSuffix = watch("suffix");

  useEffect(() => {
    if (teacher) {
      const isTeacherOrAdviser = teacher.userAccount?.roles?.some(r => ["TEACHER", "CLASS_ADVISER"].includes(r)) ?? false;
      const _isMRF = teacher.userAccount?.roles?.includes("MRF") ?? false;
      const serviceMetadata = teacher as Teacher & {
        serviceEffectiveDate?: string | null;
        serviceRemarks?: string | null;
      };

      reset({
        firstName: (teacher.firstName || "").toUpperCase(),
        lastName: (teacher.lastName || "").toUpperCase(),
        middleName: (teacher.middleName || "").toUpperCase(),
        suffix: (teacher.suffix || "").toUpperCase(),
        sex: teacher.sex,
        birthdate: teacher.birthdate ? new Date(teacher.birthdate).toISOString().slice(0, 10) : null,
        personnelType: toPersonnelType(teacher.personnelType),
        employeeId: teacher.employeeId || null,
        plantillaPosition: teacher.plantillaPosition === "MRF Coordinator" ? "" : (teacher.plantillaPosition || ""),
        departments: !isTeacherOrAdviser ? [] : (teacher.departments || []),
        functionalAssignment: teacher.functionalAssignment || "",
        specialization: teacher.specialization || "",
        undergraduateDegree: teacher.undergraduateDegree || "",
        postgraduateDegree: teacher.postgraduateDegree || "",
        majorSpecialization: teacher.majorSpecialization || "",
        minorSpecialization: teacher.minorSpecialization || "",
        indigenousCommunity: (teacher.indigenousCommunity as any) || "NOT APPLICABLE",
        natureOfAppointment: teacher.natureOfAppointment || "REGULAR_PERMANENT",
        fundingSource: teacher.fundingSource || "NATIONAL",
        roles: teacher.userAccount?.roles || [],
        ancillaryRoles: teacher.designation?.ancillaryRoles || teacher.ancillaryRoles || [],
        contactNumber: teacher.contactNumber || "",
        serviceStatus: teacher.serviceStatus || "ACTIVE",
        serviceEffectiveDate: formatDateInput(serviceMetadata.serviceEffectiveDate),
        serviceRemarks: serviceMetadata.serviceRemarks || "",
        portalActive: teacher.userAccount?.isActive ?? teacher.isActive ?? true,
      });
    } else {
      reset({
        firstName: "",
        lastName: "",
        middleName: "",
        suffix: "",
        sex: undefined as any,
        birthdate: null,
        personnelType: null,
        employeeId: null,
        plantillaPosition: "",
        departments: [],
        functionalAssignment: "",
        specialization: "",
        undergraduateDegree: "",
        postgraduateDegree: "",
        majorSpecialization: "",
        minorSpecialization: "",
        indigenousCommunity: "NOT APPLICABLE",
        natureOfAppointment: "REGULAR_PERMANENT",
        fundingSource: "NATIONAL",
        roles: [],
        ancillaryRoles: [],
        contactNumber: "",
        serviceStatus: "ACTIVE",
        serviceEffectiveDate: new Date().toISOString().slice(0, 10),
        serviceRemarks: "",
        portalActive: true,
      });
    }
  }, [teacher, reset, open]);

  const isAdding = !teacher || teacher.id === -1;
  const [isEditing, setIsEditing] = useState(isAdding);

  const currentRoles = formRoles || teacher?.userAccount?.roles || [];
  const isFormMRF = currentRoles.includes("MRF");
  const isFormTeacherOrAdviser = currentRoles.includes("TEACHER") || currentRoles.includes("CLASS_ADVISER");
  const showSF7 = !(isFormMRF && !isFormTeacherOrAdviser);

  useEffect(() => {
    if (open) setIsEditing(isAdding);
  }, [open, isAdding]);

  const designationPool = useMemo(() => {
    return getDesignationPool(formRoles);
  }, [formRoles]);

  useEffect(() => {
    if (
      formPlantillaPosition &&
      designationPool.length > 0 &&
      !designationPool.includes(formPlantillaPosition)
    ) {
      setValue("plantillaPosition", "", { shouldDirty: true });
    }
  }, [formRoles, formPlantillaPosition, designationPool, setValue]);

  const discardProfileChanges = useCallback(() => {
    reset();
  }, [reset]);

  const closePanel = useCallback(() => {
    onOpenChange(false);
  }, [onOpenChange]);

  const handleCloseAttempt = useCallback((nextOpen: boolean) => {
    if (nextOpen) {
      onOpenChange(true);
      return;
    }
    confirmOrRun(closePanel);
  }, [closePanel, confirmOrRun, onOpenChange]);

  useUnsavedChanges({
    id: "teacher-detail-panel",
    label: "Faculty/Staff profile",
    isDirty: open && isDirty,
    isSubmitting,
    onDiscard: discardProfileChanges,
  });

  const onSubmit = async (data: FormValues) => {
    setIsSubmitting(true);
    try {
      const profilePayload = {
        firstName: data.firstName.toUpperCase(),
        lastName: data.lastName.toUpperCase(),
        middleName: data.middleName ? data.middleName.toUpperCase() : "",
        suffix: data.suffix ? data.suffix.toUpperCase() : "",
        sex: data.sex,
        birthdate: data.birthdate,
        personnelType: data.personnelType,
        employeeId: data.employeeId,
        plantillaPosition: (data.plantillaPosition === "__NONE__" || data.plantillaPosition === "MRF Coordinator") ? "" : data.plantillaPosition,
        departments: data.departments,
        functionalAssignment: data.personnelType === "NON_TEACHING" ? data.functionalAssignment : null,
        specialization: data.specialization || "",
        undergraduateDegree: data.undergraduateDegree || "",
        postgraduateDegree: data.postgraduateDegree || "",
        majorSpecialization: data.majorSpecialization || "",
        minorSpecialization: data.minorSpecialization || "",
        indigenousCommunity: data.indigenousCommunity,
        natureOfAppointment: data.natureOfAppointment,
        fundingSource: data.fundingSource,
        roles: data.roles,
        ancillaryRoles: data.ancillaryRoles,
        contactNumber: data.contactNumber,
        serviceStatus: data.serviceStatus,
        serviceEffectiveDate: data.serviceEffectiveDate,
        serviceRemarks: data.serviceRemarks,
      };

      if (isAdding) {
        const createPayload = {
          ...profilePayload,
          password: defaultPasswordInput || undefined,
          portalActive: data.portalActive !== undefined ? data.portalActive : true,
        };
        await api.post<{ teacher: Teacher }>(`/teachers`, createPayload);
        sileo.success({ title: "Faculty/Staff Record Created", description: "The faculty or staff record has been saved." });
      } else {
        await api.patch(`/teachers/${teacher!.id}`, profilePayload);

        const originalPortalActive = teacher!.userAccount?.isActive ?? teacher!.isActive ?? true;
        if (data.portalActive !== undefined && data.portalActive !== originalPortalActive) {
          try {
            await api.patch(`/teachers/${teacher!.id}/portal-access`, { isActive: data.portalActive });
          } catch (err: unknown) {
            sileo.error({ title: "Portal Update Failed", description: getApiErrorMessage(err, "Profile saved, but portal status failed to update.") });
          }
        }

        sileo.success({ title: "Profile Updated", description: "The faculty/staff profile has been saved." });
      }

      if (onSaveSuccess) onSaveSuccess();
      reset(data);
      onOpenChange(false);
    } catch (err: unknown) {
      sileo.error({
        title: isAdding ? "Could Not Add Faculty/Staff" : "Could Not Update Profile",
        description: getApiErrorMessage(err, "Please check the required fields and try again.")
      });
    } finally {
      setIsSubmitting(false);
    }
  };
  // Helper maps for human-readable labels in view mode
  const ROLE_LABEL_MAP: Record<string, string> = {
    SYSTEM_ADMIN: "School Head",
    HEAD_REGISTRAR: "Registrar",
    TEACHER: "Teacher",
    CLASS_ADVISER: "Class Adviser",
    MRF: "MRF Coordinator",
  };

  const SERVICE_STATUS_LABEL_MAP: Record<string, string> = {
    ACTIVE: "Active Personnel",
    ON_LEAVE: "On Leave",
    TRANSFERRED: "Transferred",
    RETIRED_RESIGNED: "Retired / Resigned",
    DROPPED_FROM_ROLLS: "Dropped from Rolls",
  };

  const NATURE_OF_APPOINTMENT_MAP: Record<string, string> = {
    REGULAR_PERMANENT: "Regular / Permanent",
    PROVISIONAL: "Provisional",
    SUBSTITUTE: "Substitute",
    CONTRACTUAL: "Contractual",
    VOLUNTEER: "Volunteer",
    LOCAL_SCHOOL_BOARD: "Local School Board",
    OTHER: "Other",
  };

  const FUNDING_SOURCE_MAP: Record<string, string> = {
    NATIONAL: "National",
    SPECIAL_EDUCATION_FUND: "Special Education Fund",
    LOCAL_SCHOOL_BOARD: "Local School Board",
    PTA: "PTA",
    NGO: "NGO",
    OTHER: "Other",
  };

  // View Mode: grid row helper
  const ViewRow = ({ label, value }: { label: string; value: string | null | undefined }) => (
    <div className="grid grid-cols-[180px_1fr] divide-x divide-border">
      <div className="p-3 text-foreground bg-muted/30 uppercase">{label}</div>
      <div className="p-3 uppercase">{value || "ΓÇö"}</div>
    </div>
  );

  const portalIsActive = teacher?.userAccount?.isActive ?? teacher?.isActive ?? true;

  return (
    <>
      <Sheet open={open} onOpenChange={handleCloseAttempt}>
        <SheetContent
          side="right"
          aria-describedby={undefined}
          onPointerDownOutside={(e) => {
            if (isDirty) {
              e.preventDefault();
              confirmOrRun(closePanel);
            }
          }}
          onEscapeKeyDown={(e) => {
            if (isDirty) {
              e.preventDefault();
              confirmOrRun(closePanel);
            }
          }}
          className="p-0 flex flex-col h-full border-l overflow-visible w-full sm:w-auto sm:max-w-none"
          style={
            isDesktopViewport ? { width: `${panelPercentage}vw` } : undefined
          }
        >
          {/* Resize Handle ΓÇö hidden on mobile */}
          <div
            onMouseDown={startResizing}
            className="absolute left-[-4px] top-0 bottom-0 w-[8px] cursor-col-resize z-50 hover:bg-primary/30 transition-colors hidden sm:flex items-center justify-center group">
            <div className="h-8 w-1.5 rounded-full bg-muted-foreground/20 group-hover:bg-primary/50" />
          </div>

          <div className="flex-1 flex flex-col h-full overflow-hidden bg-background">
            {/* ΓöÇΓöÇΓöÇ Header ΓöÇΓöÇΓöÇ */}
            <SheetHeader className="flex flex-row items-center justify-between p-3 sm:p-4 border-b shrink-0 bg-primary font-bold text-left space-y-0 mt-0">
              <div>
                <SheetTitle className="text-base sm:text-lg text-primary-foreground font-bold uppercase flex items-center gap-2">
                  {isAdding ? "New Personnel Profile" : "Personnel Profile"}
                </SheetTitle>
              </div>
            </SheetHeader>

            <form onSubmit={handleSubmit(onSubmit)} className="flex-1 flex flex-col overflow-hidden">
              <div className="flex-1 overflow-y-auto p-3 sm:p-4 space-y-4 font-bold">

                {/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */}
                {/* SUMMARY BLOCK (Matches StudentDetailPanel)                 */}
                {/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */}
                <div className="bg-[hsl(var(--muted))] p-3 sm:p-4 rounded-md border">
                  <div className="flex flex-col items-center mb-6 pt-2">
                    <UserPhoto
                      photo={teacher?.photoPath}
                      containerClassName="w-24 h-24 sm:w-32 sm:h-32 rounded-full border-2 border-primary border-dashed shadow-md shrink-0"
                      className="w-full h-full object-cover rounded-full"
                      fallbackIcon={
                        <div className="w-full h-full rounded-full flex items-center justify-center text-white font-bold text-3xl sm:text-4xl uppercase bg-primary">
                          {isAdding ? (
                            <UserIcon className="size-12" />
                          ) : (
                            <>
                              {(formFirstName || teacher?.firstName || "N").charAt(0)}
                              {(formLastName || teacher?.lastName || "N").charAt(0)}
                            </>
                          )}
                        </div>
                      }
                    />
                    <div className="text-center mt-4">
                      <h3 className="font-bold text-lg sm:text-xl uppercase break-words">
                        {isAdding ? "New Personnel" : formatTeacherName({
                          ...teacher!,
                          firstName: formFirstName || teacher?.firstName || "",
                          lastName: formLastName || teacher?.lastName || "",
                          suffix: formSuffix ?? teacher?.suffix ?? null,
                        } as Teacher)}
                      </h3>
                      <div className="flex items-center justify-center gap-2 mt-1 font-bold flex-wrap">
                        {!isAdding && (
                          (teacher?.userAccount?.roles || []).length > 0
                            ? (teacher?.userAccount?.roles || []).map((role) => (
                              <Badge key={role} variant="outline" className="gap-1 px-3 py-1 rounded-md uppercase shadow-sm font-bold border-primary text-primary bg-primary/5">
                                {ROLE_LABEL_MAP[role] || role}
                              </Badge>
                            ))
                            : <Badge variant="outline" className="gap-1 px-3 py-1 rounded-md uppercase shadow-sm font-bold text-muted-foreground">No roles</Badge>
                        )}
                      </div>
                      {!isAdding && (
                        <p className=" mt-2 uppercase text-foreground">
                          Employee ID: <span>{teacher?.employeeId || "ΓÇö"}</span>
                        </p>
                      )}
                      {!isEditing && !isAdding && (
                        <div className="mt-4 flex justify-center w-full px-2">
                          <Button
                            variant="default"
                            className="font-bold text-sm h-10 uppercase bg-primary hover:bg-primary/90 text-primary-foreground shadow-md w-full max-w-sm rounded-md transition-all active:scale-[0.98]"
                            onClick={(e) => {
                              e.preventDefault();
                              setIsEditing(true);
                            }}
                          >
                            <UserRoundPen className="mr-2 h-5 w-5 shrink-0" />
                            Edit Profile
                          </Button>
                        </div>
                      )}
                    </div>
                  </div>


                </div>

                {/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */}
                {/* VIEW MODE ΓÇö read-only grid tables                          */}
                {/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */}
                {!isEditing && !isAdding && teacher && (
                  <>

                    {/* Personal Information */}
                    <div className="border rounded-md bg-[hsl(var(--card))] overflow-hidden">
                      <div className="p-3 font-bold text-base leading-tight bg-[hsl(var(--muted)/50)] border-b flex items-center gap-2">
                        <UserIcon className="h-4 w-4 text-primary" />
                        Personal Information
                      </div>
                      <div className="text-base leading-tight font-bold divide-y divide-border">
                        <ViewRow label="First Name" value={teacher.firstName} />
                        <ViewRow label="Middle Name" value={teacher.middleName} />
                        <ViewRow label="Last Name" value={teacher.lastName} />
