                                      searchPlaceholder="Search degrees..."
                                      className={cn(
                                        "w-full h-10 font-bold text-base leading-tight bg-background text-foreground border-border",
                                        errors.undergraduateDegree && "border-destructive focus-visible:ring-destructive"
